};

export default App;

import { ProductionEntry } from './types';

// Helper to generate a random number within a range
const rand = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1) + min);

const operators = ['Franck', 'Sidoneide', 'Deyvis', 'Erivan', 'Nahin', 'Carlos Philips', 'Edilson', 'Everson', 'Marcelo'];
const machines = ['Cast 1', 'Cast 2'];
const shifts = ['Diurno', 'Noturno'];

const generateFakeData = (): ProductionEntry[] => {
  const data: ProductionEntry[] = [];
  const start = new Date('2024-11-01');
  const end = new Date(); // Today

  let id = 1;

  for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
    // Generate 1-2 entries per day
    const entriesPerDay = rand(1, 2);

    for (let i = 0; i < entriesPerDay; i++) {
      const dateStr = d.toISOString().split('T')[0];
      const gross = rand(35000, 42000);
      const tara = rand(1100, 1500);
      const net = gross - tara;

      data.push({
        id: (id++).toString(),
        date: dateStr,
        operator: operators[rand(0, operators.length - 1)],
        machine: machines[rand(0, machines.length - 1)],
        shift: shifts[rand(0, shifts.length - 1)],
        grossWeight: gross,
        tara: tara,
        netWeight: net,
        volumes: rand(85, 110),
        tubetes: rand(40, 60),
        ecoA: 0,
        ecoBP: rand(800, 1500),
        ecoBM: rand(300, 600),
        borraTotal: rand(20, 150),
        manutencaoMin: rand(0, 1) > 0.8 ? rand(20, 90) : 0,
        processoMin: rand(0, 1) > 0.7 ? rand(10, 40) : 0,
        outrosMin: rand(0, 1) > 0.9 ? rand(5, 20) : 0,
      });
    }
  }
  return data;
};

export const INITIAL_DATA: ProductionEntry[] = generateFakeData();

export const GOAL_VALUE = 4500000; // Increased goal to match larger dataset

import React, { useState, useMemo, useEffect } from 'react';
import { Menu, Plus, TrendingUp, BarChart2, Calendar, RotateCcw, Download, Clock, Zap, Trash2, Cpu, BrainCircuit, Sparkles, CheckCircle2, AlertTriangle, X, ChevronRight, Settings, Target, Users, UserPlus, Trophy, Sparkle, RefreshCw, User, Filter } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { GoogleGenAI } from "@google/genai";
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '2.5'; // Versão incrementada para forçar refresh da lista de operadores e dados

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');

    // Se a versão mudar, reinicia para a nova lista padrão
    const defaultOps = ['Franck', 'Sidoneide', 'Deyvis', 'Erivan', 'Nahin', 'Carlos Philips', 'Edilson', 'Everson', 'Marcelo'].sort();

    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const isGoalAchieved = stats.totalNet >= goalValue && goalValue > 0;

  const machineStatus = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const machineEntries = productionData.filter(e => e.machine === m);
      const sortedEntries = [...machineEntries].sort((a, b) => b.date.localeCompare(a.date));
      const lastEntry = sortedEntries[0];
      const totalDowntime = lastEntry ? (lastEntry.manutencaoMin + lastEntry.processoMin + lastEntry.outrosMin) : 0;

      let status = 'Operando';
      let color = 'emerald';

      if (!lastEntry) { status = 'Sem Dados'; color = 'slate'; }
      else if (lastEntry.manutencaoMin > 30) { status = 'Manutenção'; color = 'orange'; }
      else if (totalDowntime > 60) { status = 'Alerta'; color = 'amber'; }

      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleRemoveOperator = (name: string) => {
    if (confirm(`Remover operador ${name}?`)) {
      setOperators(prev => prev.filter(op => op !== name));
      if (selectedOperator === name) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados para os valores iniciais? Isso apagará seus lançamentos manuais e resetará a lista de operadores.')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setOperators(['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Franck', 'Marcelo', 'Nahin', 'Sidoneide']);
      setSelectedOperator('Todos');
      setSelectedMachine('Todas');
      setStartDate('');
      setEndDate('');
      setIsMenuOpen(false);
    }
  };

  const downtimePieData = useMemo(() => [
    { name: 'Manutenção', value: stats.manut, color: '#f97316' },
    { name: 'Processo', value: stats.proc, color: '#f59e0b' },
    { name: 'Outros', value: stats.outros, color: '#94a3b8' }
  ].filter(d => d.value > 0), [stats]);

  const operatorPerformanceData = useMemo(() => {
    const performanceMap: Record<string, number> = {};
    filteredData.forEach(entry => {
      performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
    });
    return Object.entries(performanceMap)
      .map(([name, kg]) => ({ name, kg }))
      .sort((a, b) => b.kg - a.kg);
  }, [filteredData]);

  const exportToCSV = () => {
    const headers = ['Data', 'Operador', 'Maquina', 'Turno', 'Peso Liquido', 'Paradas'];
    const rows = filteredData.map(e => [e.date, e.operator, e.machine, e.shift, e.netWeight, e.manutencaoMin + e.processoMin + e.outrosMin]);
    const csvContent = [headers, ...rows].map(r => r.join(';')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `relatorio_producao_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    setIsMenuOpen(false);
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Sidebar Menu */}
      <div className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-400">
              <X size={24} />
            </button>
          </div>

          {/* Goal Setting */}
          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Global
            </h3>
            <input 
              type="number" 
              value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-500/10"
            />
          </div>

          {/* Filter Section in Menu */}
          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            {/* Operator Filter */}
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500/10 appearance-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            {/* Date Filters */}
            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold focus:outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold focus:outline-none" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Todos Filtros
            </button>
          </div>

          {/* Management */}
          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro de Operadores
            </h3>
            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Novo nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold focus:outline-none"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl hover:bg-blue-700">
                <UserPlus size={16} />
              </button>
            </form>
            <div className="max-h-24 overflow-y-auto space-y-1 pr-1 custom-scrollbar">
              {operators.map(op => (
                <div key={op} className="flex items-center justify-between bg-slate-50 px-3 py-1.5 rounded-lg group">
                  <span className="text-[10px] font-bold text-slate-700">{op}</span>
                  <button onClick={() => handleRemoveOperator(op)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all">
                    <Trash2 size={12} />
                  </button>
                </div>
              ))}
            </div>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100 transition-all">
                Exportar Relatório CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200 transition-all mt-2">
                Resetar Base de Dados <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all active:scale-95 text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo Lançamento</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-colors flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded hidden sm:block">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Goal Achieved Alert */}
        {isGoalAchieved && (
          <div className="bg-emerald-600 text-white p-4 rounded-2xl shadow-xl shadow-emerald-200 flex items-center justify-between animate-bounce">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-white/20 rounded-full flex items-center justify-center">
                <Trophy size={28} className="text-emerald-100" />
              </div>
              <div>
                <h2 className="font-black text-sm uppercase tracking-widest">Meta Atingida!</h2>
                <p className="text-[11px] font-medium text-emerald-100">A meta de produção foi superada com sucesso.</p>
              </div>
            </div>
            <Sparkle size={16} className="text-yellow-400 animate-pulse" />
          </div>
        )}

        {/* Machine Status */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatus.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex items-center gap-4">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center bg-${m.color}-100 text-${m.color}-600`}>
                {m.status === 'Operando' ? <CheckCircle2 size={20} /> : <AlertTriangle size={20} />}
              </div>
              <div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-bold text-slate-700">{m.status}</span>
                  <div className={`w-2 h-2 rounded-full bg-${m.color}-500 animate-pulse`}></div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Machine Selector Only (Cleaner Main View) */}
        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button 
                  key={m} onClick={() => setSelectedMachine(m)}
                  className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{stats.borra.toLocaleString('pt-BR')} kg</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span>
            <span className="text-xl font-black text-blue-600">{(stats.totalNet / 1000).toFixed(1)}t</span>
          </div>
        </div>

        {/* Goal Tracking */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500 shadow-emerald-100 scale-[1.01]' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className={`text-[10px] font-black uppercase tracking-widest ${isGoalAchieved ? 'text-emerald-500' : 'text-blue-500'}`}>
                 Atingimento {selectedOperator !== 'Todos' ? `de ${selectedOperator}` : 'Geral'}
               </span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{stats.totalNet.toLocaleString('pt-BR')}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {goalValue.toLocaleString('pt-BR')} kg</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {Math.round((stats.totalNet / goalValue) * 100)}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div 
              className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500 shadow-emerald-500/30' : 'bg-blue-600 shadow-blue-500/30'}`} 
              style={{ width: `${Math.min((stats.totalNet / goalValue) * 100, 100)}%` }}
            ></div>
          </div>
        </div>

        {/* Charts Row */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100">
            <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest mb-6 flex items-center gap-2">
              {selectedOperator === 'Todos' ? 'Rendimento Operacional' : `Histórico de ${selectedOperator}`}
            </h3>
            <div className="h-[240px] w-full">
              {operatorPerformanceData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={operatorPerformanceData}>
                    <CartesianGrid vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="name" tick={{ fontSize: 9, fontWeight: 'bold' }} />
                    <YAxis tick={{ fontSize: 9 }} />
                    <Tooltip />
                    <Bar dataKey="kg" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={25} />
                  </BarChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem dados para exibição</p> }
            </div>
          </div>

          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100">
            <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest mb-6 flex items-center gap-2">Principais Paradas</h3>
            <div className="h-[240px] w-full">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="50%" innerRadius={60} outerRadius={85} paddingAngle={8} dataKey="value">
                      {downtimePieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                    </Pie>
                    <Tooltip />
                    <Legend iconType="circle" wrapperStyle={{ fontSize: '10px', fontWeight: 'bold' }} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem registros de parada</p> }
            </div>
          </div>
        </div>

        {/* History */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico de Lançamentos</h3>
            <span className="text-[10px] font-bold text-slate-400 bg-slate-200 px-2 py-0.5 rounded">{filteredData.length} registros</span>
          </div>
          <div className="divide-y divide-slate-50 max-h-[500px] overflow-y-auto custom-scrollbar">
            {filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
              <div key={entry.id} className="p-4 flex items-center justify-between hover:bg-slate-50/50 transition-colors">
                <div className="flex items-center gap-4">
                  <div className={`w-2 h-10 rounded-full ${entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600'}`}></div>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                      <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                    </div>
                    <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                  </div>
                </div>
                <div className="text-right flex items-center gap-4">
                  <div>
                    <span className="block font-black text-blue-600 text-sm">{entry.netWeight.toLocaleString('pt-BR')} kg</span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase">Líquido</span>
                  </div>
                  <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>

      <LaunchModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} operators={operators}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Menu, Plus, TrendingUp, BarChart2, Calendar, RotateCcw, Download, Clock, Zap, Trash2, Cpu, BrainCircuit, Sparkles, CheckCircle2, AlertTriangle, X, ChevronRight, Settings, Target, Users, UserPlus, Trophy, Sparkle, RefreshCw, User, Filter } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { GoogleGenAI } from "@google/genai";
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '2.6'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Franck', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const isGoalAchieved = stats.totalNet >= goalValue && goalValue > 0;

  const machineStatus = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const machineEntries = productionData.filter(e => e.machine === m);
      const sortedEntries = [...machineEntries].sort((a, b) => b.date.localeCompare(a.date));
      const lastEntry = sortedEntries[0];
      const totalDowntime = lastEntry ? (lastEntry.manutencaoMin + lastEntry.processoMin + lastEntry.outrosMin) : 0;

      let status = 'Operando';
      let color = 'emerald';

      if (!lastEntry) { status = 'Sem Dados'; color = 'slate'; }
      else if (lastEntry.manutencaoMin > 30) { status = 'Manutenção'; color = 'orange'; }
      else if (totalDowntime > 60) { status = 'Alerta'; color = 'amber'; }

      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleRemoveOperator = (name: string) => {
    if (confirm(`Remover operador ${name}?`)) {
      setOperators(prev => prev.filter(op => op !== name));
      if (selectedOperator === name) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  // Logic for the Dynamic Chart
  const mainChartData = useMemo(() => {
    if (selectedOperator === 'Todos') {
      // Show Ranking
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });
      return Object.entries(performanceMap)
        .map(([name, kg]) => ({ name, value: kg, color: '#3b82f6' }))
        .sort((a, b) => b.value - a.value);
    } else {
      // Show Operator Specific Metrics
      return [
        { name: 'Prod. Líquida', value: stats.totalNet, color: '#3b82f6', unit: 'kg' },
        { name: 'ECO A', value: stats.ecoA, color: '#10b981', unit: 'kg' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, color: '#f59e0b', unit: 'kg' },
        { name: 'Borra', value: stats.borra, color: '#ef4444', unit: 'kg' },
        { name: 'Paradas', value: stats.paradas, color: '#64748b', unit: 'min' }
      ];
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => [
    { name: 'Manutenção', value: stats.manut, color: '#f97316' },
    { name: 'Processo', value: stats.proc, color: '#f59e0b' },
    { name: 'Outros', value: stats.outros, color: '#94a3b8' }
  ].filter(d => d.value > 0), [stats]);

  const exportToCSV = () => {
    const headers = ['Data', 'Operador', 'Maquina', 'Turno', 'Peso Liquido', 'Paradas'];
    const rows = filteredData.map(e => [e.date, e.operator, e.machine, e.shift, e.netWeight, e.manutencaoMin + e.processoMin + e.outrosMin]);
    const csvContent = [headers, ...rows].map(r => r.join(';')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `relatorio_${selectedOperator}_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Sidebar Menu */}
      <div className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Global
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro
            </h3>
            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Novo nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <UserPlus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Machine Status */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatus.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex items-center gap-4">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center bg-${m.color}-100 text-${m.color}-600`}>
                {m.status === 'Operando' ? <CheckCircle2 size={20} /> : <AlertTriangle size={20} />}
              </div>
              <div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-bold text-slate-700">{m.status}</span>
                  <div className={`w-2 h-2 rounded-full bg-${m.color}-500 animate-pulse`}></div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Machine Selector */}
        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button 
                  key={m} onClick={() => setSelectedMachine(m)}
                  className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{stats.borra.toLocaleString('pt-BR')} kg</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span>
            <span className="text-xl font-black text-blue-600">{(stats.totalNet / 1000).toFixed(1)}t</span>
          </div>
        </div>

        {/* Goal Tracking */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500 shadow-emerald-100' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                 Meta {selectedOperator !== 'Todos' ? `de ${selectedOperator}` : 'Geral'}
               </span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{stats.totalNet.toLocaleString('pt-BR')}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {goalValue.toLocaleString('pt-BR')} kg</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {Math.round((stats.totalNet / goalValue) * 100)}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div 
              className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} 
              style={{ width: `${Math.min((stats.totalNet / goalValue) * 100, 100)}%` }}
            ></div>
          </div>
        </div>

        {/* Dynamic Charts Row */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100">
            <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest mb-6 flex items-center gap-2">
              {selectedOperator === 'Todos' ? 'Ranking de Produção' : `Desempenho: ${selectedOperator}`}
            </h3>
            <div className="h-[240px] w-full">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={mainChartData} layout={selectedOperator !== 'Todos' ? 'horizontal' : 'vertical'}>
                    <CartesianGrid vertical={false} stroke="#f1f5f9" strokeDasharray="3 3" />
                    <XAxis 
                      type={selectedOperator === 'Todos' ? 'number' : 'category'} 
                      dataKey={selectedOperator === 'Todos' ? undefined : 'name'}
                      tick={{ fontSize: 9, fontWeight: 'bold' }} 
                    />
                    <YAxis 
                      type={selectedOperator === 'Todos' ? 'category' : 'number'} 
                      dataKey={selectedOperator === 'Todos' ? 'name' : undefined}
                      tick={{ fontSize: 9 }} 
                    />
                    <Tooltip 
                      cursor={{fill: 'transparent'}}
                      content={({ active, payload }) => {
                        if (active && payload && payload.length) {
                          const data = payload[0].payload;
                          return (
                            <div className="bg-white p-2 border border-slate-200 shadow-lg rounded-lg">
                              <p className="text-[10px] font-black text-slate-500 uppercase">{data.name}</p>
                              <p className="text-sm font-bold text-slate-800">
                                {data.value.toLocaleString('pt-BR')} {data.unit || 'kg'}
                              </p>
                            </div>
                          );
                        }
                        return null;
                      }}
                    />
                    <Bar dataKey="value" radius={[4, 4, 0, 0]} barSize={selectedOperator === 'Todos' ? 12 : 25}>
                      {mainChartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem dados</p> }
            </div>
          </div>

          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100">
            <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest mb-6 flex items-center gap-2">Principais Paradas</h3>
            <div className="h-[240px] w-full">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="50%" innerRadius={60} outerRadius={85} paddingAngle={8} dataKey="value">
                      {downtimePieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                    </Pie>
                    <Tooltip />
                    <Legend iconType="circle" wrapperStyle={{ fontSize: '10px', fontWeight: 'bold' }} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem paradas</p> }
            </div>
          </div>
        </div>

        {/* History */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico Detalhado</h3>
            <span className="text-[10px] font-bold text-slate-400 bg-slate-200 px-2 py-0.5 rounded">{filteredData.length} registros</span>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
              <div key={entry.id} className="p-4 flex items-center justify-between hover:bg-slate-50/50">
                <div className="flex items-center gap-4">
                  <div className={`w-2 h-10 rounded-full ${entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600'}`}></div>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                      <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                    </div>
                    <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                  </div>
                </div>
                <div className="text-right flex items-center gap-4">
                  <div>
                    <span className="block font-black text-blue-600 text-sm">{entry.netWeight.toLocaleString('pt-BR')} kg</span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase">Líquido</span>
                  </div>
                  <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>

      <LaunchModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} operators={operators}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Menu, Plus, TrendingUp, BarChart2, Calendar, RotateCcw, Download, Clock, Zap, Trash2, Cpu, BrainCircuit, Sparkles, CheckCircle2, AlertTriangle, X, ChevronRight, Settings, Target, Users, UserPlus, Trophy, Sparkle, RefreshCw, User, Filter, Printer } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { GoogleGenAI } from "@google/genai";
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '2.7'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Franck', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const isGoalAchieved = stats.totalNet >= goalValue && goalValue > 0;

  const machineStatus = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const machineEntries = productionData.filter(e => e.machine === m);
      const sortedEntries = [...machineEntries].sort((a, b) => b.date.localeCompare(a.date));
      const lastEntry = sortedEntries[0];
      const totalDowntime = lastEntry ? (lastEntry.manutencaoMin + lastEntry.processoMin + lastEntry.outrosMin) : 0;

      let status = 'Operando';
      let color = 'emerald';

      if (!lastEntry) { status = 'Sem Dados'; color = 'slate'; }
      else if (lastEntry.manutencaoMin > 30) { status = 'Manutenção'; color = 'orange'; }
      else if (totalDowntime > 60) { status = 'Alerta'; color = 'amber'; }

      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleRemoveOperator = (name: string) => {
    if (confirm(`Remover operador ${name}?`)) {
      setOperators(prev => prev.filter(op => op !== name));
      if (selectedOperator === name) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const mainChartData = useMemo(() => {
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });
      return Object.entries(performanceMap)
        .map(([name, kg]) => ({ name, value: kg, color: '#3b82f6' }))
        .sort((a, b) => b.value - a.value);
    } else {
      return [
        { name: 'Prod. Líquida', value: stats.totalNet, color: '#3b82f6', unit: 'kg' },
        { name: 'ECO A', value: stats.ecoA, color: '#10b981', unit: 'kg' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, color: '#f59e0b', unit: 'kg' },
        { name: 'Borra', value: stats.borra, color: '#ef4444', unit: 'kg' },
        { name: 'Paradas', value: stats.paradas, color: '#64748b', unit: 'min' }
      ];
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => [
    { name: 'Manutenção', value: stats.manut, color: '#f97316' },
    { name: 'Processo', value: stats.proc, color: '#f59e0b' },
    { name: 'Outros', value: stats.outros, color: '#94a3b8' }
  ].filter(d => d.value > 0), [stats]);

  const exportToCSV = () => {
    const headers = ['Data', 'Operador', 'Maquina', 'Turno', 'Peso Liquido', 'Paradas'];
    const rows = filteredData.map(e => [e.date, e.operator, e.machine, e.shift, e.netWeight, e.manutencaoMin + e.processoMin + e.outrosMin]);
    const csvContent = [headers, ...rows].map(r => r.join(';')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `relatorio_${selectedOperator}_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  const printChart = (elementId: string, title: string) => {
    const chartEl = document.getElementById(elementId);
    if (!chartEl) return;

    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const html = `
      <!DOCTYPE html>
      <html>
        <head>
          <title>Exportar - ${title}</title>
          <script src="https://cdn.tailwindcss.com"></script>
          <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;700;900&display=swap" rel="stylesheet">
          <style>
            @media print { @page { margin: 1cm; } }
            body { font-family: 'Inter', sans-serif; background: white; color: #1e293b; -webkit-print-color-adjust: exact; }
            .chart-container { width: 100%; max-width: 900px; margin: 0 auto; padding: 50px; }
            .chart-header { margin-bottom: 30px; border-bottom: 3px solid #f1f5f9; padding-bottom: 20px; }
            svg { width: 100% !important; height: auto !important; max-height: 500px; }
            .recharts-legend-wrapper { position: static !important; margin-top: 20px !important; }
          </style>
        </head>
        <body>
          <div class="chart-container">
            <div class="chart-header flex justify-between items-end">
              <div>
                <h1 class="text-3xl font-black uppercase tracking-tighter text-blue-600">Relatório de Desempenho</h1>
                <h2 class="text-xl font-bold text-slate-700 mt-1">${title}</h2>
              </div>
              <div class="text-right">
                <p class="text-[10px] font-black text-slate-400 uppercase tracking-widest">Data de Emissão</p>
                <p class="text-sm font-bold text-slate-600">${new Date().toLocaleString('pt-BR')}</p>
              </div>
            </div>
            <div class="chart-content bg-slate-50 p-10 rounded-3xl border border-slate-100 flex justify-center">
              ${chartEl.innerHTML}
            </div>
            <div class="mt-12 grid grid-cols-2 gap-8">
              <div class="p-4 border-l-4 border-blue-500 bg-blue-50/50 rounded-r-xl">
                <p class="text-[9px] font-black text-blue-600 uppercase">Filtro de Máquina</p>
                <p class="text-sm font-bold text-slate-700">${selectedMachine}</p>
              </div>
              <div class="p-4 border-l-4 border-indigo-500 bg-indigo-50/50 rounded-r-xl">
                <p class="text-[9px] font-black text-indigo-600 uppercase">Filtro de Operador</p>
                <p class="text-sm font-bold text-slate-700">${selectedOperator}</p>
              </div>
            </div>
            <div class="mt-20 pt-6 border-t border-slate-100 text-[10px] font-black text-slate-300 uppercase tracking-widest flex justify-between">
              <span>Manupackaging Pro - Unidade Cast</span>
              <span>Doc Ref: MP-${Math.random().toString(36).substr(2, 6).toUpperCase()}</span>
            </div>
          </div>
          <script>
            window.onload = () => {
              setTimeout(() => {
                window.print();
                window.close();
              }, 1000);
            };
          </script>
        </body>
      </html>
    `;

    printWindow.document.write(html);
    printWindow.document.close();
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Sidebar Menu */}
      <div className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Global
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro
            </h3>
            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Novo nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <UserPlus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Machine Status */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatus.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex items-center gap-4">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center bg-${m.color}-100 text-${m.color}-600`}>
                {m.status === 'Operando' ? <CheckCircle2 size={20} /> : <AlertTriangle size={20} />}
              </div>
              <div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-bold text-slate-700">{m.status}</span>
                  <div className={`w-2 h-2 rounded-full bg-${m.color}-500 animate-pulse`}></div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Machine Selector */}
        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button 
                  key={m} onClick={() => setSelectedMachine(m)}
                  className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{stats.borra.toLocaleString('pt-BR')} kg</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span>
            <span className="text-xl font-black text-blue-600">{(stats.totalNet / 1000).toFixed(1)}t</span>
          </div>
        </div>

        {/* Goal Tracking */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500 shadow-emerald-100' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                 Meta {selectedOperator !== 'Todos' ? `de ${selectedOperator}` : 'Geral'}
               </span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{stats.totalNet.toLocaleString('pt-BR')}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {goalValue.toLocaleString('pt-BR')} kg</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {Math.round((stats.totalNet / goalValue) * 100)}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div 
              className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} 
              style={{ width: `${Math.min((stats.totalNet / goalValue) * 100, 100)}%` }}
            ></div>
          </div>
        </div>

        {/* Dynamic Charts Row */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group">
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">
                {selectedOperator === 'Todos' ? 'Ranking de Produção' : `Desempenho: ${selectedOperator}`}
              </h3>
              <button 
                onClick={() => printChart('main-chart-container', selectedOperator === 'Todos' ? 'Ranking Geral de Produção' : `Perfil de Desempenho: ${selectedOperator}`)}
                className="p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                title="Imprimir / Salvar PDF"
              >
                <Printer size={16} />
              </button>
            </div>
            <div className="h-[240px] w-full" id="main-chart-container">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={mainChartData} layout={selectedOperator === 'Todos' ? 'horizontal' : 'horizontal'}>
                    <CartesianGrid vertical={false} stroke="#f1f5f9" strokeDasharray="3 3" />
                    <XAxis 
                      type="category" 
                      dataKey="name"
                      tick={{ fontSize: 9, fontWeight: 'bold' }} 
                    />
                    <YAxis 
                      type="number" 
                      tick={{ fontSize: 9 }} 
                    />
                    <Tooltip 
                      cursor={{fill: 'transparent'}}
                      content={({ active, payload }) => {
                        if (active && payload && payload.length) {
                          const data = payload[0].payload;
                          return (
                            <div className="bg-white p-2 border border-slate-200 shadow-lg rounded-lg">
                              <p className="text-[10px] font-black text-slate-500 uppercase">{data.name}</p>
                              <p className="text-sm font-bold text-slate-800">
                                {data.value.toLocaleString('pt-BR')} {data.unit || 'kg'}
                              </p>
                            </div>
                          );
                        }
                        return null;
                      }}
                    />
                    <Bar dataKey="value" radius={[4, 4, 0, 0]} barSize={25}>
                      {mainChartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem dados</p> }
            </div>
          </div>

          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group">
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">Principais Paradas</h3>
              <button 
                onClick={() => printChart('downtime-pie-container', 'Distribuição de Motivos de Parada')}
                className="p-2 text-slate-300 hover:text-orange-600 hover:bg-orange-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                title="Imprimir / Salvar PDF"
              >
                <Printer size={16} />
              </button>
            </div>
            <div className="h-[240px] w-full" id="downtime-pie-container">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="50%" innerRadius={60} outerRadius={85} paddingAngle={8} dataKey="value">
                      {downtimePieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                    </Pie>
                    <Tooltip />
                    <Legend iconType="circle" wrapperStyle={{ fontSize: '10px', fontWeight: 'bold' }} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem paradas</p> }
            </div>
          </div>
        </div>

        {/* History */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico Detalhado</h3>
            <span className="text-[10px] font-bold text-slate-400 bg-slate-200 px-2 py-0.5 rounded">{filteredData.length} registros</span>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
              <div key={entry.id} className="p-4 flex items-center justify-between hover:bg-slate-50/50">
                <div className="flex items-center gap-4">
                  <div className={`w-2 h-10 rounded-full ${entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600'}`}></div>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                      <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                    </div>
                    <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                  </div>
                </div>
                <div className="text-right flex items-center gap-4">
                  <div>
                    <span className="block font-black text-blue-600 text-sm">{entry.netWeight.toLocaleString('pt-BR')} kg</span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase">Líquido</span>
                  </div>
                  <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>

      <LaunchModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} operators={operators}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Menu, Plus, TrendingUp, BarChart2, Calendar, RotateCcw, Download, Clock, Zap, Trash2, Cpu, BrainCircuit, Sparkles, CheckCircle2, AlertTriangle, X, ChevronRight, Settings, Target, Users, UserPlus, Trophy, Sparkle, RefreshCw, User, Filter, FileDown } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { GoogleGenAI } from "@google/genai";
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '2.8'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Franck', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const isGoalAchieved = stats.totalNet >= goalValue && goalValue > 0;

  const machineStatus = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const machineEntries = productionData.filter(e => e.machine === m);
      const sortedEntries = [...machineEntries].sort((a, b) => b.date.localeCompare(a.date));
      const lastEntry = sortedEntries[0];
      const totalDowntime = lastEntry ? (lastEntry.manutencaoMin + lastEntry.processoMin + lastEntry.outrosMin) : 0;

      let status = 'Operando';
      let color = 'emerald';

      if (!lastEntry) { status = 'Sem Dados'; color = 'slate'; }
      else if (lastEntry.manutencaoMin > 30) { status = 'Manutenção'; color = 'orange'; }
      else if (totalDowntime > 60) { status = 'Alerta'; color = 'amber'; }

      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleRemoveOperator = (name: string) => {
    if (confirm(`Remover operador ${name}?`)) {
      setOperators(prev => prev.filter(op => op !== name));
      if (selectedOperator === name) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const mainChartData = useMemo(() => {
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });
      return Object.entries(performanceMap)
        .map(([name, kg]) => ({ name, value: kg, color: '#3b82f6' }))
        .sort((a, b) => b.value - a.value);
    } else {
      return [
        { name: 'Prod. Líquida', value: stats.totalNet, color: '#3b82f6', unit: 'kg' },
        { name: 'ECO A', value: stats.ecoA, color: '#10b981', unit: 'kg' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, color: '#f59e0b', unit: 'kg' },
        { name: 'Borra', value: stats.borra, color: '#ef4444', unit: 'kg' },
        { name: 'Paradas', value: stats.paradas, color: '#64748b', unit: 'min' }
      ];
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => [
    { name: 'Manutenção', value: stats.manut, color: '#f97316' },
    { name: 'Processo', value: stats.proc, color: '#f59e0b' },
    { name: 'Outros', value: stats.outros, color: '#94a3b8' }
  ].filter(d => d.value > 0), [stats]);

  const exportToCSV = () => {
    const headers = ['Data', 'Operador', 'Maquina', 'Turno', 'Peso Liquido', 'Paradas'];
    const rows = filteredData.map(e => [e.date, e.operator, e.machine, e.shift, e.netWeight, e.manutencaoMin + e.processoMin + e.outrosMin]);
    const csvContent = [headers, ...rows].map(r => r.join(';')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `relatorio_${selectedOperator}_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  const exportChartAsPDF = (elementId: string, title: string) => {
    const chartEl = document.getElementById(elementId);
    if (!chartEl) return;

    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const html = `
      <!DOCTYPE html>
      <html>
        <head>
          <title>PDF - ${title}</title>
          <script src="https://cdn.tailwindcss.com"></script>
          <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;700;900&display=swap" rel="stylesheet">
          <style>
            @media print { @page { margin: 1cm; } }
            body { font-family: 'Inter', sans-serif; background: white; color: #1e293b; -webkit-print-color-adjust: exact; }
            .chart-container { width: 100%; max-width: 900px; margin: 0 auto; padding: 50px; }
            .chart-header { margin-bottom: 30px; border-bottom: 3px solid #f1f5f9; padding-bottom: 20px; }
            svg { width: 100% !important; height: auto !important; max-height: 500px; }
          </style>
        </head>
        <body>
          <div class="chart-container">
            <div class="chart-header flex justify-between items-end">
              <div>
                <h1 class="text-3xl font-black uppercase tracking-tighter text-blue-600">Exportação de Gráfico</h1>
                <h2 class="text-xl font-bold text-slate-700 mt-1">${title}</h2>
              </div>
              <div class="text-right">
                <p class="text-[10px] font-black text-slate-400 uppercase tracking-widest">Data de Exportação</p>
                <p class="text-sm font-bold text-slate-600">${new Date().toLocaleString('pt-BR')}</p>
              </div>
            </div>
            <div class="chart-content bg-slate-50 p-10 rounded-3xl border border-slate-100 flex justify-center">
              ${chartEl.innerHTML}
            </div>
            <div class="mt-20 pt-6 border-t border-slate-100 text-[10px] font-black text-slate-300 uppercase tracking-widest flex justify-between">
              <span>Manupackaging Pro - Relatório Digital</span>
            </div>
          </div>
          <script>
            window.onload = () => {
              setTimeout(() => {
                window.print();
                window.close();
              }, 800);
            };
          </script>
        </body>
      </html>
    `;

    printWindow.document.write(html);
    printWindow.document.close();
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Sidebar Menu */}
      <div className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Global
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro
            </h3>
            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Novo nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <UserPlus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Machine Status */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatus.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex items-center gap-4">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center bg-${m.color}-100 text-${m.color}-600`}>
                {m.status === 'Operando' ? <CheckCircle2 size={20} /> : <AlertTriangle size={20} />}
              </div>
              <div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-bold text-slate-700">{m.status}</span>
                  <div className={`w-2 h-2 rounded-full bg-${m.color}-500 animate-pulse`}></div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Machine Selector */}
        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button 
                  key={m} onClick={() => setSelectedMachine(m)}
                  className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{stats.borra.toLocaleString('pt-BR')} kg</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span>
            <span className="text-xl font-black text-blue-600">{(stats.totalNet / 1000).toFixed(1)}t</span>
          </div>
        </div>

        {/* Goal Tracking */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500 shadow-emerald-100' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                 Meta {selectedOperator !== 'Todos' ? `de ${selectedOperator}` : 'Geral'}
               </span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{stats.totalNet.toLocaleString('pt-BR')}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {goalValue.toLocaleString('pt-BR')} kg</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {Math.round((stats.totalNet / goalValue) * 100)}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div 
              className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} 
              style={{ width: `${Math.min((stats.totalNet / goalValue) * 100, 100)}%` }}
            ></div>
          </div>
        </div>

        {/* Dynamic Charts Row */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group">
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">
                {selectedOperator === 'Todos' ? 'Ranking de Produção' : `Desempenho: ${selectedOperator}`}
              </h3>
              <button 
                onClick={() => exportChartAsPDF('main-chart-container', selectedOperator === 'Todos' ? 'Ranking Geral de Produção' : `Perfil de Desempenho: ${selectedOperator}`)}
                className="p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all opacity-0 group-hover:opacity-100 flex items-center gap-1"
                title="Salvar PDF"
              >
                <FileDown size={16} />
                <span className="text-[10px] font-bold">SALVAR</span>
              </button>
            </div>
            <div className="h-[240px] w-full" id="main-chart-container">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={mainChartData} layout="horizontal">
                    <CartesianGrid vertical={false} stroke="#f1f5f9" strokeDasharray="3 3" />
                    <XAxis 
                      type="category" 
                      dataKey="name"
                      tick={{ fontSize: 9, fontWeight: 'bold' }} 
                    />
                    <YAxis 
                      type="number" 
                      tick={{ fontSize: 9 }} 
                    />
                    <Tooltip 
                      cursor={{fill: 'transparent'}}
                      content={({ active, payload }) => {
                        if (active && payload && payload.length) {
                          const data = payload[0].payload;
                          return (
                            <div className="bg-white p-2 border border-slate-200 shadow-lg rounded-lg">
                              <p className="text-[10px] font-black text-slate-500 uppercase">{data.name}</p>
                              <p className="text-sm font-bold text-slate-800">
                                {data.value.toLocaleString('pt-BR')} {data.unit || 'kg'}
                              </p>
                            </div>
                          );
                        }
                        return null;
                      }}
                    />
                    <Bar dataKey="value" radius={[4, 4, 0, 0]} barSize={25}>
                      {mainChartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem dados</p> }
            </div>
          </div>

          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group">
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">Principais Paradas</h3>
              <button 
                onClick={() => exportChartAsPDF('downtime-pie-container', 'Distribuição de Motivos de Parada')}
                className="p-2 text-slate-300 hover:text-orange-600 hover:bg-orange-50 rounded-lg transition-all opacity-0 group-hover:opacity-100 flex items-center gap-1"
                title="Salvar PDF"
              >
                <FileDown size={16} />
                <span className="text-[10px] font-bold">SALVAR</span>
              </button>
            </div>
            <div className="h-[240px] w-full" id="downtime-pie-container">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="50%" innerRadius={60} outerRadius={85} paddingAngle={8} dataKey="value">
                      {downtimePieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                    </Pie>
                    <Tooltip />
                    <Legend iconType="circle" wrapperStyle={{ fontSize: '10px', fontWeight: 'bold' }} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem paradas</p> }
            </div>
          </div>
        </div>

        {/* History */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico Detalhado</h3>
            <span className="text-[10px] font-bold text-slate-400 bg-slate-200 px-2 py-0.5 rounded">{filteredData.length} registros</span>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
              <div key={entry.id} className="p-4 flex items-center justify-between hover:bg-slate-50/50">
                <div className="flex items-center gap-4">
                  <div className={`w-2 h-10 rounded-full ${entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600'}`}></div>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                      <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                    </div>
                    <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                  </div>
                </div>
                <div className="text-right flex items-center gap-4">
                  <div>
                    <span className="block font-black text-blue-600 text-sm">{entry.netWeight.toLocaleString('pt-BR')} kg</span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase">Líquido</span>
                  </div>
                  <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>

      <LaunchModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} operators={operators}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Menu, Plus, TrendingUp, BarChart2, Calendar, RotateCcw, Download, Clock, Zap, Trash2, Cpu, BrainCircuit, Sparkles, CheckCircle2, AlertTriangle, X, ChevronRight, Settings, Target, Users, UserPlus, Trophy, Sparkle, RefreshCw, User, Filter, Image as ImageIcon } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '3.0'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Franck', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const isGoalAchieved = stats.totalNet >= goalValue && goalValue > 0;

  const machineStatus = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const machineEntries = productionData.filter(e => e.machine === m);
      const sortedEntries = [...machineEntries].sort((a, b) => b.date.localeCompare(a.date));
      const lastEntry = sortedEntries[0];
      const totalDowntime = lastEntry ? (lastEntry.manutencaoMin + lastEntry.processoMin + lastEntry.outrosMin) : 0;

      let status = 'Operando';
      let color = 'emerald';

      if (!lastEntry) { status = 'Sem Dados'; color = 'slate'; }
      else if (lastEntry.manutencaoMin > 30) { status = 'Manutenção'; color = 'orange'; }
      else if (totalDowntime > 60) { status = 'Alerta'; color = 'amber'; }

      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const mainChartData = useMemo(() => {
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });
      return Object.entries(performanceMap)
        .map(([name, kg]) => ({ name, value: kg, color: '#3b82f6' }))
        .sort((a, b) => b.value - a.value);
    } else {
      return [
        { name: 'Prod. Líquida', value: stats.totalNet, color: '#3b82f6', unit: 'kg' },
        { name: 'ECO A', value: stats.ecoA, color: '#10b981', unit: 'kg' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, color: '#f59e0b', unit: 'kg' },
        { name: 'Borra', value: stats.borra, color: '#ef4444', unit: 'kg' },
        { name: 'Paradas', value: stats.paradas, color: '#64748b', unit: 'min' }
      ];
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => [
    { name: 'Manutenção', value: stats.manut, color: '#f97316' },
    { name: 'Processo', value: stats.proc, color: '#f59e0b' },
    { name: 'Outros', value: stats.outros, color: '#94a3b8' }
  ].filter(d => d.value > 0), [stats]);

  const exportToCSV = () => {
    const headers = ['Data', 'Operador', 'Maquina', 'Turno', 'Peso Liquido', 'Paradas'];
    const rows = filteredData.map(e => [e.date, e.operator, e.machine, e.shift, e.netWeight, e.manutencaoMin + e.processoMin + e.outrosMin]);
    const csvContent = [headers, ...rows].map(r => r.join(';')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `relatorio_${selectedOperator}_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  const exportChartAsImage = async (elementId: string, title: string) => {
    const chartContainer = document.getElementById(elementId);
    if (!chartContainer) return;

    const svg = chartContainer.querySelector('svg');
    if (!svg) return;

    // A4 resolution at 300 DPI
    const A4_WIDTH = 2480;
    const A4_HEIGHT = 3508;
    const PADDING = 150;

    const canvas = document.createElement('canvas');
    canvas.width = A4_WIDTH;
    canvas.height = A4_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Background
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, A4_WIDTH, A4_HEIGHT);

    // Header
    ctx.fillStyle = '#2563EB'; // blue-600
    ctx.font = '900 120px Inter, sans-serif';
    ctx.fillText('Manupackaging Pro', PADDING, 250);

    ctx.fillStyle = '#475569'; // slate-600
    ctx.font = 'bold 80px Inter, sans-serif';
    ctx.fillText(title, PADDING, 400);

    // Divider
    ctx.strokeStyle = '#F1F5F9';
    ctx.lineWidth = 10;
    ctx.beginPath();
    ctx.moveTo(PADDING, 480);
    ctx.lineTo(A4_WIDTH - PADDING, 480);
    ctx.stroke();

    // Stats info
    ctx.fillStyle = '#94A3B8';
    ctx.font = 'bold 50px Inter, sans-serif';
    ctx.fillText(`Emitido em: ${new Date().toLocaleString('pt-BR')}`, PADDING, 580);
    ctx.fillText(`Filtros: Operador: ${selectedOperator} | Máquina: ${selectedMachine}`, PADDING, 650);

    // Convert SVG to Image
    const svgData = new XMLSerializer().serializeToString(svg);
    const svgBlob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(svgBlob);

    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = url;

    await new Promise((resolve) => {
      img.onload = () => {
        const availableWidth = A4_WIDTH - (PADDING * 2);
        const scale = availableWidth / img.width;
        const drawWidth = availableWidth;
        const drawHeight = img.height * scale;

        ctx.drawImage(img, PADDING, 800, drawWidth, drawHeight);

        // Footer
        ctx.fillStyle = '#CBD5E1';
        ctx.font = 'bold 40px Inter, sans-serif';
        ctx.fillText('DOCUMENTO DIGITAL DE CONTROLE DE PRODUÇÃO - UNIDADE CAST', PADDING, A4_HEIGHT - 200);

        // Download PNG
        const pngUrl = canvas.toDataURL('image/png', 1.0);
        const downloadLink = document.createElement('a');
        downloadLink.href = pngUrl;
        downloadLink.download = `Relatorio_${title.replace(/\s+/g, '_')}_${new Date().getTime()}.png`;
        downloadLink.click();

        URL.revokeObjectURL(url);
        resolve(null);
      };
    });
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Sidebar Menu */}
      <div className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Global
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro
            </h3>
            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Novo nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <UserPlus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Machine Status */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatus.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex items-center gap-4">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center bg-${m.color}-100 text-${m.color}-600`}>
                {m.status === 'Operando' ? <CheckCircle2 size={20} /> : <AlertTriangle size={20} />}
              </div>
              <div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-bold text-slate-700">{m.status}</span>
                  <div className={`w-2 h-2 rounded-full bg-${m.color}-500 animate-pulse`}></div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Machine Selector */}
        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button 
                  key={m} onClick={() => setSelectedMachine(m)}
                  className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{stats.borra.toLocaleString('pt-BR')} kg</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span>
            <span className="text-xl font-black text-blue-600">{(stats.totalNet / 1000).toFixed(1)}t</span>
          </div>
        </div>

        {/* Goal Tracking */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500 shadow-emerald-100' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                 Meta {selectedOperator !== 'Todos' ? `de ${selectedOperator}` : 'Geral'}
               </span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{stats.totalNet.toLocaleString('pt-BR')}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {goalValue.toLocaleString('pt-BR')} kg</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {Math.round((stats.totalNet / goalValue) * 100)}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div 
              className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} 
              style={{ width: `${Math.min((stats.totalNet / goalValue) * 100, 100)}%` }}
            ></div>
          </div>
        </div>

        {/* Dynamic Charts Row */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group">
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">
                {selectedOperator === 'Todos' ? 'Ranking de Produção' : `Desempenho: ${selectedOperator}`}
              </h3>
              <button 
                onClick={() => exportChartAsImage('main-chart-container', selectedOperator === 'Todos' ? 'Ranking Geral de Produção' : `Perfil de Desempenho: ${selectedOperator}`)}
                className="p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all opacity-0 group-hover:opacity-100 flex items-center gap-1"
                title="Salvar Imagem A4"
              >
                <ImageIcon size={16} />
                <span className="text-[10px] font-bold">SALVAR A4</span>
              </button>
            </div>
            <div className="h-[240px] w-full" id="main-chart-container">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={mainChartData} layout="horizontal">
                    <CartesianGrid vertical={false} stroke="#f1f5f9" strokeDasharray="3 3" />
                    <XAxis 
                      type="category" 
                      dataKey="name"
                      tick={{ fontSize: 9, fontWeight: 'bold' }} 
                    />
                    <YAxis 
                      type="number" 
                      tick={{ fontSize: 9 }} 
                    />
                    <Tooltip 
                      cursor={{fill: 'transparent'}}
                      content={({ active, payload }) => {
                        if (active && payload && payload.length) {
                          const data = payload[0].payload;
                          return (
                            <div className="bg-white p-2 border border-slate-200 shadow-lg rounded-lg">
                              <p className="text-[10px] font-black text-slate-500 uppercase">{data.name}</p>
                              <p className="text-sm font-bold text-slate-800">
                                {data.value.toLocaleString('pt-BR')} {data.unit || 'kg'}
                              </p>
                            </div>
                          );
                        }
                        return null;
                      }}
                    />
                    <Bar dataKey="value" radius={[4, 4, 0, 0]} barSize={25}>
                      {mainChartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem dados</p> }
            </div>
          </div>

          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group">
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">Principais Paradas</h3>
              <button 
                onClick={() => exportChartAsImage('downtime-pie-container', 'Distribuição de Motivos de Parada')}
                className="p-2 text-slate-300 hover:text-orange-600 hover:bg-orange-50 rounded-lg transition-all opacity-0 group-hover:opacity-100 flex items-center gap-1"
                title="Salvar Imagem A4"
              >
                <ImageIcon size={16} />
                <span className="text-[10px] font-bold">SALVAR A4</span>
              </button>
            </div>
            <div className="h-[240px] w-full" id="downtime-pie-container">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="50%" innerRadius={60} outerRadius={85} paddingAngle={8} dataKey="value">
                      {downtimePieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                    </Pie>
                    <Tooltip />
                    <Legend iconType="circle" wrapperStyle={{ fontSize: '10px', fontWeight: 'bold' }} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem paradas</p> }
            </div>
          </div>
        </div>

        {/* History */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico Detalhado</h3>
            <span className="text-[10px] font-bold text-slate-400 bg-slate-200 px-2 py-0.5 rounded">{filteredData.length} registros</span>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
              <div key={entry.id} className="p-4 flex items-center justify-between hover:bg-slate-50/50">
                <div className="flex items-center gap-4">
                  <div className={`w-2 h-10 rounded-full ${entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600'}`}></div>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                      <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                    </div>
                    <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                  </div>
                </div>
                <div className="text-right flex items-center gap-4">
                  <div>
                    <span className="block font-black text-blue-600 text-sm">{entry.netWeight.toLocaleString('pt-BR')} kg</span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase">Líquido</span>
                  </div>
                  <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>

      <LaunchModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} operators={operators}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Menu, Plus, TrendingUp, BarChart2, Calendar, RotateCcw, Download, Clock, Zap, Trash2, Cpu, BrainCircuit, Sparkles, CheckCircle2, AlertTriangle, X, ChevronRight, Settings, Target, Users, UserPlus, Trophy, Sparkle, RefreshCw, User, Filter, Image as ImageIcon, Info } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '3.1'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Franck', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outskirts: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const isGoalAchieved = stats.totalNet >= goalValue && goalValue > 0;

  const machineStatus = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const machineEntries = productionData.filter(e => e.machine === m);
      const sortedEntries = [...machineEntries].sort((a, b) => b.date.localeCompare(a.date));
      const lastEntry = sortedEntries[0];
      const totalDowntime = lastEntry ? (lastEntry.manutencaoMin + lastEntry.processoMin + lastEntry.outrosMin) : 0;

      let status = 'Operando';
      let color = 'emerald';

      if (!lastEntry) { status = 'Sem Dados'; color = 'slate'; }
      else if (lastEntry.manutencaoMin > 30) { status = 'Manutenção'; color = 'orange'; }
      else if (totalDowntime > 60) { status = 'Alerta'; color = 'amber'; }

      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316', '#64748b'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });
      return Object.entries(performanceMap)
        .map(([name, kg], index) => ({ 
          name, 
          value: kg, 
          color: colors[index % colors.length],
          unit: 'kg'
        }))
        .sort((a, b) => b.value - a.value);
    } else {
      return [
        { name: 'Prod. Líquida', value: stats.totalNet, color: '#3b82f6', unit: 'kg' },
        { name: 'ECO A', value: stats.ecoA, color: '#10b981', unit: 'kg' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, color: '#f59e0b', unit: 'kg' },
        { name: 'Borra', value: stats.borra, color: '#ef4444', unit: 'kg' }
      ].filter(d => d.value > 0);
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => [
    { name: 'Manutenção', value: stats.manut, color: '#f97316' },
    { name: 'Processo', value: stats.proc, color: '#f59e0b' },
    { name: 'Outros', value: stats.outros, color: '#94a3b8' }
  ].filter(d => d.value > 0), [stats]);

  const exportToCSV = () => {
    const headers = ['Data', 'Operador', 'Maquina', 'Turno', 'Peso Liquido', 'Paradas'];
    const rows = filteredData.map(e => [e.date, e.operator, e.machine, e.shift, e.netWeight, e.manutencaoMin + e.processoMin + e.outrosMin]);
    const csvContent = [headers, ...rows].map(r => r.join(';')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `relatorio_${selectedOperator}_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  const exportChartAsImage = async (elementId: string, title: string) => {
    const chartContainer = document.getElementById(elementId);
    if (!chartContainer) return;

    const svg = chartContainer.querySelector('svg');
    if (!svg) return;

    const A4_WIDTH = 2480;
    const A4_HEIGHT = 3508;
    const PADDING = 150;

    const canvas = document.createElement('canvas');
    canvas.width = A4_WIDTH;
    canvas.height = A4_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, A4_WIDTH, A4_HEIGHT);

    ctx.fillStyle = '#2563EB';
    ctx.font = '900 120px Inter, sans-serif';
    ctx.fillText('Manupackaging Pro', PADDING, 250);

    ctx.fillStyle = '#475569';
    ctx.font = 'bold 80px Inter, sans-serif';
    ctx.fillText(title, PADDING, 400);

    ctx.strokeStyle = '#F1F5F9';
    ctx.lineWidth = 10;
    ctx.beginPath();
    ctx.moveTo(PADDING, 480);
    ctx.lineTo(A4_WIDTH - PADDING, 480);
    ctx.stroke();

    ctx.fillStyle = '#94A3B8';
    ctx.font = 'bold 50px Inter, sans-serif';
    ctx.fillText(`Emitido em: ${new Date().toLocaleString('pt-BR')}`, PADDING, 580);
    ctx.fillText(`Filtros: Operador: ${selectedOperator} | Máquina: ${selectedMachine}`, PADDING, 650);

    const svgData = new XMLSerializer().serializeToString(svg);
    const svgBlob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(svgBlob);

    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = url;

    await new Promise((resolve) => {
      img.onload = () => {
        const availableWidth = A4_WIDTH - (PADDING * 2);
        const scale = availableWidth / img.width;
        const drawWidth = availableWidth;
        const drawHeight = img.height * scale;

        ctx.drawImage(img, PADDING, 800, drawWidth, drawHeight);

        ctx.fillStyle = '#CBD5E1';
        ctx.font = 'bold 40px Inter, sans-serif';
        ctx.fillText('DOCUMENTO DIGITAL DE CONTROLE DE PRODUÇÃO - UNIDADE CAST', PADDING, A4_HEIGHT - 200);

        const pngUrl = canvas.toDataURL('image/png', 1.0);
        const downloadLink = document.createElement('a');
        downloadLink.href = pngUrl;
        downloadLink.download = `Relatorio_${title.replace(/\s+/g, '_')}_${new Date().getTime()}.png`;
        downloadLink.click();

        URL.revokeObjectURL(url);
        resolve(null);
      };
    });
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Sidebar Menu */}
      <div className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Global
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro
            </h3>
            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Novo nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <UserPlus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Machine Status */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatus.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex items-center gap-4">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center bg-${m.color}-100 text-${m.color}-600`}>
                {m.status === 'Operando' ? <CheckCircle2 size={20} /> : <AlertTriangle size={20} />}
              </div>
              <div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-bold text-slate-700">{m.status}</span>
                  <div className={`w-2 h-2 rounded-full bg-${m.color}-500 animate-pulse`}></div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Machine Selector */}
        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button 
                  key={m} onClick={() => setSelectedMachine(m)}
                  className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{stats.borra.toLocaleString('pt-BR')} kg</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span>
            <span className="text-xl font-black text-blue-600">{(stats.totalNet / 1000).toFixed(1)}t</span>
          </div>
        </div>

        {/* Goal Tracking */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500 shadow-emerald-100' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                 Meta {selectedOperator !== 'Todos' ? `de ${selectedOperator}` : 'Geral'}
               </span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{stats.totalNet.toLocaleString('pt-BR')}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {goalValue.toLocaleString('pt-BR')} kg</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {Math.round((stats.totalNet / goalValue) * 100)}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div 
              className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} 
              style={{ width: `${Math.min((stats.totalNet / goalValue) * 100, 100)}%` }}
            ></div>
          </div>
        </div>

        {/* Dynamic Charts Row */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group flex flex-col">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">
                {selectedOperator === 'Todos' ? 'Distribuição de Produção' : `Composição: ${selectedOperator}`}
              </h3>
              <button 
                onClick={() => exportChartAsImage('main-chart-container', selectedOperator === 'Todos' ? 'Ranking Geral de Produção' : `Perfil de Desempenho: ${selectedOperator}`)}
                className="p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all opacity-0 group-hover:opacity-100 flex items-center gap-1"
                title="Salvar Imagem A4"
              >
                <ImageIcon size={16} />
                <span className="text-[10px] font-bold">SALVAR A4</span>
              </button>
            </div>

            <div className="mb-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl border border-blue-100">
              <Info size={14} className="text-blue-500 mt-0.5 shrink-0" />
              <p className="text-[10px] text-slate-500 font-medium leading-relaxed italic">
                {selectedOperator === 'Todos' 
                  ? "Este gráfico exibe a participação de cada operador no volume total produzido. As fatias representam o peso líquido acumulado."
                  : "Detalhamento da produção individual, segregando o peso líquido, refugo (borra) e materiais reciclados gerados."
                }
              </p>
            </div>

            <div className="h-[300px] w-full" id="main-chart-container">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={mainChartData} 
                      cx="50%" 
                      cy="50%" 
                      innerRadius={55} 
                      outerRadius={85} 
                      paddingAngle={4} 
                      dataKey="value"
                    >
                      {mainChartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                      ))}
                    </Pie>
                    <Tooltip 
                      content={({ active, payload }) => {
                        if (active && payload && payload.length) {
                          const data = payload[0].payload;
                          const total = mainChartData.reduce((a, b) => a + b.value, 0);
                          const percentage = ((data.value / total) * 100).toFixed(1);
                          return (
                            <div className="bg-white p-3 border border-slate-200 shadow-xl rounded-xl">
                              <p className="text-[10px] font-black text-slate-400 uppercase mb-1">{data.name}</p>
                              <div className="flex items-baseline gap-2">
                                <span className="text-sm font-black text-slate-800">{data.value.toLocaleString('pt-BR')} {data.unit}</span>
                                <span className="text-[10px] font-bold text-blue-500">{percentage}%</span>
                              </div>
                            </div>
                          );
                        }
                        return null;
                      }}
                    />
                    <Legend 
                      verticalAlign="bottom" 
                      align="center"
                      iconType="circle"
                      wrapperStyle={{ paddingTop: '20px', fontSize: '10px', fontWeight: '800', textTransform: 'uppercase', letterSpacing: '0.05em' }}
                    />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem dados</p> }
            </div>
          </div>

          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group flex flex-col">
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">Principais Paradas</h3>
              <button 
                onClick={() => exportChartAsImage('downtime-pie-container', 'Distribuição de Motivos de Parada')}
                className="p-2 text-slate-300 hover:text-orange-600 hover:bg-orange-50 rounded-lg transition-all opacity-0 group-hover:opacity-100 flex items-center gap-1"
                title="Salvar Imagem A4"
              >
                <ImageIcon size={16} />
                <span className="text-[10px] font-bold">SALVAR A4</span>
              </button>
            </div>
            <div className="h-[300px] w-full" id="downtime-pie-container">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="50%" innerRadius={60} outerRadius={85} paddingAngle={8} dataKey="value">
                      {downtimePieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend iconType="circle" wrapperStyle={{ fontSize: '10px', fontWeight: 'bold' }} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem paradas</p> }
            </div>
          </div>
        </div>

        {/* History */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico Detalhado</h3>
            <span className="text-[10px] font-bold text-slate-400 bg-slate-200 px-2 py-0.5 rounded">{filteredData.length} registros</span>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
              <div key={entry.id} className="p-4 flex items-center justify-between hover:bg-slate-50/50">
                <div className="flex items-center gap-4">
                  <div className={`w-2 h-10 rounded-full ${entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600'}`}></div>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                      <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                    </div>
                    <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                  </div>
                </div>
                <div className="text-right flex items-center gap-4">
                  <div>
                    <span className="block font-black text-blue-600 text-sm">{entry.netWeight.toLocaleString('pt-BR')} kg</span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase">Líquido</span>
                  </div>
                  <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>

      <LaunchModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} operators={operators}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Menu, Plus, TrendingUp, BarChart2, Calendar, RotateCcw, Download, Clock, Zap, Trash2, Cpu, BrainCircuit, Sparkles, CheckCircle2, AlertTriangle, X, ChevronRight, Settings, Target, Users, UserPlus, Trophy, Sparkle, RefreshCw, User, Filter, Image as ImageIcon, Info } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '3.1'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Franck', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const isGoalAchieved = stats.totalNet >= goalValue && goalValue > 0;

  const machineStatus = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const machineEntries = productionData.filter(e => e.machine === m);
      const sortedEntries = [...machineEntries].sort((a, b) => b.date.localeCompare(a.date));
      const lastEntry = sortedEntries[0];
      const totalDowntime = lastEntry ? (lastEntry.manutencaoMin + lastEntry.processoMin + lastEntry.outrosMin) : 0;

      let status = 'Operando';
      let color = 'emerald';

      if (!lastEntry) { status = 'Sem Dados'; color = 'slate'; }
      else if (lastEntry.manutencaoMin > 30) { status = 'Manutenção'; color = 'orange'; }
      else if (totalDowntime > 60) { status = 'Alerta'; color = 'amber'; }

      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316', '#64748b'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });
      return Object.entries(performanceMap)
        .map(([name, kg], index) => ({ 
          name, 
          value: kg, 
          color: colors[index % colors.length],
          unit: 'kg'
        }))
        .sort((a, b) => b.value - a.value);
    } else {
      return [
        { name: 'Prod. Líquida', value: stats.totalNet, color: '#3b82f6', unit: 'kg' },
        { name: 'ECO A', value: stats.ecoA, color: '#10b981', unit: 'kg' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, color: '#f59e0b', unit: 'kg' },
        { name: 'Borra', value: stats.borra, color: '#ef4444', unit: 'kg' }
      ].filter(d => d.value > 0);
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => [
    { name: 'Manutenção', value: stats.manut, color: '#f97316' },
    { name: 'Processo', value: stats.proc, color: '#f59e0b' },
    { name: 'Outros', value: stats.outros, color: '#94a3b8' }
  ].filter(d => d.value > 0), [stats]);

  const exportToCSV = () => {
    const headers = ['Data', 'Operador', 'Maquina', 'Turno', 'Peso Liquido', 'Paradas'];
    const rows = filteredData.map(e => [e.date, e.operator, e.machine, e.shift, e.netWeight, e.manutencaoMin + e.processoMin + e.outrosMin]);
    const csvContent = [headers, ...rows].map(r => r.join(';')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `relatorio_${selectedOperator}_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  const exportChartAsImage = async (elementId: string, title: string) => {
    const chartContainer = document.getElementById(elementId);
    if (!chartContainer) return;

    const svg = chartContainer.querySelector('svg');
    if (!svg) return;

    const A4_WIDTH = 2480;
    const A4_HEIGHT = 3508;
    const PADDING = 150;

    const canvas = document.createElement('canvas');
    canvas.width = A4_WIDTH;
    canvas.height = A4_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, A4_WIDTH, A4_HEIGHT);

    ctx.fillStyle = '#2563EB';
    ctx.font = '900 120px Inter, sans-serif';
    ctx.fillText('Manupackaging Pro', PADDING, 250);

    ctx.fillStyle = '#475569';
    ctx.font = 'bold 80px Inter, sans-serif';
    ctx.fillText(title, PADDING, 400);

    ctx.strokeStyle = '#F1F5F9';
    ctx.lineWidth = 10;
    ctx.beginPath();
    ctx.moveTo(PADDING, 480);
    ctx.lineTo(A4_WIDTH - PADDING, 480);
    ctx.stroke();

    ctx.fillStyle = '#94A3B8';
    ctx.font = 'bold 50px Inter, sans-serif';
    ctx.fillText(`Emitido em: ${new Date().toLocaleString('pt-BR')}`, PADDING, 580);
    ctx.fillText(`Filtros: Operador: ${selectedOperator} | Máquina: ${selectedMachine}`, PADDING, 650);

    const svgData = new XMLSerializer().serializeToString(svg);
    const svgBlob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(svgBlob);

    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = url;

    await new Promise((resolve) => {
      img.onload = () => {
        const availableWidth = A4_WIDTH - (PADDING * 2);
        const scale = availableWidth / img.width;
        const drawWidth = availableWidth;
        const drawHeight = img.height * scale;

        ctx.drawImage(img, PADDING, 800, drawWidth, drawHeight);

        ctx.fillStyle = '#CBD5E1';
        ctx.font = 'bold 40px Inter, sans-serif';
        ctx.fillText('DOCUMENTO DIGITAL DE CONTROLE DE PRODUÇÃO - UNIDADE CAST', PADDING, A4_HEIGHT - 200);

        const pngUrl = canvas.toDataURL('image/png', 1.0);
        const downloadLink = document.createElement('a');
        downloadLink.href = pngUrl;
        downloadLink.download = `Relatorio_${title.replace(/\s+/g, '_')}_${new Date().getTime()}.png`;
        downloadLink.click();

        URL.revokeObjectURL(url);
        resolve(null);
      };
    });
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Sidebar Menu */}
      <div className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Global
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro
            </h3>
            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Novo nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <UserPlus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Machine Status */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatus.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex items-center gap-4">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center bg-${m.color}-100 text-${m.color}-600`}>
                {m.status === 'Operando' ? <CheckCircle2 size={20} /> : <AlertTriangle size={20} />}
              </div>
              <div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-bold text-slate-700">{m.status}</span>
                  <div className={`w-2 h-2 rounded-full bg-${m.color}-500 animate-pulse`}></div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Machine Selector */}
        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button 
                  key={m} onClick={() => setSelectedMachine(m)}
                  className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{stats.borra.toLocaleString('pt-BR')} kg</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span>
            <span className="text-xl font-black text-blue-600">{(stats.totalNet / 1000).toFixed(1)}t</span>
          </div>
        </div>

        {/* Goal Tracking */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500 shadow-emerald-100' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                 Meta {selectedOperator !== 'Todos' ? `de ${selectedOperator}` : 'Geral'}
               </span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{stats.totalNet.toLocaleString('pt-BR')}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {goalValue.toLocaleString('pt-BR')} kg</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {Math.round((stats.totalNet / goalValue) * 100)}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div 
              className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} 
              style={{ width: `${Math.min((stats.totalNet / goalValue) * 100, 100)}%` }}
            ></div>
          </div>
        </div>

        {/* Dynamic Charts Row */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group flex flex-col">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">
                {selectedOperator === 'Todos' ? 'Distribuição de Produção' : `Composição: ${selectedOperator}`}
              </h3>
              <button 
                onClick={() => exportChartAsImage('main-chart-container', selectedOperator === 'Todos' ? 'Ranking Geral de Produção' : `Perfil de Desempenho: ${selectedOperator}`)}
                className="p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all opacity-0 group-hover:opacity-100 flex items-center gap-1"
                title="Salvar Imagem A4"
              >
                <ImageIcon size={16} />
                <span className="text-[10px] font-bold">SALVAR A4</span>
              </button>
            </div>

            <div className="mb-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl border border-blue-100">
              <Info size={14} className="text-blue-500 mt-0.5 shrink-0" />
              <p className="text-[10px] text-slate-500 font-medium leading-relaxed italic">
                {selectedOperator === 'Todos' 
                  ? "Este gráfico exibe a participação de cada operador no volume total produzido. As fatias representam o peso líquido acumulado."
                  : "Detalhamento da produção individual, segregando o peso líquido, refugo (borra) e materiais reciclados gerados."
                }
              </p>
            </div>

            <div className="h-[350px] w-full" id="main-chart-container">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={mainChartData} 
                      cx="50%" 
                      cy="45%" 
                      innerRadius={55} 
                      outerRadius={80} 
                      paddingAngle={4} 
                      dataKey="value"
                      label={({ percent }) => `${(percent * 100).toFixed(1)}%`}
                    >
                      {mainChartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                      ))}
                    </Pie>
                    <Tooltip 
                      content={({ active, payload }) => {
                        if (active && payload && payload.length) {
                          const data = payload[0].payload;
                          const total = mainChartData.reduce((a, b) => a + b.value, 0);
                          const percentage = ((data.value / total) * 100).toFixed(1);
                          return (
                            <div className="bg-white p-3 border border-slate-200 shadow-xl rounded-xl">
                              <p className="text-[10px] font-black text-slate-400 uppercase mb-1">{data.name}</p>
                              <div className="flex items-baseline gap-2">
                                <span className="text-sm font-black text-slate-800">{data.value.toLocaleString('pt-BR')} {data.unit}</span>
                                <span className="text-[10px] font-bold text-blue-500">{percentage}%</span>
                              </div>
                            </div>
                          );
                        }
                        return null;
                      }}
                    />
                    <Legend 
                      verticalAlign="bottom" 
                      align="center"
                      iconType="circle"
                      formatter={(value, entry) => {
                        const data = entry.payload;
                        return (
                          <span className="text-[9px] font-bold text-slate-700 ml-1">
                            {value}: <span className="text-blue-600">{data.value.toLocaleString('pt-BR')} kg</span>
                          </span>
                        );
                      }}
                      wrapperStyle={{ 
                        paddingTop: '20px', 
                        fontSize: '10px', 
                        fontWeight: '800', 
                        textTransform: 'uppercase', 
                        letterSpacing: '0.02em',
                        lineHeight: '1.4'
                      }}
                    />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem dados</p> }
            </div>
          </div>

          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group flex flex-col">
            <div className="flex items-center justify-between mb-6">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">Principais Paradas</h3>
              <button 
                onClick={() => exportChartAsImage('downtime-pie-container', 'Distribuição de Motivos de Parada')}
                className="p-2 text-slate-300 hover:text-orange-600 hover:bg-orange-50 rounded-lg transition-all opacity-0 group-hover:opacity-100 flex items-center gap-1"
                title="Salvar Imagem A4"
              >
                <ImageIcon size={16} />
                <span className="text-[10px] font-bold">SALVAR A4</span>
              </button>
            </div>
            <div className="h-[350px] w-full" id="downtime-pie-container">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={downtimePieData} 
                      cx="50%" 
                      cy="45%" 
                      innerRadius={60} 
                      outerRadius={85} 
                      paddingAngle={8} 
                      dataKey="value"
                      label={({ percent }) => `${(percent * 100).toFixed(1)}%`}
                    >
                      {downtimePieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend 
                      iconType="circle" 
                      verticalAlign="bottom" 
                      formatter={(value, entry) => {
                        const data = entry.payload;
                        return (
                          <span className="text-[9px] font-bold text-slate-700 ml-1">
                            {value}: <span className="text-orange-600">{data.value.toLocaleString('pt-BR')} min</span>
                          </span>
                        );
                      }}
                      wrapperStyle={{ 
                        fontSize: '10px', 
                        fontWeight: 'bold',
                        paddingTop: '20px'
                      }} 
                    />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20 font-bold uppercase">Sem paradas</p> }
            </div>
          </div>
        </div>

        {/* History */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico Detalhado</h3>
            <span className="text-[10px] font-bold text-slate-400 bg-slate-200 px-2 py-0.5 rounded">{filteredData.length} registros</span>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
              <div key={entry.id} className="p-4 flex items-center justify-between hover:bg-slate-50/50">
                <div className="flex items-center gap-4">
                  <div className={`w-2 h-10 rounded-full ${entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600'}`}></div>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                      <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                    </div>
                    <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                  </div>
                </div>
                <div className="text-right flex items-center gap-4">
                  <div>
                    <span className="block font-black text-blue-600 text-sm">{entry.netWeight.toLocaleString('pt-BR')} kg</span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase">Líquido</span>
                  </div>
                  <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </main>

      <LaunchModal 
        isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} operators={operators}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Menu, Plus, TrendingUp, BarChart2, Calendar, RotateCcw, Download, Clock, Zap, Trash2, Cpu, BrainCircuit, Sparkles, CheckCircle2, AlertTriangle, X, ChevronRight, Settings, Target, Users, UserPlus, Trophy, Sparkle, RefreshCw, User, Filter, Image as ImageIcon, Info } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '3.1'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Franck', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const isGoalAchieved = stats.totalNet >= goalValue && goalValue > 0;

  const machineStatus = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const machineEntries = productionData.filter(e => e.machine === m);
      const sortedEntries = [...machineEntries].sort((a, b) => b.date.localeCompare(a.date));
      const lastEntry = sortedEntries[0];
      const totalDowntime = lastEntry ? (lastEntry.manutencaoMin + lastEntry.processoMin + lastEntry.outrosMin) : 0;

      let status = 'Operando';
      let color = 'emerald';

      if (!lastEntry) { status = 'Sem Dados'; color = 'slate'; }
      else if (lastEntry.manutencaoMin > 30) { status = 'Manutenção'; color = 'orange'; }
      else if (totalDowntime > 60) { status = 'Alerta'; color = 'amber'; }

      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316', '#64748b'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });
      return Object.entries(performanceMap)
        .map(([name, kg], index) => ({ 
          name, 
          value: kg, 
          color: colors[index % colors.length],
          unit: 'kg'
        }))
        .sort((a, b) => b.value - a.value);
    } else {
      return [
        { name: 'Prod. Líquida', value: stats.totalNet, color: '#3b82f6', unit: 'kg' },
        { name: 'ECO A', value: stats.ecoA, color: '#10b981', unit: 'kg' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, color: '#f59e0b', unit: 'kg' },
        { name: 'Borra', value: stats.borra, color: '#ef4444', unit: 'kg' }
      ].filter(d => d.value > 0);
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => [
    { name: 'Manutenção', value: stats.manut, color: '#f97316' },
    { name: 'Processo', value: stats.proc, color: '#f59e0b' },
    { name: 'Outros', value: stats.outros, color: '#94a3b8' }
  ].filter(d => d.value > 0), [stats]);

  const exportToCSV = () => {
    const headers = ['Data', 'Operador', 'Maquina', 'Turno', 'Peso Liquido', 'Paradas'];
    const rows = filteredData.map(e => [e.date, e.operator, e.machine, e.shift, e.netWeight, e.manutencaoMin + e.processoMin + e.outrosMin]);
    const csvContent = [headers, ...rows].map(r => r.join(';')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `relatorio_${selectedOperator}_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  const exportChartAsImage = async (elementId: string, title: string, chartData: any[], description: string) => {
    const chartContainer = document.getElementById(elementId);
    if (!chartContainer) return;

    const svg = chartContainer.querySelector('svg');
    if (!svg) return;

    const A4_WIDTH = 2480;
    const A4_HEIGHT = 3508;
    const PADDING = 150;

    const canvas = document.createElement('canvas');
    canvas.width = A4_WIDTH;
    canvas.height = A4_HEIGHT;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Background
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, A4_WIDTH, A4_HEIGHT);

    // Header
    ctx.fillStyle = '#2563EB';
    ctx.font = '900 120px Inter, sans-serif';
    ctx.fillText('Manupackaging Pro', PADDING, 250);

    ctx.fillStyle = '#1E293B';
    ctx.font = 'bold 80px Inter, sans-serif';
    ctx.fillText(title, PADDING, 400);

    // Filter Info
    ctx.fillStyle = '#64748B';
    ctx.font = '500 45px Inter, sans-serif';
    ctx.fillText(`Filtros Ativos: Operador: ${selectedOperator} | Máquina: ${selectedMachine} | Data: ${new Date().toLocaleDateString('pt-BR')}`, PADDING, 500);

    // Divider
    ctx.strokeStyle = '#F1F5F9';
    ctx.lineWidth = 10;
    ctx.beginPath();
    ctx.moveTo(PADDING, 580);
    ctx.lineTo(A4_WIDTH - PADDING, 580);
    ctx.stroke();

    // Chart Area
    const svgData = new XMLSerializer().serializeToString(svg);
    const svgBlob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(svgBlob);
    const img = new Image();

    await new Promise((resolve) => {
      img.onload = () => {
        const drawWidth = A4_WIDTH - (PADDING * 2);
        const drawHeight = (img.height / img.width) * drawWidth;
        ctx.drawImage(img, PADDING, 700, drawWidth, drawHeight);

        let currentY = 700 + drawHeight + 150;

        // Legend Section Title
        ctx.fillStyle = '#1E293B';
        ctx.font = 'bold 60px Inter, sans-serif';
        ctx.fillText('Detalhamento dos Dados', PADDING, currentY);
        currentY += 100;

        // Description
        ctx.fillStyle = '#64748B';
        ctx.font = 'italic 40px Inter, sans-serif';
        const words = description.split(' ');
        let line = '';
        const maxWidth = A4_WIDTH - (PADDING * 2);
        for (let n = 0; n < words.length; n++) {
            let testLine = line + words[n] + ' ';
            let metrics = ctx.measureText(testLine);
            if (metrics.width > maxWidth && n > 0) {
                ctx.fillText(line, PADDING, currentY);
                line = words[n] + ' ';
                currentY += 55;
            } else {
                line = testLine;
            }
        }
        ctx.fillText(line, PADDING, currentY);
        currentY += 150;

        // Custom Legend with Values
        chartData.forEach((item, index) => {
            // Color Circle
            ctx.fillStyle = item.color || '#3b82f6';
            ctx.beginPath();
            ctx.arc(PADDING + 30, currentY - 20, 25, 0, Math.PI * 2);
            ctx.fill();

            // Text Label
            ctx.fillStyle = '#1E293B';
            ctx.font = 'bold 50px Inter, sans-serif';
            const valueStr = `${item.name}: ${item.value.toLocaleString('pt-BR')} ${item.unit || 'kg'}`;
            ctx.fillText(valueStr, PADDING + 100, currentY);

            // Percentage calculate
            const total = chartData.reduce((acc, curr) => acc + curr.value, 0);
            const perc = ((item.value / total) * 100).toFixed(1);
            ctx.fillStyle = '#2563EB';
            ctx.font = 'bold 45px Inter, sans-serif';
            ctx.fillText(`${perc}%`, A4_WIDTH - PADDING - 250, currentY);

            currentY += 110;
        });

        // Footer
        ctx.fillStyle = '#94A3B8';
        ctx.font = 'bold 40px Inter, sans-serif';
        ctx.fillText('RELATÓRIO GERADO PELO SISTEMA MANUPACKAGING PRO - CONTROLE DE QUALIDADE', PADDING, A4_HEIGHT - 150);

        // Download
        const pngUrl = canvas.toDataURL('image/png', 1.0);
        const link = document.createElement('a');
        link.href = pngUrl;
        link.download = `Relatorio_${title.replace(/\s+/g, '_')}_${new Date().getTime()}.png`;
        link.click();

        URL.revokeObjectURL(url);
        resolve(null);
      };
      img.src = url;
    });
  };

  const productionDescription = selectedOperator === 'Todos' 
