      'Manutencao Min', 'Manutencao Motivo',
      'Processo Min', 'Processo Motivo',
      'Outros Min', 'Outros Motivo'
    ];

    const csvRows = filteredData.map(entry => [
      entry.id,
      entry.date,
      entry.operator,
      entry.machine,
      entry.shift,
      entry.grossWeight,
      entry.tara,
      entry.netWeight,
      entry.volumes,
      entry.tubetes,
