               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div 
              className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} 
              style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}
            ></div>
          </div>
          <p className="text-[10px] text-slate-400 mt-3 font-medium italic">A meta é calculada com base na produção líquida do mês vigente.</p>
        </div>

        {/* Gráficos */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group flex flex-col min-h-[520px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Distribuição de Produção</h3>
              <ImageIcon size={16} className="text-slate-200" />
            </div>
            <div className="h-[400px] w-full">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart margin={{ bottom: 0 }}>
                    <Pie 
                      data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={85} 
                      dataKey="value" label={renderCustomLabel} paddingAngle={4}
                    >
                      {mainChartData.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM DADOS</p>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl">
              <Info size={14} className="text-blue-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Visualização do volume por operador ou composição do material no período filtrado.</p>
            </div>
          </div>

          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group flex flex-col min-h-[520px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Motivos de Paradas</h3>
              <AlertTriangle size={16} className="text-slate-200" />
            </div>
            <div className="h-[400px] w-full">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={85} 
                      dataKey="value" label={renderCustomLabel} paddingAngle={6}
                    >
                      {downtimePieData.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM PARADAS</p>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-slate-50 p-3 rounded-xl">
              <Info size={14} className="text-slate-400 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Análise detalhada do tempo perdido por categoria: Manutenção, Processo e Outros.</p>
            </div>
          </div>
        </div>

        {/* Lista Histórica */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico de Lançamentos</h3>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.length > 0 ? (
              filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
                <div key={entry.id} className="p-4 flex items-center justify-between hover:bg-slate-50/50">
                  <div className="flex items-center gap-4">
                    <div className={`w-1.5 h-10 rounded-full ${entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600'}`}></div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                        <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                      </div>
                      <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                    </div>
                  </div>
                  <div className="text-right flex items-center gap-4">
                    <div>
                      <span className="block font-black text-blue-600 text-sm">{formatWeight(entry.netWeight)}</span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase">Líquido</span>
                    </div>
                    <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                  </div>
                </div>
              ))
            ) : (
              <div className="p-8 text-center text-slate-300 text-xs font-bold uppercase tracking-widest">Nenhum lançamento encontrado</div>
            )}
          </div>
        </div>
      </main>

      <LaunchModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} 
        operators={operators}
        activeMachines={activeMachines}
      />
    </div>
  );
};

export default App;

export interface ProductionEntry {
  id: string;
  date: string;
  operator: string;
  machine: string;
  shift: string;
  grossWeight: number;
  tara: number;
  netWeight: number;
  volumes: number;
  tubetes: number;
  ecoA: number;
  ecoBP: number;
  ecoBM: number;
  borraTotal: number;
  manutencaoMin: number;
  manutencaoMotivo?: string;
  processoMin: number;
  processoMotivo?: string;
  outrosMin: number;
  outrosMotivo?: string;
  isMaintenanceEntry?: boolean;
}

export interface SummaryStats {
  totalNet: number;
  ecoA: number;
  ecoBP: number;
  ecoBM: number;
  borra: number;
  paradas: number;
}

import React, { useState, useEffect } from 'react';
import { X, Save, Edit2, Package, Layers, Trash2, Clock, Wrench } from 'lucide-react';
import { ProductionEntry } from '../types';

interface LaunchModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (entry: Omit<ProductionEntry, 'id'>) => void;
  operators: string[];
  activeMachines: string[];
}

const LaunchModal: React.FC<LaunchModalProps> = ({ isOpen, onClose, onSave, operators, activeMachines }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    operator: '',
    machine: '',
    shift: 'Diurno',
    grossWeight: 0,
    tara: 0,
    netWeight: 0,
    volumes: 0,
    tubetes: 0,
    ecoA: 0,
    ecoBP: 0,
    ecoBM: 0,
    borraTotal: 0,
    manutencaoMin: 0,
    manutencaoMotivo: '',
    processoMin: 0,
    processoMotivo: '',
    outrosMin: 0,
    outrosMotivo: '',
    isMaintenanceEntry: false,
  });

  useEffect(() => {
    if (isOpen && activeMachines.length > 0) {
      setFormData(prev => ({ ...prev, machine: activeMachines[0] }));
    }
  }, [isOpen, activeMachines]);

  useEffect(() => {
    setFormData(prev => ({
      ...prev,
      netWeight: prev.isMaintenanceEntry ? 0 : prev.grossWeight - prev.tara
    }));
  }, [formData.grossWeight, formData.tara, formData.isMaintenanceEntry]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.operator) {
      alert('Por favor, selecione um operador.');
      return;
    }
    if (!formData.machine) {
      alert('Nenhuma máquina ativa selecionada.');
      return;
    }

    // Se for entrada de manutenção, zeramos os campos de produção por segurança
    const finalData = formData.isMaintenanceEntry ? {
      ...formData,
      grossWeight: 0,
      tara: 0,
      netWeight: 0,
      volumes: 0,
      tubetes: 0,
      ecoA: 0,
      ecoBP: 0,
      ecoBM: 0,
      borraTotal: 0,
    } : formData;

    onSave(finalData);
    onClose();
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as HTMLInputElement;
    let val: any;

    if (type === 'checkbox') {
      val = (e.target as HTMLInputElement).checked;
    } else {
      val = type === 'number' ? parseFloat(value) || 0 : value;
    }

    setFormData(prev => ({ ...prev, [name]: val }));
  };

  const totalParadas = formData.manutencaoMin + formData.processoMin + formData.outrosMin;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm overflow-y-auto">
      <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl relative overflow-hidden my-auto">
        {/* Header */}
        <div className="bg-[#1e293b] text-white p-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Edit2 size={20} />
            <h2 className="text-lg font-semibold tracking-tight">Novo Lançamento</h2>
          </div>
          <button onClick={onClose} className="hover:bg-white/10 p-1 rounded-full transition-colors">
            <X size={24} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-5 space-y-5 max-h-[80vh] overflow-y-auto custom-scrollbar">

          {/* Toggle Manutenção */}
          <div className={`p-4 rounded-xl flex items-center justify-between transition-colors ${formData.isMaintenanceEntry ? 'bg-orange-50 border border-orange-200' : 'bg-slate-50 border border-slate-200'}`}>
            <div className="flex items-center gap-3">
              <div className={`w-10 h-10 rounded-full flex items-center justify-center ${formData.isMaintenanceEntry ? 'bg-orange-100 text-orange-600' : 'bg-slate-200 text-slate-500'}`}>
                <Wrench size={20} />
              </div>
              <div>
                <h3 className="text-sm font-bold text-slate-800">Turno em Manutenção?</h3>
                <p className="text-[10px] text-slate-500 font-medium">Marque se não houve produção neste período.</p>
              </div>
            </div>
            <label className="relative inline-flex items-center cursor-pointer">
              <input 
                type="checkbox" 
                name="isMaintenanceEntry" 
                checked={formData.isMaintenanceEntry} 
                onChange={handleChange}
                className="sr-only peer" 
              />
              <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-orange-600"></div>
            </label>
          </div>

          {/* Main Info */}
          <div className="space-y-3">
            <div>
              <label className="text-[10px] font-bold text-gray-500 uppercase">Data</label>
              <input 
                type="date" name="date" value={formData.date} onChange={handleChange}
                className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 font-bold" 
              />
            </div>
            <div>
              <label className="text-[10px] font-bold text-gray-500 uppercase">Operador</label>
              <select 
                name="operator" value={formData.operator} onChange={handleChange}
                className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 font-bold text-slate-800"
              >
                <option value="">Selecione...</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-[10px] font-bold text-gray-500 uppercase">Máquina</label>
                <select name="machine" value={formData.machine} onChange={handleChange}
