                    <input type="number" name="ecoA" value={formData.ecoA || ''} onChange={handleChange}
                      className="w-full mt-1 bg-white border border-orange-200 rounded-lg px-3 py-2 text-sm font-bold" />
                  </div>
                  <div>
                    <label className="text-[9px] font-bold text-orange-600 uppercase">Eco B (P)</label>
                    <input type="number" name="ecoBP" value={formData.ecoBP || ''} onChange={handleChange}
                      className="w-full mt-1 bg-white border border-orange-200 rounded-lg px-3 py-2 text-sm font-bold" />
                  </div>
                  <div>
                    <label className="text-[9px] font-bold text-orange-600 uppercase">Eco B (M)</label>
                    <input type="number" name="ecoBM" value={formData.ecoBM || ''} onChange={handleChange}
