                  <div className="text-right flex items-center gap-4">
                    <div>
                      <span className={`block font-black text-sm ${entry.isMaintenanceEntry ? 'text-orange-600' : 'text-blue-600'}`}>
                        {entry.isMaintenanceEntry ? `${entry.manutencaoMin} MIN` : formatWeight(entry.netWeight)}
                      </span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase">
                        {entry.isMaintenanceEntry ? 'Downtime' : 'Líquido'}
                      </span>
                    </div>
                    <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                  </div>
                </div>
              ))
            ) : (
              <div className="p-8 text-center text-slate-300 text-xs font-bold uppercase tracking-widest">Nenhum lançamento encontrado</div>
            )}
          </div>
        </div>
      </main>

      <LaunchModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} 
        operators={operators}
        activeMachines={activeMachines}
      />
    </div>
  );
};

export default App;

import { ProductionEntry } from './types';

// Helper to generate a random number within a range
const rand = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1) + min);

// Removido 'Franck' da lista de operadores
const operators = ['Sidoneide', 'Deyvis', 'Erivan', 'Nahin', 'Carlos Philips', 'Edilson', 'Everson', 'Marcelo'];
const machines = ['Cast 1', 'Cast 2'];
const shifts = ['Diurno', 'Noturno'];

const generateFakeData = (): ProductionEntry[] => {
  const data: ProductionEntry[] = [];
  const start = new Date('2024-11-01');
  const end = new Date(); // Today

  let id = 1;

  for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
    // Generate 1-2 entries per day
    const entriesPerDay = rand(1, 2);

    for (let i = 0; i < entriesPerDay; i++) {
      const dateStr = d.toISOString().split('T')[0];
      const gross = rand(35000, 42000);
      const tara = rand(1100, 1500);
      const net = gross - tara;

      data.push({
        id: (id++).toString(),
        date: dateStr,
        operator: operators[rand(0, operators.length - 1)],
        machine: machines[rand(0, machines.length - 1)],
        shift: shifts[rand(0, shifts.length - 1)],
        grossWeight: gross,
        tara: tara,
        netWeight: net,
        volumes: rand(85, 110),
        tubetes: rand(40, 60),
        ecoA: 0,
        ecoBP: rand(800, 1500),
        ecoBM: rand(300, 600),
        borraTotal: rand(20, 150),
        manutencaoMin: rand(0, 1) > 0.8 ? rand(20, 90) : 0,
        processoMin: rand(0, 1) > 0.7 ? rand(10, 40) : 0,
        outrosMin: rand(0, 1) > 0.9 ? rand(5, 20) : 0,
      });
    }
  }
  return data;
};

export const INITIAL_DATA: ProductionEntry[] = generateFakeData();

export const GOAL_VALUE = 1250000; // Meta mensal aproximada (1.250 Toneladas)

import React, { useState, useMemo, useEffect } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, UserPlus, RefreshCw, Filter, Image as ImageIcon, Info, Power, Users, Wrench, Printer } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '3.7'; // Incrementado para forçar a limpeza dos dados antigos do Franck

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    // Se a versão mudou, ignoramos o localStorage e carregamos os INITIAL_DATA (que agora não tem o Franck)
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    // Removido 'Franck' da lista padrão
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleDeleteOperator = (op: string) => {
    if (confirm(`Deseja remover o operador "${op}" da lista ativa? Os lançamentos existentes não serão apagados.`)) {
      setOperators(prev => prev.filter(item => item !== op));
      if (selectedOperator === op) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const exportToCSV = () => {
    const headers = [
      'ID', 'Data', 'Operador', 'Maquina', 'Turno', 
      'Peso Bruto (kg)', 'Tara (kg)', 'Peso Liquido (kg)', 'Volumes', 'Tubetes (kg)',
      'Eco A (kg)', 'Eco B P (kg)', 'Eco B M (kg)', 'Borra Total (kg)',
      'Manutencao Min', 'Manutencao Motivo',
      'Processo Min', 'Processo Motivo',
      'Outros Min', 'Outros Motivo', 'Apenas Manutencao'
    ];

    const csvRows = filteredData.map(entry => [
      entry.id,
      entry.date,
      entry.operator,
      entry.machine,
      entry.shift,
      entry.grossWeight,
      entry.tara,
      entry.netWeight,
      entry.volumes,
      entry.tubetes,
      entry.ecoA,
      entry.ecoBP,
      entry.ecoBM,
      entry.borraTotal,
      entry.manutencaoMin,
      `"${entry.manutencaoMotivo || ''}"`,
      entry.processoMin,
      `"${entry.processoMotivo || ''}"`,
      entry.outrosMin,
      `"${entry.outrosMotivo || ''}"`,
      entry.isMaintenanceEntry ? 'SIM' : 'NAO'
    ]);

    const csvContent = [
      headers.join(','),
      ...csvRows.map(row => row.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `relatorio_producao_${new Date().getTime()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN`;
    if (val >= 1000) {
      return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    }
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#f59e0b', '#3b82f6', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4', '#8b5cf6', '#10b981'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });
      return Object.entries(performanceMap)
        .map(([name, kg], index) => ({ 
          name, 
          value: kg, 
          color: colors[index % colors.length],
          unit: 'KG'
        }))
        .sort((a, b) => b.value - a.value);
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, color: '#3b82f6', unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, color: '#10b981', unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, color: '#f59e0b', unit: 'KG' },
        { name: 'BORRA', value: stats.borra, color: '#ef4444', unit: 'KG' }
      ].filter(d => d.value > 0);
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => [
    { name: 'MANUTENÇÃO', value: stats.manut, color: '#f97316' },
    { name: 'PROCESSO', value: stats.proc, color: '#f59e0b' },
    { name: 'OUTROS', value: stats.outros, color: '#94a3b8' }
  ].filter(d => d.value > 0), [stats]);

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const radius = outerRadius + 14; 
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';

    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="bold">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    return (
      <div className="grid grid-cols-2 gap-x-6 gap-y-3 mt-8 max-w-lg mx-auto px-4 justify-items-center">
        {payload.map((entry: any, index: number) => {
          const data = entry.payload;
          const total = (data.unit === 'KG' || !data.unit) ? stats.totalNet : stats.paradas;
          const perc = total > 0 ? ((data.value / total) * 100).toFixed(1) : "0";
          return (
            <div key={`item-${index}`} className="flex items-center gap-2 w-full max-w-[200px]">
              <div className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-bold text-slate-700 uppercase truncate">{entry.value}:</span>
                <div className="flex items-baseline gap-1">
                  <span className="text-[10px] font-black text-blue-600">{formatWeight(data.value, data.unit)}</span>
                  <span className="text-[8px] font-medium text-slate-400 shrink-0">({perc}%)</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Menu Lateral */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Mensal (KG)
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro de Equipe
            </h3>

            <div className="space-y-1 max-h-40 overflow-y-auto custom-scrollbar pr-1">
              {operators.map(op => (
                <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg group transition-colors hover:bg-slate-100">
                  <span className="text-[11px] font-bold text-slate-700">{op}</span>
                  <button 
                    onClick={() => handleDeleteOperator(op)}
                    className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                    title="Remover Operador"
                  >
                    <Trash2 size={12} />
                  </button>
                </div>
              ))}
            </div>

            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold focus:outline-none"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <Plus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      {/* Header Fixo */}
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={handlePrint} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-all border border-slate-200" title="Imprimir Relatório">
              <Printer size={18} />
           </button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo Lançamento</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Status das Máquinas com Controle Manual */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className={`bg-white rounded-2xl p-4 shadow-sm border transition-all ${m.status === 'Operando' ? 'border-slate-100' : 'border-orange-200 shadow-orange-50 bg-orange-50/10'}`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button 
                  onClick={() => toggleMachineStatus(m.name)}
                  className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50 hover:bg-emerald-100' : 'text-orange-600 bg-orange-50 hover:bg-orange-100'}`}
                  title={m.status === 'Operando' ? "Parar para Manutenção" : "Colocar em Operação"}
                >
                  <Power size={14} />
                </button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                    <div className={`w-1.5 h-1.5 rounded-full ${m.color === 'emerald' ? 'bg-emerald-500 animate-pulse' : 'bg-orange-500'}`}></div>
                  </div>
                  <p className="text-[9px] text-slate-400 font-medium">Últ. Op: {m.lastOp}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Filtro de Máquina Visual */}
        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200 no-print">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button 
                  key={m} onClick={() => setSelectedMachine(m)}
                  className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Cards de Métricas */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Período</span>
            <span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span>
          </div>
        </div>

        {/* Card de Meta Mensal */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500 shadow-emerald-100' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                 Meta Mensal ({currentMonthName})
               </span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div 
              className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} 
              style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}
            ></div>
          </div>
          <p className="text-[10px] text-slate-400 mt-3 font-medium italic">A meta é calculada com base na produção líquida do mês vigente.</p>
        </div>

        {/* Gráficos */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group flex flex-col min-h-[520px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Distribuição de Produção</h3>
              <ImageIcon size={16} className="text-slate-200" />
            </div>
            <div className="h-[400px] w-full pt-4">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={mainChartData} cx="50%" cy="50%" innerRadius={55} outerRadius={75} 
                      dataKey="value" label={renderCustomLabel} paddingAngle={4}
                    >
                      {mainChartData.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM DADOS</p>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl no-print">
              <Info size={14} className="text-blue-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Visualização do volume por operador ou composição do material no período filtrado.</p>
            </div>
          </div>

          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group flex flex-col min-h-[520px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Motivos de Paradas</h3>
              <AlertTriangle size={16} className="text-slate-200" />
            </div>
            <div className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={downtimePieData} cx="50%" cy="50%" innerRadius={55} outerRadius={75} 
                      dataKey="value" label={renderCustomLabel} paddingAngle={6}
                    >
                      {downtimePieData.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM PARADAS</p>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-slate-50 p-3 rounded-xl no-print">
              <Info size={14} className="text-slate-400 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Análise detalhada do tempo perdido por categoria: Manutenção, Processo e Outros.</p>
            </div>
          </div>
        </div>

        {/* Lista Histórica */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden no-print">
          <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico de Lançamentos</h3>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.length > 0 ? (
              filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
                <div key={entry.id} className={`p-4 flex items-center justify-between hover:bg-slate-50/50 ${entry.isMaintenanceEntry ? 'bg-orange-50/30' : ''}`}>
                  <div className="flex items-center gap-4">
                    <div className={`w-1.5 h-10 rounded-full ${entry.isMaintenanceEntry ? 'bg-orange-500' : (entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600')}`}></div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                        <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                        {entry.isMaintenanceEntry && (
                          <span className="text-[8px] bg-orange-600 text-white px-2 py-0.5 rounded-full font-black uppercase flex items-center gap-1">
                            <Wrench size={8} /> MANUTENÇÃO
                          </span>
                        )}
                      </div>
                      <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                    </div>
                  </div>
                  <div className="text-right flex items-center gap-4">
                    <div>
                      <span className={`block font-black text-sm ${entry.isMaintenanceEntry ? 'text-orange-600' : 'text-blue-600'}`}>
                        {entry.isMaintenanceEntry ? `${entry.manutencaoMin} MIN` : formatWeight(entry.netWeight)}
                      </span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase">
                        {entry.isMaintenanceEntry ? 'Downtime' : 'Líquido'}
                      </span>
                    </div>
                    <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                  </div>
                </div>
              ))
            ) : (
              <div className="p-8 text-center text-slate-300 text-xs font-bold uppercase tracking-widest">Nenhum lançamento encontrado</div>
            )}
          </div>
        </div>
      </main>

      <LaunchModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} 
        operators={operators}
        activeMachines={activeMachines}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, UserPlus, RefreshCw, Filter, Image as ImageIcon, Info, Power, Users, Wrench, Printer } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '3.8'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  // Refs para exportação de imagem
  const prodChartRef = useRef<HTMLDivElement>(null);
  const stopChartRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleDeleteOperator = (op: string) => {
    if (confirm(`Deseja remover o operador "${op}" da lista ativa? Os lançamentos existentes não serão apagados.`)) {
      setOperators(prev => prev.filter(item => item !== op));
      if (selectedOperator === op) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const downloadChartAsImage = async (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;

    const svgElement = containerRef.current.querySelector('svg');
    if (!svgElement) return;

    try {
      const svgData = new XMLSerializer().serializeToString(svgElement);
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      const img = new Image();

      const width = svgElement.clientWidth || 800;
      const height = svgElement.clientHeight || 600;

      canvas.width = width * 2; // High DPI
      canvas.height = height * 2;

      const svgBlob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
      const url = URL.createObjectURL(svgBlob);

      img.onload = () => {
        if (!ctx) return;
        ctx.fillStyle = 'white';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.scale(2, 2);
        ctx.drawImage(img, 0, 0, width, height);

        const pngUrl = canvas.toDataURL('image/png');
        const downloadLink = document.createElement('a');
        downloadLink.href = pngUrl;
        downloadLink.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
        document.body.appendChild(downloadLink);
        downloadLink.click();
        document.body.removeChild(downloadLink);
        URL.revokeObjectURL(url);
      };
      img.src = url;
    } catch (error) {
      console.error('Falha ao exportar imagem:', error);
      alert('Não foi possível exportar a imagem. Tente usar o botão de Imprimir Relatório.');
    }
  };

  const exportToCSV = () => {
    const headers = [
      'ID', 'Data', 'Operador', 'Maquina', 'Turno', 
      'Peso Bruto (kg)', 'Tara (kg)', 'Peso Liquido (kg)', 'Volumes', 'Tubetes (kg)',
      'Eco A (kg)', 'Eco B P (kg)', 'Eco B M (kg)', 'Borra Total (kg)',
      'Manutencao Min', 'Manutencao Motivo',
      'Processo Min', 'Processo Motivo',
      'Outros Min', 'Outros Motivo', 'Apenas Manutencao'
    ];

    const csvRows = filteredData.map(entry => [
      entry.id,
      entry.date,
      entry.operator,
      entry.machine,
      entry.shift,
      entry.grossWeight,
      entry.tara,
      entry.netWeight,
      entry.volumes,
      entry.tubetes,
      entry.ecoA,
      entry.ecoBP,
      entry.ecoBM,
      entry.borraTotal,
      entry.manutencaoMin,
      `"${entry.manutencaoMotivo || ''}"`,
      entry.processoMin,
      `"${entry.processoMotivo || ''}"`,
      entry.outrosMin,
      `"${entry.outrosMotivo || ''}"`,
      entry.isMaintenanceEntry ? 'SIM' : 'NAO'
    ]);

    const csvContent = [
      headers.join(','),
      ...csvRows.map(row => row.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `relatorio_producao_${new Date().getTime()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN`;
    if (val >= 1000) {
      return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    }
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#f59e0b', '#3b82f6', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4', '#8b5cf6', '#10b981'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });
      return Object.entries(performanceMap)
        .map(([name, kg], index) => ({ 
          name, 
          value: kg, 
          color: colors[index % colors.length],
          unit: 'KG'
        }))
        .sort((a, b) => b.value - a.value);
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, color: '#3b82f6', unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, color: '#10b981', unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, color: '#f59e0b', unit: 'KG' },
        { name: 'BORRA', value: stats.borra, color: '#ef4444', unit: 'KG' }
      ].filter(d => d.value > 0);
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => [
    { name: 'MANUTENÇÃO', value: stats.manut, color: '#f97316' },
    { name: 'PROCESSO', value: stats.proc, color: '#f59e0b' },
    { name: 'OUTROS', value: stats.outros, color: '#94a3b8' }
  ].filter(d => d.value > 0), [stats]);

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const radius = outerRadius + 14; 
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';

    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="bold">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    return (
      <div className="grid grid-cols-2 gap-x-6 gap-y-3 mt-8 max-w-lg mx-auto px-4 justify-items-center">
        {payload.map((entry: any, index: number) => {
          const data = entry.payload;
          const total = (data.unit === 'KG' || !data.unit) ? stats.totalNet : stats.paradas;
          const perc = total > 0 ? ((data.value / total) * 100).toFixed(1) : "0";
          return (
            <div key={`item-${index}`} className="flex items-center gap-2 w-full max-w-[200px]">
              <div className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-bold text-slate-700 uppercase truncate">{entry.value}:</span>
                <div className="flex items-baseline gap-1">
                  <span className="text-[10px] font-black text-blue-600">{formatWeight(data.value, data.unit)}</span>
                  <span className="text-[8px] font-medium text-slate-400 shrink-0">({perc}%)</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Menu Lateral */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Mensal (KG)
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro de Equipe
            </h3>

            <div className="space-y-1 max-h-40 overflow-y-auto custom-scrollbar pr-1">
              {operators.map(op => (
                <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg group transition-colors hover:bg-slate-100">
                  <span className="text-[11px] font-bold text-slate-700">{op}</span>
                  <button 
                    onClick={() => handleDeleteOperator(op)}
                    className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                    title="Remover Operador"
                  >
                    <Trash2 size={12} />
                  </button>
                </div>
              ))}
            </div>

            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold focus:outline-none"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <Plus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      {/* Header Fixo */}
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={handlePrint} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-all border border-slate-200" title="Imprimir Relatório">
              <Printer size={18} />
           </button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo Lançamento</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Status das Máquinas com Controle Manual */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className={`bg-white rounded-2xl p-4 shadow-sm border transition-all ${m.status === 'Operando' ? 'border-slate-100' : 'border-orange-200 shadow-orange-50 bg-orange-50/10'}`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button 
                  onClick={() => toggleMachineStatus(m.name)}
                  className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50 hover:bg-emerald-100' : 'text-orange-600 bg-orange-50 hover:bg-orange-100'}`}
                  title={m.status === 'Operando' ? "Parar para Manutenção" : "Colocar em Operação"}
                >
                  <Power size={14} />
                </button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                    <div className={`w-1.5 h-1.5 rounded-full ${m.color === 'emerald' ? 'bg-emerald-500 animate-pulse' : 'bg-orange-500'}`}></div>
                  </div>
                  <p className="text-[9px] text-slate-400 font-medium">Últ. Op: {m.lastOp}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Filtro de Máquina Visual */}
        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200 no-print">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button 
                  key={m} onClick={() => setSelectedMachine(m)}
                  className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Cards de Métricas */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Período</span>
            <span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span>
          </div>
        </div>

        {/* Card de Meta Mensal */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500 shadow-emerald-100' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                 Meta Mensal ({currentMonthName})
               </span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div 
              className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} 
              style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}
            ></div>
          </div>
          <p className="text-[10px] text-slate-400 mt-3 font-medium italic">A meta é calculada com base na produção líquida do mês vigente.</p>
        </div>

        {/* Gráficos */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group flex flex-col min-h-[520px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Distribuição de Produção</h3>
              <div className="flex items-center gap-2 no-print">
                <button 
                  onClick={() => downloadChartAsImage(prodChartRef, 'distribuicao_producao')}
                  className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                  title="Baixar Gráfico como PNG"
                >
                  <Download size={16} />
                </button>
                <ImageIcon size={16} className="text-slate-200" />
              </div>
            </div>
            <div ref={prodChartRef} className="h-[400px] w-full pt-4">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={70} 
                      dataKey="value" label={renderCustomLabel} paddingAngle={4}
                    >
                      {mainChartData.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM DADOS</p>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl no-print">
              <Info size={14} className="text-blue-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Visualização do volume por operador ou composição do material no período filtrado.</p>
            </div>
          </div>

          <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 relative group flex flex-col min-h-[520px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Motivos de Paradas</h3>
              <div className="flex items-center gap-2 no-print">
                <button 
                  onClick={() => downloadChartAsImage(stopChartRef, 'motivos_paradas')}
                  className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                  title="Baixar Gráfico como PNG"
                >
                  <Download size={16} />
                </button>
                <AlertTriangle size={16} className="text-slate-200" />
              </div>
            </div>
            <div ref={stopChartRef} className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={70} 
                      dataKey="value" label={renderCustomLabel} paddingAngle={6}
                    >
                      {downtimePieData.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM PARADAS</p>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-slate-50 p-3 rounded-xl no-print">
              <Info size={14} className="text-slate-400 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Análise detalhada do tempo perdido por categoria: Manutenção, Processo e Outros.</p>
            </div>
          </div>
        </div>

        {/* Lista Histórica */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden no-print">
          <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico de Lançamentos</h3>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.length > 0 ? (
              filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
                <div key={entry.id} className={`p-4 flex items-center justify-between hover:bg-slate-50/50 ${entry.isMaintenanceEntry ? 'bg-orange-50/30' : ''}`}>
                  <div className="flex items-center gap-4">
                    <div className={`w-1.5 h-10 rounded-full ${entry.isMaintenanceEntry ? 'bg-orange-500' : (entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600')}`}></div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                        <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                        {entry.isMaintenanceEntry && (
                          <span className="text-[8px] bg-orange-600 text-white px-2 py-0.5 rounded-full font-black uppercase flex items-center gap-1">
                            <Wrench size={8} /> MANUTENÇÃO
                          </span>
                        )}
                      </div>
                      <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                    </div>
                  </div>
                  <div className="text-right flex items-center gap-4">
                    <div>
                      <span className={`block font-black text-sm ${entry.isMaintenanceEntry ? 'text-orange-600' : 'text-blue-600'}`}>
                        {entry.isMaintenanceEntry ? `${entry.manutencaoMin} MIN` : formatWeight(entry.netWeight)}
                      </span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase">
                        {entry.isMaintenanceEntry ? 'Downtime' : 'Líquido'}
                      </span>
                    </div>
                    <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                  </div>
                </div>
              ))
            ) : (
              <div className="p-8 text-center text-slate-300 text-xs font-bold uppercase tracking-widest">Nenhum lançamento encontrado</div>
            )}
          </div>
        </div>
      </main>

      <LaunchModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} 
        operators={operators}
        activeMachines={activeMachines}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, UserPlus, RefreshCw, Filter, Image as ImageIcon, Info, Power, Users, Wrench, Printer } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '3.9'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  // Refs para exportação de imagem do card COMPLETO
  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleDeleteOperator = (op: string) => {
    if (confirm(`Deseja remover o operador "${op}" da lista ativa? Os lançamentos existentes não serão apagados.`)) {
      setOperators(prev => prev.filter(item => item !== op));
      if (selectedOperator === op) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;

    // Filtra para remover o botão de download da captura
    const filter = (node: HTMLElement) => {
      const isButton = node.tagName === 'BUTTON' || node.classList?.contains('no-export');
      return !isButton;
    };

    toPng(containerRef.current, { 
      filter, 
      backgroundColor: '#ffffff',
      pixelRatio: 2, // Garante alta resolução
      style: {
        transform: 'scale(1)', // Reseta qualquer zoom
      }
    })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    })
    .catch((err) => {
      console.error('Falha ao exportar card:', err);
      alert('Houve um erro ao gerar a imagem. Tente novamente ou use a opção de Imprimir Relatório.');
    });
  };

  const exportToCSV = () => {
    const headers = [
      'ID', 'Data', 'Operador', 'Maquina', 'Turno', 
      'Peso Bruto (kg)', 'Tara (kg)', 'Peso Liquido (kg)', 'Volumes', 'Tubetes (kg)',
      'Eco A (kg)', 'Eco B P (kg)', 'Eco B M (kg)', 'Borra Total (kg)',
      'Manutencao Min', 'Manutencao Motivo',
      'Processo Min', 'Processo Motivo',
      'Outros Min', 'Outros Motivo', 'Apenas Manutencao'
    ];

    const csvRows = filteredData.map(entry => [
      entry.id,
      entry.date,
      entry.operator,
      entry.machine,
      entry.shift,
      entry.grossWeight,
      entry.tara,
      entry.netWeight,
      entry.volumes,
      entry.tubetes,
      entry.ecoA,
      entry.ecoBP,
      entry.ecoBM,
      entry.borraTotal,
      entry.manutencaoMin,
      `"${entry.manutencaoMotivo || ''}"`,
      entry.processoMin,
      `"${entry.processoMotivo || ''}"`,
      entry.outrosMin,
      `"${entry.outrosMotivo || ''}"`,
      entry.isMaintenanceEntry ? 'SIM' : 'NAO'
    ]);

    const csvContent = [
      headers.join(','),
      ...csvRows.map(row => row.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `relatorio_producao_${new Date().getTime()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN`;
    if (val >= 1000) {
      return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    }
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#f59e0b', '#3b82f6', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4', '#8b5cf6', '#10b981'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });
      return Object.entries(performanceMap)
        .map(([name, kg], index) => ({ 
          name, 
          value: kg, 
          color: colors[index % colors.length],
          unit: 'KG'
        }))
        .sort((a, b) => b.value - a.value);
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, color: '#3b82f6', unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, color: '#10b981', unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, color: '#f59e0b', unit: 'KG' },
        { name: 'BORRA', value: stats.borra, color: '#ef4444', unit: 'KG' }
      ].filter(d => d.value > 0);
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => [
    { name: 'MANUTENÇÃO', value: stats.manut, color: '#f97316' },
    { name: 'PROCESSO', value: stats.proc, color: '#f59e0b' },
    { name: 'OUTROS', value: stats.outros, color: '#94a3b8' }
  ].filter(d => d.value > 0), [stats]);

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const radius = outerRadius + 14; 
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';

    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="bold">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    return (
      <div className="grid grid-cols-2 gap-x-6 gap-y-3 mt-8 max-w-lg mx-auto px-4 justify-items-center">
        {payload.map((entry: any, index: number) => {
          const data = entry.payload;
          const total = (data.unit === 'KG' || !data.unit) ? stats.totalNet : stats.paradas;
          const perc = total > 0 ? ((data.value / total) * 100).toFixed(1) : "0";
          return (
            <div key={`item-${index}`} className="flex items-center gap-2 w-full max-w-[200px]">
              <div className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-bold text-slate-700 uppercase truncate">{entry.value}:</span>
                <div className="flex items-baseline gap-1">
                  <span className="text-[10px] font-black text-blue-600">{formatWeight(data.value, data.unit)}</span>
                  <span className="text-[8px] font-medium text-slate-400 shrink-0">({perc}%)</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Menu Lateral */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Mensal (KG)
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro de Equipe
            </h3>

            <div className="space-y-1 max-h-40 overflow-y-auto custom-scrollbar pr-1">
              {operators.map(op => (
                <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg group transition-colors hover:bg-slate-100">
                  <span className="text-[11px] font-bold text-slate-700">{op}</span>
                  <button 
                    onClick={() => handleDeleteOperator(op)}
                    className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                    title="Remover Operador"
                  >
                    <Trash2 size={12} />
                  </button>
                </div>
              ))}
            </div>

            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold focus:outline-none"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <Plus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      {/* Header Fixo */}
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={handlePrint} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-all border border-slate-200" title="Imprimir Relatório">
              <Printer size={18} />
           </button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo Lançamento</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Status das Máquinas */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className={`bg-white rounded-2xl p-4 shadow-sm border transition-all ${m.status === 'Operando' ? 'border-slate-100' : 'border-orange-200 shadow-orange-50 bg-orange-50/10'}`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button 
                  onClick={() => toggleMachineStatus(m.name)}
                  className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50 hover:bg-emerald-100' : 'text-orange-600 bg-orange-50 hover:bg-orange-100'}`}
                  title={m.status === 'Operando' ? "Parar para Manutenção" : "Colocar em Operação"}
                >
                  <Power size={14} />
                </button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                    <div className={`w-1.5 h-1.5 rounded-full ${m.color === 'emerald' ? 'bg-emerald-500 animate-pulse' : 'bg-orange-500'}`}></div>
                  </div>
                  <p className="text-[9px] text-slate-400 font-medium">Últ. Op: {m.lastOp}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Filtro Visual no-print */}
        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200 no-print">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button 
                  key={m} onClick={() => setSelectedMachine(m)}
                  className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Métricas */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Período</span>
            <span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span>
          </div>
        </div>

        {/* Card de Meta */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500 shadow-emerald-100' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                 Meta Mensal ({currentMonthName})
               </span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div 
              className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} 
              style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}
            ></div>
          </div>
        </div>

        {/* Gráficos com exportação de card completo */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Card Produção */}
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Distribuição de Produção</h3>
              <div className="flex items-center gap-2 no-print">
                <button 
                  onClick={() => downloadCardAsImage(prodCardRef, 'distribuicao_producao')}
                  className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all no-export"
                  title="Baixar Card como PNG"
                >
                  <Download size={16} />
                </button>
                <ImageIcon size={16} className="text-slate-200" />
              </div>
            </div>

            <div className="h-[400px] w-full pt-4">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={70} 
                      dataKey="value" label={renderCustomLabel} paddingAngle={4}
                    >
                      {mainChartData.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM DADOS</p>}
            </div>

            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl">
              <Info size={14} className="text-blue-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Visualização do volume por operador ou composição do material no período filtrado.</p>
            </div>
          </div>

          {/* Card Paradas */}
          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Motivos de Paradas</h3>
              <div className="flex items-center gap-2 no-print">
                <button 
                  onClick={() => downloadCardAsImage(stopCardRef, 'motivos_paradas')}
                  className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all no-export"
                  title="Baixar Card como PNG"
                >
                  <Download size={16} />
                </button>
                <AlertTriangle size={16} className="text-slate-200" />
              </div>
            </div>

            <div className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={70} 
                      dataKey="value" label={renderCustomLabel} paddingAngle={6}
                    >
                      {downtimePieData.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM PARADAS</p>}
            </div>

            <div className="mt-auto pt-4 flex items-start gap-2 bg-slate-50 p-3 rounded-xl">
              <Info size={14} className="text-slate-400 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Análise detalhada do tempo perdido por categoria: Manutenção, Processo e Outros.</p>
            </div>
          </div>
        </div>

        {/* Histórico */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden no-print">
          <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico de Lançamentos</h3>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.length > 0 ? (
              filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
                <div key={entry.id} className={`p-4 flex items-center justify-between hover:bg-slate-50/50 ${entry.isMaintenanceEntry ? 'bg-orange-50/30' : ''}`}>
                  <div className="flex items-center gap-4">
                    <div className={`w-1.5 h-10 rounded-full ${entry.isMaintenanceEntry ? 'bg-orange-500' : (entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600')}`}></div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                        <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                        {entry.isMaintenanceEntry && (
                          <span className="text-[8px] bg-orange-600 text-white px-2 py-0.5 rounded-full font-black uppercase flex items-center gap-1">
                            <Wrench size={8} /> MANUTENÇÃO
                          </span>
                        )}
                      </div>
                      <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                    </div>
                  </div>
                  <div className="text-right flex items-center gap-4">
                    <div>
                      <span className={`block font-black text-sm ${entry.isMaintenanceEntry ? 'text-orange-600' : 'text-blue-600'}`}>
                        {entry.isMaintenanceEntry ? `${entry.manutencaoMin} MIN` : formatWeight(entry.netWeight)}
                      </span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase">
                        {entry.isMaintenanceEntry ? 'Downtime' : 'Líquido'}
                      </span>
                    </div>
                    <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                  </div>
                </div>
              ))
            ) : (
              <div className="p-8 text-center text-slate-300 text-xs font-bold uppercase tracking-widest">Nenhum lançamento encontrado</div>
            )}
          </div>
        </div>
      </main>

      <LaunchModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} 
        operators={operators}
        activeMachines={activeMachines}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, UserPlus, RefreshCw, Filter, Image as ImageIcon, Info, Power, Users, Wrench, Printer } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.0'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleDeleteOperator = (op: string) => {
    if (confirm(`Deseja remover o operador "${op}" da lista ativa? Os lançamentos existentes não serão apagados.`)) {
      setOperators(prev => prev.filter(item => item !== op));
      if (selectedOperator === op) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;

    const filter = (node: HTMLElement) => {
      const isButton = node.tagName === 'BUTTON' || node.classList?.contains('no-export');
      return !isButton;
    };

    toPng(containerRef.current, { 
      filter, 
      backgroundColor: '#ffffff',
      pixelRatio: 2,
      style: { transform: 'scale(1)' }
    })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    })
    .catch((err) => {
      console.error('Falha ao exportar card:', err);
      alert('Houve um erro ao gerar a imagem.');
    });
  };

  const exportToCSV = () => {
    const headers = [
      'ID', 'Data', 'Operador', 'Maquina', 'Turno', 
      'Peso Bruto (kg)', 'Tara (kg)', 'Peso Liquido (kg)', 'Volumes', 'Tubetes (kg)',
      'Eco A (kg)', 'Eco B P (kg)', 'Eco B M (kg)', 'Borra Total (kg)',
      'Manutencao Min', 'Manutencao Motivo',
      'Processo Min', 'Processo Motivo',
      'Outros Min', 'Outros Motivo', 'Apenas Manutencao'
    ];

    const csvRows = filteredData.map(entry => [
      entry.id, entry.date, entry.operator, entry.machine, entry.shift,
      entry.grossWeight, entry.tara, entry.netWeight, entry.volumes, entry.tubetes,
      entry.ecoA, entry.ecoBP, entry.ecoBM, entry.borraTotal,
      entry.manutencaoMin, `"${entry.manutencaoMotivo || ''}"`,
      entry.processoMin, `"${entry.processoMotivo || ''}"`,
      entry.outrosMin, `"${entry.outrosMotivo || ''}"`,
      entry.isMaintenanceEntry ? 'SIM' : 'NAO'
    ]);

    const csvContent = [headers.join(','), ...csvRows.map(row => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `relatorio_producao_${new Date().getTime()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') {
      const hours = (val / 60).toFixed(1);
      return `${val.toLocaleString('pt-BR')} MIN (${hours}h)`;
    }
    if (val >= 1000) {
      return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    }
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#f59e0b', '#3b82f6', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4', '#8b5cf6', '#10b981'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });
      return Object.entries(performanceMap)
        .map(([name, kg], index) => ({ 
          name, 
          value: kg, 
          color: colors[index % colors.length],
          unit: 'KG'
        }))
        .sort((a, b) => b.value - a.value);
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, color: '#3b82f6', unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, color: '#10b981', unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, color: '#f59e0b', unit: 'KG' },
        { name: 'BORRA', value: stats.borra, color: '#ef4444', unit: 'KG' }
      ].filter(d => d.value > 0);
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => [
    { name: 'MANUTENÇÃO', value: stats.manut, color: '#f97316', unit: 'MIN' },
    { name: 'PROCESSO', value: stats.proc, color: '#f59e0b', unit: 'MIN' },
    { name: 'OUTROS', value: stats.outros, color: '#94a3b8', unit: 'MIN' }
  ].filter(d => d.value > 0), [stats]);

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const radius = outerRadius + 14; 
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';

    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="bold">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    return (
      <div className="grid grid-cols-2 gap-x-6 gap-y-3 mt-8 max-w-lg mx-auto px-4 justify-items-center">
        {payload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          const total = isMin ? stats.paradas : stats.totalNet;
          const perc = total > 0 ? ((data.value / total) * 100).toFixed(1) : "0";
          return (
            <div key={`item-${index}`} className="flex items-center gap-2 w-full max-w-[200px]">
              <div className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-bold text-slate-700 uppercase truncate">{entry.value}:</span>
                <div className="flex items-baseline gap-1">
                  <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                    {formatWeight(data.value, data.unit)}
                  </span>
                  <span className="text-[8px] font-medium text-slate-400 shrink-0">({perc}%)</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Mensal (KG)
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro de Equipe
            </h3>

            <div className="space-y-1 max-h-40 overflow-y-auto custom-scrollbar pr-1">
              {operators.map(op => (
                <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg group transition-colors hover:bg-slate-100">
                  <span className="text-[11px] font-bold text-slate-700">{op}</span>
                  <button 
                    onClick={() => handleDeleteOperator(op)}
                    className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                  >
                    <Trash2 size={12} />
                  </button>
                </div>
              ))}
            </div>

            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold focus:outline-none"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <Plus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={handlePrint} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-all border border-slate-200">
              <Printer size={18} />
           </button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo Lançamento</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className={`bg-white rounded-2xl p-4 shadow-sm border transition-all ${m.status === 'Operando' ? 'border-slate-100' : 'border-orange-200 bg-orange-50/10'}`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50 hover:bg-emerald-100' : 'text-orange-600 bg-orange-50 hover:bg-orange-100'}`}>
                  <Power size={14} />
                </button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                    <div className={`w-1.5 h-1.5 rounded-full ${m.color === 'emerald' ? 'bg-emerald-500 animate-pulse' : 'bg-orange-500'}`}></div>
                  </div>
                  <p className="text-[9px] text-slate-400 font-medium">Últ. Op: {m.lastOp}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200 no-print">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button key={m} onClick={() => setSelectedMachine(m)} className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>
                  {m}
                </button>
              ))}
           </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Período</span>
            <span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span>
          </div>
        </div>

        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Distribuição de Produção</h3>
              <div className="flex items-center gap-2 no-print">
                <button onClick={() => downloadCardAsImage(prodCardRef, 'distribuicao_producao')} className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg no-export">
                  <Download size={16} />
                </button>
                <ImageIcon size={16} className="text-slate-200" />
              </div>
            </div>
            <div className="h-[400px] w-full pt-4">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={70} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                      {mainChartData.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM DADOS</p>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl">
              <Info size={14} className="text-blue-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Visualização do volume por operador ou composição do material no período filtrado.</p>
            </div>
          </div>

          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Motivos de Paradas</h3>
              <div className="flex items-center gap-2 no-print">
                <button onClick={() => downloadCardAsImage(stopCardRef, 'motivos_paradas')} className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg no-export">
                  <Download size={16} />
                </button>
                <AlertTriangle size={16} className="text-slate-200" />
              </div>
            </div>
            <div className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={70} dataKey="value" label={renderCustomLabel} paddingAngle={6}>
                      {downtimePieData.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM PARADAS</p>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-slate-50 p-3 rounded-xl">
              <Info size={14} className="text-slate-400 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Análise detalhada do tempo perdido por categoria: Manutenção, Processo e Outros.</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden no-print">
          <div className="p-4 border-b border-slate-100 bg-slate-50">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico de Lançamentos</h3>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.length > 0 ? (
              filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
                <div key={entry.id} className={`p-4 flex items-center justify-between hover:bg-slate-50/50 ${entry.isMaintenanceEntry ? 'bg-orange-50/30' : ''}`}>
                  <div className="flex items-center gap-4">
                    <div className={`w-1.5 h-10 rounded-full ${entry.isMaintenanceEntry ? 'bg-orange-500' : (entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600')}`}></div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                        <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                        {entry.isMaintenanceEntry && <span className="text-[8px] bg-orange-600 text-white px-2 py-0.5 rounded-full font-black uppercase flex items-center gap-1"><Wrench size={8} /> MANUTENÇÃO</span>}
                      </div>
                      <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                    </div>
                  </div>
                  <div className="text-right flex items-center gap-4">
                    <div>
                      <span className={`block font-black text-sm ${entry.isMaintenanceEntry ? 'text-orange-600' : 'text-blue-600'}`}>{entry.isMaintenanceEntry ? formatWeight(entry.manutencaoMin, 'MIN') : formatWeight(entry.netWeight)}</span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase">{entry.isMaintenanceEntry ? 'Downtime' : 'Líquido'}</span>
                    </div>
                    <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                  </div>
                </div>
              ))
            ) : <div className="p-8 text-center text-slate-300 text-xs font-bold uppercase tracking-widest">Nenhum lançamento encontrado</div>}
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, UserPlus, RefreshCw, Filter, Image as ImageIcon, Info, Power, Users, Wrench, Printer } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.1'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleDeleteOperator = (op: string) => {
    if (confirm(`Deseja remover o operador "${op}" da lista ativa? Os lançamentos existentes não serão apagados.`)) {
      setOperators(prev => prev.filter(item => item !== op));
      if (selectedOperator === op) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;

    const filter = (node: HTMLElement) => {
      const isButton = node.tagName === 'BUTTON' || node.classList?.contains('no-export');
      return !isButton;
    };

    toPng(containerRef.current, { 
      filter, 
      backgroundColor: '#ffffff',
      pixelRatio: 2,
      style: { transform: 'scale(1)' }
    })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    })
    .catch((err) => {
      console.error('Falha ao exportar card:', err);
      alert('Houve um erro ao gerar a imagem.');
    });
  };

  const exportToCSV = () => {
    const headers = [
      'ID', 'Data', 'Operador', 'Maquina', 'Turno', 
      'Peso Bruto (kg)', 'Tara (kg)', 'Peso Liquido (kg)', 'Volumes', 'Tubetes (kg)',
      'Eco A (kg)', 'Eco B P (kg)', 'Eco B M (kg)', 'Borra Total (kg)',
      'Manutencao Min', 'Manutencao Motivo',
      'Processo Min', 'Processo Motivo',
      'Outros Min', 'Outros Motivo', 'Apenas Manutencao'
    ];

    const csvRows = filteredData.map(entry => [
      entry.id, entry.date, entry.operator, entry.machine, entry.shift,
      entry.grossWeight, entry.tara, entry.netWeight, entry.volumes, entry.tubetes,
      entry.ecoA, entry.ecoBP, entry.ecoBM, entry.borraTotal,
      entry.manutencaoMin, `"${entry.manutencaoMotivo || ''}"`,
      entry.processoMin, `"${entry.processoMotivo || ''}"`,
      entry.outrosMin, `"${entry.outrosMotivo || ''}"`,
      entry.isMaintenanceEntry ? 'SIM' : 'NAO'
    ]);

    const csvContent = [headers.join(','), ...csvRows.map(row => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `relatorio_producao_${new Date().getTime()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') {
      const hours = (val / 60).toFixed(1);
      return `${val.toLocaleString('pt-BR')} MIN (${hours}h)`;
    }
    if (val >= 1000) {
      return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    }
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#f59e0b', '#3b82f6', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4', '#8b5cf6', '#10b981'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });
      return Object.entries(performanceMap)
        .map(([name, kg], index) => ({ 
          name, 
          value: kg, 
          color: colors[index % colors.length],
          unit: 'KG'
        }))
        .sort((a, b) => b.value - a.value);
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, color: '#3b82f6', unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, color: '#10b981', unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, color: '#f59e0b', unit: 'KG' },
        { name: 'BORRA', value: stats.borra, color: '#ef4444', unit: 'KG' }
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value);
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => [
    { name: 'MANUTENÇÃO', value: stats.manut, color: '#f97316', unit: 'MIN' },
    { name: 'PROCESSO', value: stats.proc, color: '#f59e0b', unit: 'MIN' },
    { name: 'OUTROS', value: stats.outros, color: '#94a3b8', unit: 'MIN' }
  ].filter(d => d.value > 0).sort((a, b) => b.value - a.value), [stats]);

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, name, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const radius = outerRadius + 14; 
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';

    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="bold">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    return (
      <div className="grid grid-cols-2 gap-x-6 gap-y-3 mt-8 max-w-lg mx-auto px-4 justify-items-center">
        {payload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          const total = isMin ? stats.paradas : (stats.totalNet || 1);
          const perc = total > 0 ? ((data.value / total) * 100).toFixed(1) : "0";
          return (
            <div key={`item-${index}`} className="flex items-center gap-2 w-full max-w-[210px]">
              {/* Ranking Badge */}
              <div className="flex items-center justify-center w-5 h-5 rounded bg-slate-100 text-[8px] font-black text-slate-500 shrink-0 border border-slate-200 shadow-sm">
                {index + 1}º
              </div>
              <div className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-bold text-slate-700 uppercase truncate leading-tight">{entry.value}:</span>
                <div className="flex items-baseline gap-1">
                  <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                    {formatWeight(data.value, data.unit)}
                  </span>
                  <span className="text-[8px] font-medium text-slate-400 shrink-0">({perc}%)</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Mensal (KG)
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro de Equipe
            </h3>

            <div className="space-y-1 max-h-40 overflow-y-auto custom-scrollbar pr-1">
              {operators.map(op => (
                <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg group transition-colors hover:bg-slate-100">
                  <span className="text-[11px] font-bold text-slate-700">{op}</span>
                  <button 
                    onClick={() => handleDeleteOperator(op)}
                    className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                  >
                    <Trash2 size={12} />
                  </button>
                </div>
              ))}
            </div>

            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold focus:outline-none"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <Plus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={handlePrint} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-all border border-slate-200">
              <Printer size={18} />
           </button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo Lançamento</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className={`bg-white rounded-2xl p-4 shadow-sm border transition-all ${m.status === 'Operando' ? 'border-slate-100' : 'border-orange-200 bg-orange-50/10'}`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50 hover:bg-emerald-100' : 'text-orange-600 bg-orange-50 hover:bg-orange-100'}`}>
                  <Power size={14} />
                </button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                    <div className={`w-1.5 h-1.5 rounded-full ${m.color === 'emerald' ? 'bg-emerald-500 animate-pulse' : 'bg-orange-500'}`}></div>
                  </div>
                  <p className="text-[9px] text-slate-400 font-medium">Últ. Op: {m.lastOp}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200 no-print">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button key={m} onClick={() => setSelectedMachine(m)} className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>
                  {m}
                </button>
              ))}
           </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Período</span>
            <span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span>
          </div>
        </div>

        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Card Distribuição com Ranking na Legenda */}
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Ranking de Produção</h3>
              <div className="flex items-center gap-2 no-print">
                <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_producao')} className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg no-export">
                  <Download size={16} />
                </button>
                <ImageIcon size={16} className="text-slate-200" />
              </div>
            </div>
            <div className="h-[400px] w-full pt-4">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={70} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                      {mainChartData.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM DADOS</p>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl">
              <Info size={14} className="text-blue-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Ranking baseado no volume total produzido. As posições são recalculadas conforme os filtros aplicados.</p>
            </div>
          </div>

          {/* Card Paradas com Ranking na Legenda */}
          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Motivos de Paradas</h3>
              <div className="flex items-center gap-2 no-print">
                <button onClick={() => downloadCardAsImage(stopCardRef, 'motivos_paradas')} className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg no-export">
                  <Download size={16} />
                </button>
                <AlertTriangle size={16} className="text-slate-200" />
              </div>
            </div>
            <div className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={70} dataKey="value" label={renderCustomLabel} paddingAngle={6}>
                      {downtimePieData.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM PARADAS</p>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-slate-50 p-3 rounded-xl">
              <Info size={14} className="text-slate-400 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Análise detalhada do tempo perdido por categoria, ordenada pela criticidade (maior tempo).</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden no-print">
          <div className="p-4 border-b border-slate-100 bg-slate-50">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico de Lançamentos</h3>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.length > 0 ? (
              filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
                <div key={entry.id} className={`p-4 flex items-center justify-between hover:bg-slate-50/50 ${entry.isMaintenanceEntry ? 'bg-orange-50/30' : ''}`}>
                  <div className="flex items-center gap-4">
                    <div className={`w-1.5 h-10 rounded-full ${entry.isMaintenanceEntry ? 'bg-orange-500' : (entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600')}`}></div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                        <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                        {entry.isMaintenanceEntry && <span className="text-[8px] bg-orange-600 text-white px-2 py-0.5 rounded-full font-black uppercase flex items-center gap-1"><Wrench size={8} /> MANUTENÇÃO</span>}
                      </div>
                      <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                    </div>
                  </div>
                  <div className="text-right flex items-center gap-4">
                    <div>
                      <span className={`block font-black text-sm ${entry.isMaintenanceEntry ? 'text-orange-600' : 'text-blue-600'}`}>{entry.isMaintenanceEntry ? formatWeight(entry.manutencaoMin, 'MIN') : formatWeight(entry.netWeight)}</span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase">{entry.isMaintenanceEntry ? 'Downtime' : 'Líquido'}</span>
                    </div>
                    <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                  </div>
                </div>
              ))
            ) : <div className="p-8 text-center text-slate-300 text-xs font-bold uppercase tracking-widest">Nenhum lançamento encontrado</div>}
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, UserPlus, RefreshCw, Filter, Image as ImageIcon, Info, Power, Users, Wrench, Printer } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.2'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleDeleteOperator = (op: string) => {
    if (confirm(`Deseja remover o operador "${op}" da lista ativa? Os lançamentos existentes não serão apagados.`)) {
      setOperators(prev => prev.filter(item => item !== op));
      if (selectedOperator === op) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;

    const filter = (node: HTMLElement) => {
      const isButton = node.tagName === 'BUTTON' || node.classList?.contains('no-export');
      return !isButton;
    };

    toPng(containerRef.current, { 
      filter, 
      backgroundColor: '#ffffff',
      pixelRatio: 2,
      style: { transform: 'scale(1)' }
    })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    })
    .catch((err) => {
      console.error('Falha ao exportar card:', err);
      alert('Houve um erro ao gerar a imagem.');
    });
  };

  const exportToCSV = () => {
    const headers = [
      'ID', 'Data', 'Operador', 'Maquina', 'Turno', 
      'Peso Bruto (kg)', 'Tara (kg)', 'Peso Liquido (kg)', 'Volumes', 'Tubetes (kg)',
      'Eco A (kg)', 'Eco B P (kg)', 'Eco B M (kg)', 'Borra Total (kg)',
      'Manutencao Min', 'Manutencao Motivo',
      'Processo Min', 'Processo Motivo',
      'Outros Min', 'Outros Motivo', 'Apenas Manutencao'
    ];

    const csvRows = filteredData.map(entry => [
      entry.id, entry.date, entry.operator, entry.machine, entry.shift,
      entry.grossWeight, entry.tara, entry.netWeight, entry.volumes, entry.tubetes,
      entry.ecoA, entry.ecoBP, entry.ecoBM, entry.borraTotal,
      entry.manutencaoMin, `"${entry.manutencaoMotivo || ''}"`,
      entry.processoMin, `"${entry.processoMotivo || ''}"`,
      entry.outrosMin, `"${entry.outrosMotivo || ''}"`,
      entry.isMaintenanceEntry ? 'SIM' : 'NAO'
    ]);

    const csvContent = [headers.join(','), ...csvRows.map(row => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `relatorio_producao_${new Date().getTime()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') {
      const hours = (val / 60).toFixed(1);
      return `${val.toLocaleString('pt-BR')} MIN (${hours}h)`;
    }
    if (val >= 1000) {
      return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    }
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    // Cores ordenadas por "intensidade" ou preferência visual para o ranking
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4', '#8b5cf6'];

    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      filteredData.forEach(entry => {
        performanceMap[entry.operator] = (performanceMap[entry.operator] || 0) + entry.netWeight;
      });

      // ORDENAÇÃO RIGOROSA: Primeiro ordenamos os pares [nome, kg] pelo volume
      return Object.entries(performanceMap)
        .sort((a, b) => b[1] - a[1]) // Maior produção primeiro
        .map(([name, kg], index) => ({ 
          name, 
          value: kg, 
          color: colors[index % colors.length], // Cor atribuída pela posição no ranking
          unit: 'KG'
        }));
    } else {
      // Quando um operador específico é selecionado, rankeamos os componentes da produção dele
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' },
        { name: 'BORRA', value: stats.borra, unit: 'KG' }
      ]
      .filter(d => d.value > 0)
      .sort((a, b) => b.value - a.value)
      .map((item, index) => ({
        ...item,
        color: colors[index % colors.length]
      }));
    }
  }, [filteredData, selectedOperator, stats]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN' }
    ]
    .filter(d => d.value > 0)
    .sort((a, b) => b.value - a.value) // Rankeia paradas pelo tempo gasto
    .map((item, index) => ({
      ...item,
      color: colors[index % colors.length]
    }));
  }, [stats]);

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';

    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    return (
      <div className="grid grid-cols-2 gap-x-6 gap-y-3 mt-8 max-w-lg mx-auto px-4 justify-items-center">
        {payload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          const total = isMin ? stats.paradas : (stats.totalNet || 1);
          const perc = total > 0 ? ((data.value / total) * 100).toFixed(1) : "0";

          return (
            <div key={`item-${index}`} className="flex items-center gap-2 w-full max-w-[210px]">
              {/* Ranking Badge - Fixado pela posição no array já ordenado */}
              <div className="flex items-center justify-center w-5 h-5 rounded-md bg-slate-100 text-[8px] font-black text-slate-600 shrink-0 border border-slate-200 shadow-sm">
                {index + 1}º
              </div>
              <div className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-bold text-slate-700 uppercase truncate leading-tight">{entry.value}:</span>
                <div className="flex items-baseline gap-1">
                  <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                    {formatWeight(data.value, data.unit)}
                  </span>
                  <span className="text-[8px] font-medium text-slate-400 shrink-0">({perc}%)</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Mensal (KG)
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro de Equipe
            </h3>

            <div className="space-y-1 max-h-40 overflow-y-auto custom-scrollbar pr-1">
              {operators.map(op => (
                <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg group transition-colors hover:bg-slate-100">
                  <span className="text-[11px] font-bold text-slate-700">{op}</span>
                  <button 
                    onClick={() => handleDeleteOperator(op)}
                    className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                  >
                    <Trash2 size={12} />
                  </button>
                </div>
              ))}
            </div>

            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold focus:outline-none"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <Plus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={handlePrint} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-all border border-slate-200">
              <Printer size={18} />
           </button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo Lançamento</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className={`bg-white rounded-2xl p-4 shadow-sm border transition-all ${m.status === 'Operando' ? 'border-slate-100' : 'border-orange-200 bg-orange-50/10'}`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50 hover:bg-emerald-100' : 'text-orange-600 bg-orange-50 hover:bg-orange-100'}`}>
                  <Power size={14} />
                </button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                    <div className={`w-1.5 h-1.5 rounded-full ${m.color === 'emerald' ? 'bg-emerald-500 animate-pulse' : 'bg-orange-500'}`}></div>
                  </div>
                  <p className="text-[9px] text-slate-400 font-medium">Últ. Op: {m.lastOp}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200 no-print">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button key={m} onClick={() => setSelectedMachine(m)} className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>
                  {m}
                </button>
              ))}
           </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Período</span>
            <span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span>
          </div>
        </div>

        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Card Distribuição com Ranking Rigoroso */}
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Ranking de Produção</h3>
              <div className="flex items-center gap-2 no-print">
                <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_producao')} className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg no-export" title="Exportar PNG">
                  <Download size={16} />
                </button>
                <ImageIcon size={16} className="text-slate-200" />
              </div>
            </div>
            <div className="h-[400px] w-full pt-4">
              {mainChartData.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={mainChartData} 
                      cx="50%" cy="45%" 
                      innerRadius={55} outerRadius={70} 
                      dataKey="value" 
                      label={renderCustomLabel} 
                      paddingAngle={4}
                    >
                      {mainChartData.map((e, i) => <Cell key={`cell-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM DADOS NO PERÍODO</p>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl">
              <Info size={14} className="text-blue-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Ranking baseado no volume total de produção líquida. A ordem na legenda reflete a posição exata de cada item.</p>
            </div>
          </div>

          {/* Card Motivos de Paradas com Ranking de Downtime */}
          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">Motivos de Paradas</h3>
              <div className="flex items-center gap-2 no-print">
                <button onClick={() => downloadCardAsImage(stopCardRef, 'motivos_paradas')} className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg no-export" title="Exportar PNG">
                  <Download size={16} />
                </button>
                <AlertTriangle size={16} className="text-slate-200" />
              </div>
            </div>
            <div className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={downtimePieData} 
                      cx="50%" cy="45%" 
                      innerRadius={55} outerRadius={70} 
                      dataKey="value" 
                      label={renderCustomLabel} 
                      paddingAngle={6}
                    >
                      {downtimePieData.map((e, i) => <Cell key={`cell-d-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <p className="text-center text-slate-300 text-xs mt-20">SEM PARADAS REGISTRADAS</p>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-slate-50 p-3 rounded-xl">
              <Info size={14} className="text-slate-400 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic">Análise de tempo perdido por categoria, ordenado do maior impacto para o menor.</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden no-print">
          <div className="p-4 border-b border-slate-100 bg-slate-50">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">Histórico de Lançamentos</h3>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.length > 0 ? (
              filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
                <div key={entry.id} className={`p-4 flex items-center justify-between hover:bg-slate-50/50 ${entry.isMaintenanceEntry ? 'bg-orange-50/30' : ''}`}>
                  <div className="flex items-center gap-4">
                    <div className={`w-1.5 h-10 rounded-full ${entry.isMaintenanceEntry ? 'bg-orange-500' : (entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600')}`}></div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                        <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                        {entry.isMaintenanceEntry && <span className="text-[8px] bg-orange-600 text-white px-2 py-0.5 rounded-full font-black uppercase flex items-center gap-1"><Wrench size={8} /> MANUTENÇÃO</span>}
                      </div>
                      <p className="text-[10px] text-slate-400 font-medium">{entry.date} • {entry.shift}</p>
                    </div>
                  </div>
                  <div className="text-right flex items-center gap-4">
                    <div>
                      <span className={`block font-black text-sm ${entry.isMaintenanceEntry ? 'text-orange-600' : 'text-blue-600'}`}>{entry.isMaintenanceEntry ? formatWeight(entry.manutencaoMin, 'MIN') : formatWeight(entry.netWeight)}</span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase">{entry.isMaintenanceEntry ? 'Downtime' : 'Líquido'}</span>
                    </div>
                    <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2"><Trash2 size={16} /></button>
                  </div>
                </div>
              ))
            ) : <div className="p-8 text-center text-slate-300 text-xs font-bold uppercase tracking-widest">Nenhum lançamento encontrado</div>}
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, UserPlus, RefreshCw, Filter, Image as ImageIcon, Info, Power, Users, Wrench, Printer } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.3'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const s = filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outskirts: 0, outros: 0 });

    const qualityEfficiency = s.totalGross > 0 ? (s.totalNet / s.totalGross) * 100 : 0;
    return { ...s, qualityEfficiency };
  }, [filteredData]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleDeleteOperator = (op: string) => {
    if (confirm(`Deseja remover o operador "${op}" da lista ativa? Os lançamentos existentes não serão apagados.`)) {
      setOperators(prev => prev.filter(item => item !== op));
      if (selectedOperator === op) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;

    const filter = (node: HTMLElement) => {
      const isButton = node.tagName === 'BUTTON' || node.classList?.contains('no-export');
      return !isButton;
    };

    toPng(containerRef.current, { 
      filter, 
      backgroundColor: '#ffffff',
      pixelRatio: 2,
      style: { transform: 'scale(1)' }
    })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    })
    .catch((err) => {
      console.error('Falha ao exportar card:', err);
      alert('Houve um erro ao gerar a imagem.');
    });
  };

  const exportToCSV = () => {
    const headers = [
      'ID', 'Data', 'Operador', 'Maquina', 'Turno', 
      'Peso Bruto (kg)', 'Tara (kg)', 'Peso Liquido (kg)', 'Volumes', 'Tubetes (kg)',
      'Eco A (kg)', 'Eco B P (kg)', 'Eco B M (kg)', 'Borra Total (kg)',
      'Manutencao Min', 'Manutencao Motivo',
      'Processo Min', 'Processo Motivo',
      'Outros Min', 'Outros Motivo', 'Apenas Manutencao'
    ];

    const csvRows = filteredData.map(entry => [
      entry.id, entry.date, entry.operator, entry.machine, entry.shift,
      entry.grossWeight, entry.tara, entry.netWeight, entry.volumes, entry.tubetes,
      entry.ecoA, entry.ecoBP, entry.ecoBM, entry.borraTotal,
      entry.manutencaoMin, `"${entry.manutencaoMotivo || ''}"`,
      entry.processoMin, `"${entry.processoMotivo || ''}"`,
      entry.outrosMin, `"${entry.outrosMotivo || ''}"`,
      entry.isMaintenanceEntry ? 'SIM' : 'NAO'
    ]);

    const csvContent = [headers.join(','), ...csvRows.map(row => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `relatorio_producao_${new Date().getTime()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') {
      const hours = (val / 60).toFixed(1);
      return `${val.toLocaleString('pt-BR')} MIN (${hours}h)`;
    }
    if (val >= 1000) {
      return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    }
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4', '#8b5cf6'];

    if (selectedOperator === 'Todos') {
      // 1. Initialize all operators with 0 production to ensure a full list
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });

      // 2. Sum filtered data
      filteredData.forEach(entry => {
        if (performanceMap[entry.operator] !== undefined) {
          performanceMap[entry.operator] += entry.netWeight;
        }
      });

      // 3. STRICT SORTING: Highest to lowest
      return Object.entries(performanceMap)
        .sort((a, b) => b[1] - a[1]) // STRICT SORT
        .map(([name, kg], index) => ({ 
          name, 
          value: kg, 
          color: colors[index % colors.length], 
          unit: 'KG'
        }));
    } else {
      // Components ranking for single operator
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' },
        { name: 'BORRA', value: stats.borra, unit: 'KG' }
      ]
      .filter(d => d.value > 0)
      .sort((a, b) => b.value - a.value) // STRICT SORT
      .map((item, index) => ({
        ...item,
        color: colors[index % colors.length]
      }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN' }
    ]
    .filter(d => d.value > 0)
    .sort((a, b) => b.value - a.value) // STRICT SORT
    .map((item, index) => ({
      ...item,
      color: colors[index % colors.length]
    }));
  }, [stats]);

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';

    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;

    // Payload should already be sorted because mainChartData is sorted
    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {payload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          const total = isMin ? stats.paradas : (stats.totalNet || 1);
          const perc = total > 0 ? ((data.value / (total || 1)) * 100).toFixed(1) : "0";

          // Styling for medals (Top 3)
          let rankColor = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankColor = "bg-amber-400 text-white border-amber-500 shadow-amber-100 shadow-md"; // Gold
          if (index === 1) rankColor = "bg-slate-300 text-white border-slate-400 shadow-slate-100 shadow-md"; // Silver
          if (index === 2) rankColor = "bg-orange-400 text-white border-orange-500 shadow-orange-100 shadow-md"; // Bronze

          return (
            <div key={`item-${index}`} className="flex items-center gap-2 p-1 rounded-lg transition-colors hover:bg-slate-50">
              {/* Badge representing strictly sorted rank */}
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border transition-all ${rankColor}`}>
                {index + 1}º
              </div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <div className="flex items-baseline gap-1">
                  <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                    {formatWeight(data.value, data.unit)}
                  </span>
                  <span className="text-[8px] font-medium text-slate-400 shrink-0">({perc}%)</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Menu Lateral */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
              <Settings size={20} className="text-blue-600" /> OPÇÕES
            </h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
              <X size={24} />
            </button>
          </div>

          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Target size={14} className="text-emerald-500" /> Meta Mensal (KG)
            </h3>
            <input 
              type="number" value={goalValue} 
              onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none"
            />
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Filter size={14} className="text-blue-500" /> Filtros Ativos
            </h3>

            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select 
                value={selectedOperator} 
                onChange={(e) => setSelectedOperator(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none"
              >
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (
                  <option key={op} value={op}>{op}</option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>

            <button 
              onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} 
              className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"
            >
              <RotateCcw size={14} /> Limpar Filtros
            </button>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} className="text-blue-500" /> Cadastro de Equipe
            </h3>

            <div className="space-y-1 max-h-40 overflow-y-auto custom-scrollbar pr-1">
              {operators.map(op => (
                <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg group transition-colors hover:bg-slate-100">
                  <span className="text-[11px] font-bold text-slate-700">{op}</span>
                  <button 
                    onClick={() => handleDeleteOperator(op)}
                    className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                  >
                    <Trash2 size={12} />
                  </button>
                </div>
              ))}
            </div>

            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input 
                type="text" placeholder="Nome..." value={newOperatorName}
                onChange={(e) => setNewOperatorName(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold focus:outline-none"
              />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl">
                <Plus size={16} />
              </button>
            </form>
          </div>

          <div className="mt-auto space-y-2 pb-6">
             <button onClick={exportToCSV} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">
                Exportar CSV <Download size={16} />
             </button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">
                Resetar Base <RefreshCw size={16} />
             </button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <Cpu size={18} />
          </div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={handlePrint} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-all border border-slate-200">
              <Printer size={18} />
           </button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 transition-all text-sm">
              <Plus size={18} />
              <span className="hidden sm:inline">Novo Lançamento</span>
           </button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Status das Máquinas */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className={`bg-white rounded-2xl p-4 shadow-sm border transition-all ${m.status === 'Operando' ? 'border-slate-100' : 'border-orange-200 bg-orange-50/10'}`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50 hover:bg-emerald-100' : 'text-orange-600 bg-orange-50 hover:bg-orange-100'}`}>
                  <Power size={14} />
                </button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                    <div className={`w-1.5 h-1.5 rounded-full ${m.color === 'emerald' ? 'bg-emerald-500 animate-pulse' : 'bg-orange-500'}`}></div>
                  </div>
                  <p className="text-[9px] text-slate-400 font-medium">Últ. Op: {m.lastOp}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Seletor de Máquina */}
        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200 no-print">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button key={m} onClick={() => setSelectedMachine(m)} className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Cards de Métricas Rápidas */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span>
            <span className="text-xl font-black text-emerald-500">{stats.qualityEfficiency.toFixed(1)}%</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span>
            <span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span>
            <span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span>
          </div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
            <span className="text-[9px] font-black text-slate-400 uppercase block">Produção Período</span>
            <span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span>
          </div>
        </div>

        {/* Meta Mensal Progress Bar */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>
                {goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%
            </span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
          </div>
        </div>

        {/* Dashboards Centrais */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Card Ranking de Produção Rigoroso */}
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">
                 LEADERBOARD DE PRODUÇÃO
              </h3>
              <div className="flex items-center gap-2 no-print">
                <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_producao')} className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg no-export" title="Exportar PNG">
                  <Download size={16} />
                </button>
                <ImageIcon size={16} className="text-slate-200" />
              </div>
            </div>
            <div className="h-[380px] w-full pt-4">
              {mainChartData.some(d => d.value > 0) ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={mainChartData.filter(d => d.value > 0)} 
                      cx="50%" cy="45%" 
                      innerRadius={55} outerRadius={70} 
                      dataKey="value" 
                      label={renderCustomLabel} 
                      paddingAngle={4}
                    >
                      {mainChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="flex flex-col items-center justify-center h-full gap-4 text-center">
                   <div className="p-6 bg-slate-50 rounded-full text-slate-300"><Users size={48} /></div>
                   <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Aguardando Lançamentos...</p>
                   <Legend verticalAlign="bottom" payload={mainChartData.map(d => ({ value: d.name, color: d.color, payload: d }))} content={renderGridLegend} />
                </div>
              )}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl border border-blue-100/50">
              <Info size={14} className="text-blue-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">O ranking é absoluto: 1º ao 8º lugar conforme o volume total produzido no período. Top 3 destacados com insígnias especiais.</p>
            </div>
          </div>

          {/* Card Motivos de Paradas */}
          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">CRITICIDADE DE PARADAS</h3>
              <div className="flex items-center gap-2 no-print">
                <button onClick={() => downloadCardAsImage(stopCardRef, 'motivos_paradas')} className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg no-export" title="Exportar PNG">
                  <Download size={16} />
                </button>
                <AlertTriangle size={16} className="text-slate-200" />
              </div>
            </div>
            <div className="h-[380px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={downtimePieData} 
                      cx="50%" cy="45%" 
                      innerRadius={55} outerRadius={70} 
                      dataKey="value" 
                      label={renderCustomLabel} 
                      paddingAngle={6}
                    >
                      {downtimePieData.map((e, i) => <Cell key={`cell-d-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                 <div className="flex flex-col items-center justify-center h-full gap-4 text-center">
                    <div className="p-6 bg-emerald-50 rounded-full text-emerald-300"><CheckCircle2 size={48} /></div>
                    <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Nenhuma Parada Registrada</p>
                 </div>
              )}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-orange-50/50 p-3 rounded-xl border border-orange-100/50">
              <Info size={14} className="text-orange-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Análise de tempo perdido por categoria, ordenado do maior impacto para o menor.</p>
            </div>
          </div>
        </div>

        {/* Histórico de Lançamentos */}
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden no-print">
          <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
            <h3 className="font-black text-slate-800 text-[10px] uppercase tracking-widest">FLUXO DE PRODUÇÃO RECENTE</h3>
            <span className="text-[9px] font-bold text-slate-400">{filteredData.length} LANÇAMENTOS</span>
          </div>
          <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto custom-scrollbar">
            {filteredData.length > 0 ? (
              filteredData.slice().sort((a, b) => b.date.localeCompare(a.date)).map((entry) => (
                <div key={entry.id} className={`p-4 flex items-center justify-between transition-colors hover:bg-slate-50/80 ${entry.isMaintenanceEntry ? 'bg-orange-50/30' : ''}`}>
                  <div className="flex items-center gap-4">
                    <div className={`w-1.5 h-10 rounded-full transition-all ${entry.isMaintenanceEntry ? 'bg-orange-500' : (entry.shift === 'Diurno' ? 'bg-amber-400' : 'bg-indigo-600')}`}></div>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-black text-slate-800 text-sm">{entry.operator}</span>
                        <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-0.5 rounded font-bold uppercase">{entry.machine}</span>
                        {entry.isMaintenanceEntry && <span className="text-[8px] bg-orange-600 text-white px-2 py-0.5 rounded-full font-black uppercase flex items-center gap-1"><Wrench size={8} /> MANUTENÇÃO</span>}
                      </div>
                      <p className="text-[10px] text-slate-400 font-medium tracking-tight">{entry.date} • {entry.shift}</p>
                    </div>
                  </div>
                  <div className="text-right flex items-center gap-4">
                    <div className="flex flex-col items-end">
                      <span className={`font-black text-sm tabular-nums ${entry.isMaintenanceEntry ? 'text-orange-600' : 'text-blue-600'}`}>{entry.isMaintenanceEntry ? formatWeight(entry.manutencaoMin, 'MIN') : formatWeight(entry.netWeight)}</span>
                      <span className="text-[9px] text-slate-400 font-bold uppercase tracking-wider">{entry.isMaintenanceEntry ? 'Downtime' : 'Peso Líquido'}</span>
                    </div>
                    <button onClick={() => handleDeleteEntry(entry.id)} className="text-slate-300 hover:text-red-500 p-2 transition-colors">
                       <Trash2 size={16} />
                    </button>
                  </div>
                </div>
              ))
            ) : <div className="p-12 text-center text-slate-300 text-xs font-bold uppercase tracking-widest">Nenhum lançamento encontrado para os filtros selecionados</div>}
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Image as ImageIcon, Info, Power, Users, Wrench, Printer } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.4'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => {
    return stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0;
  }, [stats]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleDeleteOperator = (op: string) => {
    if (confirm(`Deseja remover o operador "${op}" da lista ativa? Os lançamentos existentes não serão apagados.`)) {
      setOperators(prev => prev.filter(item => item !== op));
      if (selectedOperator === op) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    const filter = (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export'));
    toPng(containerRef.current, { filter, backgroundColor: '#ffffff', pixelRatio: 2 })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error(err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4', '#8b5cf6'];

    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => {
        if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0);
      });

      // ORDENAÇÃO DE RANKING MATEMÁTICO: O maior sempre primeiro (1º)
      return Object.entries(performanceMap)
        .sort((a, b) => b[1] - a[1]) // Garantia de ordenação decrescente
        .map(([name, kg], index) => ({ 
          name, 
          value: kg, 
          color: colors[index % colors.length], 
          unit: 'KG'
        }));
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' },
        { name: 'BORRA', value: stats.borra, unit: 'KG' }
      ]
      .filter(d => d.value > 0)
      .sort((a, b) => b.value - a.value)
      .map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN' }
    ]
    .filter(d => d.value > 0)
    .sort((a, b) => b.value - a.value)
    .map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;

    // FORÇAR ORDENAÇÃO NO COMPONENTE DE LEGENDA PARA EVITAR DESVIO VISUAL
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);

    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          const total = isMin ? stats.paradas : (stats.totalNet || 1);
          const perc = total > 0 ? ((data.value / (total || 1)) * 100).toFixed(1) : "0";

          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";

          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>
                {index + 1}º
              </div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <div className="flex items-baseline gap-1">
                  <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                    {formatWeight(data.value, data.unit)}
                  </span>
                  <span className="text-[8px] font-medium text-slate-400 shrink-0">({perc}%)</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Menu Lateral */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> OPÇÕES</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>
          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Target size={14} className="text-emerald-500" /> Meta Mensal (KG)</h3>
            <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none" />
          </div>
          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Filter size={14} className="text-blue-500" /> Filtros Ativos</h3>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select value={selectedOperator} onChange={(e) => setSelectedOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (<option key={op} value={op}>{op}</option>))}
              </select>
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>
            <button onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"><RotateCcw size={14} /> Limpar Filtros</button>
          </div>
          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Users size={14} className="text-blue-500" /> Cadastro de Equipe</h3>
            <div className="space-y-1 max-h-40 overflow-y-auto custom-scrollbar pr-1">
              {operators.map(op => (
                <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg group transition-colors hover:bg-slate-100">
                  <span className="text-[11px] font-bold text-slate-700">{op}</span>
                  <button onClick={() => handleDeleteOperator(op)} className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={12} /></button>
                </div>
              ))}
            </div>
            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input type="text" placeholder="Nome..." value={newOperatorName} onChange={(e) => setNewOperatorName(e.target.value)} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold focus:outline-none" />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl"><Plus size={16} /></button>
            </form>
          </div>
          <div className="mt-auto space-y-2 pb-6">
             <button onClick={() => {}} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">Exportar CSV <Download size={16} /></button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">Resetar Base <RefreshCw size={16} /></button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={handlePrint} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className={`bg-white rounded-2xl p-4 shadow-sm border transition-all ${m.status === 'Operando' ? 'border-slate-100' : 'border-orange-200 bg-orange-50/10'}`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50 hover:bg-emerald-100' : 'text-orange-600 bg-orange-50 hover:bg-orange-100'}`}><Power size={14} /></button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                    <div className={`w-1.5 h-1.5 rounded-full ${m.color === 'emerald' ? 'bg-emerald-500 animate-pulse' : 'bg-orange-500'}`}></div>
                  </div>
                  <p className="text-[9px] text-slate-400 font-medium">Últ. Op: {m.lastOp}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200 no-print">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button key={m} onClick={() => setSelectedMachine(m)} className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>{m}</button>
              ))}
           </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span><span className="text-xl font-black text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span><span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span><span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Produção Período</span><span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span></div>
        </div>

        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">LEADERBOARD DE PRODUÇÃO</h3>
              <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_producao')} className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[380px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={70} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {mainChartData.map((e, i) => <Cell key={`cell-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl border border-blue-100/50">
              <Info size={14} className="text-blue-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">O 1º lugar é obrigatoriamente ocupado pelo maior volume de produção líquida no período selecionado.</p>
            </div>
          </div>

          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">CRITICIDADE DE PARADAS</h3>
              <button onClick={() => downloadCardAsImage(stopCardRef, 'motivos_paradas')} className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[380px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={70} dataKey="value" label={renderCustomLabel} paddingAngle={6}>
                      {downtimePieData.map((e, i) => <Cell key={`cell-d-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                 <div className="flex flex-col items-center justify-center h-full gap-4 text-center">
                    <div className="p-6 bg-emerald-50 rounded-full text-emerald-300"><CheckCircle2 size={48} /></div>
                    <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Nenhuma Parada Registrada</p>
                 </div>
              )}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-orange-50/50 p-3 rounded-xl border border-orange-100/50">
              <Info size={14} className="text-orange-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Análise de tempo perdido por categoria, ordenado do maior impacto para o menor.</p>
            </div>
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Image as ImageIcon, Info, Power, Users, Wrench, Printer, Leaf } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.5'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => {
    return stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0;
  }, [stats]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleDeleteOperator = (op: string) => {
    if (confirm(`Deseja remover o operador "${op}" da lista ativa? Os lançamentos existentes não serão apagados.`)) {
      setOperators(prev => prev.filter(item => item !== op));
      if (selectedOperator === op) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    const filter = (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export'));
    toPng(containerRef.current, { filter, backgroundColor: '#ffffff', pixelRatio: 2 })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error(err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4', '#8b5cf6'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => {
        if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0);
      });
      return Object.entries(performanceMap).sort((a, b) => b[1] - a[1]).map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' },
        { name: 'BORRA', value: stats.borra, unit: 'KG' }
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  // Novo gráfico para Eco A
  const ecoAChartData = useMemo(() => {
    const colors = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#065f46', '#064e3b', '#10b981'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoA || 0);
    });
    return Object.entries(performanceMap).sort((a, b) => b[1] - a[1]).map(([name, kg], index) => ({ 
      name, value: kg, color: colors[index % colors.length], unit: 'KG'
    }));
  }, [filteredData, operators]);

  // Novo gráfico para Eco B
  const ecoBChartData = useMemo(() => {
    const colors = ['#8b5cf6', '#a78bfa', '#c4b5fd', '#ddd6fe', '#7c3aed', '#6d28d9', '#5b21b6', '#8b5cf6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoBP || 0) + (entry.ecoBM || 0);
    });
    return Object.entries(performanceMap).sort((a, b) => b[1] - a[1]).map(([name, kg], index) => ({ 
      name, value: kg, color: colors[index % colors.length], unit: 'KG'
    }));
  }, [filteredData, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN' }
    ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);
    const totalValue = sortedPayload.reduce((sum, entry) => sum + entry.payload.value, 0);

    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          const perc = totalValue > 0 ? ((data.value / (totalValue || 1)) * 100).toFixed(1) : "0";

          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";

          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>
                {index + 1}º
              </div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <div className="flex items-baseline gap-1">
                  <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                    {formatWeight(data.value, data.unit)}
                  </span>
                  <span className="text-[8px] font-medium text-slate-400 shrink-0">({perc}%)</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Menu Lateral */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> OPÇÕES</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>
          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Target size={14} className="text-emerald-500" /> Meta Mensal (KG)</h3>
            <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none" />
          </div>
          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Filter size={14} className="text-blue-500" /> Filtros Ativos</h3>
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
              <select value={selectedOperator} onChange={(e) => setSelectedOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                <option value="Todos">Todos os Operadores</option>
                {operators.map(op => (<option key={op} value={op}>{op}</option>))}
              </select>
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
              </div>
            </div>
            <button onClick={() => { setStartDate(''); setEndDate(''); setSelectedOperator('Todos'); setSelectedMachine('Todas'); }} className="w-full flex items-center justify-center gap-2 py-2 text-xs font-black text-slate-400 hover:text-blue-600 transition-colors uppercase border border-dashed border-slate-200 rounded-xl"><RotateCcw size={14} /> Limpar Filtros</button>
          </div>
          <div className="space-y-4 pt-4 border-t border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Users size={14} className="text-blue-500" /> Cadastro de Equipe</h3>
            <div className="space-y-1 max-h-40 overflow-y-auto custom-scrollbar pr-1">
              {operators.map(op => (
                <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg group transition-colors hover:bg-slate-100">
                  <span className="text-[11px] font-bold text-slate-700">{op}</span>
                  <button onClick={() => handleDeleteOperator(op)} className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={12} /></button>
                </div>
              ))}
            </div>
            <form onSubmit={handleAddOperator} className="flex gap-2">
              <input type="text" placeholder="Nome..." value={newOperatorName} onChange={(e) => setNewOperatorName(e.target.value)} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold focus:outline-none" />
              <button type="submit" className="p-2 bg-blue-600 text-white rounded-xl"><Plus size={16} /></button>
            </form>
          </div>
          <div className="mt-auto space-y-2 pb-6">
             <button onClick={() => {}} className="w-full bg-blue-50 text-blue-600 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-blue-100">Exportar CSV <Download size={16} /></button>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">Resetar Base <RefreshCw size={16} /></button>
          </div>
        </div>
      </div>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={handlePrint} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 flex items-center gap-2">
             {selectedOperator !== 'Todos' && <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 px-2 py-1 rounded">{selectedOperator}</span>}
             <Menu size={24} />
           </button>
        </div>
      </header>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className={`bg-white rounded-2xl p-4 shadow-sm border transition-all ${m.status === 'Operando' ? 'border-slate-100' : 'border-orange-200 bg-orange-50/10'}`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50 hover:bg-emerald-100' : 'text-orange-600 bg-orange-50 hover:bg-orange-100'}`}><Power size={14} /></button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                    <div className={`w-1.5 h-1.5 rounded-full ${m.color === 'emerald' ? 'bg-emerald-500 animate-pulse' : 'bg-orange-500'}`}></div>
                  </div>
                  <p className="text-[9px] text-slate-400 font-medium">Últ. Op: {m.lastOp}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="bg-white rounded-2xl p-2 shadow-sm border border-slate-200 no-print">
           <div className="flex bg-slate-100 p-1 rounded-xl w-full">
              {['Todas', 'Cast 1', 'Cast 2'].map(m => (
                <button key={m} onClick={() => setSelectedMachine(m)} className={`flex-1 px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-tight transition-all ${selectedMachine === m ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>{m}</button>
              ))}
           </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span><span className="text-xl font-black text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span><span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span><span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Produção Período</span><span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span></div>
        </div>

        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">LEADERBOARD DE PRODUÇÃO</h3>
              <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_producao')} className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[380px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={70} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {mainChartData.map((e, i) => <Cell key={`cell-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl border border-blue-100/50">
              <Info size={14} className="text-blue-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">O 1º lugar é obrigatoriamente ocupado pelo maior volume de produção líquida no período selecionado.</p>
            </div>
          </div>

          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">CRITICIDADE DE PARADAS</h3>
              <button onClick={() => downloadCardAsImage(stopCardRef, 'motivos_paradas')} className="p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[380px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={70} dataKey="value" label={renderCustomLabel} paddingAngle={6}>
                      {downtimePieData.map((e, i) => <Cell key={`cell-d-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                 <div className="flex flex-col items-center justify-center h-full gap-4 text-center">
                    <div className="p-6 bg-emerald-50 rounded-full text-emerald-300"><CheckCircle2 size={48} /></div>
                    <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Nenhuma Parada Registrada</p>
                 </div>
              )}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-orange-50/50 p-3 rounded-xl border border-orange-100/50">
              <Info size={14} className="text-orange-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Análise de tempo perdido por categoria, ordenado do maior impacto para o menor.</p>
            </div>
          </div>

          {/* Novo Card: Distribuição Eco A */}
          <div ref={ecoACardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">
                <Leaf size={14} className="text-emerald-500" /> DISTRIBUIÇÃO ECO A
              </h3>
              <button onClick={() => downloadCardAsImage(ecoACardRef, 'ranking_eco_a')} className="p-1.5 text-slate-300 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[380px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoAChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={70} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoAChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoA-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoAChartData.every(d => d.value === 0) && (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 italic text-xs uppercase font-bold">Sem dados de Eco A</div>
              )}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-emerald-50/50 p-3 rounded-xl border border-emerald-100/50">
              <Info size={14} className="text-emerald-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Ranking específico para a produção de material Eco A por operador.</p>
            </div>
          </div>

          {/* Novo Card: Distribuição Eco B */}
          <div ref={ecoBCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest flex items-center gap-2">
                <Leaf size={14} className="text-purple-500" /> DISTRIBUIÇÃO ECO B
              </h3>
              <button onClick={() => downloadCardAsImage(ecoBCardRef, 'ranking_eco_b')} className="p-1.5 text-slate-300 hover:text-purple-600 hover:bg-purple-50 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[380px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoBChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={70} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoBChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoB-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoBChartData.every(d => d.value === 0) && (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 italic text-xs uppercase font-bold">Sem dados de Eco B</div>
              )}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-purple-50/50 p-3 rounded-xl border border-purple-100/50">
              <Info size={14} className="text-purple-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Ranking consolidado (BP + BM) para a produção de material Eco B por operador.</p>
            </div>
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Image as ImageIcon, Info, Power, Users, Wrench, Printer, Leaf } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.6'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => {
    return stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0;
  }, [stats]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleDeleteEntry = (id: string) => {
    if (confirm('Deseja realmente excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleAddOperator = (e: React.FormEvent) => {
    e.preventDefault();
    if (newOperatorName.trim() && !operators.includes(newOperatorName.trim())) {
      setOperators(prev => [...prev, newOperatorName.trim()].sort());
      setNewOperatorName('');
    }
  };

  const handleDeleteOperator = (op: string) => {
    if (confirm(`Deseja remover o operador "${op}" da lista ativa? Os lançamentos existentes não serão apagados.`)) {
      setOperators(prev => prev.filter(item => item !== op));
      if (selectedOperator === op) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    const filter = (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export'));
    toPng(containerRef.current, { filter, backgroundColor: '#ffffff', pixelRatio: 2 })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error(err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  // LÓGICA DE RANKING RIGOROSA PARA PRODUÇÃO TOTAL
  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => {
        if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0);
      });
      // ORDENAÇÃO DECRESCENTE OBRIGATÓRIA
      return Object.entries(performanceMap)
        .sort((a, b) => b[1] - a[1]) 
        .map(([name, kg], index) => ({ 
          name, value: kg, color: colors[index % colors.length], unit: 'KG'
        }));
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' },
        { name: 'BORRA', value: stats.borra, unit: 'KG' }
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  // RANKING ECO A
  const ecoAChartData = useMemo(() => {
    const colors = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#065f46', '#064e3b', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoA || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  // RANKING ECO B
  const ecoBChartData = useMemo(() => {
    const colors = ['#8b5cf6', '#a78bfa', '#c4b5fd', '#ddd6fe', '#7c3aed', '#6d28d9', '#5b21b6', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoBP || 0) + (entry.ecoBM || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN' }
    ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;

    // GARANTIR QUE A LEGENDA SIGA A ORDEM DE VALOR
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);

    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';

          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";

          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>
                {index + 1}º
              </div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                  {formatWeight(data.value, data.unit)}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      {/* Menu Lateral Reutilizado */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> OPÇÕES</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>
          <div className="space-y-4">
             <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Filtrar Operador</label>
                <select value={selectedOperator} onChange={(e) => setSelectedOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                  <option value="Todos">Todos</option>
                  {operators.map(op => (<option key={op} value={op}>{op}</option>))}
                </select>
             </div>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200">Resetar Dados <RefreshCw size={16} /></button>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {/* Status Rápido */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span><span className="text-xl font-black text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span><span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span><span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span><span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span></div>
        </div>

        {/* Dashboard de Gráficos */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Card Produção Total - RANKING CORRIGIDO */}
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">LEADERBOARD PRODUÇÃO TOTAL</h3>
              <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_total')} className="p-1.5 text-slate-300 hover:text-blue-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4} isAnimationActive={false}>
                    {mainChartData.map((e, i) => <Cell key={`cell-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* Card Paradas */}
          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest text-orange-600">IMPACTO DE PARADAS</h3>
              <button onClick={() => downloadCardAsImage(stopCardRef, 'paradas')} className="p-1.5 text-slate-300 hover:text-orange-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={6}>
                      {downtimePieData.map((e, i) => <Cell key={`cell-d-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 font-bold uppercase text-xs">Sem paradas registradas</div>
              )}
            </div>
          </div>

          {/* Card ECO A - NOVO */}
          <div ref={ecoACardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-emerald-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO A</h3>
              <button onClick={() => downloadCardAsImage(ecoACardRef, 'ranking_ecoA')} className="p-1.5 text-slate-300 hover:text-emerald-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoAChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoAChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoA-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoAChartData.every(d => d.value === 0) && <div className="text-center text-slate-300 text-[10px] font-bold uppercase mt-20">Aguardando dados de Eco A</div>}
            </div>
          </div>

          {/* Card ECO B - NOVO */}
          <div ref={ecoBCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-purple-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO B</h3>
              <button onClick={() => downloadCardAsImage(ecoBCardRef, 'ranking_ecoB')} className="p-1.5 text-slate-300 hover:text-purple-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoBChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoBChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoB-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoBChartData.every(d => d.value === 0) && <div className="text-center text-slate-300 text-[10px] font-bold uppercase mt-20">Aguardando dados de Eco B</div>}
            </div>
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Info, Power, Users, Printer } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.7'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => {
    return stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0;
  }, [stats]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    const filter = (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export'));
    toPng(containerRef.current, { filter, backgroundColor: '#ffffff', pixelRatio: 2 })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error(err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  // LÓGICA DE RANKING RIGOROSA - ORDENAÇÃO POR VALOR DECRESCENTE
  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => {
        if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0);
      });
      // AQUI ESTÁ A CORREÇÃO: b[1] - a[1] garante que o maior valor fique no index 0 (1º lugar)
      return Object.entries(performanceMap)
        .sort((a, b) => b[1] - a[1]) 
        .map(([name, kg], index) => ({ 
          name, value: kg, color: colors[index % colors.length], unit: 'KG'
        }));
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' },
        { name: 'BORRA', value: stats.borra, unit: 'KG' }
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN' }
    ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);

    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';

          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";

          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>
                {index + 1}º
              </div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                  {formatWeight(data.value, data.unit)}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      {/* Header Revertido */}
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      {/* Menu Lateral Revertido */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> OPÇÕES</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>
          <div className="space-y-4">
             <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Filtrar Operador</label>
                <select value={selectedOperator} onChange={(e) => setSelectedOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                  <option value="Todos">Todos</option>
                  {operators.map(op => (<option key={op} value={op}>{op}</option>))}
                </select>
             </div>
             <div className="space-y-3 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Meta Mensal (KG)</h3>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none" />
             </div>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200 mt-auto">Resetar Dados <RefreshCw size={16} /></button>
          </div>
        </div>
      </div>

      <main className="max-w-4xl mx-auto p-4 space-y-6">
        {/* Status Máquinas */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                   <span className="text-sm font-bold text-slate-700 block">{m.status}</span>
                   <p className="text-[9px] text-slate-400 font-medium">Últ. Op: {m.lastOp}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Status Rápido */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span><span className="text-xl font-black text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span><span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span><span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span><span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span></div>
        </div>

        {/* Meta Mensal */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
          </div>
        </div>

        {/* Dashboard de Gráficos Revertido para 1x2 */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">LEADERBOARD PRODUÇÃO TOTAL</h3>
              <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_total')} className="p-1.5 text-slate-300 hover:text-blue-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4} isAnimationActive={false}>
                    {mainChartData.map((e, i) => <Cell key={`cell-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl border border-blue-100/50">
              <Info size={14} className="text-blue-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">O ranking é absoluto: o maior volume de produção ocupa obrigatoriamente a primeira posição (1º).</p>
            </div>
          </div>

          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest text-orange-600">IMPACTO DE PARADAS</h3>
              <button onClick={() => downloadCardAsImage(stopCardRef, 'paradas')} className="p-1.5 text-slate-300 hover:text-orange-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={6}>
                      {downtimePieData.map((e, i) => <Cell key={`cell-d-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 font-bold uppercase text-xs">Sem paradas registradas</div>
              )}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-orange-50/50 p-3 rounded-xl border border-orange-100/50">
              <Info size={14} className="text-orange-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Análise de tempo perdido por categoria, ordenado do maior impacto para o menor.</p>
            </div>
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Info, Power, Users, Printer, Leaf } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.7'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => {
    return stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0;
  }, [stats]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    const filter = (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export'));
    toPng(containerRef.current, { filter, backgroundColor: '#ffffff', pixelRatio: 2 })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error(err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  // LÓGICA DE RANKING RIGOROSA - ORDENAÇÃO POR VALOR DECRESCENTE
  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => {
        if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0);
      });
      return Object.entries(performanceMap)
        .sort((a, b) => b[1] - a[1]) 
        .map(([name, kg], index) => ({ 
          name, value: kg, color: colors[index % colors.length], unit: 'KG'
        }));
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' },
        { name: 'BORRA', value: stats.borra, unit: 'KG' }
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  // RANKING ECO A
  const ecoAChartData = useMemo(() => {
    const colors = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#065f46', '#064e3b', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoA || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  // RANKING ECO B
  const ecoBChartData = useMemo(() => {
    const colors = ['#8b5cf6', '#a78bfa', '#c4b5fd', '#ddd6fe', '#7c3aed', '#6d28d9', '#5b21b6', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoBP || 0) + (entry.ecoBM || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN' }
    ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);

    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';

          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";

          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>
                {index + 1}º
              </div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                  {formatWeight(data.value, data.unit)}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> OPÇÕES</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>
          <div className="space-y-4">
             <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Filtrar Operador</label>
                <select value={selectedOperator} onChange={(e) => setSelectedOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                  <option value="Todos">Todos</option>
                  {operators.map(op => (<option key={op} value={op}>{op}</option>))}
                </select>
             </div>
             <div className="space-y-3 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Meta Mensal (KG)</h3>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none" />
             </div>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200 mt-auto">Resetar Dados <RefreshCw size={16} /></button>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {/* Status Máquinas */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                   <span className="text-sm font-bold text-slate-700 block">{m.status}</span>
                   <p className="text-[9px] text-slate-400 font-medium">Últ. Op: {m.lastOp}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Status Rápido */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span><span className="text-xl font-black text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span><span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span><span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span><span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span></div>
        </div>

        {/* Meta Mensal */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
          </div>
        </div>

        {/* Dashboard de Gráficos em Grade 2x2 */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">LEADERBOARD PRODUÇÃO TOTAL</h3>
              <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_total')} className="p-1.5 text-slate-300 hover:text-blue-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4} isAnimationActive={false}>
                    {mainChartData.map((e, i) => <Cell key={`cell-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest text-orange-600">IMPACTO DE PARADAS</h3>
              <button onClick={() => downloadCardAsImage(stopCardRef, 'paradas')} className="p-1.5 text-slate-300 hover:text-orange-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={6}>
                      {downtimePieData.map((e, i) => <Cell key={`cell-d-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 font-bold uppercase text-xs">Sem paradas registradas</div>
              )}
            </div>
          </div>

          {/* Gráfico ECO A */}
          <div ref={ecoACardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-emerald-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO A</h3>
              <button onClick={() => downloadCardAsImage(ecoACardRef, 'ranking_ecoA')} className="p-1.5 text-slate-300 hover:text-emerald-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoAChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoAChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoA-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoAChartData.every(d => d.value === 0) && <div className="text-center text-slate-300 text-[10px] font-bold uppercase mt-20">Sem dados de Eco A</div>}
            </div>
          </div>

          {/* Gráfico ECO B */}
          <div ref={ecoBCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-purple-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO B</h3>
              <button onClick={() => downloadCardAsImage(ecoBCardRef, 'ranking_ecoB')} className="p-1.5 text-slate-300 hover:text-purple-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoBChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoBChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoB-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoBChartData.every(d => d.value === 0) && <div className="text-center text-slate-300 text-[10px] font-bold uppercase mt-20">Sem dados de Eco B</div>}
            </div>
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Info, Power, Users, Printer, Leaf } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.7'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => {
    return stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0;
  }, [stats]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      const lastEntry = [...productionData].filter(e => e.machine === m).sort((a, b) => b.date.localeCompare(a.date))[0];
      return { name: m, status, color, lastOp: lastEntry?.operator || '---' };
    });
  }, [productionData, machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    const filter = (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export'));
    toPng(containerRef.current, { filter, backgroundColor: '#ffffff', pixelRatio: 2 })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error(err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  // LÓGICA DE RANKING RIGOROSA - ORDENAÇÃO POR VALOR DECRESCENTE
  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => {
        if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0);
      });
      return Object.entries(performanceMap)
        .sort((a, b) => b[1] - a[1]) 
        .map(([name, kg], index) => ({ 
          name, value: kg, color: colors[index % colors.length], unit: 'KG'
        }));
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' },
        { name: 'BORRA', value: stats.borra, unit: 'KG' }
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  // RANKING ECO A
  const ecoAChartData = useMemo(() => {
    const colors = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#065f46', '#064e3b', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoA || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  // RANKING ECO B
  const ecoBChartData = useMemo(() => {
    const colors = ['#8b5cf6', '#a78bfa', '#c4b5fd', '#ddd6fe', '#7c3aed', '#6d28d9', '#5b21b6', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoBP || 0) + (entry.ecoBM || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN' }
    ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);

    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';

          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";

          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>
                {index + 1}º
              </div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                  {formatWeight(data.value, data.unit)}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> OPÇÕES</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>
          <div className="space-y-4">
             <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Filtrar Operador</label>
                <select value={selectedOperator} onChange={(e) => setSelectedOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                  <option value="Todos">Todos</option>
                  {operators.map(op => (<option key={op} value={op}>{op}</option>))}
                </select>
             </div>
             <div className="space-y-3 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Meta Mensal (KG)</h3>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none" />
             </div>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200 mt-auto">Resetar Dados <RefreshCw size={16} /></button>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {/* Status Máquinas */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                   <span className="text-sm font-bold text-slate-700 block">{m.status}</span>
                   <p className="text-[9px] text-slate-400 font-medium">Últ. Op: {m.lastOp}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Status Rápido */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span><span className="text-xl font-black text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span><span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span><span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span><span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span></div>
        </div>

        {/* Meta Mensal */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
          </div>
        </div>

        {/* Dashboard de Gráficos em Grade 2x2 */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Card Produção Total */}
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">LEADERBOARD PRODUÇÃO TOTAL</h3>
              <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_total')} className="p-1.5 text-slate-300 hover:text-blue-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4} isAnimationActive={false}>
                    {mainChartData.map((e, i) => <Cell key={`cell-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            {/* Descrição Adicionada */}
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl border border-blue-100/50">
              <Info size={14} className="text-blue-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">O ranking é absoluto: o maior volume de produção líquida ocupa obrigatoriamente a primeira posição (1º).</p>
            </div>
          </div>

          {/* Card Paradas */}
          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest text-orange-600">IMPACTO DE PARADAS</h3>
              <button onClick={() => downloadCardAsImage(stopCardRef, 'paradas')} className="p-1.5 text-slate-300 hover:text-orange-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={6}>
                      {downtimePieData.map((e, i) => <Cell key={`cell-d-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 font-bold uppercase text-xs">Sem paradas registradas</div>
              )}
            </div>
            {/* Descrição Adicionada */}
            <div className="mt-auto pt-4 flex items-start gap-2 bg-orange-50/50 p-3 rounded-xl border border-orange-100/50">
              <Info size={14} className="text-orange-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Análise de tempo perdido por categoria, ordenado do maior impacto para o menor no período.</p>
            </div>
          </div>

          {/* Card ECO A */}
          <div ref={ecoACardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-emerald-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO A</h3>
              <button onClick={() => downloadCardAsImage(ecoACardRef, 'ranking_ecoA')} className="p-1.5 text-slate-300 hover:text-emerald-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoAChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoAChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoA-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoAChartData.every(d => d.value === 0) && <div className="text-center text-slate-300 text-[10px] font-bold uppercase mt-20">Sem dados de Eco A</div>}
            </div>
            {/* Descrição Adicionada */}
            <div className="mt-auto pt-4 flex items-start gap-2 bg-emerald-50/50 p-3 rounded-xl border border-emerald-100/50">
              <Info size={14} className="text-emerald-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Ranking específico para a produção de material Eco A por operador no período selecionado.</p>
            </div>
          </div>

          {/* Card ECO B */}
          <div ref={ecoBCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-purple-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO B</h3>
              <button onClick={() => downloadCardAsImage(ecoBCardRef, 'ranking_ecoB')} className="p-1.5 text-slate-300 hover:text-purple-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoBChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoBChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoB-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoBChartData.every(d => d.value === 0) && <div className="text-center text-slate-300 text-[10px] font-bold uppercase mt-20">Sem dados de Eco B</div>}
            </div>
            {/* Descrição Adicionada */}
            <div className="mt-auto pt-4 flex items-start gap-2 bg-purple-50/50 p-3 rounded-xl border border-purple-100/50">
              <Info size={14} className="text-purple-500 mt-0.5" />
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Ranking consolidado (BP + BM) para a produção de material Eco B por operador.</p>
            </div>
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Info, Power, Users, Printer, Leaf } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.7'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [newOperatorName, setNewOperatorName] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => {
    return stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0;
  }, [stats]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      return { name: m, status, color };
    });
  }, [machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setIsMenuOpen(false);
    }
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    const filter = (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export'));
    toPng(containerRef.current, { filter, backgroundColor: '#ffffff', pixelRatio: 2 })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error(err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  // LÓGICA DE RANKING RIGOROSA
  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => {
        if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0);
      });
      return Object.entries(performanceMap)
        .sort((a, b) => b[1] - a[1]) 
        .map(([name, kg], index) => ({ 
          name, value: kg, color: colors[index % colors.length], unit: 'KG'
        }));
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' },
        { name: 'BORRA', value: stats.borra, unit: 'KG' }
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  // RANKING ECO A
  const ecoAChartData = useMemo(() => {
    const colors = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#065f46', '#064e3b', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoA || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  // RANKING ECO B
  const ecoBChartData = useMemo(() => {
    const colors = ['#8b5cf6', '#a78bfa', '#c4b5fd', '#ddd6fe', '#7c3aed', '#6d28d9', '#5b21b6', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoBP || 0) + (entry.ecoBM || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN' }
    ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);

    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';

          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";

          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>
                {index + 1}º
              </div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                  {formatWeight(data.value, data.unit)}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> OPÇÕES</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>
          <div className="space-y-4">
             <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Filtrar Operador</label>
                <select value={selectedOperator} onChange={(e) => setSelectedOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                  <option value="Todos">Todos</option>
                  {operators.map(op => (<option key={op} value={op}>{op}</option>))}
                </select>
             </div>
             <div className="space-y-3 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Meta Mensal (KG)</h3>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none" />
             </div>
             <button onClick={handleResetData} className="w-full bg-slate-100 text-slate-500 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-slate-200 mt-auto">Resetar Dados <RefreshCw size={16} /></button>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {/* Status Máquinas - SEM ÚLTIMO OPERADOR */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                   <span className="text-sm font-bold text-slate-700 block">{m.status}</span>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Status Rápido */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span><span className="text-xl font-black text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span><span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span><span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span><span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span></div>
        </div>

        {/* Meta Mensal */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
          </div>
        </div>

        {/* Dashboard de Gráficos em Grade 2x2 */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Card Produção Total */}
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">LEADERBOARD PRODUÇÃO TOTAL</h3>
              <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_total')} className="p-1.5 text-slate-300 hover:text-blue-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4} isAnimationActive={false}>
                    {mainChartData.map((e, i) => <Cell key={`cell-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl border border-blue-100/50">
              <span className="no-export"><Info size={14} className="text-blue-500 mt-0.5" /></span>
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">O ranking é absoluto: o maior volume de produção líquida ocupa obrigatoriamente a primeira posição (1º).</p>
            </div>
          </div>

          {/* Card Paradas */}
          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest text-orange-600">IMPACTO DE PARADAS</h3>
              <button onClick={() => downloadCardAsImage(stopCardRef, 'paradas')} className="p-1.5 text-slate-300 hover:text-orange-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={6}>
                      {downtimePieData.map((e, i) => <Cell key={`cell-d-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 font-bold uppercase text-xs">Sem paradas registradas</div>
              )}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-orange-50/50 p-3 rounded-xl border border-orange-100/50">
              <span className="no-export"><Info size={14} className="text-orange-500 mt-0.5" /></span>
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Análise de tempo perdido por categoria, ordenado do maior impacto para o menor no período.</p>
            </div>
          </div>

          {/* Card ECO A */}
          <div ref={ecoACardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-emerald-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO A</h3>
              <button onClick={() => downloadCardAsImage(ecoACardRef, 'ranking_ecoA')} className="p-1.5 text-slate-300 hover:text-emerald-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoAChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoAChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoA-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoAChartData.every(d => d.value === 0) && <div className="text-center text-slate-300 text-[10px] font-bold uppercase mt-20">Sem dados de Eco A</div>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-emerald-50/50 p-3 rounded-xl border border-emerald-100/50">
              <span className="no-export"><Info size={14} className="text-emerald-500 mt-0.5" /></span>
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Ranking específico para a produção de material Eco A por operador no período selecionado.</p>
            </div>
          </div>

          {/* Card ECO B */}
          <div ref={ecoBCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-purple-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO B</h3>
              <button onClick={() => downloadCardAsImage(ecoBCardRef, 'ranking_ecoB')} className="p-1.5 text-slate-300 hover:text-purple-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoBChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoBChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoB-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoBChartData.every(d => d.value === 0) && <div className="text-center text-slate-300 text-[10px] font-bold uppercase mt-20">Sem dados de Eco B</div>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-purple-50/50 p-3 rounded-xl border border-purple-100/50">
              <span className="no-export"><Info size={14} className="text-purple-500 mt-0.5" /></span>
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Ranking consolidado (BP + BM) para a produção de material Eco B por operador.</p>
            </div>
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Info, Power, Users, Printer, Leaf, Calendar } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.7'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => {
    return stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0;
  }, [stats]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      return { name: m, status, color };
    });
  }, [machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setSelectedMachine('Todas');
      setStartDate('');
      setEndDate('');
      setIsMenuOpen(false);
    }
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    const filter = (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export'));
    toPng(containerRef.current, { filter, backgroundColor: '#ffffff', pixelRatio: 2 })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error(err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  // LÓGICA DE RANKING
  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => {
        if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0);
      });
      return Object.entries(performanceMap)
        .sort((a, b) => b[1] - a[1]) 
        .map(([name, kg], index) => ({ 
          name, value: kg, color: colors[index % colors.length], unit: 'KG'
        }));
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' },
        { name: 'BORRA', value: stats.borra, unit: 'KG' }
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  // RANKING ECO A
  const ecoAChartData = useMemo(() => {
    const colors = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#065f46', '#064e3b', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoA || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  // RANKING ECO B
  const ecoBChartData = useMemo(() => {
    const colors = ['#8b5cf6', '#a78bfa', '#c4b5fd', '#ddd6fe', '#7c3aed', '#6d28d9', '#5b21b6', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoBP || 0) + (entry.ecoBM || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN' }
    ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);

    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';

          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";

          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>
                {index + 1}º
              </div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                  {formatWeight(data.value, data.unit)}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      {/* Menu Lateral Restaurado */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> MENU</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>

          <div className="space-y-6">
             {/* Seção de Filtros */}
             <div className="space-y-4">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Filter size={14} /> Filtros de Dados</h3>

                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                    <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-2 py-2 text-[10px] font-bold text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500/20" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                    <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-2 py-2 text-[10px] font-bold text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500/20" />
                  </div>
                </div>

                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Máquina</label>
                  <select value={selectedMachine} onChange={(e) => setSelectedMachine(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                    <option value="Todas">Todas as Máquinas</option>
                    <option value="Cast 1">Cast 1</option>
                    <option value="Cast 2">Cast 2</option>
                  </select>
                </div>

                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
                  <select value={selectedOperator} onChange={(e) => setSelectedOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                    <option value="Todos">Todos os Operadores</option>
                    {operators.map(op => (<option key={op} value={op}>{op}</option>))}
                  </select>
                </div>
             </div>

             {/* Seção de Metas */}
             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Target size={14} /> Configurações</h3>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Meta Mensal (KG)</label>
                  <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20" />
                </div>
             </div>

             {/* Botão de Reset */}
             <div className="pt-6">
                <button onClick={handleResetData} className="w-full bg-red-50 text-red-600 border border-red-100 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-red-100 transition-colors">
                  Resetar Dados <RefreshCw size={16} />
                </button>
             </div>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {/* Status Máquinas */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                   <span className="text-sm font-bold text-slate-700 block">{m.status}</span>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Status Rápido */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span><span className="text-xl font-black text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span><span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span><span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span><span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span></div>
        </div>

        {/* Meta Mensal */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
          </div>
        </div>

        {/* Dashboard de Gráficos em Grade 2x2 */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Card Produção Total */}
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">LEADERBOARD PRODUÇÃO TOTAL</h3>
              <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_total')} className="p-1.5 text-slate-300 hover:text-blue-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4} isAnimationActive={false}>
                    {mainChartData.map((e, i) => <Cell key={`cell-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl border border-blue-100/50">
              <span className="no-export"><Info size={14} className="text-blue-500 mt-0.5" /></span>
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">O ranking é absoluto: o maior volume de produção líquida ocupa obrigatoriamente a primeira posição (1º).</p>
            </div>
          </div>

          {/* Card Paradas */}
          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest text-orange-600">IMPACTO DE PARADAS</h3>
              <button onClick={() => downloadCardAsImage(stopCardRef, 'paradas')} className="p-1.5 text-slate-300 hover:text-orange-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={6}>
                      {downtimePieData.map((e, i) => <Cell key={`cell-d-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 font-bold uppercase text-xs">Sem paradas registradas</div>
              )}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-orange-50/50 p-3 rounded-xl border border-orange-100/50">
              <span className="no-export"><Info size={14} className="text-orange-500 mt-0.5" /></span>
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Análise de tempo perdido por categoria, ordenado do maior impacto para o menor no período.</p>
            </div>
          </div>

          {/* Card ECO A */}
          <div ref={ecoACardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-emerald-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO A</h3>
              <button onClick={() => downloadCardAsImage(ecoACardRef, 'ranking_ecoA')} className="p-1.5 text-slate-300 hover:text-emerald-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoAChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoAChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoA-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoAChartData.every(d => d.value === 0) && <div className="text-center text-slate-300 text-[10px] font-bold uppercase mt-20">Sem dados de Eco A</div>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-emerald-50/50 p-3 rounded-xl border border-emerald-100/50">
              <span className="no-export"><Info size={14} className="text-emerald-500 mt-0.5" /></span>
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Ranking específico para a produção de material Eco A por operador no período selecionado.</p>
            </div>
          </div>

          {/* Card ECO B */}
          <div ref={ecoBCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-purple-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO B</h3>
              <button onClick={() => downloadCardAsImage(ecoBCardRef, 'ranking_ecoB')} className="p-1.5 text-slate-300 hover:text-purple-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoBChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoBChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoB-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoBChartData.every(d => d.value === 0) && <div className="text-center text-slate-300 text-[10px] font-bold uppercase mt-20">Sem dados de Eco B</div>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-purple-50/50 p-3 rounded-xl border border-purple-100/50">
              <span className="no-export"><Info size={14} className="text-purple-500 mt-0.5" /></span>
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Ranking consolidado (BP + BM) para a produção de material Eco B por operador.</p>
            </div>
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Info, Power, Users, Printer, Leaf, Calendar, UserPlus } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.7'; 

const App: React.FC = () => {
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [newOperatorName, setNewOperatorName] = useState('');

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => {
    return stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0;
  }, [stats]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      const color = status === 'Operando' ? 'emerald' : 'orange';
      return { name: m, status, color };
    });
  }, [machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleAddOperator = () => {
    if (!newOperatorName.trim()) return;
    if (operators.includes(newOperatorName.trim())) {
      alert('Operador já cadastrado.');
      return;
    }
    setOperators(prev => [...prev, newOperatorName.trim()].sort());
    setNewOperatorName('');
  };

  const handleRemoveOperator = (name: string) => {
    if (confirm(`Deseja realmente excluir o operador ${name}?`)) {
      setOperators(prev => prev.filter(op => op !== name));
      if (selectedOperator === name) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setSelectedMachine('Todas');
      setStartDate('');
      setEndDate('');
      setIsMenuOpen(false);
    }
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    const filter = (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export'));
    toPng(containerRef.current, { filter, backgroundColor: '#ffffff', pixelRatio: 2 })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error(err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => {
        if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0);
      });
      return Object.entries(performanceMap)
        .sort((a, b) => b[1] - a[1]) 
        .map(([name, kg], index) => ({ 
          name, value: kg, color: colors[index % colors.length], unit: 'KG'
        }));
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' },
        { name: 'BORRA', value: stats.borra, unit: 'KG' }
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  const ecoAChartData = useMemo(() => {
    const colors = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#065f46', '#064e3b', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoA || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  const ecoBChartData = useMemo(() => {
    const colors = ['#8b5cf6', '#a78bfa', '#c4b5fd', '#ddd6fe', '#7c3aed', '#6d28d9', '#5b21b6', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoBP || 0) + (entry.ecoBM || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN' }
    ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);

    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';

          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";

          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>
                {index + 1}º
              </div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                  {formatWeight(data.value, data.unit)}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      {/* Menu Lateral Restaurado com Gerenciamento de Operadores */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> MENU</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>

          <div className="space-y-6">
             {/* Seção de Filtros */}
             <div className="space-y-4">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Filter size={14} /> Filtros de Dados</h3>

                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                    <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-2 py-2 text-[10px] font-bold text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500/20" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                    <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-2 py-2 text-[10px] font-bold text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500/20" />
                  </div>
                </div>

                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Máquina</label>
                  <select value={selectedMachine} onChange={(e) => setSelectedMachine(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                    <option value="Todas">Todas as Máquinas</option>
                    <option value="Cast 1">Cast 1</option>
                    <option value="Cast 2">Cast 2</option>
                  </select>
                </div>

                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
                  <select value={selectedOperator} onChange={(e) => setSelectedOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                    <option value="Todos">Todos os Operadores</option>
                    {operators.map(op => (<option key={op} value={op}>{op}</option>))}
                  </select>
                </div>
             </div>

             {/* Seção de Gerenciamento de Operadores */}
             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Users size={14} /> Gerenciar Operadores</h3>

                <div className="flex gap-2">
                  <input 
                    type="text" 
                    placeholder="Nome do operador" 
                    value={newOperatorName}
                    onChange={(e) => setNewOperatorName(e.target.value)}
                    className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                  />
                  <button 
                    onClick={handleAddOperator}
                    className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700 transition-colors"
                  >
                    <UserPlus size={16} />
                  </button>
                </div>

                <div className="max-h-40 overflow-y-auto custom-scrollbar space-y-1 pr-1">
                  {operators.map(op => (
                    <div key={op} className="flex items-center justify-between bg-slate-50 p-2 rounded-lg border border-slate-100 group">
                      <span className="text-[10px] font-bold text-slate-600">{op}</span>
                      <button 
                        onClick={() => handleRemoveOperator(op)}
                        className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>
                  ))}
                </div>
             </div>

             {/* Seção de Configurações */}
             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Target size={14} /> Configurações de Meta</h3>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Meta Mensal (KG)</label>
                  <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20" />
                </div>
             </div>

             {/* Botão de Reset */}
             <div className="pt-6">
                <button onClick={handleResetData} className="w-full bg-red-50 text-red-600 border border-red-100 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-red-100 transition-colors">
                  Resetar Todos Dados <RefreshCw size={16} />
                </button>
             </div>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {/* Status Máquinas */}
        <div className="grid grid-cols-2 gap-4">
          {machineStatusCards.map((m) => (
            <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
              <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
              </div>
              <div className="flex items-center gap-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                  {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                </div>
                <div>
                   <span className="text-sm font-bold text-slate-700 block">{m.status}</span>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Status Rápido */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span><span className="text-xl font-black text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span><span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span><span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
          <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span><span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span></div>
        </div>

        {/* Meta Mensal */}
        <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
          <div className="flex items-center justify-between mb-4">
            <div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
               <div className="flex items-baseline gap-2">
                  <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                  <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
               </div>
            </div>
            <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
          </div>
          <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
          </div>
        </div>

        {/* Dashboard de Gráficos em Grade 2x2 */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Card Produção Total */}
          <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">LEADERBOARD PRODUÇÃO TOTAL</h3>
              <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_total')} className="p-1.5 text-slate-300 hover:text-blue-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4} isAnimationActive={false}>
                    {mainChartData.map((e, i) => <Cell key={`cell-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-blue-50/50 p-3 rounded-xl border border-blue-100/50">
              <span className="no-export"><Info size={14} className="text-blue-500 mt-0.5" /></span>
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">O ranking é absoluto: o maior volume de produção líquida ocupa obrigatoriamente a primeira posição (1º).</p>
            </div>
          </div>

          {/* Card Paradas */}
          <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest text-orange-600">IMPACTO DE PARADAS</h3>
              <button onClick={() => downloadCardAsImage(stopCardRef, 'paradas')} className="p-1.5 text-slate-300 hover:text-orange-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              {stats.paradas > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={6}>
                      {downtimePieData.map((e, i) => <Cell key={`cell-d-${i}`} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" content={renderGridLegend} />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="flex flex-col items-center justify-center h-full text-slate-300 font-bold uppercase text-xs">Sem paradas registradas</div>
              )}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-orange-50/50 p-3 rounded-xl border border-orange-100/50">
              <span className="no-export"><Info size={14} className="text-orange-500 mt-0.5" /></span>
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Análise de tempo perdido por categoria, ordenado do maior impacto para o menor no período.</p>
            </div>
          </div>

          {/* Card ECO A */}
          <div ref={ecoACardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-emerald-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO A</h3>
              <button onClick={() => downloadCardAsImage(ecoACardRef, 'ranking_ecoA')} className="p-1.5 text-slate-300 hover:text-emerald-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoAChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoAChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoA-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoAChartData.every(d => d.value === 0) && <div className="text-center text-slate-300 text-[10px] font-bold uppercase mt-20">Sem dados de Eco A</div>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-emerald-50/50 p-3 rounded-xl border border-emerald-100/50">
              <span className="no-export"><Info size={14} className="text-emerald-500 mt-0.5" /></span>
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Ranking específico para a produção de material Eco A por operador no período selecionado.</p>
            </div>
          </div>

          {/* Card ECO B */}
          <div ref={ecoBCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-black text-purple-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO B</h3>
              <button onClick={() => downloadCardAsImage(ecoBCardRef, 'ranking_ecoB')} className="p-1.5 text-slate-300 hover:text-purple-600 rounded-lg no-export"><Download size={16} /></button>
            </div>
            <div className="h-[400px] w-full pt-4">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={ecoBChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                    {ecoBChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoB-${i}`} fill={e.color} stroke="none" />)}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" content={renderGridLegend} />
                </PieChart>
              </ResponsiveContainer>
              {ecoBChartData.every(d => d.value === 0) && <div className="text-center text-slate-300 text-[10px] font-bold uppercase mt-20">Sem dados de Eco B</div>}
            </div>
            <div className="mt-auto pt-4 flex items-start gap-2 bg-purple-50/50 p-3 rounded-xl border border-purple-100/50">
              <span className="no-export"><Info size={14} className="text-purple-500 mt-0.5" /></span>
              <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Ranking consolidado (BP + BM) para a produção de material Eco B por operador.</p>
            </div>
          </div>
        </div>
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Info, Power, Users, Printer, Leaf, Calendar, UserPlus, BarChart3, FileText, FileSpreadsheet } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.8'; 

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports'>('dashboard');
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [newOperatorName, setNewOperatorName] = useState('');

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    });
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  // Agrupamento Mensal para Relatórios
  const monthlyReports = useMemo(() => {
    const groups: Record<string, any> = {};

    productionData.forEach(entry => {
      const date = new Date(entry.date + 'T00:00:00');
      const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      const monthLabel = new Intl.DateTimeFormat('pt-BR', { month: 'long', year: 'numeric' }).format(date);

      if (!groups[key]) {
        groups[key] = {
          key,
          label: monthLabel.toUpperCase(),
          totalNet: 0,
          totalGross: 0,
          borra: 0,
          downtimeMin: 0,
          ecoA: 0,
          ecoB: 0,
          entries: 0
        };
      }

      groups[key].totalNet += entry.netWeight || 0;
      groups[key].totalGross += entry.grossWeight || 0;
      groups[key].borra += entry.borraTotal || 0;
      groups[key].downtimeMin += (entry.manutencaoMin || 0) + (entry.processoMin || 0) + (entry.outrosMin || 0);
      groups[key].ecoA += entry.ecoA || 0;
      groups[key].ecoB += (entry.ecoBP || 0) + (entry.ecoBM || 0);
      groups[key].entries += 1;
    });

    return Object.values(groups).sort((a, b) => b.key.localeCompare(a.key));
  }, [productionData]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => {
    return stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0;
  }, [stats]);

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const monthlyData = productionData.filter(entry => entry.date.startsWith(currentMonthPrefix));
    return monthlyData.reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => {
    return new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase();
  }, []);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => {
    const machines = ['Cast 1', 'Cast 2'];
    return machines.map(m => {
      const status = machineManualStatus[m] || 'Operando';
      return { name: m, status };
    });
  }, [machineManualStatus]);

  const toggleMachineStatus = (machineName: string) => {
    setMachineManualStatus(prev => ({
      ...prev,
      [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando'
    }));
  };

  const activeMachines = useMemo(() => {
    return Object.entries(machineManualStatus)
      .filter(([_, status]) => status === 'Operando')
      .map(([name]) => name);
  }, [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => {
    const entryWithId: ProductionEntry = {
      ...newEntry,
      id: Math.random().toString(36).substr(2, 9),
    };
    setProductionData(prev => [...prev, entryWithId]);
  };

  const handleAddOperator = () => {
    if (!newOperatorName.trim()) return;
    if (operators.includes(newOperatorName.trim())) {
      alert('Operador já cadastrado.');
      return;
    }
    setOperators(prev => [...prev, newOperatorName.trim()].sort());
    setNewOperatorName('');
  };

  const handleRemoveOperator = (name: string) => {
    if (confirm(`Deseja realmente excluir o operador ${name}?`)) {
      setOperators(prev => prev.filter(op => op !== name));
      if (selectedOperator === name) setSelectedOperator('Todos');
    }
  };

  const handleResetData = () => {
    if (confirm('Deseja resetar todos os dados?')) {
      setProductionData(INITIAL_DATA);
      setGoalValue(DEFAULT_GOAL);
      setSelectedOperator('Todos');
      setSelectedMachine('Todas');
      setStartDate('');
      setEndDate('');
      setIsMenuOpen(false);
    }
  };

  const exportMonthlyReportToCSV = () => {
    const headers = ['Mês', 'Produção Líquida (KG)', 'Eficiência (%)', 'Borra (KG)', 'Tempo Parado (Hrs)', 'Eco A (KG)', 'Eco B (KG)'];
    const rows = monthlyReports.map(r => [
      r.label,
      r.totalNet.toFixed(0),
      (r.totalGross > 0 ? (r.totalNet / r.totalGross) * 100 : 0).toFixed(1),
      r.borra.toFixed(0),
      (r.downtimeMin / 60).toFixed(1),
      r.ecoA.toFixed(0),
      r.ecoB.toFixed(0)
    ]);

    const csvContent = "data:text/csv;charset=utf-8," 
      + headers.join(",") + "\n" 
      + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `relatorio_mensal_manupackaging_${new Date().getFullYear()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    const filter = (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export'));
    toPng(containerRef.current, { filter, backgroundColor: '#ffffff', pixelRatio: 2 })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error(err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => {
        if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0);
      });
      return Object.entries(performanceMap)
        .sort((a, b) => b[1] - a[1]) 
        .map(([name, kg], index) => ({ 
          name, value: kg, color: colors[index % colors.length], unit: 'KG'
        }));
    } else {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' },
        { name: 'BORRA', value: stats.borra, unit: 'KG' }
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  const ecoAChartData = useMemo(() => {
    const colors = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#065f46', '#064e3b', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoA || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  const ecoBChartData = useMemo(() => {
    const colors = ['#8b5cf6', '#a78bfa', '#c4b5fd', '#ddd6fe', '#7c3aed', '#6d28d9', '#5b21b6', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => {
      if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoBP || 0) + (entry.ecoBM || 0);
    });
    return Object.entries(performanceMap)
      .sort((a, b) => b[1] - a[1])
      .map(([name, kg], index) => ({ 
        name, value: kg, color: colors[index % colors.length], unit: 'KG'
      }));
  }, [filteredData, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN' }
    ].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);

    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';

          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";

          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>
                {index + 1}º
              </div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>
                  {formatWeight(data.value, data.unit)}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">
          {`${(percent * 100).toFixed(1)}%`}
        </text>
      </g>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      {/* Navegação de Abas */}
      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="bg-slate-200/50 p-1 rounded-2xl inline-flex gap-1">
          <button 
            onClick={() => setActiveTab('dashboard')}
            className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <BarChart3 size={16} /> Dashboard
          </button>
          <button 
            onClick={() => setActiveTab('reports')}
            className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <FileText size={16} /> Relatórios
          </button>
        </div>
      </div>

      {/* Menu Lateral */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> MENU</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>

          <div className="space-y-6">
             <div className="space-y-4">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Filter size={14} /> Filtros de Dados</h3>

                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                    <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-2 py-2 text-[10px] font-bold text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500/20" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
