             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Users size={14} /> Gerenciar Operadores</h3>

                <div className="flex gap-2">
                  <input 
                    type="text" 
                    placeholder="Nome do operador" 
                    value={newOperatorName}
                    onChange={(e) => setNewOperatorName(e.target.value)}
                    className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                  />
                  <button 
                    onClick={handleAddOperator}
                    className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700 transition-colors"
                  >
                    <UserPlus size={16} />
                  </button>
                </div>

                <div className="max-h-40 overflow-y-auto custom-scrollbar space-y-1 pr-1">
                  {operators.map(op => (
                    <div key={op} className="flex items-center justify-between bg-slate-50 p-2 rounded-lg border border-slate-100 group">
                      <span className="text-[10px] font-bold text-slate-600">{op}</span>
                      <button 
                        onClick={() => handleRemoveOperator(op)}
                        className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>
                  ))}
                </div>
             </div>

             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Target size={14} /> Configurações de Meta</h3>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Meta Mensal (KG)</label>
                  <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20" />
                </div>
             </div>

             <div className="pt-6">
                <button onClick={handleResetData} className="w-full bg-red-50 text-red-600 border border-red-100 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-red-100 transition-colors">
                  Resetar Todos Dados <RefreshCw size={16} />
                </button>
             </div>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' ? (
          <>
            {/* Status Máquinas */}
            <div className="grid grid-cols-2 gap-4">
              {machineStatusCards.map((m) => (
                <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                    <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg transition-all no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
                  </div>
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                      {m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                    </div>
                    <div>
                       <span className="text-sm font-bold text-slate-700 block">{m.status}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {/* Status Rápido */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Eficiência</span><span className="text-xl font-black text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Total Borra</span><span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Paradas</span><span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] font-black text-slate-400 uppercase block">Produção Total</span><span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span></div>
            </div>

            {/* Meta Mensal */}
            <div className={`bg-white rounded-2xl p-6 shadow-sm border transition-all ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
              <div className="flex items-center justify-between mb-4">
                <div>
                   <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Meta Mensal ({currentMonthName})</span>
                   <div className="flex items-baseline gap-2">
                      <span className="text-4xl font-black text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span>
                      <span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span>
                   </div>
                </div>
                <span className={`text-3xl font-black ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
              </div>
              <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
                <div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
              </div>
            </div>

            {/* Gráficos */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
                <div className="flex items-center justify-between mb-2">
                  <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest">LEADERBOARD PRODUÇÃO TOTAL</h3>
                  <button onClick={() => downloadCardAsImage(prodCardRef, 'ranking_total')} className="p-1.5 text-slate-300 hover:text-blue-600 rounded-lg no-export"><Download size={16} /></button>
                </div>
                <div className="h-[400px] w-full pt-4">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={mainChartData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4} isAnimationActive={false}>
                        {mainChartData.map((e, i) => <Cell key={`cell-${i}`} fill={e.color} stroke="none" />)}
                      </Pie>
                      <Tooltip />
                      <Legend verticalAlign="bottom" content={renderGridLegend} />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="font-black text-slate-800 text-xs uppercase tracking-widest text-orange-600">IMPACTO DE PARADAS</h3>
                  <button onClick={() => downloadCardAsImage(stopCardRef, 'paradas')} className="p-1.5 text-slate-300 hover:text-orange-600 rounded-lg no-export"><Download size={16} /></button>
                </div>
                <div className="h-[400px] w-full pt-4">
                  {stats.paradas > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={downtimePieData} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={6}>
                          {downtimePieData.map((e, i) => <Cell key={`cell-d-${i}`} fill={e.color} stroke="none" />)}
                        </Pie>
                        <Tooltip />
                        <Legend verticalAlign="bottom" content={renderGridLegend} />
                      </PieChart>
                    </ResponsiveContainer>
                  ) : (
                    <div className="flex flex-col items-center justify-center h-full text-slate-300 font-bold uppercase text-xs">Sem paradas registradas</div>
                  )}
                </div>
              </div>

              <div ref={ecoACardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
                <div className="flex items-center justify-between mb-2">
                  <h3 className="font-black text-emerald-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO A</h3>
                  <button onClick={() => downloadCardAsImage(ecoACardRef, 'ranking_ecoA')} className="p-1.5 text-slate-300 hover:text-emerald-600 rounded-lg no-export"><Download size={16} /></button>
                </div>
                <div className="h-[400px] w-full pt-4">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={ecoAChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                        {ecoAChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoA-${i}`} fill={e.color} stroke="none" />)}
                      </Pie>
                      <Tooltip />
                      <Legend verticalAlign="bottom" content={renderGridLegend} />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div ref={ecoBCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
                <div className="flex items-center justify-between mb-2">
                  <h3 className="font-black text-purple-700 text-xs uppercase tracking-widest flex items-center gap-2"><Leaf size={14} /> DISTRIBUIÇÃO ECO B</h3>
                  <button onClick={() => downloadCardAsImage(ecoBCardRef, 'ranking_ecoB')} className="p-1.5 text-slate-300 hover:text-purple-600 rounded-lg no-export"><Download size={16} /></button>
                </div>
                <div className="h-[400px] w-full pt-4">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={ecoBChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>
                        {ecoBChartData.filter(d => d.value > 0).map((e, i) => <Cell key={`cell-ecoB-${i}`} fill={e.color} stroke="none" />)}
                      </Pie>
                      <Tooltip />
                      <Legend verticalAlign="bottom" content={renderGridLegend} />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>
          </>
        ) : (
          /* Seção de Relatórios Mensais */
          <div className="space-y-6">
            <div className="flex items-center justify-between mb-2">
              <h2 className="text-xl font-black text-slate-800 flex items-center gap-2">
                <FileSpreadsheet size={24} className="text-blue-600" />
                CONSOLIDADO MENSAL
              </h2>
              <button 
                onClick={exportMonthlyReportToCSV}
                className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold px-4 py-2 rounded-xl flex items-center gap-2 shadow-lg shadow-emerald-200 text-sm transition-all"
              >
                <Download size={18} /> Exportar CSV
              </button>
            </div>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-slate-50 border-b border-slate-100">
                      <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Mês Referência</th>
                      <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Produção (KG)</th>
                      <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Eficiência</th>
                      <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Borra (KG)</th>
                      <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Paradas</th>
                      <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Eco A/B</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {monthlyReports.map((report) => {
                      const efficiency = report.totalGross > 0 ? (report.totalNet / report.totalGross) * 100 : 0;
                      return (
                        <tr key={report.key} className="hover:bg-slate-50 transition-colors group">
                          <td className="px-6 py-5">
                            <span className="text-sm font-black text-slate-700">{report.label}</span>
                            <span className="block text-[10px] text-slate-400 font-bold">{report.entries} lançamentos</span>
                          </td>
                          <td className="px-6 py-5">
                            <span className="text-sm font-black text-blue-600">{formatWeight(report.totalNet)}</span>
                          </td>
                          <td className="px-6 py-5">
                            <div className="flex items-center gap-2">
                              <span className={`text-xs font-black px-2 py-1 rounded-lg ${efficiency >= 95 ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>
                                {efficiency.toFixed(1)}%
                              </span>
                            </div>
                          </td>
                          <td className="px-6 py-5">
                            <span className="text-sm font-black text-red-500">{formatWeight(report.borra)}</span>
                          </td>
                          <td className="px-6 py-5 text-sm font-black text-slate-600">
                            {(report.downtimeMin / 60).toFixed(1)}h
                          </td>
                          <td className="px-6 py-5">
                            <div className="flex flex-col gap-1">
                              <span className="text-[10px] font-black text-emerald-600">A: {formatWeight(report.ecoA)}</span>
                              <span className="text-[10px] font-black text-purple-600">B: {formatWeight(report.ecoB)}</span>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </main>

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Info, Power, Users, Printer, Leaf, Calendar, UserPlus, BarChart3, FileText, FileSpreadsheet, List } from 'lucide-react';
import {渲染GridLegend, renderCustomLabel} from './components/ChartUtils'; // Hypothetical or internal
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '4.9'; 

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports'>('dashboard');
  const [reportView, setReportView] = useState<'summary' | 'detailed'>('summary');
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [newOperatorName, setNewOperatorName] = useState('');

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const monthlyReports = useMemo(() => {
    const groups: Record<string, any> = {};
    productionData.forEach(entry => {
      const date = new Date(entry.date + 'T00:00:00');
      const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      const monthLabel = new Intl.DateTimeFormat('pt-BR', { month: 'long', year: 'numeric' }).format(date);
      if (!groups[key]) {
        groups[key] = { key, label: monthLabel.toUpperCase(), totalNet: 0, totalGross: 0, borra: 0, downtimeMin: 0, ecoA: 0, ecoB: 0, entries: 0 };
      }
      groups[key].totalNet += entry.netWeight || 0;
      groups[key].totalGross += entry.grossWeight || 0;
      groups[key].borra += entry.borraTotal || 0;
      groups[key].downtimeMin += (entry.manutencaoMin || 0) + (entry.processoMin || 0) + (entry.outrosMin || 0);
      groups[key].ecoA += entry.ecoA || 0;
      groups[key].ecoB += (entry.ecoBP || 0) + (entry.ecoBM || 0);
      groups[key].entries += 1;
    });
    return Object.values(groups).sort((a: any, b: any) => b.key.localeCompare(a.key));
  }, [productionData]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0, [stats]);
  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    return productionData.filter(entry => entry.date.startsWith(currentMonthPrefix)).reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase(), []);
  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => ['Cast 1', 'Cast 2'].map(m => ({ name: m, status: machineManualStatus[m] || 'Operando' })), [machineManualStatus]);
  const toggleMachineStatus = (machineName: string) => setMachineManualStatus(prev => ({ ...prev, [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando' }));
  const activeMachines = useMemo(() => Object.entries(machineManualStatus).filter(([_, status]) => status === 'Operando').map(([name]) => name), [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) }, ...prev]);
  const handleAddOperator = () => {
    if (!newOperatorName.trim()) return;
    if (operators.includes(newOperatorName.trim())) return alert('Operador já cadastrado.');
    setOperators(prev => [...prev, newOperatorName.trim()].sort());
    setNewOperatorName('');
  };
  const handleRemoveOperator = (name: string) => { if (confirm(`Deseja realmente excluir o operador ${name}?`)) setOperators(prev => prev.filter(op => op !== name)); };
  const handleResetData = () => { if (confirm('Deseja resetar todos os dados?')) { setProductionData(INITIAL_DATA); setGoalValue(DEFAULT_GOAL); setIsMenuOpen(false); } };

  const exportFullDetailedCSV = () => {
    const headers = [
      'Data', 'Operador', 'Maquina', 'Turno', 
      'P. Bruto (KG)', 'Tara (KG)', 'P. Liquido (KG)', 
      'Volumes', 'Tubetes', 'Eco A', 'Eco B (P)', 'Eco B (M)', 
      'Borra Total', 'Manutencao (Min)', 'Manutencao Motivo', 
      'Processo (Min)', 'Processo Motivo', 'Outros (Min)', 'Outros Motivo'
    ];
    const rows = filteredData.map(e => [
      e.date, e.operator, e.machine, e.shift,
      e.grossWeight, e.tara, e.netWeight,
      e.volumes, e.tubetes, e.ecoA, e.ecoBP, e.ecoBM,
      e.borraTotal, e.manutencaoMin, `"${e.manutencaoMotivo || ''}"`,
      e.processoMin, `"${e.processoMotivo || ''}"`, e.outrosMin, `"${e.outrosMotivo || ''}"`
    ]);
    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers.join(",") + "\n" + rows.map(e => e.join(",")).join("\n");
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI(csvContent));
    link.setAttribute("download", `relatorio_detalhado_manupackaging_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    toPng(containerRef.current, { filter: (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export')), backgroundColor: '#ffffff', pixelRatio: 2 })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error(err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => { if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0); });
      return Object.entries(performanceMap).sort((a, b) => b[1] - a[1]).map(([name, kg], index) => ({ name, value: kg, color: colors[index % colors.length], unit: 'KG' }));
    } else {
      return [{ name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' }, { name: 'ECO A', value: stats.ecoA, unit: 'KG' }, { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' }, { name: 'BORRA', value: stats.borra, unit: 'KG' }].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  const ecoAChartData = useMemo(() => {
    const colors = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#065f46', '#064e3b', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => { if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoA || 0); });
    return Object.entries(performanceMap).sort((a, b) => b[1] - a[1]).map(([name, kg], index) => ({ name, value: kg, color: colors[index % colors.length], unit: 'KG' }));
  }, [filteredData, operators]);

  const ecoBChartData = useMemo(() => {
    const colors = ['#8b5cf6', '#a78bfa', '#c4b5fd', '#ddd6fe', '#7c3aed', '#6d28d9', '#5b21b6', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => { if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoBP || 0) + (entry.ecoBM || 0); });
    return Object.entries(performanceMap).sort((a, b) => b[1] - a[1]).map(([name, kg], index) => ({ name, value: kg, color: colors[index % colors.length], unit: 'KG' }));
  }, [filteredData, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [{ name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' }, { name: 'PROCESSO', value: stats.proc, unit: 'MIN' }, { name: 'OUTROS', value: stats.outros, unit: 'MIN' }].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);
    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";
          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>{index + 1}º</div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>{formatWeight(data.value, data.unit)}</span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">{`${(percent * 100).toFixed(1)}%`}</text>
      </g>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="bg-slate-200/50 p-1 rounded-2xl inline-flex gap-1">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}><BarChart3 size={16} /> Dashboard</button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}><FileText size={16} /> Relatórios</button>
        </div>
      </div>

      {/* Menu Lateral */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> MENU</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>
          <div className="space-y-6">
             <div className="space-y-4">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Filter size={14} /> Filtros de Dados</h3>
                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                    <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-2 py-2 text-[10px] font-bold text-slate-700 focus:outline-none" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                    <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-2 py-2 text-[10px] font-bold text-slate-700 focus:outline-none" />
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Máquina</label>
                  <select value={selectedMachine} onChange={(e) => setSelectedMachine(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                    <option value="Todas">Todas as Máquinas</option>
                    <option value="Cast 1">Cast 1</option>
                    <option value="Cast 2">Cast 2</option>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Operador</label>
                  <select value={selectedOperator} onChange={(e) => setSelectedOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                    <option value="Todos">Todos os Operadores</option>
                    {operators.map(op => (<option key={op} value={op}>{op}</option>))}
                  </select>
                </div>
             </div>
             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Users size={14} /> Gerenciar Operadores</h3>
                <div className="flex gap-2">
                  <input type="text" placeholder="Nome" value={newOperatorName} onChange={(e) => setNewOperatorName(e.target.value)} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold text-slate-700 focus:outline-none" />
                  <button onClick={handleAddOperator} className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700"><UserPlus size={16} /></button>
                </div>
                <div className="max-h-40 overflow-y-auto custom-scrollbar space-y-1">
                  {operators.map(op => (
                    <div key={op} className="flex items-center justify-between bg-slate-50 p-2 rounded-lg border border-slate-100 group">
                      <span className="text-[10px] font-bold text-slate-600">{op}</span>
                      <button onClick={() => handleRemoveOperator(op)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100"><Trash2 size={12} /></button>
                    </div>
                  ))}
                </div>
             </div>
             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Target size={14} /> Meta Mensal</h3>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none" />
             </div>
             <button onClick={handleResetData} className="w-full bg-red-50 text-red-600 border border-red-100 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-red-100">Resetar Dados <RefreshCw size={16} /></button>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' ? (
          <>
            <div className="grid grid-cols-2 gap-4">
              {machineStatusCards.map((m) => (
                <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                    <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
                  </div>
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>{m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}</div>
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                  </div>
                </div>
              ))}
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Eficiência</span><span className="text-xl text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Total Borra</span><span className="text-xl text-red-500">{formatWeight(stats.borra)}</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Paradas</span><span className="text-xl text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Produção Total</span><span className="text-xl text-blue-600">{formatWeight(stats.totalNet)}</span></div>
            </div>
            <div className={`bg-white rounded-2xl p-6 shadow-sm border ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
              <div className="flex items-center justify-between mb-4 font-black">
                <div><span className="text-[10px] uppercase text-slate-400">Meta Mensal ({currentMonthName})</span><div className="flex items-baseline gap-2"><span className="text-4xl text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span><span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span></div></div>
                <span className={`text-3xl ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
              </div>
              <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden"><div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {[prodCardRef, stopCardRef, ecoACardRef, ecoBCardRef].map((ref, idx) => (
                <div key={idx} ref={ref} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[580px]">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className={`font-black text-xs uppercase tracking-widest ${idx === 1 ? 'text-orange-600' : idx === 2 ? 'text-emerald-700' : idx === 3 ? 'text-purple-700' : 'text-slate-800'}`}>{idx === 0 ? 'Leaderboard Produção Total' : idx === 1 ? 'Impacto de Paradas' : idx === 2 ? 'Distribuição Eco A' : 'Distribuição Eco B'}</h3>
                    <button onClick={() => downloadCardAsImage(ref, idx === 0 ? 'prod' : idx === 1 ? 'stops' : idx === 2 ? 'ecoA' : 'ecoB')} className="p-1.5 text-slate-300 hover:text-blue-600 rounded-lg no-export"><Download size={16} /></button>
                  </div>
                  <div className="h-[400px] w-full pt-4">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={idx === 0 ? mainChartData : idx === 1 ? downtimePieData : idx === 2 ? ecoAChartData.filter(d => d.value > 0) : ecoBChartData.filter(d => d.value > 0)} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={idx === 1 ? 6 : 4}>{ (idx === 0 ? mainChartData : idx === 1 ? downtimePieData : idx === 2 ? ecoAChartData.filter(d => d.value > 0) : ecoBChartData.filter(d => d.value > 0)).map((e, i) => <Cell key={`c-${i}`} fill={e.color} stroke="none" />) }</Pie>
                        <Tooltip /><Legend verticalAlign="bottom" content={renderGridLegend} />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>
                  <div className="mt-auto pt-4 flex items-start gap-2 bg-slate-50/50 p-3 rounded-xl border border-slate-100">
                    <span className="no-export"><Info size={14} className="text-slate-400 mt-0.5" /></span>
                    <p className="text-[10px] text-slate-500 leading-relaxed italic font-medium">Análise filtrada por período e operadores, exibindo os maiores volumes em destaque.</p>
                  </div>
                </div>
              ))}
            </div>
          </>
        ) : (
          <div className="space-y-6">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
              <div className="flex items-center gap-4">
                <h2 className="text-xl font-black text-slate-800 flex items-center gap-2"><FileSpreadsheet size={24} className="text-blue-600" /> Relatórios</h2>
                <div className="bg-slate-200 p-1 rounded-xl flex">
                  <button onClick={() => setReportView('summary')} className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${reportView === 'summary' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>Resumo Mensal</button>
                  <button onClick={() => setReportView('detailed')} className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${reportView === 'detailed' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>Lançamentos Diários</button>
                </div>
              </div>
              <button onClick={exportFullDetailedCSV} className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold px-4 py-2 rounded-xl flex items-center gap-2 shadow-lg shadow-emerald-200 text-sm"><Download size={18} /> Exportar CSV Completo</button>
            </div>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
              <div className="overflow-x-auto custom-scrollbar">
                {reportView === 'summary' ? (
                  <table className="w-full text-left border-collapse">
                    <thead>
                      <tr className="bg-slate-50 border-b border-slate-100">
                        <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Mês Referência</th>
                        <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Produção (KG)</th>
                        <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Eficiência</th>
                        <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Borra (KG)</th>
                        <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Paradas</th>
                        <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Eco A/B</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {monthlyReports.map((r) => {
                        const eff = r.totalGross > 0 ? (r.totalNet / r.totalGross) * 100 : 0;
                        return (
                          <tr key={r.key} className="hover:bg-slate-50 transition-colors">
                            <td className="px-6 py-5"><span className="text-sm font-black text-slate-700 block">{r.label}</span><span className="text-[10px] text-slate-400 font-bold">{r.entries} itens</span></td>
                            <td className="px-6 py-5 text-sm font-black text-blue-600">{formatWeight(r.totalNet)}</td>
                            <td className="px-6 py-5"><span className={`text-xs font-black px-2 py-1 rounded-lg ${eff >= 95 ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>{eff.toFixed(1)}%</span></td>
                            <td className="px-6 py-5 text-sm font-black text-red-500">{formatWeight(r.borra)}</td>
                            <td className="px-6 py-5 text-sm font-black text-slate-600">{(r.downtimeMin / 60).toFixed(1)}h</td>
                            <td className="px-6 py-5"><div className="flex flex-col"><span className="text-[10px] font-black text-emerald-600">A: {formatWeight(r.ecoA)}</span><span className="text-[10px] font-black text-purple-600">B: {formatWeight(r.ecoB)}</span></div></td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                ) : (
                  <table className="w-full text-left border-collapse min-w-[1500px]">
                    <thead>
                      <tr className="bg-slate-50 border-b border-slate-100 text-[9px] font-black text-slate-400 uppercase tracking-widest">
                        <th className="px-4 py-3 sticky left-0 bg-slate-50 z-10">Data</th>
                        <th className="px-4 py-3">Operador</th>
                        <th className="px-4 py-3">Máquina</th>
                        <th className="px-4 py-3">Turno</th>
                        <th className="px-4 py-3 text-blue-600">P. Bruto</th>
                        <th className="px-4 py-3 text-blue-600">Tara</th>
                        <th className="px-4 py-3 text-blue-600">P. Líquido</th>
                        <th className="px-4 py-3">Volumes</th>
                        <th className="px-4 py-3">Tubetes</th>
                        <th className="px-4 py-3 text-emerald-600">Eco A</th>
                        <th className="px-4 py-3 text-purple-600">Eco B (P)</th>
                        <th className="px-4 py-3 text-purple-600">Eco B (M)</th>
                        <th className="px-4 py-3 text-red-500">Borra</th>
                        <th className="px-4 py-3 text-orange-600">Manut (Min)</th>
                        <th className="px-4 py-3">Motivo Manut.</th>
                        <th className="px-4 py-3 text-orange-600">Proc (Min)</th>
                        <th className="px-4 py-3">Motivo Proc.</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {filteredData.map((e) => (
                        <tr key={e.id} className="hover:bg-slate-50 transition-colors text-[10px] font-bold text-slate-600">
                          <td className="px-4 py-3 font-black text-slate-800 sticky left-0 bg-white group-hover:bg-slate-50 transition-colors border-r border-slate-100">{e.date}</td>
                          <td className="px-4 py-3">{e.operator}</td>
                          <td className="px-4 py-3">{e.machine}</td>
                          <td className="px-4 py-3">{e.shift}</td>
                          <td className="px-4 py-3 text-blue-600">{e.grossWeight}</td>
                          <td className="px-4 py-3 text-blue-400">{e.tara}</td>
                          <td className="px-4 py-3 text-blue-700 font-black">{e.netWeight}</td>
                          <td className="px-4 py-3">{e.volumes}</td>
                          <td className="px-4 py-3">{e.tubetes}</td>
                          <td className="px-4 py-3 text-emerald-600">{e.ecoA}</td>
                          <td className="px-4 py-3 text-purple-600">{e.ecoBP}</td>
                          <td className="px-4 py-3 text-purple-600">{e.ecoBM}</td>
                          <td className="px-4 py-3 text-red-500">{e.borraTotal}</td>
                          <td className="px-4 py-3 text-orange-600">{e.manutencaoMin}</td>
                          <td className="px-4 py-3 italic text-slate-400 max-w-xs truncate">{e.manutencaoMotivo || '-'}</td>
                          <td className="px-4 py-3 text-orange-500">{e.processoMin}</td>
                          <td className="px-4 py-3 italic text-slate-400 max-w-xs truncate">{e.processoMotivo || '-'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                )}
              </div>
            </div>
          </div>
        )}
      </main>
      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, RotateCcw, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Info, Power, Users, Printer, Leaf, Calendar, UserPlus, BarChart3, FileText, FileSpreadsheet, List, Search } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '5.0'; 

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports'>('dashboard');
  const [reportView, setReportView] = useState<'summary' | 'detailed'>('summary');
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    const defaultOps = ['Carlos Philips', 'Deyvis', 'Edilson', 'Erivan', 'Everson', 'Marcelo', 'Nahin', 'Sidoneide'].sort();
    if (savedVersion !== APP_DATA_VERSION) return defaultOps;
    return savedOps ? JSON.parse(savedOps) : defaultOps;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [newOperatorName, setNewOperatorName] = useState('');

  // Filtros
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMonth, setSelectedMonth] = useState<string>('Todos');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  // Lista de meses disponíveis para o filtro
  const availableMonths = useMemo(() => {
    const months = new Set<string>();
    productionData.forEach(entry => {
      const parts = entry.date.split('-');
      months.add(`${parts[0]}-${parts[1]}`);
    });
    return Array.from(months).sort((a, b) => b.localeCompare(a));
  }, [productionData]);

  const handleMonthChange = (month: string) => {
    setSelectedMonth(month);
    if (month === 'Todos') {
      setStartDate('');
      setEndDate('');
    } else {
      const [year, monthNum] = month.split('-');
      const firstDay = `${year}-${monthNum}-01`;
      const lastDay = new Date(parseInt(year), parseInt(monthNum), 0).getDate();
      const lastDayStr = `${year}-${monthNum}-${String(lastDay).padStart(2, '0')}`;
      setStartDate(firstDay);
      setEndDate(lastDayStr);
    }
  };

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const monthlyReports = useMemo(() => {
    const groups: Record<string, any> = {};
    productionData.forEach(entry => {
      const date = new Date(entry.date + 'T00:00:00');
      const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      const monthLabel = new Intl.DateTimeFormat('pt-BR', { month: 'long', year: 'numeric' }).format(date);
      if (!groups[key]) {
        groups[key] = { key, label: monthLabel.toUpperCase(), totalNet: 0, totalGross: 0, borra: 0, downtimeMin: 0, ecoA: 0, ecoB: 0, entries: 0 };
      }
      groups[key].totalNet += entry.netWeight || 0;
      groups[key].totalGross += entry.grossWeight || 0;
      groups[key].borra += entry.borraTotal || 0;
      groups[key].downtimeMin += (entry.manutencaoMin || 0) + (entry.processoMin || 0) + (entry.outrosMin || 0);
      groups[key].ecoA += entry.ecoA || 0;
      groups[key].ecoB += (entry.ecoBP || 0) + (entry.ecoBM || 0);
      groups[key].entries += 1;
    });
    return Object.values(groups).sort((a: any, b: any) => b.key.localeCompare(a.key));
  }, [productionData]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0, [stats]);
  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    return productionData.filter(entry => entry.date.startsWith(currentMonthPrefix)).reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase(), []);
  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => ['Cast 1', 'Cast 2'].map(m => ({ name: m, status: machineManualStatus[m] || 'Operando' })), [machineManualStatus]);
  const toggleMachineStatus = (machineName: string) => setMachineManualStatus(prev => ({ ...prev, [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando' }));
  const activeMachines = useMemo(() => Object.entries(machineManualStatus).filter(([_, status]) => status === 'Operando').map(([name]) => name), [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) }, ...prev]);
  const handleAddOperator = () => {
    if (!newOperatorName.trim()) return;
    if (operators.includes(newOperatorName.trim())) return alert('Operador já cadastrado.');
    setOperators(prev => [...prev, newOperatorName.trim()].sort());
    setNewOperatorName('');
  };
  const handleRemoveOperator = (name: string) => { if (confirm(`Deseja realmente excluir o operador ${name}?`)) setOperators(prev => prev.filter(op => op !== name)); };
  const handleResetData = () => { if (confirm('Deseja resetar todos os dados?')) { setProductionData(INITIAL_DATA); setGoalValue(DEFAULT_GOAL); setIsMenuOpen(false); } };

  const exportFullDetailedCSV = () => {
    const headers = [
      'Data', 'Operador', 'Maquina', 'Turno', 
      'P. Bruto (KG)', 'Tara (KG)', 'P. Liquido (KG)', 
      'Volumes', 'Tubetes', 'Eco A', 'Eco B (P)', 'Eco B (M)', 
      'Borra Total', 'Manutencao (Min)', 'Manutencao Motivo', 
      'Processo (Min)', 'Processo Motivo', 'Outros (Min)', 'Outros Motivo'
    ];
    const rows = filteredData.map(e => [
      e.date, e.operator, e.machine, e.shift,
      e.grossWeight, e.tara, e.netWeight,
      e.volumes, e.tubetes, e.ecoA, e.ecoBP, e.ecoBM,
      e.borraTotal, e.manutencaoMin, `"${e.manutencaoMotivo || ''}"`,
      e.processoMin, `"${e.processoMotivo || ''}"`, e.outrosMin, `"${e.outrosMotivo || ''}"`
    ]);
    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers.join(",") + "\n" + rows.map(e => e.join(",")).join("\n");
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI(csvContent));
    link.setAttribute("download", `relatorio_detalhado_manupackaging_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    toPng(containerRef.current, { filter: (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export')), backgroundColor: '#ffffff', pixelRatio: 2 })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error(err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => { if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0); });
      return Object.entries(performanceMap).sort((a, b) => b[1] - a[1]).map(([name, kg], index) => ({ name, value: kg, color: colors[index % colors.length], unit: 'KG' }));
    } else {
      return [{ name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' }, { name: 'ECO A', value: stats.ecoA, unit: 'KG' }, { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' }, { name: 'BORRA', value: stats.borra, unit: 'KG' }].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  const ecoAChartData = useMemo(() => {
    const colors = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#065f46', '#064e3b', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => { if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoA || 0); });
    return Object.entries(performanceMap).sort((a, b) => b[1] - a[1]).map(([name, kg], index) => ({ name, value: kg, color: colors[index % colors.length], unit: 'KG' }));
  }, [filteredData, operators]);

  const ecoBChartData = useMemo(() => {
    const colors = ['#8b5cf6', '#a78bfa', '#c4b5fd', '#ddd6fe', '#7c3aed', '#6d28d9', '#5b21b6', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => { if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoBP || 0) + (entry.ecoBM || 0); });
    return Object.entries(performanceMap).sort((a, b) => b[1] - a[1]).map(([name, kg], index) => ({ name, value: kg, color: colors[index % colors.length], unit: 'KG' }));
  }, [filteredData, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [{ name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' }, { name: 'PROCESSO', value: stats.proc, unit: 'MIN' }, { name: 'OUTROS', value: stats.outros, unit: 'MIN' }].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload) return null;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);
    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";
          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>{index + 1}º</div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>{formatWeight(data.value, data.unit)}</span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">{`${(percent * 100).toFixed(1)}%`}</text>
      </g>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="bg-slate-200/50 p-1 rounded-2xl inline-flex gap-1">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}><BarChart3 size={16} /> Dashboard</button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}><FileText size={16} /> Relatórios</button>
        </div>
      </div>

      {/* Menu Lateral */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> MENU</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>
          <div className="space-y-6">
             {/* Busca Rápida por Mês */}
             <div className="space-y-4">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Search size={14} /> Busca Rápida</h3>
