             </div>
             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Users size={14} /> Gerenciar Operadores</h3>
                <div className="flex gap-2">
                  <input type="text" placeholder="Nome" value={newOperatorName} onChange={(e) => setNewOperatorName(e.target.value)} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold text-slate-700 focus:outline-none" />
                  <button onClick={handleAddOperator} className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700"><UserPlus size={16} /></button>
                </div>
                <div className="max-h-40 overflow-y-auto custom-scrollbar space-y-1">
                  {operators.map(op => (
                    <div key={op} className="flex items-center justify-between bg-slate-50 p-2 rounded-lg border border-slate-100 group">
                      <span className="text-[10px] font-bold text-slate-600">{op}</span>
                      <button onClick={() => handleRemoveOperator(op)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100"><Trash2 size={12} /></button>
                    </div>
                  ))}
                </div>
             </div>
             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Target size={14} /> Meta Mensal</h3>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none" />
             </div>
             <button onClick={handleResetData} className="w-full bg-red-50 text-red-600 border border-red-100 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-red-100">Resetar Dados <RefreshCw size={16} /></button>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' ? (
          <>
            <div className="grid grid-cols-2 gap-4">
              {machineStatusCards.map((m) => (
                <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                    <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
                  </div>
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>{m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}</div>
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                  </div>
                </div>
              ))}
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Eficiência</span><span className="text-xl text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Total Borra</span><span className="text-xl text-red-500">{formatWeight(stats.borra)}</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Paradas</span><span className="text-xl text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Produção Total</span><span className="text-xl text-blue-600">{formatWeight(stats.totalNet)}</span></div>
