                          <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Mês Referência</th>
                          <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Produção (KG)</th>
                          <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Eficiência</th>
                          <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Borra (KG)</th>
                          <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Paradas</th>
                          <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Eco A/B</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {monthlyReports.map((r) => {
                          const eff = r.totalGross > 0 ? (r.totalNet / r.totalGross) * 100 : 0;
                          return (
                            <tr key={r.key} className="hover:bg-slate-50 transition-colors">
                              <td className="px-6 py-5"><span className="text-sm font-black text-slate-700 block">{r.label}</span><span className="text-[10px] text-slate-400 font-bold">{r.entries} itens</span></td>
                              <td className="px-6 py-5 text-sm font-black text-blue-600">{formatWeight(r.totalNet)}</td>
                              <td className="px-6 py-5"><span className={`text-xs font-black px-2 py-1 rounded-lg ${eff >= 95 ? 'bg-emerald-100 text-emerald-700' : 'bg-orange-100 text-orange-700'}`}>{eff.toFixed(1)}%</span></td>
                              <td className="px-6 py-5 text-sm font-black text-red-500">{formatWeight(r.borra)}</td>
                              <td className="px-6 py-5 text-sm font-black text-slate-600">{(r.downtimeMin / 60).toFixed(1)}h</td>
                              <td className="px-6 py-5"><div className="flex flex-col"><span className="text-[10px] font-black text-emerald-600">A: {formatWeight(r.ecoA)}</span><span className="text-[10px] font-black text-purple-600">B: {formatWeight(r.ecoB)}</span></div></td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  ) : (
                    <table className="w-full text-left border-collapse min-w-[2000px]">
                      <thead>
                        <tr className="bg-slate-50 border-b border-slate-100 text-[9px] font-black text-slate-400 uppercase tracking-widest">
                          <th className="px-4 py-3 sticky left-0 bg-slate-50 z-10">Data</th>
                          <th className="px-4 py-3">Operador</th>
                          <th className="px-4 py-3">Máquina</th>
                          <th className="px-4 py-3">Turno</th>
                          <th className="px-4 py-3 text-blue-600">P. Bruto</th>
                          <th className="px-4 py-3 text-blue-600">Tara</th>
                          <th className="px-4 py-3 text-blue-700 font-black">P. Líquido</th>
                          <th className="px-4 py-3">Volumes</th>
                          <th className="px-4 py-3">Tubetes</th>
                          <th className="px-4 py-3 text-emerald-600">Eco A</th>
                          <th className="px-4 py-3 text-purple-600">Eco B (P)</th>
                          <th className="px-4 py-3 text-purple-600">Eco B (M)</th>
                          <th className="px-4 py-3 text-red-500">Borra</th>
                          <th className="px-4 py-3 text-orange-600">Manut (Min)</th>
                          <th className="px-4 py-3">Motivo Manut.</th>
                          <th className="px-4 py-3 text-orange-600">Proc (Min)</th>
                          <th className="px-4 py-3">Motivo Proc.</th>
                          <th className="px-4 py-3 text-slate-600">Outros (Min)</th>
                          <th className="px-4 py-3">Motivo Outros</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {filteredData.map((e) => (
                          <tr key={e.id} className="hover:bg-slate-50 transition-colors text-[10px] font-bold text-slate-600">
                            <td className="px-4 py-3 font-black text-slate-800 sticky left-0 bg-white group-hover:bg-slate-50 transition-colors border-r border-slate-100">{e.date}</td>
                            <td className="px-4 py-3">{e.operator}</td>
                            <td className="px-4 py-3">{e.machine}</td>
                            <td className="px-4 py-3">{e.shift}</td>
                            <td className="px-4 py-3 text-blue-600">{e.grossWeight}</td>
                            <td className="px-4 py-3 text-blue-400">{e.tara}</td>
                            <td className="px-4 py-3 text-blue-700 font-black">{e.netWeight}</td>
                            <td className="px-4 py-3">{e.volumes}</td>
                            <td className="px-4 py-3">{e.tubetes}</td>
                            <td className="px-4 py-3 text-emerald-600">{e.ecoA}</td>
                            <td className="px-4 py-3 text-purple-600">{e.ecoBP}</td>
                            <td className="px-4 py-3 text-purple-600">{e.ecoBM}</td>
                            <td className="px-4 py-3 text-red-500">{e.borraTotal}</td>
                            <td className="px-4 py-3 text-orange-600">{e.manutencaoMin}</td>
                            <td className="px-4 py-3 italic text-slate-400 max-w-xs truncate">{e.manutencaoMotivo || '-'}</td>
                            <td className="px-4 py-3 text-orange-500">{e.processoMin}</td>
                            <td className="px-4 py-3 italic text-slate-400 max-w-xs truncate">{e.processoMotivo || '-'}</td>
                            <td className="px-4 py-3 text-slate-500">{e.outrosMin}</td>
                            <td className="px-4 py-3 italic text-slate-400 max-w-xs truncate">{e.outrosMotivo || '-'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </main>
      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Power, Users, Printer, UserPlus, BarChart3, FileText, FileSpreadsheet, Search, Info } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
// Removed unused import 'calamities' which was causing a build error
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL, DEFAULT_OPERATORS } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '6.0'; 

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports'>('dashboard');
  const [reportView, setReportView] = useState<'summary' | 'detailed'>('summary');
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedData = localStorage.getItem('manupackaging_data');
    if (savedVersion !== APP_DATA_VERSION) return INITIAL_DATA;
    return savedData ? JSON.parse(savedData) : INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedVersion = localStorage.getItem('manupackaging_version');
    const savedOps = localStorage.getItem('manupackaging_operators');
    if (savedVersion !== APP_DATA_VERSION) return DEFAULT_OPERATORS;
    return savedOps ? JSON.parse(savedOps) : DEFAULT_OPERATORS;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [newOperatorName, setNewOperatorName] = useState('');

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMonth, setSelectedMonth] = useState<string>('Todos');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
    localStorage.setItem('manupackaging_version', APP_DATA_VERSION);
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  const availableMonths = useMemo(() => {
    const months = new Set<string>();
    productionData.forEach(entry => {
      const parts = entry.date.split('-');
      months.add(`${parts[0]}-${parts[1]}`);
    });
    return Array.from(months).sort((a, b) => b.localeCompare(a));
  }, [productionData]);

  const handleMonthChange = (month: string) => {
    setSelectedMonth(month);
    if (month === 'Todos') {
      setStartDate('');
      setEndDate('');
    } else {
      const [year, monthNum] = month.split('-');
      const firstDay = `${year}-${monthNum}-01`;
      const lastDay = new Date(parseInt(year), parseInt(monthNum), 0).getDate();
      const lastDayStr = `${year}-${monthNum}-${String(lastDay).padStart(2, '0')}`;
      setStartDate(firstDay);
      setEndDate(lastDayStr);
    }
  };

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const monthlyReports = useMemo(() => {
    const groups: Record<string, any> = {};
    productionData.forEach(entry => {
      const date = new Date(entry.date + 'T00:00:00');
      const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      const monthLabel = new Intl.DateTimeFormat('pt-BR', { month: 'long', year: 'numeric' }).format(date);
      if (!groups[key]) {
        groups[key] = { key, label: monthLabel.toUpperCase(), totalNet: 0, totalGross: 0, borra: 0, downtimeMin: 0, ecoA: 0, ecoB: 0, entries: 0 };
      }
      groups[key].totalNet += entry.netWeight || 0;
      groups[key].totalGross += entry.grossWeight || 0;
      groups[key].borra += entry.borraTotal || 0;
      groups[key].downtimeMin += (entry.manutencaoMin || 0) + (entry.processoMin || 0) + (entry.outrosMin || 0);
      groups[key].ecoA += entry.ecoA || 0;
      groups[key].ecoB += (entry.ecoBP || 0) + (entry.ecoBM || 0);
      groups[key].entries += 1;
    });
    return Object.values(groups).sort((a: any, b: any) => b.key.localeCompare(a.key));
  }, [productionData]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, detractors: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0, [stats]);
  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    return productionData.filter(entry => entry.date.startsWith(currentMonthPrefix)).reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const currentMonthName = useMemo(() => new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase(), []);
  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;

  const machineStatusCards = useMemo(() => ['Cast 1', 'Cast 2'].map(m => ({ name: m, status: machineManualStatus[m] || 'Operando' })), [machineManualStatus]);
  const toggleMachineStatus = (machineName: string) => setMachineManualStatus(prev => ({ ...prev, [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando' }));
  const activeMachines = useMemo(() => Object.entries(machineManualStatus).filter(([_, status]) => status === 'Operando').map(([name]) => name), [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) }, ...prev]);
  const handleAddOperator = () => {
    if (!newOperatorName.trim()) return;
    if (operators.includes(newOperatorName.trim())) return alert('Operador já cadastrado.');
    setOperators(prev => [...prev, newOperatorName.trim()].sort());
    setNewOperatorName('');
  };
  const handleRemoveOperator = (name: string) => { if (confirm(`Deseja realmente excluir o operador ${name}?`)) setOperators(prev => prev.filter(op => op !== name)); };
  const handleResetData = () => { if (confirm('Deseja resetar todos os dados?')) { setProductionData(INITIAL_DATA); setGoalValue(DEFAULT_GOAL); setOperators(DEFAULT_OPERATORS); setIsMenuOpen(false); } };

  const exportFullDetailedCSV = () => {
    const headers = [
      'Data', 'Operador', 'Maquina', 'Turno', 
      'P. Bruto (KG)', 'Tara (KG)', 'P. Liquido (KG)', 
      'Volumes', 'Tubetes', 'Eco A', 'Eco B (P)', 'Eco B (M)', 
      'Borra Total', 'Manutencao (Min)', 'Manutencao Motivo', 
      'Processo (Min)', 'Processo Motivo', 'Outros (Min)', 'Outros Motivo'
    ];
    const rows = filteredData.map(e => [
      e.date, e.operator, e.machine, e.shift,
      e.grossWeight, e.tara, e.netWeight,
      e.volumes, e.tubetes, e.ecoA, e.ecoBP, e.ecoBM,
      e.borraTotal, e.manutencaoMin, `"${e.manutencaoMotivo || ''}"`,
      e.processoMin, `"${e.processoMotivo || ''}"`, e.outrosMin, `"${e.outrosMotivo || ''}"`
    ]);
    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers.join(",") + "\n" + rows.map(e => e.join(",")).join("\n");
    const link = document.createElement("a");
    link.setAttribute("href", encodeURI(csvContent));
    link.setAttribute("download", `relatorio_detalhado_manupackaging_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    toPng(containerRef.current, { 
      filter: (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export')),
      backgroundColor: '#ffffff',
      pixelRatio: 3,
      cacheBust: true,
    })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error('Erro ao baixar imagem:', err));
  };

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => { if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0); });
      return Object.entries(performanceMap).sort((a, b) => b[1] - a[1]).map(([name, kg], index) => ({ name, value: kg, color: colors[index % colors.length], unit: 'KG' }));
    } else {
      return [{ name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' }, { name: 'ECO A', value: stats.ecoA, unit: 'KG' }, { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' }, { name: 'BORRA', value: stats.borra, unit: 'KG' }].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  const ecoAChartData = useMemo(() => {
    const colors = ['#10b981', '#34d399', '#6ee7b7', '#a7f3d0', '#059669', '#065f46', '#064e3b', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => { if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoA || 0); });
    return Object.entries(performanceMap).sort((a, b) => b[1] - a[1]).map(([name, kg], index) => ({ name, value: kg, color: colors[index % colors.length], unit: 'KG' }));
  }, [filteredData, operators]);

  const ecoBChartData = useMemo(() => {
    const colors = ['#8b5cf6', '#a78bfa', '#c4b5fd', '#ddd6fe', '#7c3aed', '#6d28d9', '#5b21b6', '#3b82f6'];
    const performanceMap: Record<string, number> = {};
    operators.forEach(op => { performanceMap[op] = 0; });
    filteredData.forEach(entry => { if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.ecoBP || 0) + (entry.ecoBM || 0); });
    return Object.entries(performanceMap).sort((a, b) => b[1] - a[1]).map(([name, kg], index) => ({ name, value: kg, color: colors[index % colors.length], unit: 'KG' }));
  }, [filteredData, operators]);

  const downtimePieData = useMemo(() => {
    const colors = ['#f97316', '#f59e0b', '#94a3b8'];
    return [{ name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' }, { name: 'PROCESSO', value: stats.proc, unit: 'MIN' }, { name: 'OUTROS', value: stats.outros, unit: 'MIN' }].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
  }, [stats]);

  const chartDescriptions = [
    "Análise comparativa da produção líquida total por operador ou categoria, destacando os maiores volumes e desempenho de meta.",
    "Distribuição do tempo de inatividade da planta, categorizado entre manutenções preventivas/corretivas, ajustes de processo e outros motivos externos.",
    "Visualização do volume de recuperação Eco A por colaborador, permitindo identificar os turnos com maior eficiência de reciclagem primária.",
    "Monitoramento de materiais Eco B (Pequenos e Médios) gerados durante a operação, crucial para o controle de desperdício e sustentabilidade."
  ];

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload || payload.length === 0) return <div className="text-center text-[10px] text-slate-400 mt-8 font-bold">Nenhum dado registrado</div>;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);
    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";
          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg hover:bg-slate-50 transition-colors">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>{index + 1}º</div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.value}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>{formatWeight(data.value, data.unit)}</span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const sin = Math.sin(-midAngle * RADIAN);
    const cos = Math.cos(-midAngle * RADIAN);
    const sx = cx + (outerRadius) * cos;
    const sy = cy + (outerRadius) * sin;
    const mx = cx + (outerRadius + 15) * cos;
    const my = cy + (outerRadius + 15) * sin;
    const ex = mx + (cos >= 0 ? 1 : -1) * 8;
    const ey = my;
    const textAnchor = cos >= 0 ? 'start' : 'end';
    return (
      <g>
        <path d={`M${sx},${sy}L${mx},${my}L${ex},${ey}`} stroke={fill} fill="none" strokeWidth={1.5} />
        <circle cx={ex} cy={ey} r={1.5} fill={fill} stroke="none" />
        <text x={ex + (cos >= 0 ? 1 : -1) * 6} y={ey + 3} textAnchor={textAnchor} fill="#64748b" fontSize={9} fontWeight="black">{`${(percent * 100).toFixed(1)}%`}</text>
      </g>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="bg-slate-200/50 p-1 rounded-2xl inline-flex gap-1">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}><BarChart3 size={16} /> Dashboard</button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}><FileText size={16} /> Relatórios</button>
        </div>
      </div>

      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> MENU</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>
          <div className="space-y-6">
             <div className="space-y-4">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Search size={14} /> Busca Rápida</h3>
