                  <label className="text-[10px] font-bold text-slate-500 uppercase">Filtrar por Mês</label>
                  <select 
                    value={selectedMonth} 
                    onChange={(e) => handleMonthChange(e.target.value)} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                  >
                    <option value="Todos">Exibir Tudo</option>
                    {availableMonths.map(m => {
                      const [y, mn] = m.split('-');
                      const date = new Date(parseInt(y), parseInt(mn)-1, 1);
                      const label = new Intl.DateTimeFormat('pt-BR', { month: 'long', year: 'numeric' }).format(date).toUpperCase();
                      return <option key={m} value={m}>{label}</option>
                    })}
                  </select>
                </div>
             </div>

             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Filter size={14} /> Filtros Personalizados</h3>
                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Início</label>
                    <input type="date" value={startDate} onChange={(e) => { setStartDate(e.target.value); setSelectedMonth('Todos'); }} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-2 py-2 text-[10px] font-bold text-slate-700 focus:outline-none" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Fim</label>
                    <input type="date" value={endDate} onChange={(e) => { setEndDate(e.target.value); setSelectedMonth('Todos'); }} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-2 py-2 text-[10px] font-bold text-slate-700 focus:outline-none" />
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Máquina</label>
                  <select value={selectedMachine} onChange={(e) => setSelectedMachine(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700 focus:outline-none">
                    <option value="Todas">Todas as Máquinas</option>
                    <option value="Cast 1">Cast 1</option>
                    <option value="Cast 2">Cast 2</option>
                  </select>
