import React, { useState, useEffect } from 'react';
import { X, Save, Edit2, Package, Layers, Trash2, Clock, Wrench, CalendarX } from 'lucide-react';
import { ProductionEntry } from '../types';

interface LaunchModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (entry: Omit<ProductionEntry, 'id'>) => void;
  operators: string[];
  activeMachines: string[];
}

const LaunchModal: React.FC<LaunchModalProps> = ({ isOpen, onClose, onSave, operators, activeMachines }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    operator: '',
    machine: '',
    shift: 'Diurno',
    grossWeight: 0,
    tara: 0,
    netWeight: 0,
    volumes: 0,
    tubetes: 0,
    ecoA: 0,
    ecoBP: 0,
    ecoBM: 0,
    borraTotal: 0,
    manutencaoMin: 0,
    manutencaoMotivo: '',
    processoMin: 0,
    processoMotivo: '',
    outrosMin: 0,
    outrosMotivo: '',
    isMaintenanceEntry: false,
    isNoWorkDay: false,
    noWorkReason: '',
  });

  useEffect(() => {
    if (isOpen && activeMachines.length > 0) {
      setFormData(prev => ({ ...prev, machine: activeMachines[0] }));
    }
  }, [isOpen, activeMachines]);

  useEffect(() => {
    setFormData(prev => ({
      ...prev,
      netWeight: (prev.isMaintenanceEntry || prev.isNoWorkDay) ? 0 : Math.max(0, prev.grossWeight - prev.tara)
    }));
  }, [formData.grossWeight, formData.tara, formData.isMaintenanceEntry, formData.isNoWorkDay]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.operator) {
      alert('Por favor, selecione um operador.');
      return;
    }
    if (!formData.machine) {
      alert('Nenhuma máquina ativa selecionada.');
      return;
    }

    // Se for entrada de manutenção ou sem expediente, zeramos os campos de produção
    const isSpecialEntry = formData.isMaintenanceEntry || formData.isNoWorkDay;
    const finalData = isSpecialEntry ? {
      ...formData,
      grossWeight: 0,
      tara: 0,
      netWeight: 0,
      volumes: 0,
      tubetes: 0,
      ecoA: 0,
      ecoBP: 0,
      ecoBM: 0,
      borraTotal: 0,
      // Se não for dia de trabalho, as paradas técnicas também costumam ser zero
      manutencaoMin: formData.isNoWorkDay ? 0 : formData.manutencaoMin,
      processoMin: formData.isNoWorkDay ? 0 : formData.processoMin,
      outrosMin: formData.isNoWorkDay ? 0 : formData.outrosMin,
    } : formData;

    onSave(finalData);
    onClose();
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as HTMLInputElement;
    let val: any;

    if (type === 'checkbox') {
      val = (e.target as HTMLInputElement).checked;

      // Se marcar "Sem expediente", desmarca "Manutenção" e vice-versa
      if (name === 'isNoWorkDay' && val) {
        setFormData(prev => ({ ...prev, [name]: val, isMaintenanceEntry: false }));
        return;
      }
      if (name === 'isMaintenanceEntry' && val) {
        setFormData(prev => ({ ...prev, [name]: val, isNoWorkDay: false }));
        return;
      }
    } else {
      val = type === 'number' ? parseFloat(value) || 0 : value;
    }

    setFormData(prev => ({ ...prev, [name]: val }));
  };

