                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                  >
                    <option value="Todos">Exibir Tudo</option>
                    {availableMonths.map(m => {
                      const [y, mn] = m.split('-');
                      const date = new Date(parseInt(y), parseInt(mn)-1, 1);
                      const label = new Intl.DateTimeFormat('pt-BR', { month: 'long', year: 'numeric' }).format(date).toUpperCase();
                      return <option key={m} value={m}>{label}</option>
