                  <button onClick={handleAddOperator} className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700"><UserPlus size={16} /></button>
                </div>
             </div>
             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Target size={14} /> Meta Mensal</h3>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none" />
             </div>
             <button onClick={handleResetData} className="w-full bg-red-50 text-red-600 border border-red-100 p-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-between hover:bg-red-100">Resetar Dados <RefreshCw size={16} /></button>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' ? (
          <>
            <div className="grid grid-cols-2 gap-4">
              {machineStatusCards.map((m) => (
                <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                    <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg no-print ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
                  </div>
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>{m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}</div>
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                  </div>
                </div>
              ))}
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Eficiência</span><span className="text-xl text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Total Borra</span><span className="text-xl text-red-500">{formatWeight(stats.borra)}</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Paradas</span><span className="text-xl text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Produção Total</span><span className="text-xl text-blue-600">{formatWeight(stats.totalNet)}</span></div>
            </div>
            <div className={`bg-white rounded-2xl p-6 shadow-sm border ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
              <div className="flex items-center justify-between mb-4 font-black">
                <div><span className="text-[10px] uppercase text-slate-400">Meta Mensal ({currentMonthName})</span><div className="flex items-baseline gap-2"><span className="text-4xl text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span><span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span></div></div>
                <span className={`text-3xl ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
              </div>
              <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden"><div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div></div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {[prodCardRef, stopCardRef, ecoACardRef, ecoBCardRef].map((ref, idx) => {
                const chartData = idx === 0 ? mainChartData : idx === 1 ? downtimePieData : idx === 2 ? ecoAChartData : ecoBChartData;
                const hasData = chartData.length > 0;

                return (
                  <div key={idx} ref={ref} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[620px]">
                    <div className="flex items-center justify-between mb-4">
                      <h3 className={`font-black text-xs uppercase tracking-widest ${idx === 1 ? 'text-orange-600' : idx === 2 ? 'text-emerald-700' : idx === 3 ? 'text-purple-700' : 'text-slate-800'}`}>
                        {idx === 0 ? 'Produção Total' : idx === 1 ? 'Impacto de Paradas' : idx === 2 ? 'Distribuição Eco A' : 'Distribuição Eco B'}
                      </h3>
                      <button onClick={() => downloadCardAsImage(ref, idx === 0 ? 'prod' : idx === 1 ? 'stops' : idx === 2 ? 'ecoA' : 'ecoB')} className="p-1.5 text-slate-300 hover:text-blue-600 rounded-lg no-export transition-colors">
                        <Download size={16} />
                      </button>
                    </div>
                    <div className="h-[400px] w-full pt-4 flex items-center justify-center">
                      {hasData ? (
                        <ResponsiveContainer width="100%" height="100%">
                          <PieChart>
                            <Pie 
                              data={chartData} 
                              cx="50%" 
                              cy="45%" 
                              innerRadius={55} 
                              outerRadius={75} 
                              dataKey="value" 
                              label={renderCustomLabel} 
                              paddingAngle={idx === 1 ? 6 : 4}
                            > 
                              {chartData.map((e, i) => <Cell key={`c-${i}`} fill={e.color} stroke="none" />)} 
                            </Pie>
                            <Tooltip />
                            <Legend verticalAlign="bottom" content={renderGridLegend} />
                          </PieChart>
                        </ResponsiveContainer>
                      ) : (
                        <div className="flex flex-col items-center gap-2 text-slate-300">
                          <BarChart3 size={48} strokeWidth={1} />
                          <span className="text-[10px] font-black uppercase tracking-widest">Sem lançamentos para este período</span>
                        </div>
                      )}
                    </div>
                    <div className="mt-auto pt-6 flex items-start gap-2 bg-slate-50 p-4 rounded-xl border border-slate-100">
                      <div className="shrink-0 mt-0.5 text-slate-400">
                        <Info size={14} />
                      </div>
                      <p className="text-[10px] text-slate-500 leading-relaxed font-medium italic">
                        {chartDescriptions[idx]}
                      </p>
                    </div>
                  </div>
                );
              })}
            </div>
          </>
        ) : (
          <div className="space-y-6">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
              <div className="flex items-center gap-4">
                <h2 className="text-xl font-black text-slate-800 flex items-center gap-2"><FileSpreadsheet size={24} className="text-blue-600" /> Relatórios</h2>
                <div className="bg-slate-200 p-1 rounded-xl flex">
                  <button onClick={() => setReportView('summary')} className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${reportView === 'summary' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>Resumo Mensal</button>
