import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Power, Users, Printer, UserPlus, BarChart3, FileText, FileSpreadsheet, Search, Info, Upload, Save } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL, DEFAULT_OPERATORS } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '6.3'; 

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports'>('dashboard');
  const [reportView, setReportView] = useState<'summary' | 'detailed'>('summary');

  // Lógica de Recuperação de Dados (Busca em chaves antigas caso a atual esteja vazia)
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const currentKey = 'manupackaging_data';
      const legacyKeys = ['production_data', 'production-logs', 'production_entries'];

      const savedData = localStorage.getItem(currentKey);
      if (savedData && JSON.parse(savedData).length > 0) {
        return JSON.parse(savedData);
      }

      // Se a chave atual estiver vazia, tenta as antigas (Recuperação)
      for (const key of legacyKeys) {
        const legacyData = localStorage.getItem(key);
        if (legacyData) {
          const parsed = JSON.parse(legacyData);
          if (parsed && Array.isArray(parsed) && parsed.length > 0) {
            console.log(`Dados recuperados da chave legada: ${key}`);
            // Salva na chave nova imediatamente para estabilizar
            localStorage.setItem(currentKey, legacyData);
            return parsed;
          }
        }
      }

      return INITIAL_DATA;
    } catch (e) {
      console.error("Erro ao carregar dados salvos:", e);
      return INITIAL_DATA;
    }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal') || localStorage.getItem('production_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedOps = localStorage.getItem('manupackaging_operators') || localStorage.getItem('production_operators');
    return savedOps ? JSON.parse(savedOps) : DEFAULT_OPERATORS;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [newOperatorName, setNewOperatorName] = useState('');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Filtros
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMonth, setSelectedMonth] = useState<string>('Todos');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  // Salvamento Automático
  useEffect(() => {
    localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
  }, [productionData]);

  useEffect(() => {
    localStorage.setItem('manupackaging_goal', goalValue.toString());
  }, [goalValue]);

  useEffect(() => {
    localStorage.setItem('manupackaging_operators', JSON.stringify(operators));
  }, [operators]);

  useEffect(() => {
    localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus));
  }, [machineManualStatus]);

  // Funções de Backup
  const exportBackup = () => {
    const backup = {
      productionData,
      goalValue,
      operators,
      machineManualStatus,
      version: APP_DATA_VERSION,
      exportDate: new Date().toISOString()
    };
    const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `backup_manupackaging_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importBackup = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.productionData) setProductionData(json.productionData);
        if (json.goalValue) setGoalValue(json.goalValue);
        if (json.operators) setOperators(json.operators);
        if (json.machineManualStatus) setMachineManualStatus(json.machineManualStatus);
        alert("Dados restaurados com sucesso!");
        setIsMenuOpen(false);
      } catch (err) {
        alert("Erro ao importar arquivo.");
      }
    };
    reader.readAsText(file);
  };

  const availableMonths = useMemo(() => {
    const months = new Set<string>();
    productionData.forEach(entry => {
      const parts = entry.date.split('-');
      months.add(`${parts[0]}-${parts[1]}`);
    });
    return Array.from(months).sort((a, b) => b.localeCompare(a));
  }, [productionData]);

  const handleMonthChange = (month: string) => {
    setSelectedMonth(month);
    if (month === 'Todos') {
      setStartDate('');
      setEndDate('');
    } else {
      const [year, monthNum] = month.split('-');
      const firstDay = `${year}-${monthNum}-01`;
      const lastDay = new Date(parseInt(year), parseInt(monthNum), 0).getDate();
      const lastDayStr = `${year}-${monthNum}-${String(lastDay).padStart(2, '0')}`;
      setStartDate(firstDay);
      setEndDate(lastDayStr);
    }
  };

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0, [stats]);
  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    return productionData.filter(entry => entry.date.startsWith(currentMonthPrefix)).reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;
  const currentMonthName = useMemo(() => new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase(), []);

  const machineStatusCards = useMemo(() => ['Cast 1', 'Cast 2'].map(m => ({ name: m, status: machineManualStatus[m] || 'Operando' })), [machineManualStatus]);
  const toggleMachineStatus = (machineName: string) => setMachineManualStatus(prev => ({ ...prev, [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando' }));
  const activeMachines = useMemo(() => Object.entries(machineManualStatus).filter(([_, status]) => status === 'Operando').map(([name]) => name), [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) }, ...prev]);
  const handleAddOperator = () => {
    if (!newOperatorName.trim() || operators.includes(newOperatorName.trim())) return;
    setOperators(prev => [...prev, newOperatorName.trim()].sort());
    setNewOperatorName('');
  };
  const handleResetData = () => { if (confirm('ATENÇÃO: Isso apagará TODOS os lançamentos salvos localmente. Deseja continuar?')) { setProductionData(INITIAL_DATA); setIsMenuOpen(false); } };

  // Gráficos e UI (Mantendo a regra da legenda filtrada)
  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => { if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0); });
      return Object.entries(performanceMap)
        .filter(([_, kg]) => kg > 0)
        .sort((a, b) => b[1] - a[1])
        .map(([name, kg], index) => ({ name, value: kg, color: colors[index % colors.length], unit: 'KG' }));
    } else {
      return [{ name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' }, { name: 'ECO A', value: stats.ecoA, unit: 'KG' }, { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' }, { name: 'BORRA', value: stats.borra, unit: 'KG' }].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload || payload.length === 0) return <div className="text-center text-[10px] text-slate-400 mt-8 font-bold">Nenhum dado registrado</div>;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);
    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";
          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>{index + 1}º</div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{data.name}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>{formatWeight(data.value, data.unit)}</span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200" title="Imprimir"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="bg-slate-200/50 p-1 rounded-2xl inline-flex gap-1">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><BarChart3 size={16} /> Dashboard</button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><FileText size={16} /> Relatórios</button>
        </div>
      </div>

      {/* Menu Lateral */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> CONFIGURAÇÕES</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>
          <div className="space-y-6">
             {/* Filtros */}
             <div className="space-y-4">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Search size={14} /> Busca e Filtros</h3>
                <div className="space-y-2">
                  <select value={selectedMonth} onChange={(e) => handleMonthChange(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-blue-600">
                    <option value="Todos">Exibir Tudo (Mês)</option>
                    {availableMonths.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                  <select value={selectedMachine} onChange={(e) => setSelectedMachine(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold">
                    <option value="Todas">Todas as Máquinas</option>
                    <option value="Cast 1">Cast 1</option>
                    <option value="Cast 2">Cast 2</option>
                  </select>
                </div>
             </div>

             {/* Segurança e Backup */}
             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-emerald-600 uppercase tracking-widest flex items-center gap-2"><Save size={14} /> Backup e Segurança</h3>
                <p className="text-[10px] text-slate-400 italic">Exporte seus dados regularmente para evitar perdas em limpezas de navegador.</p>
                <button onClick={exportBackup} className="w-full bg-emerald-50 text-emerald-600 border border-emerald-100 p-3 rounded-xl font-black text-[10px] uppercase flex items-center justify-between hover:bg-emerald-100 transition-colors">Exportar Backup (.json) <Download size={16} /></button>
                <button onClick={() => fileInputRef.current?.click()} className="w-full bg-blue-50 text-blue-600 border border-blue-100 p-3 rounded-xl font-black text-[10px] uppercase flex items-center justify-between hover:bg-blue-100 transition-colors">Importar Backup <Upload size={16} /></button>
                <input type="file" ref={fileInputRef} onChange={importBackup} accept=".json" className="hidden" />
                <button onClick={handleResetData} className="w-full bg-red-50 text-red-600 border border-red-100 p-3 rounded-xl font-black text-[10px] uppercase flex items-center justify-between hover:bg-red-100 transition-colors">Resetar Banco Local <RefreshCw size={16} /></button>
             </div>

             {/* Operadores */}
             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Users size={14} /> Operadores</h3>
                <div className="flex gap-2">
                  <input type="text" placeholder="Novo nome..." value={newOperatorName} onChange={(e) => setNewOperatorName(e.target.value)} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold" />
                  <button onClick={handleAddOperator} className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700"><Plus size={16} /></button>
                </div>
             </div>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' ? (
          <>
            <div className="grid grid-cols-2 gap-4">
              {machineStatusCards.map((m) => (
                <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                    <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
                  </div>
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>{m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}</div>
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                  </div>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] text-slate-400 uppercase font-black block">Eficiência</span><span className="text-xl font-black text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] text-slate-400 uppercase font-black block">Total Borra</span><span className="text-xl font-black text-red-500">{formatWeight(stats.borra)}</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] text-slate-400 uppercase font-black block">Paradas</span><span className="text-xl font-black text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100"><span className="text-[9px] text-slate-400 uppercase font-black block">Produção Total</span><span className="text-xl font-black text-blue-600">{formatWeight(stats.totalNet)}</span></div>
            </div>

            <div className={`bg-white rounded-2xl p-6 shadow-sm border ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
              <div className="flex items-center justify-between mb-4 font-black">
                <div><span className="text-[10px] uppercase text-slate-400">Meta Mensal ({currentMonthName})</span><div className="flex items-baseline gap-2"><span className="text-4xl text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span><span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span></div></div>
                <span className={`text-3xl ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
              </div>
              <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden"><div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div></div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {[prodCardRef, stopCardRef].map((ref, idx) => {
                const chartData = idx === 0 ? mainChartData : [{ name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' }, { name: 'PROCESSO', value: stats.proc, unit: 'MIN' }, { name: 'OUTROS', value: stats.outros, unit: 'MIN' }].filter(d => d.value > 0);
                const hasData = chartData.length > 0;

                return (
                  <div key={idx} ref={ref} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 min-h-[520px] flex flex-col">
                    <h3 className="font-black text-xs uppercase text-slate-800 mb-6">{idx === 0 ? 'Produção por Operador' : 'Impacto de Paradas'}</h3>
                    {hasData ? (
                      <div className="flex-1 flex flex-col">
                        <div className="h-[300px]">
                          <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                              <Pie data={chartData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} dataKey="value" paddingAngle={5}>
                                {chartData.map((e: any, i) => <Cell key={`c-${i}`} fill={e.color || (idx === 1 ? ['#f97316', '#f59e0b', '#64748b'][i] : '#3b82f6')} />)}
                              </Pie>
                              <Tooltip />
                              <Legend verticalAlign="bottom" content={renderGridLegend} />
                            </PieChart>
                          </ResponsiveContainer>
                        </div>
                      </div>
                    ) : (
                      <div className="flex-1 flex flex-col items-center justify-center text-slate-300 gap-2"><BarChart3 size={48} /><span className="text-[10px] font-black uppercase">Nenhum dado no período</span></div>
                    )}
                  </div>
                );
              })}
            </div>
          </>
        ) : (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[1200px]">
                <thead>
                  <tr className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                    <th className="px-4 py-3 sticky left-0 bg-slate-50 z-10">Data</th>
                    <th className="px-4 py-3">Operador</th>
                    <th className="px-4 py-3">Máquina</th>
                    <th className="px-4 py-3">P. Líquido</th>
                    <th className="px-4 py-3">Obs/Status</th>
                    <th className="px-4 py-3 text-red-500">Borra</th>
                    <th className="px-4 py-3 text-orange-600">Paradas</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[10px] font-bold">
                  {filteredData.map((e) => (
                    <tr key={e.id} className={`hover:bg-slate-50 ${e.isNoWorkDay ? 'bg-red-50/40 text-red-600' : 'text-slate-600'}`}>
                      <td className="px-4 py-3 sticky left-0 bg-white group-hover:bg-slate-50 transition-colors border-r border-slate-50">{e.date}</td>
                      <td className="px-4 py-3">{e.operator}</td>
                      <td className="px-4 py-3">{e.machine}</td>
                      <td className="px-4 py-3 font-black">{e.netWeight} KG</td>
                      <td className="px-4 py-3">
                        {e.isNoWorkDay ? <span className="bg-red-100 px-2 py-0.5 rounded-full text-[8px]">NÃO OPEROU: {e.noWorkReason}</span> : e.isMaintenanceEntry ? <span className="bg-orange-100 px-2 py-0.5 rounded-full text-[8px]">MANUTENÇÃO TOTAL</span> : '-'}
                      </td>
                      <td className="px-4 py-3 text-red-500">{e.borraTotal}</td>
                      <td className="px-4 py-3 text-orange-600">{ (e.manutencaoMin || 0) + (e.processoMin || 0) + (e.outrosMin || 0) } min</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>
      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Power, Users, Printer, UserPlus, BarChart3, FileText, FileSpreadsheet, Search, Info, Upload, Save } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL, DEFAULT_OPERATORS } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '6.4'; 

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports'>('dashboard');
  const [reportView, setReportView] = useState<'summary' | 'detailed'>('summary');

  // Lógica de Recuperação de Dados de Emergência
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const currentKey = 'manupackaging_data';
      const legacyKeys = ['production_data', 'production-logs', 'production_entries'];
      const savedData = localStorage.getItem(currentKey);

      if (savedData && JSON.parse(savedData).length > 0) return JSON.parse(savedData);

      for (const key of legacyKeys) {
        const legacyData = localStorage.getItem(key);
        if (legacyData) {
          const parsed = JSON.parse(legacyData);
          if (parsed && Array.isArray(parsed) && parsed.length > 0) {
            localStorage.setItem(currentKey, legacyData);
            return parsed;
          }
        }
      }
      return INITIAL_DATA;
    } catch (e) {
      return INITIAL_DATA;
    }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal') || localStorage.getItem('production_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedOps = localStorage.getItem('manupackaging_operators') || localStorage.getItem('production_operators');
    return savedOps ? JSON.parse(savedOps) : DEFAULT_OPERATORS;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [newOperatorName, setNewOperatorName] = useState('');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Filtros
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMonth, setSelectedMonth] = useState<string>('Todos');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  // Salvamento Automático
  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_operators', JSON.stringify(operators)); }, [operators]);
  useEffect(() => { localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus)); }, [machineManualStatus]);

  // Funções de Backup
  const exportBackup = () => {
    const backup = { productionData, goalValue, operators, machineManualStatus, version: APP_DATA_VERSION, exportDate: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `backup_manupackaging_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importBackup = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.productionData) setProductionData(json.productionData);
        if (json.goalValue) setGoalValue(json.goalValue);
        if (json.operators) setOperators(json.operators);
        if (json.machineManualStatus) setMachineManualStatus(json.machineManualStatus);
        alert("Dados restaurados com sucesso!");
        setIsMenuOpen(false);
      } catch (err) {
        alert("Erro ao importar arquivo.");
      }
    };
    reader.readAsText(file);
  };

  const availableMonths = useMemo(() => {
    const months = new Set<string>();
    productionData.forEach(entry => {
      const parts = entry.date.split('-');
      months.add(`${parts[0]}-${parts[1]}`);
    });
    return Array.from(months).sort((a, b) => b.localeCompare(a));
  }, [productionData]);

  const handleMonthChange = (month: string) => {
    setSelectedMonth(month);
    if (month === 'Todos') {
      setStartDate('');
      setEndDate('');
    } else {
      const [year, monthNum] = month.split('-');
      const firstDay = `${year}-${monthNum}-01`;
      const lastDay = new Date(parseInt(year), parseInt(monthNum), 0).getDate();
      const lastDayStr = `${year}-${monthNum}-${String(lastDay).padStart(2, '0')}`;
      setStartDate(firstDay);
      setEndDate(lastDayStr);
    }
  };

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const qualityEfficiency = useMemo(() => stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0, [stats]);
  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const currentMonthPrefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    return productionData.filter(entry => entry.date.startsWith(currentMonthPrefix)).reduce((sum, entry) => sum + (entry.netWeight || 0), 0);
  }, [productionData]);

  const isGoalAchieved = currentMonthStats >= goalValue && goalValue > 0;
  const currentMonthName = useMemo(() => new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(new Date()).toUpperCase(), []);

  const machineStatusCards = useMemo(() => ['Cast 1', 'Cast 2'].map(m => ({ name: m, status: machineManualStatus[m] || 'Operando' })), [machineManualStatus]);
  const toggleMachineStatus = (machineName: string) => setMachineManualStatus(prev => ({ ...prev, [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando' }));
  const activeMachines = useMemo(() => Object.entries(machineManualStatus).filter(([_, status]) => status === 'Operando').map(([name]) => name), [machineManualStatus]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) }, ...prev]);
  const handleAddOperator = () => {
    if (!newOperatorName.trim() || operators.includes(newOperatorName.trim())) return;
    setOperators(prev => [...prev, newOperatorName.trim()].sort());
    setNewOperatorName('');
  };
  const handleRemoveOperator = (op: string) => {
    if (confirm(`Excluir o operador ${op}?`)) setOperators(prev => prev.filter(o => o !== op));
  };
  const handleResetData = () => { if (confirm('ATENÇÃO: Isso apagará TODOS os lançamentos salvos localmente. Deseja continuar?')) { setProductionData(INITIAL_DATA); setIsMenuOpen(false); } };

  // Gráficos (Só operadores com dados aparecem na legenda)
  const mainChartData = useMemo(() => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];
    if (selectedOperator === 'Todos') {
      const performanceMap: Record<string, number> = {};
      operators.forEach(op => { performanceMap[op] = 0; });
      filteredData.forEach(entry => { if (performanceMap[entry.operator] !== undefined) performanceMap[entry.operator] += (entry.netWeight || 0); });
      return Object.entries(performanceMap)
        .filter(([_, kg]) => kg > 0)
        .sort((a, b) => b[1] - a[1])
        .map(([name, kg], index) => ({ name, value: kg, color: colors[index % colors.length], unit: 'KG' }));
    } else {
      return [{ name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG' }, { name: 'ECO A', value: stats.ecoA, unit: 'KG' }, { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG' }, { name: 'BORRA', value: stats.borra, unit: 'KG' }].filter(d => d.value > 0).sort((a, b) => b.value - a.value).map((item, index) => ({ ...item, color: colors[index % colors.length] }));
    }
  }, [filteredData, selectedOperator, stats, operators]);

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload || payload.length === 0) return <div className="text-center text-[10px] text-slate-400 mt-8 font-bold">Nenhum dado registrado</div>;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);
    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";
          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>{index + 1}º</div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{data.name}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>{formatWeight(data.value, data.unit)}</span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => window.print()} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 border border-slate-200" title="Imprimir"><Printer size={18} /></button>
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="bg-slate-200/50 p-1 rounded-2xl inline-flex gap-1">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><BarChart3 size={16} /> Dashboard</button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><FileText size={16} /> Relatórios</button>
        </div>
      </div>

      {/* Menu Lateral Restaurado com Todas as Informações */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> CONFIGURAÇÕES</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>

          <div className="space-y-6">
             {/* 1. Busca e Filtros */}
             <div className="space-y-4">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Search size={14} /> Busca e Filtros</h3>
                <div className="space-y-2">
                  <div className="space-y-1">
                    <label className="text-[9px] font-bold text-slate-500 uppercase">Por Mês</label>
                    <select value={selectedMonth} onChange={(e) => handleMonthChange(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-blue-600">
                      <option value="Todos">Exibir Tudo (Mês)</option>
                      {availableMonths.map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold text-slate-500 uppercase">Início</label>
                      <input type="date" value={startDate} onChange={(e) => {setStartDate(e.target.value); setSelectedMonth('Todos');}} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold text-slate-500 uppercase">Fim</label>
                      <input type="date" value={endDate} onChange={(e) => {setEndDate(e.target.value); setSelectedMonth('Todos');}} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-2 py-2 text-[10px] font-bold" />
                    </div>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-bold text-slate-500 uppercase">Máquina</label>
                    <select value={selectedMachine} onChange={(e) => setSelectedMachine(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold">
                      <option value="Todas">Todas as Máquinas</option>
                      <option value="Cast 1">Cast 1</option>
                      <option value="Cast 2">Cast 2</option>
                    </select>
                  </div>
                </div>
             </div>

             {/* 2. Gerenciar Operadores */}
             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Users size={14} /> Gerenciar Operadores</h3>
                <div className="flex gap-2">
                  <input type="text" placeholder="Nome..." value={newOperatorName} onChange={(e) => setNewOperatorName(e.target.value)} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold" />
                  <button onClick={handleAddOperator} className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700"><UserPlus size={16} /></button>
                </div>
                <div className="max-h-40 overflow-y-auto custom-scrollbar space-y-1 pr-2">
                  {operators.map(op => (
                    <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg border border-slate-100 group">
                      <span className="text-[11px] font-bold text-slate-700">{op}</span>
                      <button onClick={() => handleRemoveOperator(op)} className="text-slate-300 hover:text-red-500 transition-colors"><Trash2 size={14} /></button>
                    </div>
                  ))}
                </div>
             </div>

             {/* 3. Meta Mensal */}
             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Target size={14} /> Meta de Produção (KG)</h3>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600 focus:outline-none" />
             </div>

             {/* 4. Segurança e Backup */}
             <div className="space-y-3 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-emerald-600 uppercase tracking-widest flex items-center gap-2"><Save size={14} /> Segurança de Dados</h3>
                <button onClick={exportBackup} className="w-full bg-emerald-50 text-emerald-600 border border-emerald-100 p-3 rounded-xl font-black text-[10px] uppercase flex items-center justify-between hover:bg-emerald-100 transition-colors">Exportar Backup (.json) <Download size={16} /></button>
                <button onClick={() => fileInputRef.current?.click()} className="w-full bg-blue-50 text-blue-600 border border-blue-100 p-3 rounded-xl font-black text-[10px] uppercase flex items-center justify-between hover:bg-blue-100 transition-colors">Importar Backup <Upload size={16} /></button>
                <input type="file" ref={fileInputRef} onChange={importBackup} accept=".json" className="hidden" />
                <button onClick={handleResetData} className="w-full bg-red-50 text-red-600 border border-red-100 p-3 rounded-xl font-black text-[10px] uppercase flex items-center justify-between hover:bg-red-100 transition-colors">Resetar Banco Local <RefreshCw size={16} /></button>
             </div>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' ? (
          <>
            <div className="grid grid-cols-2 gap-4">
              {machineStatusCards.map((m) => (
                <div key={m.name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{m.name}</span>
                    <button onClick={() => toggleMachineStatus(m.name)} className={`p-1.5 rounded-lg ${m.status === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
                  </div>
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center ${m.status === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>{m.status === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}</div>
                    <span className="text-sm font-bold text-slate-700">{m.status}</span>
                  </div>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Eficiência</span><span className="text-xl text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Total Borra</span><span className="text-xl text-red-500">{formatWeight(stats.borra)}</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Paradas</span><span className="text-xl text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Produção Total</span><span className="text-xl text-blue-600">{formatWeight(stats.totalNet)}</span></div>
            </div>

            <div className={`bg-white rounded-2xl p-6 shadow-sm border ${isGoalAchieved ? 'border-emerald-500' : 'border-blue-500/10'}`}>
              <div className="flex items-center justify-between mb-4 font-black">
                <div><span className="text-[10px] uppercase text-slate-400">Meta Mensal ({currentMonthName})</span><div className="flex items-baseline gap-2"><span className="text-4xl text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span><span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span></div></div>
                <span className={`text-3xl ${isGoalAchieved ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
              </div>
              <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden"><div className={`h-full rounded-full transition-all duration-1000 ${isGoalAchieved ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div></div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {[prodCardRef, stopCardRef].map((ref, idx) => {
                const chartData = idx === 0 ? mainChartData : [{ name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN' }, { name: 'PROCESSO', value: stats.proc, unit: 'MIN' }, { name: 'OUTROS', value: stats.outros, unit: 'MIN' }].filter(d => d.value > 0);
                const hasData = chartData.length > 0;

                return (
                  <div key={idx} ref={ref} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[520px]">
                    <h3 className="font-black text-xs uppercase tracking-widest text-slate-800 mb-6">{idx === 0 ? 'Produção por Operador' : 'Impacto de Paradas'}</h3>
                    {hasData ? (
                      <div className="flex-1">
                        <ResponsiveContainer width="100%" height={350}>
                          <PieChart>
                            <Pie data={chartData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} dataKey="value" paddingAngle={5}>
                              {chartData.map((e: any, i) => <Cell key={`c-${i}`} fill={e.color || (idx === 1 ? ['#f97316', '#f59e0b', '#64748b'][i] : '#3b82f6')} />)}
                            </Pie>
                            <Tooltip />
                            <Legend verticalAlign="bottom" content={renderGridLegend} />
                          </PieChart>
                        </ResponsiveContainer>
                      </div>
                    ) : (
                      <div className="flex-1 flex flex-col items-center justify-center text-slate-300 gap-2"><BarChart3 size={48} /><span className="text-[10px] font-black uppercase">Nenhum dado</span></div>
                    )}
                  </div>
                );
              })}
            </div>
          </>
        ) : (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[1200px]">
                <thead>
                  <tr className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                    <th className="px-4 py-3 sticky left-0 bg-slate-50 z-10">Data</th>
                    <th className="px-4 py-3">Operador</th>
                    <th className="px-4 py-3">Máquina</th>
                    <th className="px-4 py-3">P. Líquido</th>
                    <th className="px-4 py-3">Status</th>
                    <th className="px-4 py-3 text-red-500">Borra</th>
                    <th className="px-4 py-3 text-orange-600">Paradas</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[10px] font-bold">
                  {filteredData.map((e) => (
                    <tr key={e.id} className={`hover:bg-slate-50 ${e.isNoWorkDay ? 'bg-red-50/40 text-red-600' : 'text-slate-600'}`}>
                      <td className="px-4 py-3 sticky left-0 bg-white group-hover:bg-slate-50 transition-colors border-r border-slate-50">{e.date}</td>
                      <td className="px-4 py-3">{e.operator}</td>
                      <td className="px-4 py-3">{e.machine}</td>
                      <td className="px-4 py-3 font-black">{e.netWeight} KG</td>
                      <td className="px-4 py-3">
                        {e.isNoWorkDay ? <span className="bg-red-100 px-2 py-0.5 rounded-full text-[8px]">NÃO OPEROU</span> : e.isMaintenanceEntry ? <span className="bg-orange-100 px-2 py-0.5 rounded-full text-[8px]">MANUTENÇÃO</span> : '-'}
                      </td>
                      <td className="px-4 py-3 text-red-500">{e.borraTotal}</td>
                      <td className="px-4 py-3 text-orange-600">{ (e.manutencaoMin || 0) + (e.processoMin || 0) + (e.outrosMin || 0) } min</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>
      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Power, Users, Printer, UserPlus, BarChart3, FileText, FileSpreadsheet, Search, Info, Upload, Save } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL, DEFAULT_OPERATORS } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '6.5'; 

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports'>('dashboard');
  const [reportView, setReportView] = useState<'summary' | 'detailed'>('summary');

  // Lógica de Recuperação de Dados de Emergência (Busca em chaves antigas e novas)
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const currentKey = 'manupackaging_data';
      const legacyKeys = ['production_data', 'production-logs', 'production_entries'];
      const savedData = localStorage.getItem(currentKey);

      if (savedData && JSON.parse(savedData).length > 0) return JSON.parse(savedData);

      for (const key of legacyKeys) {
        const legacyData = localStorage.getItem(key);
        if (legacyData) {
          const parsed = JSON.parse(legacyData);
          if (parsed && Array.isArray(parsed) && parsed.length > 0) {
            localStorage.setItem(currentKey, legacyData);
            return parsed;
          }
        }
      }
      return INITIAL_DATA;
    } catch (e) {
      return INITIAL_DATA;
    }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal') || localStorage.getItem('production_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedOps = localStorage.getItem('manupackaging_operators') || localStorage.getItem('production_operators');
    return savedOps ? JSON.parse(savedOps) : DEFAULT_OPERATORS;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [newOperatorName, setNewOperatorName] = useState('');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Filtros
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMonth, setSelectedMonth] = useState<string>('Todos');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  // Salvamento Automático
  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_operators', JSON.stringify(operators)); }, [operators]);
  useEffect(() => { localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus)); }, [machineManualStatus]);

  // Funcionalidade de Download de Imagem do Card
  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    toPng(containerRef.current, { 
      filter: (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export')),
      backgroundColor: '#ffffff',
      pixelRatio: 3,
      cacheBust: true,
    })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error('Erro ao baixar imagem:', err));
  };

  const handleMonthChange = (month: string) => {
    setSelectedMonth(month);
    if (month === 'Todos') {
      setStartDate('');
      setEndDate('');
    } else {
      const [year, monthNum] = month.split('-');
      const firstDay = `${year}-${monthNum}-01`;
      const lastDay = new Date(parseInt(year), parseInt(monthNum), 0).getDate();
      const lastDayStr = `${year}-${monthNum}-${String(lastDay).padStart(2, '0')}`;
      setStartDate(firstDay);
      setEndDate(lastDayStr);
    }
  };

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  // Preparação de Dados para os Gráficos
  const chartColors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];

  const mainChartData = useMemo(() => {
    if (selectedOperator !== 'Todos') {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG', color: '#3b82f6' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG', color: '#10b981' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG', color: '#8b5cf6' },
        { name: 'BORRA', value: stats.borra, unit: 'KG', color: '#ef4444' }
      ].filter(d => d.value > 0);
    }
    const map: Record<string, number> = {};
    operators.forEach(op => map[op] = 0);
    filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.netWeight || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: chartColors[i % chartColors.length] }));
  }, [filteredData, operators, selectedOperator, stats]);

  const stopChartData = useMemo(() => {
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN', color: '#f97316' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN', color: '#f59e0b' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN', color: '#94a3b8' }
    ].filter(d => d.value > 0);
  }, [stats]);

  const ecoAChartData = useMemo(() => {
    const map: Record<string, number> = {};
    operators.forEach(op => map[op] = 0);
    filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.ecoA || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: ['#10b981', '#34d399', '#6ee7b7', '#059669'][i % 4] }));
  }, [filteredData, operators]);

  const ecoBChartData = useMemo(() => {
    const map: Record<string, number> = {};
    operators.forEach(op => map[op] = 0);
    filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.ecoBP || 0) + (e.ecoBM || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: ['#8b5cf6', '#a78bfa', '#c4b5fd', '#7c3aed'][i % 4] }));
  }, [filteredData, operators]);

  const chartDescriptions = [
    "Análise comparativa da produção líquida total por operador ou categoria, destacando os maiores volumes e desempenho de meta.",
    "Distribuição do tempo de inatividade da planta, categorizado entre manutenções, ajustes de processo e outros motivos externos.",
    "Visualização do volume de recuperação Eco A por colaborador, permitindo identificar os turnos com maior eficiência de reciclagem primária.",
    "Monitoramento de materiais Eco B (Pequenos e Médios) gerados durante a operação, crucial para o controle de desperdício."
  ];

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload || payload.length === 0) return <div className="text-center text-[10px] text-slate-400 mt-8 font-bold">Nenhum dado registrado</div>;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);
    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";
          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>{index + 1}º</div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: data.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{data.name}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>{formatWeight(data.value, data.unit)}</span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
    const x = cx + radius * Math.cos(-midAngle * RADIAN);
    const y = cy + radius * Math.sin(-midAngle * RADIAN);
    return percent > 0.05 ? (
      <text x={x} y={y} fill="white" textAnchor="middle" dominantBaseline="central" fontSize={9} fontWeight="black">
        {`${(percent * 100).toFixed(0)}%`}
      </text>
    ) : null;
  };

  // Funções de Gestão e UI
  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const prefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    return productionData.filter(e => e.date.startsWith(prefix)).reduce((s, e) => s + (e.netWeight || 0), 0);
  }, [productionData]);

  const toggleMachineStatus = (machineName: string) => setMachineManualStatus(prev => ({ ...prev, [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando' }));
  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) }, ...prev]);
  const handleAddOperator = () => { if (!newOperatorName.trim() || operators.includes(newOperatorName.trim())) return; setOperators(prev => [...prev, newOperatorName.trim()].sort()); setNewOperatorName(''); };
  const handleRemoveOperator = (op: string) => { if (confirm(`Excluir o operador ${op}?`)) setOperators(prev => prev.filter(o => o !== op)); };

  const availableMonths = useMemo(() => Array.from(new Set(productionData.map(e => e.date.substring(0,7)))).sort((a,b) => b.localeCompare(a)), [productionData]);
  const qualityEfficiency = useMemo(() => stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0, [stats]);

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="bg-slate-200/50 p-1 rounded-2xl inline-flex gap-1">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><BarChart3 size={16} /> Dashboard</button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><FileText size={16} /> Relatórios</button>
        </div>
      </div>

      {/* Menu Lateral Completo */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> CONFIGURAÇÕES</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>

          <div className="space-y-6">
             <div className="space-y-4">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Search size={14} /> Filtros</h3>
                <div className="space-y-2">
                  <select value={selectedMonth} onChange={(e) => handleMonthChange(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-blue-600">
                    <option value="Todos">Exibir Tudo (Mês)</option>
                    {availableMonths.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                  <select value={selectedMachine} onChange={(e) => setSelectedMachine(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold">
                    <option value="Todas">Todas as Máquinas</option>
                    <option value="Cast 1">Cast 1</option>
                    <option value="Cast 2">Cast 2</option>
                  </select>
                </div>
             </div>

             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Users size={14} /> Operadores</h3>
                <div className="flex gap-2">
                  <input type="text" placeholder="Nome..." value={newOperatorName} onChange={(e) => setNewOperatorName(e.target.value)} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold" />
                  <button onClick={handleAddOperator} className="bg-blue-600 text-white p-2 rounded-xl"><UserPlus size={16} /></button>
                </div>
                <div className="max-h-40 overflow-y-auto custom-scrollbar space-y-1">
                  {operators.map(op => (
                    <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg border border-slate-100">
                      <span className="text-[11px] font-bold text-slate-700">{op}</span>
                      <button onClick={() => handleRemoveOperator(op)} className="text-slate-300 hover:text-red-500"><Trash2 size={14} /></button>
                    </div>
                  ))}
                </div>
             </div>

             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Target size={14} /> Meta Mensal (KG)</h3>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600" />
             </div>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' ? (
          <>
            <div className="grid grid-cols-2 gap-4">
              {['Cast 1', 'Cast 2'].map((name) => (
                <div key={name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{name}</span>
                    <button onClick={() => toggleMachineStatus(name)} className={`p-1.5 rounded-lg ${machineManualStatus[name] === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
                  </div>
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center ${machineManualStatus[name] === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>{machineManualStatus[name] === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}</div>
                    <span className="text-sm font-bold text-slate-700">{machineManualStatus[name] || 'Operando'}</span>
                  </div>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Eficiência</span><span className="text-xl text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Total Borra</span><span className="text-xl text-red-500">{formatWeight(stats.borra)}</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Paradas</span><span className="text-xl text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Produção Total</span><span className="text-xl text-blue-600">{formatWeight(stats.totalNet)}</span></div>
            </div>

            <div className="bg-white rounded-2xl p-6 shadow-sm border border-blue-500/10">
              <div className="flex items-center justify-between mb-4 font-black">
                <div><span className="text-[10px] uppercase text-slate-400">Meta Mensal</span><div className="flex items-baseline gap-2"><span className="text-4xl text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span><span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span></div></div>
                <span className="text-3xl text-blue-600">{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
              </div>
              <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden"><div className="h-full bg-blue-600 rounded-full transition-all duration-1000" style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div></div>
            </div>

            {/* Os 4 Gráficos Restaurados */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {[
                { ref: prodCardRef, title: 'Produção Total', data: mainChartData, id: 'prod' },
                { ref: stopCardRef, title: 'Impacto de Paradas', data: stopChartData, id: 'stop' },
                { ref: ecoACardRef, title: 'Distribuição Eco A', data: ecoAChartData, id: 'ecoa' },
                { ref: ecoBCardRef, title: 'Distribuição Eco B', data: ecoBChartData, id: 'ecob' }
              ].map((chart, idx) => (
                <div key={chart.id} ref={chart.ref} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[620px]">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="font-black text-xs uppercase tracking-widest text-slate-800">{chart.title}</h3>
                    <button onClick={() => downloadCardAsImage(chart.ref, chart.id)} className="p-1.5 text-slate-300 hover:text-blue-600 no-export transition-colors">
                      <Download size={16} />
                    </button>
                  </div>
                  <div className="h-[400px] w-full pt-4">
                    {chart.data.length > 0 ? (
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={chart.data} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}> 
                            {chart.data.map((e: any, i) => <Cell key={`c-${i}`} fill={e.color} stroke="none" />)} 
                          </Pie>
                          <Tooltip />
                          <Legend verticalAlign="bottom" content={renderGridLegend} />
                        </PieChart>
                      </ResponsiveContainer>
                    ) : (
                      <div className="flex flex-col items-center justify-center h-full text-slate-300 gap-2"><BarChart3 size={48} /><span className="text-[10px] font-black uppercase">Nenhum dado</span></div>
                    )}
                  </div>
                  <div className="mt-auto pt-6 flex items-start gap-2 bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <Info size={14} className="shrink-0 mt-0.5 text-slate-400" />
                    <p className="text-[10px] text-slate-500 leading-relaxed font-medium italic">{chartDescriptions[idx]}</p>
                  </div>
                </div>
              ))}
            </div>
          </>
        ) : (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[1200px]">
                <thead>
                  <tr className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                    <th className="px-4 py-3 sticky left-0 bg-slate-50 z-10">Data</th>
                    <th className="px-4 py-3">Operador</th>
                    <th className="px-4 py-3">Máquina</th>
                    <th className="px-4 py-3 font-black text-blue-700">P. Líquido</th>
                    <th className="px-4 py-3">Status</th>
                    <th className="px-4 py-3 text-red-500">Borra</th>
                    <th className="px-4 py-3 text-orange-600">Paradas (Min)</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[10px] font-bold">
                  {filteredData.map((e) => (
                    <tr key={e.id} className={`hover:bg-slate-50 ${e.isNoWorkDay ? 'bg-red-50/40 text-red-600' : 'text-slate-600'}`}>
                      <td className="px-4 py-3 sticky left-0 bg-white group-hover:bg-slate-50 border-r border-slate-50">{e.date}</td>
                      <td className="px-4 py-3">{e.operator}</td>
                      <td className="px-4 py-3">{e.machine}</td>
                      <td className="px-4 py-3 font-black">{e.netWeight} KG</td>
                      <td className="px-4 py-3">
                        {e.isNoWorkDay ? <span className="bg-red-100 px-2 py-0.5 rounded-full text-[8px]">NÃO OPEROU</span> : e.isMaintenanceEntry ? <span className="bg-orange-100 px-2 py-0.5 rounded-full text-[8px]">MANUTENÇÃO</span> : '-'}
                      </td>
                      <td className="px-4 py-3 text-red-500">{e.borraTotal}</td>
                      <td className="px-4 py-3 text-orange-600">{(e.manutencaoMin||0) + (e.processoMin||0) + (e.outrosMin||0)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>
      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={Object.entries(machineManualStatus).filter(([_, s]) => s === 'Operando').map(([n]) => n)} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Power, Users, Printer, UserPlus, BarChart3, FileText, FileSpreadsheet, Search, Info, Upload, Save } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL, DEFAULT_OPERATORS } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '6.5'; 

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports'>('dashboard');
  const [reportView, setReportView] = useState<'summary' | 'detailed'>('summary');

  // Lógica de Recuperação de Dados de Emergência (Busca em chaves antigas e novas)
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const currentKey = 'manupackaging_data';
      const legacyKeys = ['production_data', 'production-logs', 'production_entries'];
      const savedData = localStorage.getItem(currentKey);

      if (savedData && JSON.parse(savedData).length > 0) return JSON.parse(savedData);

      for (const key of legacyKeys) {
        const legacyData = localStorage.getItem(key);
        if (legacyData) {
          const parsed = JSON.parse(legacyData);
          if (parsed && Array.isArray(parsed) && parsed.length > 0) {
            localStorage.setItem(currentKey, legacyData);
            return parsed;
          }
        }
      }
      return INITIAL_DATA;
    } catch (e) {
      return INITIAL_DATA;
    }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal') || localStorage.getItem('production_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedOps = localStorage.getItem('manupackaging_operators') || localStorage.getItem('production_operators');
    return savedOps ? JSON.parse(savedOps) : DEFAULT_OPERATORS;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    return saved ? JSON.parse(saved) : { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [newOperatorName, setNewOperatorName] = useState('');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Filtros
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMonth, setSelectedMonth] = useState<string>('Todos');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  // Salvamento Automático
  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_operators', JSON.stringify(operators)); }, [operators]);
  useEffect(() => { localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus)); }, [machineManualStatus]);

  // Funcionalidade de Download de Imagem do Card
  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    toPng(containerRef.current, { 
      filter: (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export')),
      backgroundColor: '#ffffff',
      pixelRatio: 3,
      cacheBust: true,
    })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error('Erro ao baixar imagem:', err));
  };

  const handleMonthChange = (month: string) => {
    setSelectedMonth(month);
    if (month === 'Todos') {
      setStartDate('');
      setEndDate('');
    } else {
      const [year, monthNum] = month.split('-');
      const firstDay = `${year}-${monthNum}-01`;
      const lastDay = new Date(parseInt(year), parseInt(monthNum), 0).getDate();
      const lastDayStr = `${year}-${monthNum}-${String(lastDay).padStart(2, '0')}`;
      setStartDate(firstDay);
      setEndDate(lastDayStr);
    }
  };

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  // Preparação de Dados para os Gráficos
  const chartColors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];

  const mainChartData = useMemo(() => {
    if (selectedOperator !== 'Todos') {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG', color: '#3b82f6' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG', color: '#10b981' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG', color: '#8b5cf6' },
        { name: 'BORRA', value: stats.borra, unit: 'KG', color: '#ef4444' }
      ].filter(d => d.value > 0);
    }
    const map: Record<string, number> = {};
    operators.forEach(op => map[op] = 0);
    filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.netWeight || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: chartColors[i % chartColors.length] }));
  }, [filteredData, operators, selectedOperator, stats]);

  const stopChartData = useMemo(() => {
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN', color: '#f97316' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN', color: '#f59e0b' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN', color: '#94a3b8' }
    ].filter(d => d.value > 0);
  }, [stats]);

  const ecoAChartData = useMemo(() => {
    const map: Record<string, number> = {};
    operators.forEach(op => map[op] = 0);
    filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.ecoA || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: ['#10b981', '#34d399', '#6ee7b7', '#059669'][i % 4] }));
  }, [filteredData, operators]);

  const ecoBChartData = useMemo(() => {
    const map: Record<string, number> = {};
    operators.forEach(op => map[op] = 0);
    filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.ecoBP || 0) + (e.ecoBM || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: ['#8b5cf6', '#a78bfa', '#c4b5fd', '#7c3aed'][i % 4] }));
  }, [filteredData, operators]);

  const chartDescriptions = [
    "Análise comparativa da produção líquida total por operador ou categoria, destacando os maiores volumes e desempenho de meta.",
    "Distribuição do tempo de inatividade da planta, categorizado entre manutenções, ajustes de processo e outros motivos externos.",
    "Visualização do volume de recuperação Eco A por colaborador, permitindo identificar os turnos com maior eficiência de reciclagem primária.",
    "Monitoramento de materiais Eco B (Pequenos e Médios) gerados durante a operação, crucial para o controle de desperdício."
  ];

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload || payload.length === 0) return <div className="text-center text-[10px] text-slate-400 mt-8 font-bold">Nenhum dado registrado</div>;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);
    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";
          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>{index + 1}º</div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: data.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{data.name}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>{formatWeight(data.value, data.unit)}</span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
    const x = cx + radius * Math.cos(-midAngle * RADIAN);
    const y = cy + radius * Math.sin(-midAngle * RADIAN);
    return percent > 0.05 ? (
      <text x={x} y={y} fill="white" textAnchor="middle" dominantBaseline="central" fontSize={9} fontWeight="black">
        {`${(percent * 100).toFixed(0)}%`}
      </text>
    ) : null;
  };

  // Funções de Gestão e UI
  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const prefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    return productionData.filter(e => e.date.startsWith(prefix)).reduce((s, e) => s + (e.netWeight || 0), 0);
  }, [productionData]);

  const toggleMachineStatus = (machineName: string) => setMachineManualStatus(prev => ({ ...prev, [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando' }));
  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) }, ...prev]);
  const handleAddOperator = () => { if (!newOperatorName.trim() || operators.includes(newOperatorName.trim())) return; setOperators(prev => [...prev, newOperatorName.trim()].sort()); setNewOperatorName(''); };
  const handleRemoveOperator = (op: string) => { if (confirm(`Excluir o operador ${op}?`)) setOperators(prev => prev.filter(o => o !== op)); };

  // Explicitly typing sort parameters as strings to resolve 'unknown' type issue on line 242.
  const availableMonths = useMemo(() => Array.from(new Set(productionData.map(e => e.date.substring(0,7)))).sort((a: string, b: string) => b.localeCompare(a)), [productionData]);
  const qualityEfficiency = useMemo(() => stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0, [stats]);

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="bg-slate-200/50 p-1 rounded-2xl inline-flex gap-1">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><BarChart3 size={16} /> Dashboard</button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><FileText size={16} /> Relatórios</button>
        </div>
      </div>

      {/* Menu Lateral Completo */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> CONFIGURAÇÕES</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>

          <div className="space-y-6">
             <div className="space-y-4">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Search size={14} /> Filtros</h3>
                <div className="space-y-2">
                  <select value={selectedMonth} onChange={(e) => handleMonthChange(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-blue-600">
                    <option value="Todos">Exibir Tudo (Mês)</option>
                    {availableMonths.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                  <select value={selectedMachine} onChange={(e) => setSelectedMachine(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold">
                    <option value="Todas">Todas as Máquinas</option>
                    <option value="Cast 1">Cast 1</option>
                    <option value="Cast 2">Cast 2</option>
                  </select>
                </div>
             </div>

             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Users size={14} /> Operadores</h3>
                <div className="flex gap-2">
                  <input type="text" placeholder="Nome..." value={newOperatorName} onChange={(e) => setNewOperatorName(e.target.value)} className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold" />
                  <button onClick={handleAddOperator} className="bg-blue-600 text-white p-2 rounded-xl"><UserPlus size={16} /></button>
                </div>
                <div className="max-h-40 overflow-y-auto custom-scrollbar space-y-1">
                  {operators.map(op => (
                    <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg border border-slate-100">
                      <span className="text-[11px] font-bold text-slate-700">{op}</span>
                      <button onClick={() => handleRemoveOperator(op)} className="text-slate-300 hover:text-red-500"><Trash2 size={14} /></button>
                    </div>
                  ))}
                </div>
             </div>

             <div className="space-y-4 pt-4 border-t border-slate-100">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Target size={14} /> Meta Mensal (KG)</h3>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600" />
             </div>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' ? (
          <>
            <div className="grid grid-cols-2 gap-4">
              {['Cast 1', 'Cast 2'].map((name) => (
                <div key={name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{name}</span>
                    <button onClick={() => toggleMachineStatus(name)} className={`p-1.5 rounded-lg ${machineManualStatus[name] === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button>
                  </div>
                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center ${machineManualStatus[name] === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>{machineManualStatus[name] === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}</div>
                    <span className="text-sm font-bold text-slate-700">{machineManualStatus[name] || 'Operando'}</span>
                  </div>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Eficiência</span><span className="text-xl text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Total Borra</span><span className="text-xl text-red-500">{formatWeight(stats.borra)}</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Paradas</span><span className="text-xl text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Produção Total</span><span className="text-xl text-blue-600">{formatWeight(stats.totalNet)}</span></div>
            </div>

            <div className="bg-white rounded-2xl p-6 shadow-sm border border-blue-500/10">
              <div className="flex items-center justify-between mb-4 font-black">
                <div><span className="text-[10px] uppercase text-slate-400">Meta Mensal</span><div className="flex items-baseline gap-2"><span className="text-4xl text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span><span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span></div></div>
                <span className="text-3xl text-blue-600">{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
              </div>
              <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden"><div className="h-full bg-blue-600 rounded-full transition-all duration-1000" style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div></div>
            </div>

            {/* Os 4 Gráficos Restaurados */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {[
                { ref: prodCardRef, title: 'Produção Total', data: mainChartData, id: 'prod' },
                { ref: stopCardRef, title: 'Impacto de Paradas', data: stopChartData, id: 'stop' },
                { ref: ecoACardRef, title: 'Distribuição Eco A', data: ecoAChartData, id: 'ecoa' },
                { ref: ecoBCardRef, title: 'Distribuição Eco B', data: ecoBChartData, id: 'ecob' }
              ].map((chart, idx) => (
                <div key={chart.id} ref={chart.ref} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[620px]">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="font-black text-xs uppercase tracking-widest text-slate-800">{chart.title}</h3>
                    <button onClick={() => downloadCardAsImage(chart.ref, chart.id)} className="p-1.5 text-slate-300 hover:text-blue-600 no-export transition-colors">
                      <Download size={16} />
                    </button>
                  </div>
                  <div className="h-[400px] w-full pt-4">
                    {chart.data.length > 0 ? (
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={chart.data} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}> 
                            {chart.data.map((e: any, i) => <Cell key={`c-${i}`} fill={e.color} stroke="none" />)} 
                          </Pie>
                          <Tooltip />
                          <Legend verticalAlign="bottom" content={renderGridLegend} />
                        </PieChart>
                      </ResponsiveContainer>
                    ) : (
                      <div className="flex flex-col items-center justify-center h-full text-slate-300 gap-2"><BarChart3 size={48} /><span className="text-[10px] font-black uppercase">Nenhum dado</span></div>
                    )}
                  </div>
                  <div className="mt-auto pt-6 flex items-start gap-2 bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <Info size={14} className="shrink-0 mt-0.5 text-slate-400" />
                    <p className="text-[10px] text-slate-500 leading-relaxed font-medium italic">{chartDescriptions[idx]}</p>
                  </div>
                </div>
              ))}
            </div>
          </>
        ) : (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[1200px]">
                <thead>
                  <tr className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                    <th className="px-4 py-3 sticky left-0 bg-slate-50 z-10">Data</th>
                    <th className="px-4 py-3">Operador</th>
                    <th className="px-4 py-3">Máquina</th>
                    <th className="px-4 py-3 font-black text-blue-700">P. Líquido</th>
                    <th className="px-4 py-3">Status</th>
                    <th className="px-4 py-3 text-red-500">Borra</th>
                    <th className="px-4 py-3 text-orange-600">Paradas (Min)</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[10px] font-bold">
                  {filteredData.map((e) => (
                    <tr key={e.id} className={`hover:bg-slate-50 ${e.isNoWorkDay ? 'bg-red-50/40 text-red-600' : 'text-slate-600'}`}>
                      <td className="px-4 py-3 sticky left-0 bg-white group-hover:bg-slate-50 border-r border-slate-50">{e.date}</td>
                      <td className="px-4 py-3">{e.operator}</td>
                      <td className="px-4 py-3">{e.machine}</td>
                      <td className="px-4 py-3 font-black">{e.netWeight} KG</td>
                      <td className="px-4 py-3">
                        {e.isNoWorkDay ? <span className="bg-red-100 px-2 py-0.5 rounded-full text-[8px]">NÃO OPEROU</span> : e.isMaintenanceEntry ? <span className="bg-orange-100 px-2 py-0.5 rounded-full text-[8px]">MANUTENÇÃO</span> : '-'}
                      </td>
                      <td className="px-4 py-3 text-red-500">{e.borraTotal}</td>
                      <td className="px-4 py-3 text-orange-600">{(e.manutencaoMin||0) + (e.processoMin||0) + (e.outrosMin||0)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>
      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={Object.entries(machineManualStatus).filter(([_, s]) => s === 'Operando').map(([n]) => n)} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Power, Users, Printer, UserPlus, BarChart3, FileText, FileSpreadsheet, Search, Info, Upload, Save } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL, DEFAULT_OPERATORS } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '6.7'; 

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports'>('dashboard');

  // Inicialização robusta dos dados de produção com fallback para chaves legadas
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const currentKey = 'manupackaging_data';
      const legacyKeys = ['production_data', 'production-logs', 'production_entries'];
      const savedData = localStorage.getItem(currentKey);

      if (savedData) {
        const parsed = JSON.parse(savedData);
        if (Array.isArray(parsed) && parsed.length > 0) return parsed;
      }

      for (const key of legacyKeys) {
        const legacyData = localStorage.getItem(key);
        if (legacyData) {
          const parsed = JSON.parse(legacyData);
          if (Array.isArray(parsed) && parsed.length > 0) {
            localStorage.setItem(currentKey, legacyData);
            return parsed;
          }
        }
      }
      return INITIAL_DATA;
    } catch (e) {
      console.error("Erro ao carregar dados:", e);
      return INITIAL_DATA;
    }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal') || localStorage.getItem('production_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedOps = localStorage.getItem('manupackaging_operators') || localStorage.getItem('production_operators');
    if (savedOps) {
      try {
        const parsed = JSON.parse(savedOps);
        if (Array.isArray(parsed)) return parsed;
      } catch (e) {}
    }
    return DEFAULT_OPERATORS;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {}
    }
    return { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [newOperatorName, setNewOperatorName] = useState('');

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Filtros
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMonth, setSelectedMonth] = useState<string>('Todos');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  // Salvamento Automático
  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_operators', JSON.stringify(operators)); }, [operators]);
  useEffect(() => { localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus)); }, [machineManualStatus]);

  // Funcionalidade de Download de Imagem do Card
  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    toPng(containerRef.current, { 
      filter: (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export')),
      backgroundColor: '#ffffff',
      pixelRatio: 3,
      cacheBust: true,
    })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error('Erro ao baixar imagem:', err));
  };

  const handleMonthChange = (month: string) => {
    setSelectedMonth(month);
    if (month === 'Todos') {
      setStartDate('');
      setEndDate('');
    } else {
      const [year, monthNum] = month.split('-');
      const firstDay = `${year}-${monthNum}-01`;
      const lastDay = new Date(parseInt(year), parseInt(monthNum), 0).getDate();
      const lastDayStr = `${year}-${monthNum}-${String(lastDay).padStart(2, '0')}`;
      setStartDate(firstDay);
      setEndDate(lastDayStr);
    }
  };

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const chartColors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];

  const mainChartData = useMemo(() => {
    if (selectedOperator !== 'Todos') {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG', color: '#3b82f6' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG', color: '#10b981' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG', color: '#8b5cf6' },
        { name: 'BORRA', value: stats.borra, unit: 'KG', color: '#ef4444' }
      ].filter(d => d.value > 0);
    }
    const map: Record<string, number> = {};
    operators.forEach(op => map[op] = 0);
    filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.netWeight || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: chartColors[i % chartColors.length] }));
  }, [filteredData, operators, selectedOperator, stats]);

  const stopChartData = useMemo(() => {
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN', color: '#f97316' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN', color: '#f59e0b' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN', color: '#94a3b8' }
    ].filter(d => d.value > 0);
  }, [stats]);

  const ecoAChartData = useMemo(() => {
    const map: Record<string, number> = {};
    operators.forEach(op => map[op] = 0);
    filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.ecoA || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: ['#10b981', '#34d399', '#6ee7b7', '#059669'][i % 4] }));
  }, [filteredData, operators]);

  const ecoBChartData = useMemo(() => {
    const map: Record<string, number> = {};
    operators.forEach(op => map[op] = 0);
    filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.ecoBP || 0) + (e.ecoBM || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: ['#8b5cf6', '#a78bfa', '#c4b5fd', '#7c3aed'][i % 4] }));
  }, [filteredData, operators]);

  const chartDescriptions = [
    "Análise comparativa da produção líquida total por operador ou categoria, destacando os maiores volumes e desempenho de meta.",
    "Distribuição do tempo de inatividade da planta, categorizado entre manutenções, ajustes de processo e outros motivos externos.",
    "Visualização do volume de recuperação Eco A por colaborador, permitindo identificar os turnos com maior eficiência de reciclagem primária.",
    "Monitoramento de materiais Eco B (Pequenos e Médios) gerados durante a operação, crucial para o controle de desperdício."
  ];

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload || payload.length === 0) return <div className="text-center text-[10px] text-slate-400 mt-8 font-bold">Nenhum dado registrado</div>;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);
    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";
          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>{index + 1}º</div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: data.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{data.name}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>{formatWeight(data.value, data.unit)}</span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
    const x = cx + radius * Math.cos(-midAngle * RADIAN);
    const y = cy + radius * Math.sin(-midAngle * RADIAN);
    return percent > 0.05 ? (
      <text x={x} y={y} fill="white" textAnchor="middle" dominantBaseline="central" fontSize={9} fontWeight="black">
        {`${(percent * 100).toFixed(0)}%`}
      </text>
    ) : null;
  };

  const currentMonthStats = useMemo(() => {
    const now = new Date();
    const prefix = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    return productionData.filter(e => e.date.startsWith(prefix)).reduce((s, e) => s + (e.netWeight || 0), 0);
  }, [productionData]);

  const toggleMachineStatus = (machineName: string) => setMachineManualStatus(prev => ({ ...prev, [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando' }));
  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'>) => setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) }, ...prev]);
  const handleAddOperator = () => { if (!newOperatorName.trim() || operators.includes(newOperatorName.trim())) return; setOperators(prev => [...prev, newOperatorName.trim()].sort()); setNewOperatorName(''); };
  const handleRemoveOperator = (op: string) => { if (confirm(`Excluir o operador ${op}?`)) setOperators(prev => prev.filter(o => o !== op)); };

  const availableMonths = useMemo(() => Array.from(new Set(productionData.map(e => e.date.substring(0,7)))).sort((a: string, b: string) => b.localeCompare(a)), [productionData]);
  const qualityEfficiency = useMemo(() => stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0, [stats]);

