  contents: "What good Italian restaurants are nearby?",
  config: {
    tools: [{googleMaps: {}}],
    toolConfig: {
      retrievalConfig: {
        latLng: {
          latitude: 37.78193,
          longitude: -122.40476
        }
      }
    }
  },
});
console.log(response.text);
/* To get place URLs, in the form [{"maps": {"uri": "", "title": ""},  ... }] */
