            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Eficiência</span><span className="text-xl text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Total Borra</span><span className="text-xl text-red-500">{formatWeight(stats.borra)}</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Paradas</span><span className="text-xl text-orange-500">{(stats.paradas / 60).toFixed(1)}h</span></div>
              <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Produção Total</span><span className="text-xl text-blue-600">{formatWeight(stats.totalNet)}</span></div>
            </div>

            <div className="bg-white rounded-2xl p-6 shadow-sm border border-blue-500/10 space-y-4">
              {isGoalReached && (
