                  </div>
                  <div className="h-[400px] w-full pt-4">
                    {chart.data.length > 0 ? (
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={chart.data} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}> 
                            {chart.data.map((e: any, i) => <Cell key={`c-${i}`} fill={e.color} stroke="none" />)} 
                          </Pie>
                          <Tooltip />
                          <Legend verticalAlign="bottom" content={renderGridLegend} />
                        </PieChart>
                      </ResponsiveContainer>
                    ) : (
                      <div className="flex flex-col items-center justify-center h-full text-slate-300 gap-2"><BarChart3 size={48} /><span className="text-[10px] font-black uppercase">Nenhum dado</span></div>
                    )}
                  </div>
                  <div className="mt-auto pt-6 flex items-start gap-2 bg-slate-50 p-4 rounded-xl border border-slate-100">
                    <div className="w-5 h-5 flex items-center justify-center"><Info size={14} className="shrink-0 text-slate-400" /></div>
                    <p className="text-[10px] text-slate-500 leading-relaxed font-medium italic">{chartDescriptions[idx]}</p>
                  </div>
                </div>
              ))}
            </div>
          </>
        ) : (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[1200px]">
                <thead>
                  <tr className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                    <th className="px-4 py-3 sticky left-0 bg-slate-50 z-10">Data</th>
                    <th className="px-4 py-3">Operador</th>
                    <th className="px-4 py-3">Máquina</th>
                    <th className="px-4 py-3 font-black text-blue-700">P. Líquido</th>
                    <th className="px-4 py-3">Status</th>
                    <th className="px-4 py-3 text-red-500">Borra</th>
                    <th className="px-4 py-3 text-orange-600">Paradas (Min)</th>
                    <th className="px-4 py-3 text-right">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[10px] font-bold">
                  {filteredData.map((e) => (
                    <tr key={e.id} className={`hover:bg-slate-50 ${e.isNoWorkDay ? 'bg-red-50/40 text-red-600' : 'text-slate-600'}`}>
                      <td className="px-4 py-3 sticky left-0 bg-white group-hover:bg-slate-50 border-r border-slate-50">{e.date}</td>
                      <td className="px-4 py-3">{e.operator}</td>
                      <td className="px-4 py-3">{e.machine}</td>
                      <td className="px-4 py-3 font-black">{e.netWeight} KG</td>
                      <td className="px-4 py-3">
                        {e.isNoWorkDay ? <span className="bg-red-100 px-2 py-0.5 rounded-full text-[8px]">NÃO OPEROU</span> : e.isMaintenanceEntry ? <span className="bg-orange-100 px-2 py-0.5 rounded-full text-[8px]">MANUTENÇÃO</span> : '-'}
                      </td>
                      <td className="px-4 py-3 text-red-500">{e.borraTotal}</td>
                      <td className="px-4 py-3 text-orange-600">{(e.manutencaoMin||0) + (e.processoMin||0) + (e.outrosMin||0)}</td>
                      <td className="px-4 py-3 text-right space-x-2">
                        <button onClick={() => handleOpenEdit(e)} className="text-blue-500 hover:text-blue-700 transition-colors p-1"><Edit2 size={14} /></button>
                        <button onClick={() => handleDeleteEntry(e.id)} className="text-red-400 hover:text-red-600 transition-colors p-1"><Trash2 size={14} /></button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>
      <LaunchModal 
        isOpen={isModalOpen} 
        onClose={() => { setIsModalOpen(false); setEditingEntry(null); }} 
        onSave={handleSaveEntry} 
        operators={operators} 
        activeMachines={Object.entries(machineManualStatus).filter(([_, s]) => s === 'Operando').map(([n]) => n)}
        initialData={editingEntry}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { X, Save, Edit2, Package, Layers, Trash2, Clock, Wrench, CalendarX } from 'lucide-react';
import { ProductionEntry } from '../types';

interface LaunchModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (entry: Omit<ProductionEntry, 'id'> & { id?: string }) => void;
  operators: string[];
  activeMachines: string[];
  initialData?: ProductionEntry | null;
}

const LaunchModal: React.FC<LaunchModalProps> = ({ isOpen, onClose, onSave, operators, activeMachines, initialData }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    operator: '',
    machine: '',
    shift: 'Diurno',
    grossWeight: 0,
    tara: 0,
    netWeight: 0,
    volumes: 0,
    tubetes: 0,
    ecoA: 0,
    ecoBP: 0,
    ecoBM: 0,
    borraTotal: 0,
    manutencaoMin: 0,
    manutencaoMotivo: '',
    processoMin: 0,
    processoMotivo: '',
    outrosMin: 0,
    outrosMotivo: '',
    isMaintenanceEntry: false,
    isNoWorkDay: false,
    noWorkReason: '',
  });

  useEffect(() => {
    if (isOpen) {
      if (initialData) {
        setFormData({
          date: initialData.date,
          operator: initialData.operator,
          machine: initialData.machine,
          shift: initialData.shift,
          grossWeight: initialData.grossWeight,
          tara: initialData.tara,
          netWeight: initialData.netWeight,
          volumes: initialData.volumes,
          tubetes: initialData.tubetes,
          ecoA: initialData.ecoA,
          ecoBP: initialData.ecoBP,
          ecoBM: initialData.ecoBM,
          borraTotal: initialData.borraTotal,
          manutencaoMin: initialData.manutencaoMin,
          manutencaoMotivo: initialData.manutencaoMotivo || '',
          processoMin: initialData.processoMin,
          processoMotivo: initialData.processoMotivo || '',
          outrosMin: initialData.outrosMin,
          outrosMotivo: initialData.outrosMotivo || '',
          isMaintenanceEntry: initialData.isMaintenanceEntry || false,
          isNoWorkDay: initialData.isNoWorkDay || false,
          noWorkReason: initialData.noWorkReason || '',
        });
      } else {
        setFormData({
          date: new Date().toISOString().split('T')[0],
          operator: '',
          machine: activeMachines.length > 0 ? activeMachines[0] : '',
          shift: 'Diurno',
          grossWeight: 0,
          tara: 0,
          netWeight: 0,
          volumes: 0,
          tubetes: 0,
          ecoA: 0,
          ecoBP: 0,
          ecoBM: 0,
          borraTotal: 0,
          manutencaoMin: 0,
          manutencaoMotivo: '',
          processoMin: 0,
          processoMotivo: '',
          outrosMin: 0,
          outrosMotivo: '',
          isMaintenanceEntry: false,
          isNoWorkDay: false,
          noWorkReason: '',
        });
      }
    }
  }, [isOpen, initialData, activeMachines]);

  useEffect(() => {
    setFormData(prev => ({
      ...prev,
      netWeight: (prev.isMaintenanceEntry || prev.isNoWorkDay) ? 0 : Math.max(0, prev.grossWeight - prev.tara)
    }));
  }, [formData.grossWeight, formData.tara, formData.isMaintenanceEntry, formData.isNoWorkDay]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.operator) {
      alert('Por favor, selecione um operador.');
      return;
    }
    if (!formData.machine) {
      alert('Nenhuma máquina ativa selecionada.');
      return;
    }

    const isSpecialEntry = formData.isMaintenanceEntry || formData.isNoWorkDay;
    const finalData = isSpecialEntry ? {
      ...formData,
      grossWeight: 0,
      tara: 0,
      netWeight: 0,
      volumes: 0,
      tubetes: 0,
      ecoA: 0,
      ecoBP: 0,
      ecoBM: 0,
      borraTotal: 0,
      manutencaoMin: formData.isNoWorkDay ? 0 : formData.manutencaoMin,
      processoMin: formData.isNoWorkDay ? 0 : formData.processoMin,
      outrosMin: formData.isNoWorkDay ? 0 : formData.outrosMin,
    } : formData;

    onSave(initialData ? { ...finalData, id: initialData.id } : finalData);
    onClose();
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as HTMLInputElement;
    let val: any;

    if (type === 'checkbox') {
      val = (e.target as HTMLInputElement).checked;

      if (name === 'isNoWorkDay' && val) {
        setFormData(prev => ({ ...prev, [name]: val, isMaintenanceEntry: false }));
        return;
      }
      if (name === 'isMaintenanceEntry' && val) {
        setFormData(prev => ({ ...prev, [name]: val, isNoWorkDay: false }));
        return;
      }
    } else {
      val = type === 'number' ? parseFloat(value) || 0 : value;
    }

    setFormData(prev => ({ ...prev, [name]: val }));
  };

  const totalParadas = formData.manutencaoMin + formData.processoMin + formData.outrosMin;
  const isHiddenProduction = formData.isMaintenanceEntry || formData.isNoWorkDay;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm overflow-y-auto">
      <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl relative overflow-hidden my-auto">
