                  <div className="flex items-center gap-3">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center ${machineManualStatus[name] === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>{machineManualStatus[name] === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}</div>
                    <span className="text-sm font-bold text-slate-700">{machineManualStatus[name] || 'Operando'}</span>
                  </div>
                </div>
