               <button 
                onClick={() => setPendingImportData(null)}
                className="flex-1 px-6 py-3 bg-white border border-slate-200 text-slate-600 font-black text-xs uppercase rounded-2xl hover:bg-slate-100 transition-all shadow-sm"
               >
                 Cancelar
               </button>
               <button 
                onClick={confirmPendingImport}
                className="flex-1 px-6 py-3 bg-blue-600 text-white font-black text-xs uppercase rounded-2xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-200 flex items-center justify-center gap-2"
               >
                 <CheckCircle2 size={16} /> Confirmar Importação
               </button>
            </div>
          </div>
        </div>
      )}

      {/* Overlay de Carregamento para Importação */}
      {isImporting && (
        <div className="fixed inset-0 z-[100] bg-slate-900/60 backdrop-blur-md flex flex-col items-center justify-center text-white p-6 text-center animate-in fade-in duration-300">
          <div className="relative">
             <Loader2 size={64} className="text-blue-400 animate-spin" />
             <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-12 h-12 bg-white/10 rounded-full blur-xl animate-pulse" />
             </div>
          </div>
          <h2 className="mt-8 text-2xl font-black uppercase tracking-widest italic">Lendo Backup</h2>
          <p className="mt-2 text-slate-300 text-sm font-bold max-w-xs uppercase tracking-tight">Processando pacotes de dados e verificando integridade do arquivo...</p>
        </div>
      )}

      <input type="file" ref={fileInputRef} onChange={handleImportData} accept=".json" className="hidden" />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Power, Users, Printer, UserPlus, BarChart3, FileText, FileSpreadsheet, Search, Info, Upload, Save, Trophy, Edit2, Loader2 } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { toPng } from 'html-to-image';
import { ProductionEntry } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL, DEFAULT_OPERATORS } from './constants';
import LaunchModal from './components/LaunchModal';

const APP_DATA_VERSION = '6.9'; 

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports'>('dashboard');

  // Inicialização ultra-robusta com varredura de migração para evitar perda de dados em atualizações
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const primaryKey = 'manupackaging_data';
      const initKey = 'manupackaging_initialized';
      const legacyKeys = ['production_data', 'production-logs', 'production_entries', 'production_data_v1'];

      const savedData = localStorage.getItem(primaryKey);
      const isInitialized = localStorage.getItem(initKey);

      // 1. Se já existe dado na chave primária, usa ele imediatamente
      if (savedData !== null) {
        const parsed = JSON.parse(savedData);
        if (Array.isArray(parsed)) return parsed;
      }

      // 2. Se a chave primária está vazia, mas o sistema já foi usado, faz varredura legada
      for (const key of legacyKeys) {
        const legacyData = localStorage.getItem(key);
        if (legacyData) {
          const parsed = JSON.parse(legacyData);
          if (Array.isArray(parsed) && parsed.length > 0) {
            console.warn(`Migração detectada: recuperando dados da chave ${key}`);
            return parsed;
          }
        }
      }

      // 3. Se for a primeiríssima execução (sem nenhum rastro no browser), usa dados iniciais
      if (!isInitialized) {
        return INITIAL_DATA;
      }

      return [];
    } catch (e) {
      console.error("Erro crítico na carga de dados:", e);
      return INITIAL_DATA;
    }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal') || localStorage.getItem('production_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedOps = localStorage.getItem('manupackaging_operators') || localStorage.getItem('production_operators');
    if (savedOps) {
      try {
        const parsed = JSON.parse(savedOps);
        if (Array.isArray(parsed)) return parsed;
      } catch (e) {}
    }
    return DEFAULT_OPERATORS;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {}
    }
    return { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [newOperatorName, setNewOperatorName] = useState('');
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const [pendingImportData, setPendingImportData] = useState<any>(null);

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Filtros
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMonth, setSelectedMonth] = useState<string>('Todos');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');

  // Trava de URL: Garante que a barra de endereços permaneça limpa para o preview
  useEffect(() => {
    const handleUrlLock = () => {
      if (window.location.hash) {
        window.history.replaceState(null, '', window.location.pathname + window.location.search);
      }
    };
    window.addEventListener('hashchange', handleUrlLock);
    handleUrlLock(); // Executa na montagem
    return () => window.removeEventListener('hashchange', handleUrlLock);
  }, []);

  // Salvamento Automático com Guarda contra Sobrescrita Nula
  useEffect(() => { 
    if (productionData !== undefined && productionData !== null) {
      localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
      localStorage.setItem('manupackaging_initialized', 'true'); // Sinaliza que o browser já possui dados de produção
    }
  }, [productionData]);

  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_operators', JSON.stringify(operators)); }, [operators]);
  useEffect(() => { localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus)); }, [machineManualStatus]);

  // Funcionalidade de Download de Imagem do Card
  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    toPng(containerRef.current, { 
      filter: (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export')),
      backgroundColor: '#ffffff',
      pixelRatio: 3,
      cacheBust: true,
    })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error('Erro ao baixar imagem:', err));
  };

  const handleMonthChange = (month: string) => {
    setSelectedMonth(month);
    if (month === 'Todos') {
      setStartDate('');
      setEndDate('');
    } else {
      const [year, monthNum] = month.split('-');
      const firstDay = `${year}-${monthNum}-01`;
      const lastDay = new Date(parseInt(year), parseInt(monthNum), 0).getDate();
      const lastDayStr = `${year}-${monthNum}-${String(lastDay).padStart(2, '0')}`;
      setStartDate(firstDay);
      setEndDate(lastDayStr);
    }
  };

  const handleExportData = () => {
    // Garantia de exportação total dos dados (productionData contém todo o histórico bruto)
    const exportObj = {
      version: APP_DATA_VERSION,
      production: productionData,
      goal: goalValue,
      operators: operators,
      machineStatus: machineManualStatus,
      exportedAt: new Date().toISOString()
    };
    const blob = new Blob([JSON.stringify(exportObj, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `backup_manupackaging_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();

    reader.onload = (event) => {
      setTimeout(() => {
        setIsImporting(false);
        try {
          const content = event.target?.result as string;
          const imported = JSON.parse(content);

          if (imported) {
             // Normalização para capturar dados de produção independente da estrutura de chaves
             const productionEntries = Array.isArray(imported) ? imported : (imported.production || imported.productionData || imported.data || []);

             if (Array.isArray(productionEntries)) {
                // Seta o preview para o usuário confirmar a importação integral
                setPendingImportData({
                  production: productionEntries,
                  goal: imported.goal !== undefined ? Number(imported.goal) : goalValue,
                  operators: Array.isArray(imported.operators) ? imported.operators : operators,
                  machineStatus: imported.machineStatus || machineManualStatus,
                  exportedAt: imported.exportedAt || null
                });
             } else {
                alert('Erro: O arquivo não contém uma estrutura de dados de produção válida.');
             }
          }
        } catch (err) {
          console.error("Erro na importação:", err);
          alert('Erro crítico ao processar o arquivo de backup. Verifique se o arquivo JSON não está corrompido.');
        }
        if (fileInputRef.current) fileInputRef.current.value = '';
      }, 1500);
    };
    reader.readAsText(file);
  };

  const confirmPendingImport = () => {
    if (!pendingImportData) return;

    // Restauração integral de todos os estados do sistema, incluindo relatórios e configurações
    setProductionData(pendingImportData.production);
    setGoalValue(pendingImportData.goal);
    setOperators(pendingImportData.operators);
    setMachineManualStatus(pendingImportData.machineStatus);

    // Reset de filtros para garantir visibilidade total pós-restauração
    setSelectedMonth('Todos');
    setSelectedMachine('Todas');
    setSelectedOperator('Todos');
    setStartDate('');
    setEndDate('');

    setPendingImportData(null);
    alert('Backup restaurado com sucesso! Todo o histórico e configurações diárias foram aplicados.');
  };

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const entryDate = entry.date;
      const matchesStart = !startDate || entryDate >= startDate;
      const matchesEnd = !endDate || entryDate <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      return matchesStart && matchesEnd && matchesMachine && matchesOperator;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator]);

  const stats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
    const sevenDaysAgoStr = sevenDaysAgo.toISOString().split('T')[0];

    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0),
      totalGross: acc.totalGross + (curr.grossWeight || 0),
      totalDaily: acc.totalDaily + (curr.date === today ? (curr.netWeight || 0) : 0),
      totalWeekly: acc.totalWeekly + (curr.date >= sevenDaysAgoStr ? (curr.netWeight || 0) : 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, totalDaily: 0, totalWeekly: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const chartColors = ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'];

  const mainChartData = useMemo(() => {
    if (selectedOperator !== 'Todos') {
      return [
        { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG', color: '#3b82f6' },
        { name: 'ECO A', value: stats.ecoA, unit: 'KG', color: '#10b981' },
        { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG', color: '#8b5cf6' },
        { name: 'BORRA', value: stats.borra, unit: 'KG', color: '#ef4444' }
      ].filter(d => d.value > 0);
    }
    const map: Record<string, number> = {};
    operators.forEach(op => map[op] = 0);
    filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.netWeight || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: chartColors[i % chartColors.length] }));
  }, [filteredData, operators, selectedOperator, stats]);

  const stopChartData = useMemo(() => {
    return [
      { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN', color: '#f97316' },
      { name: 'PROCESSO', value: stats.proc, unit: 'MIN', color: '#f59e0b' },
      { name: 'OUTROS', value: stats.outros, unit: 'MIN', color: '#94a3b8' }
    ].filter(d => d.value > 0);
  }, [stats]);

  const ecoAChartData = useMemo(() => {
    const map: Record<string, number> = {};
    operators.forEach(op => map[op] = 0);
    filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.ecoA || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: ['#10b981', '#34d399', '#6ee7b7', '#059669'][i % 4] }));
  }, [filteredData, operators]);

  const ecoBChartData = useMemo(() => {
    const map: Record<string, number> = {};
    operators.forEach(op => map[op] = 0);
    filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.ecoBP || 0) + (e.ecoBM || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: ['#8b5cf6', '#a78bfa', '#c4b5fd', '#7c3aed'][i % 4] }));
  }, [filteredData, operators]);

  const chartDescriptions = [
    "Análise comparativa da produção líquida total por operador ou categoria, destacando os maiores volumes e desempenho de meta.",
    "Distribuição do tempo de inatividade da planta, categorizado entre manutenções, ajustes de processo e outros motivos externos.",
    "Visualização do volume de recuperação Eco A por colaborador, permitindo identificar os turnos com maior eficiência de reciclagem primária.",
    "Monitoramento de materiais Eco B (Pequenos e Médios) gerados durante a operação, crucial para o controle de desperdício."
  ];

  const formatWeight = (val: number, unitOverride?: string) => {
    if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`;
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`;
    return `${val.toLocaleString('pt-BR')} KG`;
  };

  const renderGridLegend = (props: any) => {
    const { payload } = props;
    if (!payload || payload.length === 0) return <div className="text-center text-[10px] text-slate-400 mt-8 font-bold">Nenhum dado registrado</div>;
    const sortedPayload = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);
    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sortedPayload.map((entry: any, index: number) => {
          const data = entry.payload;
          const isMin = data.unit === 'MIN';
          let rankClass = "bg-slate-100 text-slate-600 border-slate-200";
          if (index === 0) rankClass = "bg-amber-400 text-white border-amber-500 shadow-md shadow-amber-100";
          if (index === 1) rankClass = "bg-slate-300 text-white border-slate-400 shadow-md shadow-slate-100";
          if (index === 2) rankClass = "bg-orange-400 text-white border-orange-500 shadow-md shadow-orange-100";
          return (
            <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg">
              <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${rankClass}`}>{index + 1}º</div>
              <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: data.color }} />
              <div className="flex flex-col min-w-0">
                <span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{data.name}:</span>
                <span className={`text-[10px] font-black ${isMin ? 'text-orange-600' : 'text-blue-600'}`}>{formatWeight(data.value, data.unit)}</span>
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, fill }: any) => {
    const RADIAN = Math.PI / 180;
    const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
    const x = cx + radius * Math.cos(-midAngle * RADIAN);
    const y = cy + radius * Math.sin(-midAngle * RADIAN);
    return percent > 0.05 ? (
      <text x={x} y={y} fill="white" textAnchor="middle" dominantBaseline="central" fontSize={9} fontWeight="black">
        {`${(percent * 100).toFixed(0)}%`}
      </text>
    ) : null;
  };

  const currentMonthStats = useMemo(() => {
    const prefix = selectedMonth !== 'Todos' ? selectedMonth : `${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}`;
    return productionData.filter(e => e.date.startsWith(prefix)).reduce((s, e) => s + (e.netWeight || 0), 0);
  }, [productionData, selectedMonth]);

  const toggleMachineStatus = (machineName: string) => setMachineManualStatus(prev => ({ ...prev, [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando' }));

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'> & { id?: string }) => {
    if (newEntry.id) {
      setProductionData(prev => prev.map(e => e.id === newEntry.id ? (newEntry as ProductionEntry) : e));
    } else {
      setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) } as ProductionEntry, ...prev]);
    }
    setEditingEntry(null);
  };

  const handleDeleteEntry = (id: string) => {
    setProductionData(prev => prev.filter(e => e.id !== id));
    setDeletingId(null);
  };

  const handleOpenEdit = (entry: ProductionEntry) => {
    setEditingEntry(entry);
    setIsModalOpen(true);
  };

  const handleAddOperator = () => { if (!newOperatorName.trim() || operators.includes(newOperatorName.trim())) return; setOperators(prev => [...prev, newOperatorName.trim()].sort()); setNewOperatorName(''); };
  const handleRemoveOperator = (op: string) => { if (confirm(`Excluir o operador ${op}?`)) setOperators(prev => prev.filter(o => o !== op)); };

  const availableMonths = useMemo(() => Array.from(new Set(productionData.map(e => e.date.substring(0,7)))).sort((a: string, b: string) => b.localeCompare(a)), [productionData]);
  const qualityEfficiency = useMemo(() => stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0, [stats]);

  const isGoalReached = currentMonthStats >= goalValue;

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
          <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
           <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button>
           <button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="bg-slate-200/50 p-1 rounded-2xl inline-flex gap-1">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><BarChart3 size={16} /> Dashboard</button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><FileText size={16} /> Relatórios</button>
        </div>
      </div>

      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> CONFIGURAÇÕES</h2>
            <button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button>
          </div>

          <div className="space-y-6">
             <div className="space-y-4">
                <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Search size={14} /> Filtros</h3>
                <div className="space-y-3">
                  <select value={selectedOperator} onChange={(e) => setSelectedOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700">
                    <option value="Todos">Todos os Operadores</option>
                    {operators.map(op => <option key={op} value={op}>{op}</option>)}
                  </select>
                  <select value={selectedMonth} onChange={(e) => handleMonthChange(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-blue-600">
                    <option value="Todos">Filtrar por Mês</option>
