                  <div>
                    <h4 className="text-xs font-black text-emerald-800 uppercase tracking-widest">Parabéns! Meta Mensal Atingida</h4>
                    <p className="text-[10px] text-emerald-600 font-bold">Produção superada em {formatWeight(currentMonthStats - goalValue)} 🎉</p>
                  </div>
