                              {/* Mapeamento dos Membros do Turno a partir do shiftTeams */}
                              {['Cast 1', 'Cast 2'].map(maquina => (
                                <div key={maquina} className="space-y-1.5">
                                   <div className="flex items-center gap-1 opacity-50"><Cpu size={10} /><span className="text-[8px] font-black text-slate-500 uppercase tracking-tighter">{maquina}</span></div>
                                   {(shiftTeams[turnoKey][maquina] || []).map((member: any, mIdx: number) => (
