                                        <div className="flex flex-col min-w-0">
                                          <span className={`text-[10px] truncate leading-tight ${member.role === 'Operador' ? 'font-black text-slate-800 uppercase' : 'font-medium text-slate-600'}`}>
                                            {member.name || '---'}
                                          </span>
                                          <span className="text-[7px] text-slate-400 font-bold uppercase tracking-tighter leading-none">{member.role}</span>
                                        </div>
                                     </div>
                                   ))}
                                </div>
                              ))}
                           </div>
                        </div>
                      </div>
                    ))}
                  </div>
               </div>
            </div>

