                          <span className="text-[10px] text-slate-400 font-bold uppercase">Min</span>
                        </div>
                      </div>
                      <input type="text" name="outrosMotivo" value={formData.outrosMotivo} onChange={handleChange}
                        placeholder="Descreva outros motivos..." className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-xs italic" />
                    </div>
                  </>
                )}

