                className="text-xs font-bold text-slate-400 hover:text-blue-600 transition-colors uppercase tracking-widest"
              >
                {authMode === 'login' ? 'Não tem acesso? Cadastre-se' : 'Já possui conta? Fazer Login'}
              </button>
            </div>
          </div>
        </div>
      </div>
    );
