><td className="px-4 py-3 text-red-500">{e.borraTotal}</td><td className="px-4 py-3 text-orange-600" title={e.manutencaoMotivo}>{e.manutencaoMin}</td><td className="px-4 py-3 text-orange-600" title={e.processoMotivo}>{e.processoMin}</td><td className="px-4 py-3 text-orange-600" title={e.outrosMotivo}>{e.outrosMin}</td><td className="px-4 py-3">{e.isNoWorkDay ? <span className="bg-red-100 px-2 py-0.5 rounded-full text-[8px]">NÃO OPEROU</span> : e.isMaintenanceEntry ? <span className="bg-orange-100 px-2 py-0.5 rounded-full text-[8px]">MANUTENÇÃO</span> : '-'}</td><td className="px-4 py-3 text-right space-x-2"><button onClick={() => handleEditEntry(e)} className="text-blue-500 p-1"><Edit2 size={14} /></button><button onClick={() => handleDeleteEntry(e.id)} className="text-red-400 p-1"><Trash2 size={14} /></button></td></tr> ))}</tbody></table></div></div>
