firmar</button></div></div></div> )}
      {isImporting && ( <div className="fixed inset-0 z-[100] bg-slate-900/60 backdrop-blur-md flex flex-col items-center justify-center text-white p-6 text-center animate-in fade-in duration-300"><div className="relative"><Loader2 size={64} className="text-blue-400 animate-spin" /></div><h2 className="mt-8 text-2xl font-black uppercase tracking-widest italic">Lendo Backup</h2><p className="mt-2 text-slate-300 text-sm font-bold max-w-xs uppercase tracking-tight">Processando pacotes de dados...</p></div> )}
      <input type="file" ref={fileInputRef} onChange={handleImportData} accept=".json" className="hidden" />

      {/* --- CHAT UI --- */}
      {isChatOpen && (
        <div className="fixed bottom-24 right-6 w-80 bg-white shadow-2xl rounded-2xl border border-slate-200 overflow-hidden z-[60] animate-in slide-in-from-bottom-5 fade-in duration-300 flex flex-col h-96">
          <div className="bg-blue-600 p-4 flex items-center justify-between text-white">
            <h3 className="font-bold text-sm flex items-center gap-2"><MessageSquare size={16} /> Chat Interno</h3>
            <button onClick={() => setIsChatOpen(false)} className="hover:bg-white/20 p-1 rounded-full"><X size={16} /></button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50 custom-scrollbar">
            {chatMessages.length === 0 ? (
              <div className="text-center text-slate-400 text-xs mt-10">Nenhuma mensagem ainda.<br/>Inicie a conversa!</div>
            ) : (
              chatMessages.map((msg) => (
                <div key={msg.id} className={`flex flex-col ${msg.user === (authData.user || 'Eu') ? 'items-end' : 'items-start'}`}>
                  <span className="text-[10px] text-slate-400 mb-1 px-1">{msg.user} • {msg.time}</span>
                  <div className={`px-4 py-2 rounded-2xl max-w-[85%] text-xs font-medium ${msg.user === (authData.user || 'Eu') ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none shadow-sm'}`}>
                    {msg.text}
                  </div>
                </div>
              ))
            )}
            <div ref={chatEndRef} />
          </div>
          <form onSubmit={handleSendMessage} className="p-3 bg-white border-t border-slate-100 flex gap-2">
            <input 
              type="text" 
              value={chatMessage} 
              onChange={(e) => setChatMessage(e.target.value)} 
              placeholder="Digite sua mensagem..." 
              className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold focus:outline-none focus:ring-2 focus:ring-blue-500/20"
            />
            <button type="submit" className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700 transition-colors shadow-sm disabled:opacity-50" disabled={!chatMessage.trim()}>
              <Send size={16} />
            </button>
          </form>
        </div>
      )}
      <button 
        onClick={() => setIsChatOpen(!isChatOpen)}
        className="fixed bottom-6 right-6 bg-blue-600 text-white p-4 rounded-full shadow-lg shadow-blue-300 hover:bg-blue-700 transition-all z-[60] hover:scale-105 active:scale-95"
      >
        <MessageSquare size={24} />
      </button>
    </div>
  );
};

export default App;

