import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Menu, Plus, Download, Trash2, Cpu, CheckCircle2, AlertTriangle, X, Settings, Target, RefreshCw, Filter, Power, Users, Printer, UserPlus, BarChart3, FileText, FileSpreadsheet, Search, Info, Upload, Save, Trophy, Edit2, Loader2, Users2, ShieldCheck, Lock, LogOut, ArrowRight, User, Eye, EyeOff, MessageSquare, Send } from 'lucide-react';
import { Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
