                                      (member.status || 'Ativo') === 'Ativo' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 
                                      member.status === 'Demitido' ? 'bg-red-50 text-red-500 border-red-100' : 
                                      member.status === 'Vaga' ? 'bg-blue-50 text-blue-500 border-blue-100' : 
