  const handleRemoveShiftMember = (turno: string, maquina: string, index: number) => { setShiftTeams(prev => ({ ...prev, [turno]: { ...prev[turno], [maquina]: prev[turno][maquina].filter((_: any, i: number) => i !== index) } })); };

  // --- NEW PERSONNEL HELPERS ---
  const toggleGroup = (groupKey: string) => {
    setExpandedGroups(prev => ({ ...prev, [groupKey]: !prev[groupKey] }));
  };

  const getShiftStyle = (groupName: string) => {
    if (groupName.includes('Noturno')) return { bg: 'bg-indigo-100', text: 'text-indigo-800', cell: 'bg-indigo-600', icon: <Moon className="w-3 h-3" /> };
    if (groupName.includes('Diurno')) return { bg: 'bg-amber-100', text: 'text-amber-800', cell: 'bg-amber-500', icon: <Sun className="w-3 h-3" /> };
    return { bg: 'bg-emerald-100', text: 'text-emerald-800', cell: 'bg-emerald-600', icon: <Briefcase className="w-3 h-3" /> };
  };

  const checkIsWorking = (emp: any, targetDate: Date) => {
    const start = new Date(emp.startDate);
    const target = new Date(targetDate);
    start.setHours(0,0,0,0); target.setHours(0,0,0,0);
    const diffDays = Math.floor((target.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
    if (diffDays < 0) return false;
    if (emp.shiftType === 'Comercial') return target.getDay() !== 0 && target.getDay() !== 6;
    return diffDays % 2 === 0;
  };

  const handleDismiss = (emp: any) => {
    setEmployees(employees.filter(e => e.id !== emp.id));
    setVacancies([...vacancies, { ...emp, id: Date.now(), openSince: new Date().toLocaleDateString() }]);
  };

  const handleRehire = (emp: any) => {
    setVacancies(vacancies.filter(v => v.id !== emp.id));
    setEmployees([...employees, { ...emp, id: Date.now() }]);
