        )}
      </main>

      {/* Modals */}
      <LaunchModal
        isOpen={isModalOpen}
        onClose={() => { setIsModalOpen(false); setEditingEntry(null); }}
        onSave={handleSaveEntry}
        operators={operators}
        activeMachines={Object.keys(machineManualStatus).filter(k => machineManualStatus[k] === 'Operando')}
        initialData={editingEntry}
      />

      {/* Chat Bubble */}
      <div className="fixed bottom-4 right-4 z-40 flex flex-col items-end gap-2 no-print">
        {isChatOpen && (
          <div className="bg-white rounded-2xl shadow-2xl border border-slate-100 w-80 h-96 flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 fade-in duration-300 mb-2">
             <div className="bg-blue-600 p-3 flex items-center justify-between text-white">
               <h3 className="font-bold text-sm flex items-center gap-2"><MessageSquare size={16} /> Chat de Turno</h3>
               <button onClick={() => setIsChatOpen(false)} className="hover:bg-white/10 p-1 rounded-full"><X size={16} /></button>
             </div>
             <div className="flex-1 overflow-y-auto p-3 space-y-3 bg-slate-50">
               {chatMessages.map(msg => (
                 <div key={msg.id} className={`flex flex-col ${msg.user === (authData.user || 'Eu') ? 'items-end' : 'items-start'}`}>
                   <div className={`max-w-[80%] rounded-xl p-2.5 text-xs font-medium ${msg.user === (authData.user || 'Eu') ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none'}`}>
                     {msg.text}
                   </div>
                   <span className="text-[9px] text-slate-400 mt-1 px-1">{msg.user} • {msg.time}</span>
                 </div>
               ))}
               <div ref={chatEndRef} />
             </div>
             <form onSubmit={handleSendMessage} className="p-2 bg-white border-t border-slate-100 flex gap-2">
               <input 
                 className="flex-1 bg-slate-100 rounded-xl px-3 py-2 text-xs font-medium focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                 placeholder="Digite sua mensagem..."
                 value={chatMessage}
                 onChange={e => setChatMessage(e.target.value)}
               />
               <button type="submit" className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700 transition-colors">
                 <Send size={16} />
               </button>
             </form>
          </div>
        )}
        <button 
          onClick={() => setIsChatOpen(!isChatOpen)}
          className="bg-blue-600 hover:bg-blue-700 text-white p-4 rounded-full shadow-lg shadow-blue-300 transition-all hover:scale-110 active:scale-95 flex items-center justify-center relative group"
        >
          {isChatOpen ? <X size={24} /> : <MessageSquare size={24} />}
          {!isChatOpen && chatMessages.length > 0 && (
             <span className="absolute top-0 right-0 w-3 h-3 bg-red-500 rounded-full border-2 border-white"></span>
          )}
        </button>
      </div>

    </div>
  );
};

