xt-orange-600" title={e.manutencaoMotivo}>{e.manutencaoMin}</td><td className="px-4 py-3 text-orange-600" title={e.processoMotivo}>{e.processoMin}</td><td className="px-4 py-3 text-orange-600" title={e.outrosMotivo}>{e.outrosMin}</td><td className="px-4 py-3">{e.isNoWorkDay ? <span className="bg-red-100 px-2 py-0.5 rounded-full text-[8px]">NÃO OPEROU</span> : e.isMaintenanceEntry ? <span className="bg-orange-100 px-2 py-0.5 rounded-full text-[8px]">MANUTENÇÃO</span> : '-'}</td><td className="px-4 py-3 text-right space-x-2"><button onClick={() => handleEditEntry(e)} className="text-blue-500 p-1"><Edit2 size={14} /></button><button onClick={() => handleDeleteEntry(e.id)} className="text-red-400 p-1"><Trash2 size={14} /></button></td></tr> ))}</tbody><tfoot className="bg-slate-100 font-black text-[10px] text-slate-700 uppercase tracking-tight border-t-2 border-slate-200"><tr><td className="px-4 py-3 sticky left-0 bg-slate-100 border-r border-slate-200">TOTAIS</td><td className="px-4 py-3">-</td><td className="px-4 py-3">-</td><td className="px-4 py-3">-</td><td className="px-4 py-3">{reportTotals.gross}</td><td className="px-4 py-3">{reportTotals.tara}</td><td className="px-4 py-3 text-blue-700">{reportTotals.net} KG</td><td className="px-4 py-3">{reportTotals.vols}</td><td className="px-4 py-3">{reportTotals.tub}</td><td className="px-4 py-3 text-emerald-600">{reportTotals.ecoA}</td><td className="px-4 py-3 text-purple-600">{reportTotals.ecoBP}</td><td className="px-4 py-3 text-purple-600">{reportTotals.ecoBM}</td><td className="px-4 py-3 text-red-500">{reportTotals.borra}</td><td className="px-4 py-3 text-orange-600">{reportTotals.manut}</td><td className="px-4 py-3 text-orange-600">{reportTotals.proc}</td><td className="px-4 py-3 text-orange-600">{reportTotals.outros}</td><td className="px-4 py-3">-</td><td className="px-4 py-3">-</td></tr></tfoot></table></div></div>
        ) : (
