                 <Printer size={16} /> Salvar PDF
               </button>
            </div>
            <div className="overflow-x-auto"><table className="w-full text-left border-collapse min-w-[2200px]"><thead><tr className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100"><th className="px-4 py-3 sticky left-0 bg-slate-50 z-10">Data</th><th className="px-4 py-3">Turno</th><th className="px-4 py-3">Operador</th><th className="px-4 py-3">Máquina</th><th className="px-4 py-3">Bruto</th><th className="px-4 py-3">Tara</th><th className="px-4 py-3 font-black text-blue-700">P. Líquido</th><th className="px-4 py-3">Vols</th><th className="px-4 py-3">Tubetes</th><th className="px-4 py-3 text-emerald-600">Eco A</th><th className="px-4 py-3 text-purple-600">Eco B (P)</th><th className="px-4 py-3 text-purple-600">Eco B (M)</th><th className="px-4 py-3 text-red-500">Borra</th><th className="px-4 py-3 text-orange-600">Manut.</th><th className="px-4 py-3 text-orange-600">Proc.</th><th className="px-4 py-3 text-orange-600">Outros</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-right">Ações</th></tr></thead><tbody className="divide-y divide-slate-100 text-[10px] font-bold">{filteredData.map((e) => ( <tr key={e.id} className={`hover:bg-slate-50 ${e.isNoWorkDay ? 'bg-red-50/40 text-red-600' : 'text-slate-600'}`}><td className="px-4 py-3 sticky left-0 bg-white border-r border-slate-50">{e.date}</td><td className="px-4 py-3">{e.shift || '-'}</td><td className="px-4 py-3">{e.operator}</td><td className="px-4 py-3">{e.machine}</td><td className="px-4 py-3">{e.grossWeight}</td><td className="px-4 py-3">{e.tara}</td><td className="px-4 py-3 font-black">{e.netWeight} KG</td><td className="px-4 py-3">{e.volumes}</td><td className="px-4 py-3">{e.tubetes}</td><td className="px-4 py-3 text-emerald-600">{e.ecoA}</td><td className="px-4 py-3 text-purple-600">{e.ecoBP}</td><td className="px-4 py-3 text-purple-600">{e.ecoBM}</td><td className="px-4 py-3 text-red-500">{e.borraTotal}</td><td className="px-4 py-3 text-orange-600" title={e.manutencaoMotivo}>{e.manutencaoMin}</td><td className="px-4 py-3 text-orange-600" title={e.processoMotivo}>{e.processoMin}</td><td className="px-4 py-3 text-orange-600" title={e.outrosMotivo}>{e.outrosMin}</td><td className="px-4 py-3">{e.isNoWorkDay ? <span className="bg-red-100 px-2 py-0.5 rounded-full text-[8px]">NÃO OPEROU</span> : e.isMaintenanceEntry ? <span className="bg-orange-100 px-2 py-0.5 rounded-full text-[8px]">MANUTENÇÃO</span> : '-'}</td><td className="px-4 py-3 text-right space-x-2"><button onClick={() => handleEditEntry(e)} className="text-blue-500 p-1"><Edit2 size={14} /></button><button onClick={() => handleDeleteEntry(e.id)} className="text-red-400 p-1"><Trash2 size={14} /></button></td></tr> ))}</tbody><tfoot className="bg-slate-100 font-black text-[10px] text-slate-700 uppercase tracking-tight border-t-2 border-slate-200"><tr><td className="px-4 py-3 sticky left-0 bg-slate-100 border-r border-slate-200">TOTAIS</td><td className="px-4 py-3">-</td><td className="px-4 py-3">-</td><td className="px-4 py-3">-</td><td className="px-4 py-3">{reportTotals.gross}</td><td className="px-4 py-3">{reportTotals.tara}</td><td className="px-4 py-3 text-blue-700">{reportTotals.net} KG</td><td className="px-4 py-3">{reportTotals.vols}</td><td className="px-4 py-3">{reportTotals.tub}</td><td className="px-4 py-3 text-emerald-600">{reportTotals.ecoA}</td><td className="px-4 py-3 text-purple-600">{reportTotals.ecoBP}</td><td className="px-4 py-3 text-purple-600">{reportTotals.ecoBM}</td><td className="px-4 py-3 text-red-500">{reportTotals.borra}</td><td className="px-4 py-3 text-orange-600">{reportTotals.manut}</td><td className="px-4 py-3 text-orange-600">{reportTotals.proc}</td><td className="px-4 py-3 text-orange-600">{reportTotals.outros}</td><td className="px-4 py-3">-</td><td className="px-4 py-3">-</td></tr></tfoot></table></div></div>
        ) : (
          <div className="space-y-6">
            {/* Top Navigation for Personnel Management */}
            <div className="flex justify-center">
                <div className="bg-white p-1 rounded-2xl inline-flex gap-1 shadow-sm border border-slate-200 overflow-x-auto max-w-full">
                    <button onClick={() => setPersonnelViewMode('schedule')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-wide transition-all ${personnelViewMode === 'schedule' ? 'bg-orange-50 text-orange-600 shadow-sm border border-orange-100' : 'text-slate-500 hover:bg-slate-50'}`}>
                        <Briefcase size={16} /> Escalas
                    </button>
                    <button onClick={() => setPersonnelViewMode('team')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-wide transition-all ${personnelViewMode === 'team' ? 'bg-orange-50 text-orange-600 shadow-sm border border-orange-100' : 'text-slate-500 hover:bg-slate-50'}`}>
                        <Users size={16} /> Gerir Pessoal
                    </button>
                    <button onClick={handleGeneratePDF} className="flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-wide transition-all text-slate-500 hover:bg-slate-50 hover:text-slate-700">
                        {isPdfLoading ? <Loader2 size={16} className="animate-spin" /> : <FileDown size={16} />} Organograma PDF
                    </button>
                </div>
            </div>

            {/* Conteúdo Principal do Tab Personnel */}
            <div id="printable-area">
              {personnelViewMode === 'schedule' && (
                <div className="space-y-6">
                  {/* Controles de Escala */}
                  <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                    <div className="flex items-center gap-4">
                      <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><ChevronLeft /></button>
                      <h2 className="text-lg font-bold uppercase tracking-tight min-w-[150px] text-center">{currentDate.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })}</h2>
                      <button onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><ChevronRight /></button>
                    </div>

                    <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
                      {['Todos', 'Diurno', 'Noturno'].map(s => (
                        <button 
                          key={s} 
                          onClick={() => setFilterShift(s)}
                          className={`px-3 py-1.5 text-[10px] font-bold rounded-md transition-all ${filterShift === s ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                        >
                          {s.toUpperCase()}
                        </button>
                      ))}
                    </div>
                  </div>

                  {/* Tabela de Escala */}
                  <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-x-auto">
                    <table className="w-full text-[10px]">
                      <thead className="bg-slate-50 border-b">
                        <tr>
                          <th className="px-4 py-4 text-left sticky left-0 bg-slate-50 z-20 min-w-[180px] border-r shadow-[2px_0_5px_rgba(0,0,0,0.05)]">Máquina / Colaborador</th>
                          <th className="px-2 py-4 border-r">Turno</th>
                          {monthDays.map(d => {
                            const isWeekend = d.getDay() === 0 || d.getDay() === 6;
                            return (
                              <th key={d.toISOString()} className={`px-1 text-center font-bold min-w-[28px] ${isWeekend ? 'bg-slate-100/50 text-slate-400' : 'text-slate-400'}`}>
                                {d.getDate()}
                              </th>
                            );
                          })}
                        </tr>
                      </thead>
                      <tbody>
                        {Object.entries(groupedByMachine).sort((a, b) => sortGroupKeys(a[0], b[0])).map(([groupKey, groupEmps]: [string, any[]]) => (
                          <React.Fragment key={groupKey}>
                            <tr onClick={() => toggleGroup(groupKey)} className="bg-slate-100/30 cursor-pointer hover:bg-slate-100 border-b">
                              <td colSpan={monthDays.length + 2} className="px-4 py-2 font-black text-slate-500 sticky left-0 bg-slate-50/90 backdrop-blur-sm uppercase tracking-widest text-[9px]">
                                <div className="flex items-center gap-2">
                                  {expandedGroups[groupKey] ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
                                  {groupKey} <span className="text-slate-300 font-normal">({groupEmps.length})</span>
                                </div>
                              </td>
                            </tr>
                            {expandedGroups[groupKey] && groupEmps.map(emp => (
                              <tr key={emp.id} className="border-b hover:bg-slate-50/50 transition-colors">
                                <td className="px-4 py-2 sticky left-0 bg-white z-10 font-bold border-r text-slate-700 shadow-[2px_0_5px_rgba(0,0,0,0.02)]">{emp.name}</td>
                                <td className="px-2 py-2 text-center border-r">
                                  <span className={`px-2 py-0.5 rounded-full text-[8px] font-bold ${getShiftStyle(emp.group).bg} ${getShiftStyle(emp.group).text}`}>
                                    {emp.group.toUpperCase()}
                                  </span>
                                </td>
                                {monthDays.map(day => {
                                  const isWorking = checkIsWorking(emp, day);
                                  const isWeekend = day.getDay() === 0 || day.getDay() === 6;
                                  return (
                                    <td key={day.toISOString()} className={`p-0.5 ${isWeekend ? 'bg-slate-50/30' : ''}`}>
                                      <div className={`w-full h-6 rounded-sm transition-all ${isWorking ? getShiftStyle(emp.group).cell : 'bg-transparent border border-transparent hover:border-slate-200'}`}></div>
                                    </td>
                                  );
                                })}
                              </tr>
                            ))}
                          </React.Fragment>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

              {personnelViewMode === 'team' && (
                <div className="max-w-5xl mx-auto space-y-6">
                  <div className="flex gap-4 border-b border-slate-200">
                    <button onClick={() => setTeamViewMode('active')} className={`pb-3 px-4 text-sm font-bold transition-all ${teamViewMode === 'active' ? 'border-b-2 border-orange-500 text-orange-600' : 'text-slate-400 hover:text-slate-600'}`}>ATIVOS ({employees.length})</button>
                    <button onClick={() => setTeamViewMode('vacancies')} className={`pb-3 px-4 text-sm font-bold transition-all ${teamViewMode === 'vacancies' ? 'border-b-2 border-red-500 text-red-600' : 'text-slate-400 hover:text-slate-600'}`}>VAGAS ({vacancies.length})</button>
                  </div>

                  {teamViewMode === 'active' && (
                    <div className="grid gap-4">
                      {Object.entries(groupedByMachine).sort((a, b) => sortGroupKeys(a[0], b[0])).map(([key, emps]: [string, any[]]) => (
                        <div key={key} className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden transition-all hover:shadow-md">
                          <div className="bg-slate-50 px-4 py-2 font-bold text-[10px] text-slate-500 uppercase border-b tracking-wider">{key}</div>
                          <div className="divide-y divide-slate-100">
                            {emps.map(emp => (
                              <div key={emp.id} className="p-4 flex items-center justify-between hover:bg-slate-50 group">
                                <div className="flex items-center gap-4">
                                  <div className={`w-10 h-10 rounded-lg flex items-center justify-center font-bold text-white shadow-sm ${getShiftStyle(emp.group).cell}`}>{emp.name[0]}</div>
                                  <div>
                                    <h4 className="font-bold text-slate-800 text-sm">{emp.name}</h4>
                                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">{emp.role} • {emp.group} • {emp.shiftType}</p>
                                  </div>
                                </div>
                                <button onClick={() => handleDismiss(emp)} className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all opacity-0 group-hover:opacity-100" title="Demitir">
                                  <UserMinus className="w-5 h-5" />
                                </button>
                              </div>
                            ))}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}

                  {teamViewMode === 'vacancies' && (
                    <div className="space-y-4">
                      {vacancies.length === 0 ? (
                        <div className="bg-white rounded-xl border border-slate-200 p-12 text-center">
                          <CheckCircle2 className="w-12 h-12 text-emerald-400 mx-auto mb-3" />
                          <p className="font-bold text-slate-500 uppercase text-xs tracking-widest">Tudo em ordem. Sem vagas abertas.</p>
                        </div>
                      ) : (
                        vacancies.map(v => (
                          <div key={v.id} className="flex items-center justify-between p-5 bg-white rounded-xl border-l-4 border-l-red-500 border-slate-200 shadow-sm">
                            <div>
                              <h4 className="font-bold text-slate-800">{v.name}</h4>
                              <p className="text-[10px] text-slate-400 font-bold uppercase">Saída: {v.openSince}</p>
                            </div>
                            <button onClick={() => handleRehire(v)} className="bg-emerald-100 text-emerald-700 px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-emerald-200 transition-colors flex items-center gap-2">
                               <RefreshCw size={14} /> Recontratar
                            </button>
                          </div>
                        ))
                      )}
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </main>

      {/* Modals */}
      <LaunchModal
        isOpen={isModalOpen}
        onClose={() => { setIsModalOpen(false); setEditingEntry(null); }}
        onSave={handleSaveEntry}
        operators={operators}
        activeMachines={Object.keys(machineManualStatus).filter(k => machineManualStatus[k] === 'Operando')}
        initialData={editingEntry}
      />

      {/* Chat Bubble */}
      <div className="fixed bottom-4 right-4 z-40 flex flex-col items-end gap-2 no-print">
        {isChatOpen && (
          <div className="bg-white rounded-2xl shadow-2xl border border-slate-100 w-80 h-96 flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 fade-in duration-300 mb-2">
             <div className="bg-blue-600 p-3 flex items-center justify-between text-white">
               <h3 className="font-bold text-sm flex items-center gap-2"><MessageSquare size={16} /> Chat de Turno</h3>
               <button onClick={() => setIsChatOpen(false)} className="hover:bg-white/10 p-1 rounded-full"><X size={16} /></button>
             </div>
             <div className="flex-1 overflow-y-auto p-3 space-y-3 bg-slate-50">
               {chatMessages.map(msg => (
                 <div key={msg.id} className={`flex flex-col ${msg.user === (authData.user || 'Eu') ? 'items-end' : 'items-start'}`}>
                   <div className={`max-w-[80%] rounded-xl p-2.5 text-xs font-medium ${msg.user === (authData.user || 'Eu') ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none'}`}>
                     {msg.text}
                   </div>
                   <span className="text-[9px] text-slate-400 mt-1 px-1">{msg.user} • {msg.time}</span>
                 </div>
               ))}
               <div ref={chatEndRef} />
             </div>
             <form onSubmit={handleSendMessage} className="p-2 bg-white border-t border-slate-100 flex gap-2">
               <input 
                 className="flex-1 bg-slate-100 rounded-xl px-3 py-2 text-xs font-medium focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                 placeholder="Digite sua mensagem..."
                 value={chatMessage}
                 onChange={e => setChatMessage(e.target.value)}
               />
               <button type="submit" className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700 transition-colors">
                 <Send size={16} />
               </button>
             </form>
          </div>
        )}
        <button 
          onClick={() => setIsChatOpen(!isChatOpen)}
          className="bg-blue-600 hover:bg-blue-700 text-white p-4 rounded-full shadow-lg shadow-blue-300 transition-all hover:scale-110 active:scale-95 flex items-center justify-center relative group"
        >
          {isChatOpen ? <X size={24} /> : <MessageSquare size={24} />}
          {!isChatOpen && chatMessages.length > 0 && (
             <span className="absolute top-0 right-0 w-3 h-3 bg-red-500 rounded-full border-2 border-white"></span>
          )}
        </button>
      </div>

    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
