    reader.onload = (event) => {
      setTimeout(() => {
        setIsImporting(false);
        try {
          const content = event.target?.result as string;
          const imported = JSON.parse(content);
          if (imported) {
             const productionEntries = Array.isArray(imported) ? imported : (imported.production || imported.productionData || imported.data || []);
             if (Array.isArray(productionEntries)) {
                setPendingImportData({ production: productionEntries, goal: imported.goal !== undefined ? Number(imported.goal) : goalValue, operators: Array.isArray(imported.operators) ? imported.operators : operators, machineStatus: imported.machineStatus || machineManualStatus, shiftTeams: imported.shiftTeams || shiftTeams, exportedAt: imported.exportedAt || null });
             } else { alert('Erro: Estrutura inválida.'); }
          }
        } catch (err) { alert('Erro crítico no backup.'); }
        if (fileInputRef.current) fileInputRef.current.value = '';
      }, 1500);
    };
    reader.readAsText(file);
  };

  const confirmPendingImport = () => {
