const App: React.FC = () => {
  // --- AUTHENTICATION STATE ---
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!localStorage.getItem('manupackaging_session'));
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [authData, setAuthData] = useState({ user: 'adaiasmelo', pass: '123456' }); 
  const [authError, setAuthError] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  // --- CHAT STATE ---
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{id: number, user: string, text: string, time: string}[]>(() => {
    try { return JSON.parse(localStorage.getItem('manupackaging_chat_history') || '[]'); } catch { return []; }
  });
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_chat_history', JSON.stringify(chatMessages));
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  useEffect(() => {
    const syncChat = (e: StorageEvent) => {
      if (e.key === 'manupackaging_chat_history' && e.newValue) {
        setChatMessages(JSON.parse(e.newValue));
      }
    };
    window.addEventListener('storage', syncChat);
    return () => window.removeEventListener('storage', syncChat);
  }, []);

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatMessage.trim()) return;
    const newMsg = { 
      id: Date.now(), 
      user: authData.user || 'Eu', 
      text: chatMessage, 
      time: new Date().toLocaleTimeString('pt-BR', {hour:'2-digit', minute:'2-digit'}) 
    };
    setChatMessages(prev => [...prev, newMsg]);
    setChatMessage('');
  };

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    if (authData.user === 'adaiasmelo' && authData.pass === '123456') {
      localStorage.setItem('manupackaging_session', 'true');
      setIsAuthenticated(true);
      return;
    }
    const users = JSON.parse(localStorage.getItem('manupackaging_users') || '[]');
    if (authMode === 'register') {
      if (users.find((u: any) => u.user === authData.user)) {
        setAuthError('Usuário já existe.');
        return;
      }
      if (authData.pass.length < 4) {
        setAuthError('Senha muito curta.');
        return;
      }
      users.push(authData);
      localStorage.setItem('manupackaging_users', JSON.stringify(users));
      setAuthMode('login');
      setAuthError('Conta criada! Faça login.');
    } else {
      const validUser = users.find((u: any) => u.user === authData.user && u.pass === authData.pass);
      if (validUser) {
        localStorage.setItem('manupackaging_session', 'true');
        setIsAuthenticated(true);
      } else {
        setAuthError('Credenciais inválidas.');
      }
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('manupackaging_session');
    setIsAuthenticated(false);
    setAuthData({ user: 'adaiasmelo', pass: '123456' }); 
  };
  // ---------------------------

  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports' | 'personnel'>('dashboard');

  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const primaryKey = 'manupackaging_data';
      const initKey = 'manupackaging_initialized';
      const legacyKeys = ['production_data', 'production-logs', 'production_entries', 'production_data_v1', 'manupackaging_data_v6'];
      const savedData = localStorage.getItem(primaryKey);
      const isInitialized = localStorage.getItem(initKey);
      if (savedData !== null) {
        try {
          const parsed = JSON.parse(savedData);
          if (Array.isArray(parsed)) return parsed;
        } catch (e) { console.error("Erro na leitura da chave primária", e); }
      }
      for (const key of legacyKeys) {
        const legacyData = localStorage.getItem(key);
        if (legacyData) {
          try {
            const parsed = JSON.parse(legacyData);
            if (Array.isArray(parsed) && parsed.length > 0) return parsed;
          } catch (e) {}
        }
      }
      return isInitialized === 'true' ? [] : INITIAL_DATA;
    } catch (e) {
      console.error("Erro crítico na carga de dados:", e);
      return [];
    }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal') || localStorage.getItem('production_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedOps = localStorage.getItem('manupackaging_operators') || localStorage.getItem('production_operators');
    if (savedOps) {
      try {
        const parsed = JSON.parse(savedOps);
        if (Array.isArray(parsed)) return parsed;
      } catch (e) {}
    }
    return DEFAULT_OPERATORS;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    if (saved) {
      try { return JSON.parse(saved); } catch (e) {}
    }
    return { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  // --- PERSONNEL MANAGEMENT STATE ---
  const [currentDate, setCurrentDate] = useState(new Date());
  const [personnelViewMode, setPersonnelViewMode] = useState<'team' | 'orgchart'>('team');
  const [teamViewMode, setTeamViewMode] = useState<'active' | 'vacancies'>('active');
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({});
  const [filterShift, setFilterShift] = useState('Todos');
  const [isPdfLoading, setIsPdfLoading] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [selectedEmployeeId, setSelectedEmployeeId] = useState<number | null>(null);

  // New States for Personnel Actions
  const [isPersonnelModalOpen, setIsPersonnelModalOpen] = useState(false);
  const [personnelForm, setPersonnelForm] = useState<any>({ id: null, name: '', role: 'Auxiliar', sector: 'Extrusão', machine: 'Cast 1', shiftType: '12x36', group: 'Diurno 1', status: 'Ativo' });

  // Vacation Modal States
  const [isVacationModalOpen, setIsVacationModalOpen] = useState(false);
  const [vacationForm, setVacationForm] = useState({ empId: 0, days: 30, startDate: '' });

  const [vacancies, setVacancies] = useState<any[]>(() => {
    try { return JSON.parse(localStorage.getItem('manupackaging_vacancies') || '[]'); } catch { return []; }
  });

  const [employees, setEmployees] = useState<any[]>(() => {
    try { 
      const saved = localStorage.getItem('manupackaging_employees');
      return saved ? JSON.parse(saved) : PERSONNEL_INITIAL_DATA; 
    } catch { return PERSONNEL_INITIAL_DATA; }
  });

  useEffect(() => { localStorage.setItem('manupackaging_employees', JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem('manupackaging_vacancies', JSON.stringify(vacancies)); }, [vacancies]);

  // html2pdf injection
  useEffect(() => {
    if (!document.getElementById('html2pdf-script')) {
      const script = document.createElement('script');
      script.id = 'html2pdf-script';
      script.src = "https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js";
      script.async = true;
      document.body.appendChild(script);
    }
  }, []);

  const [shiftTeams, setShiftTeams] = useState<Record<string, any>>(() => {
    const saved = localStorage.getItem('manupackaging_shift_teams');
    let data = null;
    if (saved) {
      try { data = JSON.parse(saved); } catch (e) {}
    }
    const defaultData = { 
      'A': { 'Cast 1': [], 'Cast 2': [] }, 'B': { 'Cast 1': [], 'Cast 2': [] }, 
      'C': { 'Cast 1': [], 'Cast 2': [] }, 'D': { 'Cast 1': [], 'Cast 2': [] } 
    };
    return data || defaultData;
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [newOperatorName, setNewOperatorName] = useState('');
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const [pendingImportData, setPendingImportData] = useState<any>(null);
  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [selectedMonth, setSelectedMonth] = useState<string>('Todos');
  const [selectedMachine, setSelectedMachine] = useState<string>('Todas');
  const [selectedOperator, setSelectedOperator] = useState<string>('Todos');
  const [searchTerm, setSearchTerm] = useState('');

  // Ref para backup automático
  const autoBackupTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isFirstRender = useRef(true);

  useEffect(() => {
    const handleUrlLock = () => {
      if (window.location.hash) {
        window.history.replaceState(null, '', window.location.pathname + window.location.search);
      }
    };
    window.addEventListener('hashchange', handleUrlLock);
    handleUrlLock();
    return () => window.removeEventListener('hashchange', handleUrlLock);
  }, []);

  useEffect(() => { 
    if (Array.isArray(productionData)) {
      localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
      localStorage.setItem('manupackaging_initialized', 'true');
    }
  }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_operators', JSON.stringify(operators)); }, [operators]);
  useEffect(() => { localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus)); }, [machineManualStatus]);
  useEffect(() => { localStorage.setItem('manupackaging_shift_teams', JSON.stringify(shiftTeams)); }, [shiftTeams]);

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    toPng(containerRef.current, { 
      filter: (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export')),
      backgroundColor: '#ffffff',
      pixelRatio: 3,
      cacheBust: true,
    })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error('Erro ao baixar imagem:', err));
  };

  const handleMonthChange = (month: string) => {
    setSelectedMonth(month);
    if (month === 'Todos') {
      setStartDate(''); setEndDate('');
    } else {
      const [year, monthNum] = month.split('-');
      const firstDay = `${year}-${monthNum}-01`;
      const lastDay = new Date(parseInt(year), parseInt(monthNum), 0).getDate();
      const lastDayStr = `${year}-${monthNum}-${String(lastDay).padStart(2, '0')}`;
      setStartDate(firstDay); setEndDate(lastDayStr);
    }
  };

  const handleExportData = () => {
    const exportObj = { version: APP_DATA_VERSION, production: productionData, goal: goalValue, operators: operators, machineStatus: machineManualStatus, shiftTeams: shiftTeams, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(exportObj, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    const now = new Date();
    const dateStr = now.toLocaleDateString('pt-BR').replace(/\//g, '-');
    const timeStr = now.toLocaleTimeString('pt-BR').replace(/:/g, '-');
    link.download = `backup_${dateStr}_${timeStr}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  // Lógica de Backup Automático (30 segundos após alteração)
  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }

    if (autoBackupTimerRef.current) {
      clearTimeout(autoBackupTimerRef.current);
    }

    autoBackupTimerRef.current = setTimeout(() => {
      handleExportData();
    }, 30000);

    return () => {
      if (autoBackupTimerRef.current) {
        clearTimeout(autoBackupTimerRef.current);
      }
    };
  }, [productionData, goalValue, operators, machineManualStatus, shiftTeams]);

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      setTimeout(() => {
        setIsImporting(false);
        try {
          const content = event.target?.result as string;
          const imported = JSON.parse(content);
          if (imported) {
             const productionEntries = Array.isArray(imported) ? imported : (imported.production || imported.productionData || imported.data || []);
             if (Array.isArray(productionEntries)) {
                setPendingImportData({ production: productionEntries, goal: imported.goal !== undefined ? Number(imported.goal) : goalValue, operators: Array.isArray(imported.operators) ? imported.operators : operators, machineStatus: imported.machineStatus || machineManualStatus, shiftTeams: imported.shiftTeams || shiftTeams, exportedAt: imported.exportedAt || null });
             } else { alert('Erro: Estrutura inválida.'); }
          }
        } catch (err) { alert('Erro crítico no backup.'); }
        if (fileInputRef.current) fileInputRef.current.value = '';
      }, 1500);
    };
    reader.readAsText(file);
  };

  const confirmPendingImport = () => {
    if (!pendingImportData) return;
    setProductionData(pendingImportData.production); setGoalValue(pendingImportData.goal); setOperators(pendingImportData.operators); setMachineManualStatus(pendingImportData.machineStatus); setShiftTeams(pendingImportData.shiftTeams || shiftTeams); setSelectedMonth('Todos'); setSelectedMachine('Todas'); setSelectedOperator('Todos'); setStartDate(''); setEndDate(''); setPendingImportData(null);
    alert('Backup restaurado!');
  };

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const matchesStart = !startDate || entry.date >= startDate;
      const matchesEnd = !endDate || entry.date <= endDate;
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;

      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = !searchTerm || 
        entry.operator?.toLowerCase().includes(searchLower) ||
        entry.machine?.toLowerCase().includes(searchLower) ||
        entry.shift?.toLowerCase().includes(searchLower) ||
        entry.id?.toLowerCase().includes(searchLower) ||
        entry.date?.includes(searchLower);

      return matchesStart && matchesEnd && matchesMachine && matchesOperator && matchesSearch;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, startDate, endDate, selectedMachine, selectedOperator, searchTerm]);

  const stats = useMemo(() => {
    const today = new Date().toLocaleDateString('sv-SE');
    const sevenDaysAgo = new Date(); sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
    const sevenDaysAgoStr = sevenDaysAgo.toLocaleDateString('sv-SE');
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0), totalGross: acc.totalGross + (curr.grossWeight || 0), totalDaily: acc.totalDaily + (curr.date === today ? (curr.netWeight || 0) : 0), totalWeekly: acc.totalWeekly + (curr.date >= sevenDaysAgoStr ? (curr.netWeight || 0) : 0), ecoA: acc.ecoA + (curr.ecoA || 0), ecoBP: acc.ecoBP + (curr.ecoBP || 0), ecoBM: acc.ecoBM + (curr.ecoBM || 0), borra: acc.borra + (curr.borraTotal || 0), paradas: acc.paradas + (curr.manutencaoMin || 0) + (curr.processoMin || 0) + (curr.outrosMin || 0), manut: acc.manut + (curr.manutencaoMin || 0), proc: acc.proc + (curr.processoMin || 0), outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, totalDaily: 0, totalWeekly: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, paradas: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const reportTotals = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      gross: acc.gross + (curr.grossWeight || 0),
      tara: acc.tara + (curr.tara || 0),
      net: acc.net + (curr.netWeight || 0),
      vols: acc.vols + (curr.volumes || 0),
      tub: acc.tub + (curr.tubetes || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { gross: 0, tara: 0, net: 0, vols: 0, tub: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const mainChartData = useMemo(() => {
    if (selectedOperator !== 'Todos') return [ { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG', color: '#3b82f6' }, { name: 'ECO A', value: stats.ecoA, unit: 'KG', color: '#10b981' }, { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG', color: '#8b5cf6' }, { name: 'BORRA', value: stats.borra, unit: 'KG', color: '#ef4444' } ].filter(d => d.value > 0);
    const map: Record<string, number> = {}; operators.forEach(op => map[op] = 0); filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.netWeight || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'][i % 8] }));
  }, [filteredData, operators, selectedOperator, stats]);

  const stopChartData = useMemo(() => [ { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN', color: '#f97316' }, { name: 'PROCESSO', value: stats.proc, unit: 'MIN', color: '#f59e0b' }, { name: 'OUTROS', value: stats.outros, unit: 'MIN', color: '#94a3b8' } ].filter(d => d.value > 0), [stats]);
  const ecoAChartData = useMemo(() => { const map: Record<string, number> = {}; operators.forEach(op => map[op] = 0); filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.ecoA || 0); }); return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: ['#10b981', '#34d399', '#6ee7b7', '#059669'][i % 4] })); }, [filteredData, operators]);
  const ecoBChartData = useMemo(() => { const map: Record<string, number> = {}; operators.forEach(op => map[op] = 0); filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.ecoBP || 0) + (e.ecoBM || 0); }); return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: ['#8b5cf6', '#a78bfa', '#c4b5fd', '#7c3aed'][i % 4] })); }, [filteredData, operators]);

  const formatWeight = (val: number, unitOverride?: string) => { if (unitOverride === 'MIN') return `${val.toLocaleString('pt-BR')} MIN (${(val / 60).toFixed(1)}h)`; if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 3 })} T`; return `${val.toLocaleString('pt-BR')} KG`; };

  const renderGridLegend = (props: any) => {
    const { payload } = props; if (!payload || payload.length === 0) return <div className="text-center text-[10px] mt-8 font-bold text-slate-400">Nenhum dado</div>;
    const sorted = [...payload].sort((a: any, b: any) => b.payload.value - a.payload.value);
    return (
      <div className="grid grid-cols-2 gap-x-4 gap-y-3 mt-8 max-w-lg mx-auto px-4">
        {sorted.map((entry: any, index: number) => (
          <div key={`rank-${index}`} className="flex items-center gap-2 p-1 rounded-lg">
            <div className={`flex items-center justify-center w-5 h-5 rounded-md text-[8px] font-black shrink-0 border ${index === 0 ? 'bg-amber-400 text-white' : 'bg-slate-100 text-slate-600'}`}>{index + 1}º</div>
            <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.payload.color }} />
            <div className="flex flex-col min-w-0"><span className="text-[10px] font-black text-slate-700 uppercase truncate leading-none mb-0.5">{entry.payload.name}:</span><span className="text-[10px] font-black text-blue-600">{formatWeight(entry.payload.value, entry.payload.unit)}</span></div>
          </div>
        ))}
      </div>
    );
  };

  const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }: any) => { const RADIAN = Math.PI / 180; const radius = outerRadius + 25; const x = cx + radius * Math.cos(-midAngle * RADIAN); const y = cy + radius * Math.sin(-midAngle * RADIAN); return percent > 0.02 ? ( <text x={x} y={y} fill="#64748b" textAnchor={x > cx ? 'start' : 'end'} dominantBaseline="central" fontSize={10} fontWeight="black">{`${(percent * 100).toFixed(0)}%`}</text> ) : null; };

  const currentMonthStats = useMemo(() => { const prefix = selectedMonth !== 'Todos' ? selectedMonth : `${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}`; return productionData.filter(e => e.date.startsWith(prefix)).reduce((s, e) => s + (e.netWeight || 0), 0); }, [productionData, selectedMonth]);

  const toggleMachineStatus = (machineName: string) => setMachineManualStatus(prev => ({ ...prev, [machineName]: prev[machineName] === 'Operando' ? 'Manutenção' : 'Operando' }));
  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'> & { id?: string }) => { if (newEntry.id) { setProductionData(prev => prev.map(e => e.id === newEntry.id ? (newEntry as ProductionEntry) : e)); } else { setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) } as ProductionEntry, ...prev]); } setEditingEntry(null); };
  const handleEditEntry = (entry: ProductionEntry) => { setEditingEntry(entry); setIsModalOpen(true); };
  const handleDeleteEntry = (id: string) => { 
    if (window.confirm('Tem certeza que deseja excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id)); 
    }
  };
  const handleAddOperator = () => { if (!newOperatorName.trim() || operators.includes(newOperatorName.trim())) return; setOperators(prev => [...prev, newOperatorName.trim()].sort()); setNewOperatorName(''); };
  const handleRemoveOperator = (op: string) => { if (window.confirm(`Excluir o operador ${op}?`)) setOperators(prev => prev.filter(o => o !== op)); };

  const handleUpdateShiftMember = (turno: string, maquina: string, index: number, field: string, value: string) => { 
    // Old implementation - now unused in rendering but kept for safety/logic preservation if needed by other components
    setShiftTeams(prev => { const newTeam = [...prev[turno][maquina]]; newTeam[index] = { ...newTeam[index], [field]: value }; return { ...prev, [turno]: { ...prev[turno], [maquina]: newTeam } }; }); 
  };
  const handleAddShiftMember = (turno: string, maquina: string) => { setShiftTeams(prev => ({ ...prev, [turno]: { ...prev[turno], [maquina]: [...prev[turno][maquina], { role: 'Auxiliar', name: '', status: 'Ativo' }] } })); };
  const handleRemoveShiftMember = (turno: string, maquina: string, index: number) => { setShiftTeams(prev => ({ ...prev, [turno]: { ...prev[turno], [maquina]: prev[turno][maquina].filter((_: any, i: number) => i !== index) } })); };

  // --- NEW PERSONNEL HELPERS ---
  const toggleGroup = (groupKey: string) => {
    setExpandedGroups(prev => ({ ...prev, [groupKey]: !prev[groupKey] }));
  };

  const getShiftStyle = (groupName: string) => {
    if (groupName.includes('Noturno')) return { bg: 'bg-indigo-100', text: 'text-indigo-800', cell: 'bg-indigo-600', icon: <Moon className="w-3 h-3" /> };
    if (groupName.includes('Diurno')) return { bg: 'bg-amber-100', text: 'text-amber-800', cell: 'bg-amber-500', icon: <Sun className="w-3 h-3" /> };
    return { bg: 'bg-emerald-100', text: 'text-emerald-800', cell: 'bg-emerald-600', icon: <Briefcase className="w-3 h-3" /> };
  };

  const checkIsWorking = (emp: any, targetDate: Date) => {
    const start = new Date(emp.startDate);
    const target = new Date(targetDate);
    start.setHours(0,0,0,0); target.setHours(0,0,0,0);
    const diffDays = Math.floor((target.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
    if (diffDays < 0) return false;
    if (emp.shiftType === 'Comercial') return target.getDay() !== 0 && target.getDay() !== 6;
    return diffDays % 2 === 0;
  };

  const handleDismiss = (emp: any) => {
    if (window.confirm(`Confirmar demissão de ${emp.name}? (Mover para histórico)`)) {
      setEmployees(prev => prev.filter(e => e.id !== emp.id));
      setVacancies(prev => [...prev, { ...emp, id: Date.now(), openSince: new Date().toLocaleDateString() }]);
      setSelectedEmployeeId(null);
    }
  };

  const handleRehire = (emp: any) => {
    setVacancies(prev => prev.filter(v => v.id !== emp.id));
    setEmployees(prev => [...prev, { ...emp, id: Date.now() }]);
  };

  const handleToggleVacation = (emp: any) => {
    if (emp.status === 'Férias') {
      if(window.confirm(`Confirmar retorno de ${emp.name} das férias?`)) {
        setEmployees(employees.map(e => e.id === emp.id ? { ...e, status: 'Ativo', vacationInfo: null } : e));
      }
    } else {
      setVacationForm({ 
        empId: emp.id, 
        days: 30, 
        startDate: new Date().toISOString().split('T')[0] 
      });
      setIsVacationModalOpen(true);
    }
  };

  // Funcao para excluir permanentemente
  const handleDeletePersonnel = (emp: any) => {
    if (window.confirm(`Tem certeza que deseja excluir ${emp.name} permanentemente? Esta ação não pode ser desfeita.`)) {
      setEmployees(prev => prev.filter(e => e.id !== emp.id));
      if (selectedEmployeeId === emp.id) setSelectedEmployeeId(null);
    }
  };

  const handleDeleteVacancy = (vac: any) => {
    if (window.confirm(`Tem certeza que deseja excluir o registro de ${vac.name} permanentemente?`)) {
        setVacancies(prev => prev.filter(v => v.id !== vac.id));
    }
  };

  const handleSaveVacation = (e: React.FormEvent) => {
    e.preventDefault();
    const start = new Date(vacationForm.startDate);
    const returnDate = new Date(start);
    returnDate.setDate(returnDate.getDate() + parseInt(vacationForm.days as any));

    setEmployees(employees.map(emp => emp.id === vacationForm.empId ? { 
       ...emp, 
       status: 'Férias',
       vacationInfo: {
          start: vacationForm.startDate,
          days: vacationForm.days,
          return: returnDate.toISOString().split('T')[0]
       }
    } : emp));
    setIsVacationModalOpen(false);
  };

  const getReturnDate = () => {
     if (!vacationForm.startDate || !vacationForm.days) return '-';
     const d = new Date(vacationForm.startDate);
     d.setDate(d.getDate() + parseInt(vacationForm.days as any));
     return d.toLocaleDateString('pt-BR');
  };

  const openPersonnelModal = (emp?: any) => {
    if (emp) {
      setPersonnelForm(emp);
    } else {
      setPersonnelForm({ id: null, name: '', role: 'Auxiliar', sector: 'Extrusão', machine: 'Cast 1', shiftType: '12x36', group: 'Diurno 1', status: 'Ativo' });
    }
    setIsPersonnelModalOpen(true);
  };

  const handleSavePersonnel = (e: React.FormEvent) => {
    e.preventDefault();
    if (personnelForm.id) {
       setEmployees(employees.map(emp => emp.id === personnelForm.id ? personnelForm : emp));
    } else {
       setEmployees([...employees, { ...personnelForm, id: Date.now(), startDate: new Date().toISOString().split('T')[0] }]);
    }
    setIsPersonnelModalOpen(false);
  };

  const handleGeneratePDF = () => {
    if (!(window as any).html2pdf) return;
    setIsPdfLoading(true);
    const element = document.getElementById('printable-area');
    (window as any).html2pdf().set({ 
        margin: 10, 
        filename: 'escala_fabrica.pdf', 
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'landscape' } 
    }).from(element).save().then(() => setIsPdfLoading(false));
  };

  const monthDays = useMemo(() => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    return Array.from({ length: new Date(year, month + 1, 0).getDate() }, (_, i) => new Date(year, month, i + 1));
  }, [currentDate]);

  const filteredEmployees = useMemo(() => {
    if (filterShift === 'Todos') return employees;
    return employees.filter(emp => emp.group.includes(filterShift));
  }, [employees, filterShift]);

  const groupedByMachine = useMemo(() => {
    const groups: Record<string, any[]> = {};
    filteredEmployees.forEach(emp => {
      // Grouping by "Sector - Shift - Machine" to create hierarchy
      // Ex: Extrusão - Diurno 1 - Cast 1
      let key = '';
      if (emp.sector === 'Extrusão') {
         key = `${emp.sector} - ${emp.group} - ${emp.machine}`;
      } else {
         key = `${emp.sector} - ${emp.machine || 'Geral'}`;
      }

      if (!groups[key]) groups[key] = [];
      groups[key].push(emp);
    });

    // Ordenação: Líder > Operador 1 > Operador 2 > Operador 3 > Operador (Genérico) > Auxiliar
    const getRolePriority = (role: string) => {
      const r = role.toLowerCase();
      if (r.includes('líder')) return 0;
      if (r === 'operador 1') return 1;
      if (r === 'operador 2') return 2;
      if (r === 'operador 3') return 3;
      if (r.includes('operador')) return 4; // Prioridade para "Operador" genérico (compatibilidade)
      return 10; // Auxiliares e outros no final
    };

    Object.keys(groups).forEach(key => {
      groups[key].sort((a, b) => getRolePriority(a.role) - getRolePriority(b.role));
    });

    return groups;
  }, [filteredEmployees]);

  // Helper to sort groups chronologically: Dia 1 -> Noite 1 -> Dia 2 -> Noite 2
  const sortGroupKeys = (a: string, b: string) => {
    // Defines the exact order weight
    const getWeight = (str: string) => {
      if (str.includes('Fita')) return 100; // Fita last
      if (str.includes('Diurno 1')) return str.includes('Cast 1') ? 1 : 2;
      if (str.includes('Noturno 1')) return str.includes('Cast 1') ? 3 : 4;
      if (str.includes('Diurno 2')) return str.includes('Cast 1') ? 5 : 6;
      if (str.includes('Noturno 2')) return str.includes('Cast 1') ? 7 : 8;
      return 99;
    };
    return getWeight(a) - getWeight(b);
  };
  // -----------------------------

  const qualityEfficiency = useMemo(() => stats.totalGross > 0 ? (stats.totalNet / stats.totalGross) * 100 : 0, [stats]);
  const isGoalReached = currentMonthStats >= goalValue;

  const personnelStats = useMemo(() => {
    const vacation = employees.filter(e => e.status === 'Férias').length;
    return { 
      activeCount: employees.length, 
      vacancyCount: vacancies.length, 
      vacationCount: vacation,
      totalCount: employees.length + vacancies.length
    };
  }, [employees, vacancies]);

  // RENDERIZAÇÃO DA TELA DE LOGIN (GATEKEEPER)
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-xl border border-slate-100 p-8 w-full max-w-md space-y-8 animate-in fade-in zoom-in-95 duration-300">
          <div className="text-center space-y-2">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg shadow-blue-200 mb-4">
              <ShieldCheck size={32} />
            </div>
            <h1 className="text-2xl font-black text-slate-800 tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></h1>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Acesso Restrito ao Sistema</p>
          </div>

          <form onSubmit={handleAuth} className="space-y-6">
            <div className="space-y-4">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase flex items-center gap-2"><User size={12} /> Usuário</label>
                <input 
                  type="text" 
                  value={authData.user}
                  onChange={(e) => setAuthData({...authData, user: e.target.value})}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                  placeholder="Seu nome de usuário"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase flex items-center gap-2"><Lock size={12} /> Senha</label>
                <div className="relative">
                  <input 
                    type={showPassword ? 'text' : 'password'} 
                    value={authData.pass}
                    onChange={(e) => setAuthData({...authData, pass: e.target.value})}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 pr-10 text-sm font-bold text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                    placeholder="••••••••"
                  />
                  <button 
                    type="button" 
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-blue-600 transition-colors"
                  >
                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>
            </div>

            {authError && (
              <div className="bg-red-50 text-red-600 p-3 rounded-xl text-xs font-bold flex items-center gap-2 animate-bounce-slow">
                <AlertTriangle size={14} /> {authError}
              </div>
            )}

            <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl shadow-lg shadow-blue-200 flex items-center justify-center gap-2 transition-all">
              {authMode === 'login' ? 'Entrar no Sistema' : 'Criar Conta'} <ArrowRight size={18} />
            </button>
          </form>

          <div className="pt-6 border-t border-slate-100 text-center">
            <button 
              onClick={() => { setAuthMode(authMode === 'login' ? 'register' : 'login'); setAuthError(''); }}
              className="text-xs font-bold text-slate-400 hover:text-blue-600 transition-colors uppercase tracking-tight"
            >
              {authMode === 'login' ? 'Não tem acesso? Criar conta' : 'Já tem conta? Fazer login'}
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2"><div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div><span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span></h1>
        <div className="flex items-center gap-2"><button onClick={handleExportData} className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-emerald-200 text-sm" title="Salvar Backup Manualmente"><Save size={18} /><span className="hidden sm:inline">Backup</span></button><button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 shadow-lg shadow-blue-200 text-sm"><Plus size={18} /><span className="hidden sm:inline">Novo Lançamento</span></button><button onClick={handleLogout} className="p-2 hover:bg-red-50 hover:text-red-600 rounded-lg text-slate-400 transition-colors" title="Sair"><LogOut size={24} /></button><button onClick={() => setIsMenuOpen(true)} className="p-2 hover:bg-slate-100 rounded-lg text-slate-600"><Menu size={24} /></button></div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="bg-slate-200/50 p-1 rounded-2xl inline-flex gap-1 overflow-x-auto no-scrollbar max-w-full">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><BarChart3 size={16} /> Dashboard</button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><FileText size={16} /> Relatórios</button>
          <button onClick={() => setActiveTab('personnel')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all whitespace-nowrap ${activeTab === 'personnel' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><Users2 size={16} /> Gestão de Pessoal</button>
        </div>
      </div>

      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto custom-scrollbar`}>
          <div className="flex items-center justify-between"><h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> CONFIGURAÇÕES</h2><button onClick={() => setIsMenuOpen(false)} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={24} /></button></div>
          <div className="space-y-6">
             <div className="space-y-4"><h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Search size={14} /> Filtros</h3><div className="space-y-3"><select value={selectedOperator} onChange={(e) => setSelectedOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700"><option value="Todos">Todos os Operadores</option>{operators.map(op => <option key={op} value={op}>{op}</option>)}</select><select value={selectedMachine} onChange={(e) => setSelectedMachine(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-slate-700"><option value="Todas">Todas as Máquinas</option><option value="Cast 1">Cast 1</option><option value="Cast 2">Cast 2</option></select><select value={selectedMonth} onChange={(e) => handleMonthChange(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold text-blue-600"><option value="Todos">Filtrar por Mês</option>{Array.from(new Set(productionData.map(e => e.date.substring(0,7)))).sort((a: string, b: string) => b.localeCompare(a)).map(m => <option key={m} value={m}>{m}</option>)}</select></div></div>
             <div className="space-y-4 pt-4 border-t border-slate-100"><h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><UserPlus size={14} /> Gerenciar Operadores</h3><div className="flex gap-2"><input type="text" value={newOperatorName} onChange={(e) => setNewOperatorName(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleAddOperator()} placeholder="Nome do operador..." className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold" /><button onClick={handleAddOperator} className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700 shadow-sm transition-all"><Plus size={18} /></button></div><div className="max-h-40 overflow-y-auto custom-scrollbar pr-2 space-y-1">{operators.map(op => ( <div key={op} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg group"><span className="text-xs font-bold text-slate-600 uppercase">{op}</span><button onClick={() => handleRemoveOperator(op)} className="text-slate-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"><Trash2 size={14} /></button></div> ))}</div></div>
             <div className="space-y-4 pt-4 border-t border-slate-100"><h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><RefreshCw size={14} /> Backup</h3><div className="grid grid-cols-2 gap-2"><button onClick={handleExportData} className="flex items-center justify-center gap-2 bg-slate-100 hover:bg-blue-600 hover:text-white text-slate-600 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all border border-slate-200"><Download size={14} /> Exportar</button><button onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center gap-2 bg-slate-100 hover:bg-emerald-600 hover:text-white text-slate-600 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all border border-slate-200"><Upload size={14} /> Importar</button></div></div>
             <div className="space-y-4 pt-4 border-t border-slate-100"><h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Target size={14} /> Meta Mensal (KG)</h3><input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600" /></div>
          </div>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' ? (
          <>
            <div className="grid grid-cols-2 gap-4">{['Cast 1', 'Cast 2'].map((name) => ( <div key={name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100"><div className="flex items-center justify-between mb-2"><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{name}</span><button onClick={() => toggleMachineStatus(name)} className={`p-1.5 rounded-lg ${machineManualStatus[name] === 'Operando' ? 'text-emerald-600 bg-emerald-50' : 'text-orange-600 bg-orange-50'}`}><Power size={14} /></button></div><div className="flex items-center gap-3"><div className={`w-8 h-8 rounded-full flex items-center justify-center ${machineManualStatus[name] === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>{machineManualStatus[name] === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}</div><span className="text-sm font-bold text-slate-700">{machineManualStatus[name] || 'Operando'}</span></div></div> ))}</div>
            <div className="bg-white rounded-2xl p-6 shadow-sm border border-blue-500/10 space-y-4">{isGoalReached && ( <div className="bg-emerald-50 border border-emerald-200 rounded-xl p-4 flex items-center gap-4 animate-bounce-slow"><div className="w-10 h-10 bg-emerald-500 rounded-full flex items-center justify-center text-white shadow-lg shadow-emerald-200"><Trophy size={20} /></div><div><h4 className="text-xs font-black text-emerald-800 uppercase tracking-widest">Meta Mensal Atingida</h4><p className="text-[10px] text-emerald-600 font-bold">Produção superada em {formatWeight(currentMonthStats - goalValue)} 🎉</p></div></div> )}<div className="flex items-center justify-between font-black"><div><span className="text-[10px] uppercase text-slate-400">Meta Mensal</span><div className="flex items-baseline gap-2"><span className="text-4xl text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span><span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span></div></div><span className={`text-3xl ${isGoalReached ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span></div><div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden"><div className={`h-full rounded-full transition-all duration-1000 ${isGoalReached ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div></div></div>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4"><div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Eficiência</span><span className="text-xl text-emerald-500">{qualityEfficiency.toFixed(1)}%</span></div><div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Produção Diária</span><span className="text-xl text-blue-600">{formatWeight(stats.totalDaily)}</span></div><div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Produção Semanal</span><span className="text-xl text-blue-600">{formatWeight(stats.totalWeekly)}</span></div><div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 font-black"><span className="text-[9px] text-slate-400 uppercase block">Produção Total</span><span className="text-xl text-blue-600">{formatWeight(stats.totalNet)}</span></div></div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">{[ { ref: prodCardRef, title: 'Produção Total', data: mainChartData, id: 'prod' }, { ref: stopCardRef, title: 'Impacto de Paradas', data: stopChartData, id: 'stop' }, { ref: ecoACardRef, title: 'Distribuição Eco A', data: ecoAChartData, id: 'ecoa' }, { ref: ecoBCardRef, title: 'Distribuição Eco B', data: ecoBChartData, id: 'ecob' } ].map((chart, idx) => ( <div key={chart.id} ref={chart.ref} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col min-h-[620px]"><div className="flex items-center justify-between mb-4"><h3 className="font-black text-xs uppercase tracking-widest text-slate-800">{chart.title}</h3><button onClick={() => downloadCardAsImage(chart.ref, chart.id)} className="p-1.5 text-slate-300 hover:text-blue-600 no-export transition-colors"><Download size={16} /></button></div><div className="h-[400px] w-full pt-4">{chart.data.length > 0 ? ( <ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={chart.data} cx="50%" cy="45%" innerRadius={55} outerRadius={75} dataKey="value" label={renderCustomLabel} paddingAngle={4}>{chart.data.map((e: any, i) => <Cell key={`c-${i}`} fill={e.color} stroke="none" />)}</Pie><Tooltip /><Legend verticalAlign="bottom" content={renderGridLegend} /></PieChart></ResponsiveContainer> ) : ( <div className="flex flex-col items-center justify-center h-full text-slate-300 gap-2"><BarChart3 size={48} /><span className="text-[10px] font-black uppercase">Nenhum dado</span></div> )}</div><div className="mt-auto pt-6 flex items-start gap-2 bg-slate-50 p-4 rounded-xl border border-slate-100"><div className="w-5 h-5 flex items-center justify-center"><Info size={14} className="shrink-0 text-slate-400" /></div><p className="text-[10px] text-slate-500 leading-relaxed font-medium italic">Monitoramento técnico dos indicadores chave de performance da unidade.</p></div></div> ))}</div>
          </>
        ) : activeTab === 'reports' ? (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="p-4 border-b border-slate-100 flex items-center justify-between gap-4 bg-slate-50/50">
               <div className="relative flex-1 max-w-md">
