                 <Printer size={16} /> Salvar PDF
               </button>
            </div>
            <div className="overflow-x-auto"><table className="w-full text-left border-collapse min-w-[2200px]"><thead><tr className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100"><th className="px-4 py-3 sticky left-0 bg-slate-50 z-10">Data</th><th className="px-4 py-3">Turno</th><th className="px-4 py-3">Operador</th><th className="px-4 py-3">Máquina</th><th className="px-4 py-3">Bruto</th><th className="px-4 py-3">Tara</th><th className="px-4 py-3 font-black text-blue-700">P. Líquido</th><th className="px-4 py-3">Vols</th><th className="px-4 py-3">Tubetes</th><th className="px-4 py-3 text-emerald-600">Eco A</th><th className="px-4 py-3 text-purple-600">Eco B (P)</th><th className="px-4 py-3 text-purple-600">Eco B (M)</th><th className="px-4 py-3 text-red-500">Borra</th><th className="px-4 py-3 text-orange-600">Manut.</th><th className="px-4 py-3 text-orange-600">Proc.</th><th className="px-4 py-3 text-orange-600">Outros</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-right">Ações</th></tr></thead><tbody className="divide-y divide-slate-100 text-[10px] font-bold">{filteredData.map((e) => ( <tr key={e.id} className={`hover:bg-slate-50 ${e.isNoWorkDay ? 'bg-red-50/40 text-red-600' : 'text-slate-600'}`}><td className="px-4 py-3 sticky left-0 bg-white border-r border-slate-50">{e.date}</td><td className="px-4 py-3">{e.shift || '-'}</td><td className="px-4 py-3">{e.operator}</td><td className="px-4 py-3">{e.machine}</td><td className="px-4 py-3">{e.grossWeight}</td><td className="px-4 py-3">{e.tara}</td><td className="px-4 py-3 font-black">{e.netWeight} KG</td><td className="px-4 py-3">{e.volumes}</td><td className="px-4 py-3">{e.tubetes}</td><td className="px-4 py-3 text-emerald-600">{e.ecoA}</td><td className="px-4 py-3 text-purple-600">{e.ecoBP}</td><td className="px-4 py-3 text-purple-600">{e.ecoBM}</td><td className="px-4 py-3 text-red-500">{e.borraTotal}</td><td className="px-4 py-3 text-orange-600" title={e.manutencaoMotivo}>{e.manutencaoMin}</td><td className="px-4 py-3 text-orange-600" title={e.processoMotivo}>{e.processoMin}</td><td className="px-4 py-3 text-orange-600" title={e.outrosMotivo}>{e.outrosMin}</td><td className="px-4 py-3">{e.isNoWorkDay ? <span className="bg-red-100 px-2 py-0.5 rounded-full text-[8px]">NÃO OPEROU</span> : e.isMaintenanceEntry ? <span className="bg-orange-100 px-2 py-0.5 rounded-full text-[8px]">MANUTENÇÃO</span> : '-'}</td><td className="px-4 py-3 text-right space-x-2"><button onClick={(ev) => { ev.stopPropagation(); handleEditEntry(e); }} className="text-blue-500 p-1"><Edit2 size={14} /></button><button onClick={(ev) => { ev.stopPropagation(); handleDeleteEntry(e.id); }} className="text-red-400 p-1"><Trash2 size={14} /></button></td></tr> ))}</tbody><tfoot className="bg-slate-100 font-black text-[10px] text-slate-700 uppercase tracking-tight border-t-2 border-slate-200"><tr><td className="px-4 py-3 sticky left-0 bg-slate-100 border-r border-slate-200">TOTAIS</td><td className="px-4 py-3">-</td><td className="px-4 py-3">-</td><td className="px-4 py-3">-</td><td className="px-4 py-3">{reportTotals.gross}</td><td className="px-4 py-3">{reportTotals.tara}</td><td className="px-4 py-3 text-blue-700">{reportTotals.net} KG</td><td className="px-4 py-3">{reportTotals.vols}</td><td className="px-4 py-3">{reportTotals.tub}</td><td className="px-4 py-3 text-emerald-600">{reportTotals.ecoA}</td><td className="px-4 py-3 text-purple-600">{reportTotals.ecoBP}</td><td className="px-4 py-3 text-purple-600">{reportTotals.ecoBM}</td><td className="px-4 py-3 text-red-500">{reportTotals.borra}</td><td className="px-4 py-3 text-orange-600">{reportTotals.manut}</td><td className="px-4 py-3 text-orange-600">{reportTotals.proc}</td><td className="px-4 py-3 text-orange-600">{reportTotals.outros}</td><td className="px-4 py-3">-</td><td className="px-4 py-3">-</td></tr></tfoot></table></div></div>
