                  <input required type="text" value={personnelForm.name} onChange={e => setPersonnelForm({...personnelForm, name: e.target.value})} className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" />
               </div>
               <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Cargo</label>
                    <select value={personnelForm.role} onChange={e => setPersonnelForm({...personnelForm, role: e.target.value})} className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold">
                       <option value="Líder">Líder</option>
                       <option value="Operador 1">Operador 1</option>
                       <option value="Operador 2">Operador 2</option>
                       <option value="Operador 3">Operador 3</option>
                       <option value="Auxiliar">Auxiliar</option>
                    </select>
                  </div>
                  <div>
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Setor</label>
                    <select value={personnelForm.sector} onChange={e => setPersonnelForm({...personnelForm, sector: e.target.value})} className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold">
                       <option value="Extrusão">Extrusão</option>
                       <option value="Fita">Fita</option>
                    </select>
                  </div>
               </div>
               <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Máquina</label>
                    <select value={personnelForm.machine} onChange={e => setPersonnelForm({...personnelForm, machine: e.target.value})} className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold">
                       <option value="Cast 1">Cast 1</option>
                       <option value="Cast 2">Cast 2</option>
                       <option value="Ghezzi">Ghezzi</option>
                       <option value="Lintech">Lintech</option>
                       <option value="Wutec">Wutec</option>
                    </select>
                  </div>
                  <div>
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Turno/Grupo</label>
                    <select value={personnelForm.group} onChange={e => setPersonnelForm({...personnelForm, group: e.target.value})} className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold">
                       <option value="Diurno 1">Diurno 1</option>
                       <option value="Noturno 1">Noturno 1</option>
                       <option value="Diurno 2">Diurno 2</option>
                       <option value="Noturno 2">Noturno 2</option>
                       <option value="Comercial">Comercial</option>
                    </select>
                  </div>
               </div>

               {/* Lógica para cálculo de descanso de 36h */}
               {personnelForm.id && (() => {
                  const currentEmp = employees.find(e => e.id === personnelForm.id);
                  if (!currentEmp || currentEmp.group === personnelForm.group) return null;

                  const isG1 = (g: string) => g.includes('1');
                  const isG2 = (g: string) => g.includes('2');
                  const oldG = currentEmp.group;
                  const newG = personnelForm.group;

                  if ((isG1(oldG) && isG2(newG)) || (isG2(oldG) && isG1(newG))) {
                     const date = new Date();
                     date.setDate(date.getDate() + 2); // Garante a margem segura para 36h
                     const targetIsEven = isG1(newG);
                     const dateIsEven = date.getDate() % 2 === 0;
                     if (targetIsEven !== dateIsEven) { date.setDate(date.getDate() + 1); }

                     return (
                        <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 text-xs text-amber-800 animate-in fade-in">
                           <p className="font-bold flex items-center gap-2"><AlertTriangle size={14} /> Regra de Descanso (36h)</p>
                           <p className="mt-1">
                              Mudança de <strong>{oldG}</strong> ({isG1(oldG) ? 'Par' : 'Ímpar'}) para <strong>{newG}</strong> ({isG1(newG) ? 'Par' : 'Ímpar'}).
                              Para garantir o descanso mínimo, a folga sugerida é até: <strong>{date.toLocaleDateString('pt-BR')}</strong>.
                           </p>
                        </div>
                     );
                  }
                  return null;
               })()}

               <button type="submit" className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl shadow-lg shadow-blue-200 hover:bg-blue-700 transition-all mt-2">Salvar Informações</button>
            </form>
          </div>
        </div>
      )}

      {/* Chat Bubble */}
      <div className="fixed bottom-4 right-4 z-40 flex flex-col items-end gap-2 no-print">
        {isChatOpen && (
          <div className="bg-white rounded-2xl shadow-2xl border border-slate-100 w-80 h-96 flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 fade-in duration-300 mb-2">
             <div className="bg-blue-600 p-3 flex items-center justify-between text-white">
               <h3 className="font-bold text-sm flex items-center gap-2"><MessageSquare size={16} /> Chat de Turno</h3>
               <button onClick={() => setIsChatOpen(false)} className="hover:bg-white/10 p-1 rounded-full"><X size={16} /></button>
             </div>
             <div className="flex-1 overflow-y-auto p-3 space-y-3 bg-slate-50">
               {chatMessages.map(msg => (
                 <div key={msg.id} className={`flex flex-col ${msg.user === (authData.user || 'Eu') ? 'items-end' : 'items-start'}`}>
                   <div className={`max-w-[80%] rounded-xl p-2.5 text-xs font-medium ${msg.user === (authData.user || 'Eu') ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none'}`}>
                     {msg.text}
                   </div>
                   <span className="text-[9px] text-slate-400 mt-1 px-1">{msg.user} • {msg.time}</span>
                 </div>
               ))}
               <div ref={chatEndRef} />
             </div>
             <form onSubmit={handleSendMessage} className="p-2 bg-white border-t border-slate-100 flex gap-2">
               <input 
                 className="flex-1 bg-slate-100 rounded-xl px-3 py-2 text-xs font-medium focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                 placeholder="Digite sua mensagem..."
                 value={chatMessage}
                 onChange={e => setChatMessage(e.target.value)}
               />
               <button type="submit" className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700 transition-colors">
                 <Send size={16} />
               </button>
             </form>
          </div>
        )}
        <button 
          onClick={() => setIsChatOpen(!isChatOpen)}
          className="bg-blue-600 hover:bg-blue-700 text-white p-4 rounded-full shadow-lg shadow-blue-300 transition-all hover:scale-110 active:scale-95 flex items-center justify-center relative group"
        >
          {isChatOpen ? <X size={24} /> : <MessageSquare size={24} />}
          {!isChatOpen && chatMessages.length > 0 && (
             <span className="absolute top-0 right-0 w-3 h-3 bg-red-500 rounded-full border-2 border-white"></span>
          )}
        </button>
      </div>

    </div>
  );
};

