                              >
                                <div className="flex items-center gap-4">
                                  <div className={`w-10 h-10 rounded-lg flex items-center justify-center font-bold text-white shadow-sm relative ${getShiftStyle(emp.group).cell}`}>
                                    {emp.name[0]}
                                    {emp.status === 'Férias' && <div className="absolute -top-1 -right-1 w-4 h-4 bg-orange-500 rounded-full border-2 border-white flex items-center justify-center"><Palmtree size={8} className="text-white" /></div>}
                                  </div>
                                  <div>
                                    <h4 className="font-bold text-slate-800 text-sm flex items-center gap-2">
