                                          </span>
                                       )}
                                    </div>
                                  </div>
                                </div>
                                {selectedEmployeeId === emp.id && (
                                  <div className="flex items-center gap-2 w-full sm:w-auto justify-end animate-in fade-in slide-in-from-right-4 duration-200">
                                    <button onClick={(e) => { e.preventDefault(); e.stopPropagation(); openPersonnelModal(emp); }} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all" title="Editar">
                                      <UserCog size={18} />
                                    </button>
                                    <button onClick={(e) => { e.preventDefault(); e.stopPropagation(); handleToggleVacation(emp); }} className={`p-2 rounded-lg transition-all ${emp.status === 'Férias' ? 'text-orange-600 bg-orange-100' : 'text-slate-400 hover:text-orange-600 hover:bg-orange-50'}`} title="Férias">
                                      <Palmtree size={18} />
                                    </button>
                                    <button onClick={(e) => { e.preventDefault(); e.stopPropagation(); handleDismiss(emp); }} className="p-2 text-slate-400 hover:text-amber-500 hover:bg-amber-50 rounded-lg transition-all" title="Demitir (Mover para Vagas)">
                                      <UserMinus size={18} />
