                </div>
                <button onClick={() => setIsVacationModalOpen(false)} className="hover:bg-white/10 p-1 rounded-full"><X size={24} /></button>
             </div>
             <form onSubmit={handleSaveVacation} className="p-5 space-y-4">
                <div>
                   <label className="text-[10px] font-bold text-slate-500 uppercase">Data Início</label>
                   <input required type="date" value={vacationForm.startDate} onChange={e => setVacationForm({...vacationForm, startDate: e.target.value})} className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" />
                </div>
                <div>
                   <label className="text-[10px] font-bold text-slate-500 uppercase">Quantidade de Dias</label>
                   <input required type="number" min="1" max="60" value={vacationForm.days} onChange={e => setVacationForm({...vacationForm, days: parseInt(e.target.value)})} className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" />
                </div>
                <div className="bg-orange-50 border border-orange-100 p-3 rounded-lg flex flex-col items-center justify-center">
                    <span className="text-[10px] font-black text-orange-400 uppercase tracking-widest mb-1">Data de Retorno Prevista</span>
                    <span className="text-lg font-black text-orange-600">{getReturnDate()}</span>
                </div>
                <button type="submit" className="w-full bg-orange-500 text-white font-bold py-3 rounded-xl shadow-lg shadow-orange-200 hover:bg-orange-600 transition-all">Confirmar Férias</button>
             </form>
          </div>
        </div>
      )}

      {/* Personnel Modal */}
      {isPersonnelModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl relative overflow-hidden animate-in fade-in zoom-in-95 duration-300">
