    // Ordenação: Líder > Operador 1 > Operador 2 > Operador 3 > Operador (Genérico) > Auxiliar
    const getRolePriority = (role: string) => {
      const r = role.toLowerCase();
      if (r.includes('líder')) return 0;
      if (r === 'operador 1') return 1;
      if (r === 'operador 2') return 2;
      if (r === 'operador 3') return 3;
