  const handleAddOperator = () => { if (!newOperatorName.trim() || operators.includes(newOperatorName.trim())) return; setOperators(prev => [...prev, newOperatorName.trim()].sort()); setNewOperatorName(''); };
  const handleRemoveOperator = (op: string) => { setTimeout(() => { if (window.confirm(`Excluir o operador ${op}?`)) { setOperators(prev => prev.filter(o => o !== op)); } }, 100); };

  // ... (outros auxiliares de pessoal mantidos para integridade)

