const App: React.FC = () => {
  // --- AUTHENTICATION STATE ---
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!localStorage.getItem('manupackaging_session'));
  const [authMode, setAuthMode] = useState<'login' | 'register'>('login');
  const [authData, setAuthData] = useState({ user: 'adaiasmelo', pass: '123456' }); 
  const [authError, setAuthError] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  // --- CHAT STATE ---
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<{id: number, user: string, text: string, time: string}[]>(() => {
    try { return JSON.parse(localStorage.getItem('manupackaging_chat_history') || '[]'); } catch { return []; }
  });
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('manupackaging_chat_history', JSON.stringify(chatMessages));
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatMessage.trim()) return;
    const newMsg = { 
      id: Date.now(), 
      user: authData.user || 'Eu', 
      text: chatMessage, 
      time: new Date().toLocaleTimeString('pt-BR', {hour:'2-digit', minute:'2-digit'}) 
    };
    setChatMessages(prev => [...prev, newMsg]);
    setChatMessage('');
  };

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    if (authData.user === 'adaiasmelo' && authData.pass === '123456') {
      localStorage.setItem('manupackaging_session', 'true');
      setIsAuthenticated(true);
      return;
    }
    const users = JSON.parse(localStorage.getItem('manupackaging_users') || '[]');
    if (authMode === 'register') {
      if (users.find((u: any) => u.user === authData.user)) {
        setAuthError('Usuário já existe.');
        return;
      }
      users.push(authData);
      localStorage.setItem('manupackaging_users', JSON.stringify(users));
      setAuthMode('login');
      setAuthError('Conta criada! Faça login.');
    } else {
      const validUser = users.find((u: any) => u.user === authData.user && u.pass === authData.pass);
      if (validUser) {
        localStorage.setItem('manupackaging_session', 'true');
        setIsAuthenticated(true);
      } else {
        setAuthError('Credenciais inválidas.');
      }
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('manupackaging_session');
    setIsAuthenticated(false);
  };

  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports' | 'personnel'>('dashboard');

  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const primaryKey = 'manupackaging_data';
      const initKey = 'manupackaging_initialized';
      const savedData = localStorage.getItem(primaryKey);
      const isInitialized = localStorage.getItem(initKey);
      if (savedData !== null) {
        try {
          const parsed = JSON.parse(savedData);
          if (Array.isArray(parsed)) return parsed;
        } catch (e) {}
      }
      return isInitialized === 'true' ? [] : INITIAL_DATA;
    } catch (e) {
      return [];
    }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const savedGoal = localStorage.getItem('manupackaging_goal');
    return savedGoal ? parseFloat(savedGoal) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const savedOps = localStorage.getItem('manupackaging_operators');
    if (savedOps) {
      try {
        const parsed = JSON.parse(savedOps);
        if (Array.isArray(parsed)) return parsed;
      } catch (e) {}
    }
    return DEFAULT_OPERATORS;
  });

  const [machineManualStatus, setMachineManualStatus] = useState<Record<string, 'Operando' | 'Manutenção'>>(() => {
    const saved = localStorage.getItem('manupackaging_machine_status');
    if (saved) {
      try { return JSON.parse(saved); } catch (e) {}
    }
    return { 'Cast 1': 'Operando', 'Cast 2': 'Operando' };
  });

  const [employees, setEmployees] = useState<any[]>(() => {
    try { 
      const saved = localStorage.getItem('manupackaging_employees');
      return saved ? JSON.parse(saved) : PERSONNEL_INITIAL_DATA; 
    } catch { return PERSONNEL_INITIAL_DATA; }
  });

  const [vacancies, setVacancies] = useState<any[]>(() => {
    try { return JSON.parse(localStorage.getItem('manupackaging_vacancies') || '[]'); } catch { return []; }
  });

  const [personnelViewMode, setPersonnelViewMode] = useState<'team' | 'orgchart'>('team');
  const [teamViewMode, setTeamViewMode] = useState<'active' | 'vacancies'>('active');
  const [selectedEmployeeId, setSelectedEmployeeId] = useState<number | null>(null);
  const [isPersonnelModalOpen, setIsPersonnelModalOpen] = useState(false);
  const [personnelForm, setPersonnelForm] = useState<any>({ id: null, name: '', role: 'Auxiliar', sector: 'Extrusão', machine: 'Cast 1', shiftType: '12x36', group: 'Diurno 1', status: 'Ativo' });
  const [isVacationModalOpen, setIsVacationModalOpen] = useState(false);
  const [vacationForm, setVacationForm] = useState({ empId: 0, days: 30, startDate: '' });

  useEffect(() => { localStorage.setItem('manupackaging_employees', JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem('manupackaging_vacancies', JSON.stringify(vacancies)); }, [vacancies]);
  useEffect(() => { 
    if (Array.isArray(productionData)) {
      localStorage.setItem('manupackaging_data', JSON.stringify(productionData));
      localStorage.setItem('manupackaging_initialized', 'true');
    }
  }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_operators', JSON.stringify(operators)); }, [operators]);
  useEffect(() => { localStorage.setItem('manupackaging_machine_status', JSON.stringify(machineManualStatus)); }, [machineManualStatus]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMonth, setSelectedMonth] = useState('Todos');
  const [selectedMachine, setSelectedMachine] = useState('Todas');
  const [selectedOperator, setSelectedOperator] = useState('Todos');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [pendingImportData, setPendingImportData] = useState<any>(null);
  const [isImporting, setIsImporting] = useState(false);

  const prodCardRef = useRef<HTMLDivElement>(null);
  const stopCardRef = useRef<HTMLDivElement>(null);
  const ecoACardRef = useRef<HTMLDivElement>(null);
  const ecoBCardRef = useRef<HTMLDivElement>(null);

  const downloadCardAsImage = (containerRef: React.RefObject<HTMLDivElement>, fileName: string) => {
    if (!containerRef.current) return;
    toPng(containerRef.current, { 
      filter: (node: HTMLElement) => !(node.tagName === 'BUTTON' || node.classList?.contains('no-export')),
      backgroundColor: '#ffffff',
      pixelRatio: 3,
    })
    .then((dataUrl) => {
      const link = document.createElement('a');
      link.download = `${fileName}_${new Date().toISOString().split('T')[0]}.png`;
      link.href = dataUrl;
      link.click();
    }).catch(err => console.error('Erro ao baixar imagem:', err));
  };

  const handleExportData = () => {
    const exportObj = { version: APP_DATA_VERSION, production: productionData, goal: goalValue, operators: operators, machineStatus: machineManualStatus, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(exportObj, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `backup_manupackaging_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      setTimeout(() => {
        setIsImporting(false);
        try {
          const content = event.target?.result as string;
          const imported = JSON.parse(content);
          if (imported) {
             const productionEntries = Array.isArray(imported) ? imported : (imported.production || imported.productionData || imported.data || []);
             if (Array.isArray(productionEntries)) {
                setPendingImportData({ production: productionEntries, goal: imported.goal !== undefined ? Number(imported.goal) : goalValue, operators: Array.isArray(imported.operators) ? imported.operators : operators, machineStatus: imported.machineStatus || machineManualStatus });
             }
          }
        } catch (err) { alert('Erro no backup.'); }
        if (fileInputRef.current) fileInputRef.current.value = '';
      }, 1000);
    };
    reader.readAsText(file);
  };

  const confirmPendingImport = () => {
    if (!pendingImportData) return;
    setProductionData(pendingImportData.production); 
    setGoalValue(pendingImportData.goal); 
    setOperators(pendingImportData.operators); 
    setMachineManualStatus(pendingImportData.machineStatus); 
    setPendingImportData(null);
  };

  const filteredData = useMemo(() => {
    return productionData.filter(entry => {
      const matchesMachine = selectedMachine === 'Todas' || entry.machine === selectedMachine;
      const matchesOperator = selectedOperator === 'Todos' || entry.operator === selectedOperator;
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = !searchTerm || 
        entry.operator?.toLowerCase().includes(searchLower) ||
        entry.machine?.toLowerCase().includes(searchLower) ||
        entry.date?.includes(searchLower);
      return matchesMachine && matchesOperator && matchesSearch;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, selectedMachine, selectedOperator, searchTerm]);

  const stats = useMemo(() => {
    const today = new Date().toLocaleDateString('sv-SE');
    return filteredData.reduce((acc, curr) => ({
      totalNet: acc.totalNet + (curr.netWeight || 0), 
      totalGross: acc.totalGross + (curr.grossWeight || 0), 
      totalDaily: acc.totalDaily + (curr.date === today ? (curr.netWeight || 0) : 0),
      ecoA: acc.ecoA + (curr.ecoA || 0), 
      ecoBP: acc.ecoBP + (curr.ecoBP || 0), 
      ecoBM: acc.ecoBM + (curr.ecoBM || 0), 
      borra: acc.borra + (curr.borraTotal || 0), 
      manut: acc.manut + (curr.manutencaoMin || 0), 
      proc: acc.proc + (curr.processoMin || 0), 
      outros: acc.outros + (curr.outrosMin || 0),
    }), { totalNet: 0, totalGross: 0, totalDaily: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const reportTotals = useMemo(() => {
    return filteredData.reduce((acc, curr) => ({
      gross: acc.gross + (curr.grossWeight || 0),
      tara: acc.tara + (curr.tara || 0),
      net: acc.net + (curr.netWeight || 0),
      vols: acc.vols + (curr.volumes || 0),
      tub: acc.tub + (curr.tubetes || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borra: acc.borra + (curr.borraTotal || 0),
      manut: acc.manut + (curr.manutencaoMin || 0),
      proc: acc.proc + (curr.processoMin || 0),
      outros: acc.outros + (curr.outrosMin || 0),
    }), { gross: 0, tara: 0, net: 0, vols: 0, tub: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredData]);

  const mainChartData = useMemo(() => {
    if (selectedOperator !== 'Todos') return [ { name: 'PROD. LÍQUIDA', value: stats.totalNet, unit: 'KG', color: '#3b82f6' }, { name: 'ECO A', value: stats.ecoA, unit: 'KG', color: '#10b981' }, { name: 'ECO B', value: stats.ecoBP + stats.ecoBM, unit: 'KG', color: '#8b5cf6' }, { name: 'BORRA', value: stats.borra, unit: 'KG', color: '#ef4444' } ].filter(d => d.value > 0);
    const map: Record<string, number> = {}; operators.forEach(op => map[op] = 0); filteredData.forEach(e => { if(map[e.operator] !== undefined) map[e.operator] += (e.netWeight || 0); });
    return Object.entries(map).filter(([_, v]) => v > 0).sort((a,b) => b[1] - a[1]).map(([name, value], i) => ({ name, value, unit: 'KG', color: ['#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#f97316', '#64748b', '#ef4444', '#06b6d4'][i % 8] }));
  }, [filteredData, operators, selectedOperator, stats]);

  const stopChartData = useMemo(() => [ { name: 'MANUTENÇÃO', value: stats.manut, unit: 'MIN', color: '#f97316' }, { name: 'PROCESSO', value: stats.proc, unit: 'MIN', color: '#f59e0b' }, { name: 'OUTROS', value: stats.outros, unit: 'MIN', color: '#94a3b8' } ].filter(d => d.value > 0), [stats]);

  const currentMonthStats = useMemo(() => { 
    const prefix = `${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}`;
    return productionData.filter(e => e.date.startsWith(prefix)).reduce((s, e) => s + (e.netWeight || 0), 0); 
  }, [productionData]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'> & { id?: string }) => { 
    if (newEntry.id) { 
      setProductionData(prev => prev.map(e => e.id === newEntry.id ? (newEntry as ProductionEntry) : e)); 
    } else { 
      setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) } as ProductionEntry, ...prev]); 
    } 
    setEditingEntry(null); 
  };

  const handleDeleteEntry = (id: string) => { 
    if (window.confirm('Tem certeza que deseja excluir este lançamento?')) {
      setProductionData(prev => prev.filter(e => e.id !== id)); 
    }
  };

  const formatWeight = (val: number) => { 
    if (val >= 1000) return `${(val / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 1 })} T`; 
    return `${val.toLocaleString('pt-BR')} KG`; 
  };

  // --- PERSONNEL HELPERS ---
  const groupedByMachine = useMemo(() => {
    const groups: Record<string, any[]> = {};
    employees.forEach(emp => {
      const key = emp.sector === 'Extrusão' ? `${emp.sector} - ${emp.group} - ${emp.machine}` : `${emp.sector} - ${emp.machine}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(emp);
    });
    return groups;
  }, [employees]);

  const handleDismiss = (emp: any) => {
    if (window.confirm(`Deseja remover ${emp.name}?`)) {
      setEmployees(prev => prev.filter(e => e.id !== emp.id));
      setVacancies(prev => [...prev, { ...emp, id: Date.now(), openSince: new Date().toLocaleDateString('pt-BR') }]);
    }
  };

  const handleToggleVacation = (emp: any) => {
    if (emp.status === 'Férias') {
      setEmployees(employees.map(e => e.id === emp.id ? { ...e, status: 'Ativo', vacationInfo: null } : e));
    } else {
      setVacationForm({ empId: emp.id, days: 30, startDate: new Date().toISOString().split('T')[0] });
      setIsVacationModalOpen(true);
    }
  };

  const handleSaveVacation = (e: React.FormEvent) => {
    e.preventDefault();
    const start = new Date(vacationForm.startDate);
    const returnDate = new Date(start);
    returnDate.setDate(returnDate.getDate() + vacationForm.days);
    setEmployees(employees.map(emp => emp.id === vacationForm.empId ? { ...emp, status: 'Férias', vacationInfo: { return: returnDate.toISOString().split('T')[0] } } : emp));
    setIsVacationModalOpen(false);
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-xl border border-slate-100 p-8 w-full max-w-md space-y-8">
          <div className="text-center space-y-2">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4">
              <ShieldCheck size={32} />
            </div>
            <h1 className="text-2xl font-black text-slate-800 tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></h1>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Acesso ao Sistema</p>
          </div>
          <form onSubmit={handleAuth} className="space-y-6">
            <input type="text" value={authData.user} onChange={(e) => setAuthData({...authData, user: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold" placeholder="Usuário" />
            <input type="password" value={authData.pass} onChange={(e) => setAuthData({...authData, pass: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold" placeholder="Senha" />
            {authError && <p className="text-red-500 text-xs font-bold">{authError}</p>}
            <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl shadow-lg transition-all">Entrar</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-20 overflow-x-hidden">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
           <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
           <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
          <button onClick={handleExportData} className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold px-4 py-2 rounded-lg text-sm flex items-center gap-2"><Save size={18} /><span className="hidden sm:inline">Backup</span></button>
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg text-sm flex items-center gap-2"><Plus size={18} /><span className="hidden sm:inline">Lançar</span></button>
          <button onClick={handleLogout} className="p-2 text-slate-400 hover:text-red-500"><LogOut size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2 text-slate-600 hover:bg-slate-100 rounded-lg"><Menu size={24} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="bg-slate-200/50 p-1 rounded-2xl inline-flex gap-1 overflow-x-auto no-scrollbar max-w-full">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><BarChart3 size={16} /> Dashboard</button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><FileText size={16} /> Relatórios</button>
          <button onClick={() => setActiveTab('personnel')} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'personnel' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}><Users2 size={16} /> Pessoal</button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' ? (
          <>
            <div className="grid grid-cols-2 gap-4">
              {['Cast 1', 'Cast 2'].map(name => (
                <div key={name} className="bg-white rounded-2xl p-4 shadow-sm border border-slate-100">
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{name}</span>
                    <div className={`w-3 h-3 rounded-full ${machineManualStatus[name] === 'Operando' ? 'bg-emerald-500' : 'bg-orange-500'}`}></div>
                  </div>
                  <div className="flex items-center gap-3 mt-1">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center ${machineManualStatus[name] === 'Operando' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>
                      {machineManualStatus[name] === 'Operando' ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                    </div>
                    <span className="text-sm font-bold text-slate-700">{machineManualStatus[name]}</span>
                  </div>
                </div>
              ))}
            </div>

            <div className="bg-white rounded-2xl p-6 shadow-sm border border-blue-500/10 space-y-4">
              <div className="flex items-center justify-between font-black">
                <div><span className="text-[10px] uppercase text-slate-400">Progresso Mensal</span><div className="flex items-baseline gap-2"><span className="text-4xl text-slate-800 tracking-tighter">{formatWeight(currentMonthStats)}</span><span className="text-slate-400 font-medium text-xs">/ {formatWeight(goalValue)}</span></div></div>
                <span className={`text-3xl ${currentMonthStats >= goalValue ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
              </div>
              <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
                <div className={`h-full rounded-full transition-all duration-1000 ${currentMonthStats >= goalValue ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div ref={prodCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 min-h-[520px] flex flex-col">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="font-black text-xs uppercase tracking-widest text-slate-800">Distribuição de Produção</h3>
                    <button onClick={() => downloadCardAsImage(prodCardRef, 'producao')} className="text-slate-300 hover:text-blue-600"><Download size={16} /></button>
                  </div>
                  <div className="flex-1 h-[350px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={mainChartData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} dataKey="value" paddingAngle={5}>
                          {mainChartData.map((e: any, i) => <Cell key={i} fill={e.color} />)}
                        </Pie>
                        <Tooltip />
                        <Legend />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>
               </div>

               <div ref={stopCardRef} className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 min-h-[520px] flex flex-col">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="font-black text-xs uppercase tracking-widest text-slate-800">Causas de Parada</h3>
                    <button onClick={() => downloadCardAsImage(stopCardRef, 'paradas')} className="text-slate-300 hover:text-blue-600"><Download size={16} /></button>
                  </div>
                  <div className="flex-1 h-[350px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={stopChartData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} dataKey="value" paddingAngle={5}>
                          {stopChartData.map((e: any, i) => <Cell key={i} fill={e.color} />)}
                        </Pie>
                        <Tooltip />
                        <Legend />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>
               </div>
            </div>
          </>
        ) : activeTab === 'reports' ? (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="p-4 border-b border-slate-100 flex items-center justify-between gap-4 bg-slate-50/50">
               <div className="relative flex-1 max-w-md">
                 <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                 <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar..." className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl text-xs font-bold text-slate-700 focus:outline-none" />
               </div>
               <button onClick={() => window.print()} className="flex items-center gap-2 px-4 py-2 bg-slate-800 text-white rounded-xl text-xs font-bold uppercase no-print"><Printer size={16} /> Exportar PDF</button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[1500px]">
                <thead>
                  <tr className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                    <th className="px-4 py-3 sticky left-0 bg-slate-50 z-10">Data</th>
                    <th className="px-4 py-3">Turno</th>
                    <th className="px-4 py-3">Operador</th>
                    <th className="px-4 py-3">Máquina</th>
                    <th className="px-4 py-3 font-black text-blue-700">P. Líquido</th>
                    <th className="px-4 py-3">Eco A</th>
                    <th className="px-4 py-3">Eco B (P)</th>
                    <th className="px-4 py-3">Eco B (M)</th>
                    <th className="px-4 py-3 text-red-500">Borra</th>
                    <th className="px-4 py-3 text-right">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[10px] font-bold">
                  {filteredData.map((e) => (
                    <tr key={e.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-4 py-3 sticky left-0 bg-white border-r border-slate-50">{e.date}</td>
                      <td className="px-4 py-3">{e.shift || '-'}</td>
                      <td className="px-4 py-3">{e.operator}</td>
                      <td className="px-4 py-3">{e.machine}</td>
                      <td className="px-4 py-3 font-black">{e.netWeight} KG</td>
                      <td className="px-4 py-3">{e.ecoA}</td>
                      <td className="px-4 py-3">{e.ecoBP}</td>
                      <td className="px-4 py-3">{e.ecoBM}</td>
                      <td className="px-4 py-3 text-red-500">{e.borraTotal}</td>
                      <td className="px-4 py-3 text-right space-x-2">
                        <button onClick={() => setEditingEntry(e) || setIsModalOpen(true)} className="text-blue-500 p-1.5 hover:bg-blue-50 rounded-lg"><Edit2 size={14} /></button>
                        <button onClick={() => handleDeleteEntry(e.id)} className="text-red-500 p-1.5 hover:bg-red-50 rounded-lg"><Trash2 size={14} /></button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        ) : (
          <div className="space-y-6">
            <div className="flex justify-between items-center bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
               <div className="flex gap-4">
                  <button onClick={() => setTeamViewMode('active')} className={`text-xs font-black uppercase tracking-widest pb-1 border-b-2 ${teamViewMode === 'active' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400'}`}>Ativos</button>
                  <button onClick={() => setTeamViewMode('vacancies')} className={`text-xs font-black uppercase tracking-widest pb-1 border-b-2 ${teamViewMode === 'vacancies' ? 'border-red-600 text-red-600' : 'border-transparent text-slate-400'}`}>Vagas</button>
               </div>
               <button className="bg-blue-600 text-white px-4 py-2 rounded-xl text-xs font-bold shadow-lg shadow-blue-200 flex items-center gap-2"><Plus size={16} /> Novo</button>
            </div>

            {teamViewMode === 'active' ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {Object.entries(groupedByMachine).map(([key, emps]) => (
                  <div key={key} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                    <div className="bg-slate-50 px-4 py-2 font-bold text-[10px] text-slate-500 uppercase border-b">{key}</div>
                    <div className="divide-y divide-slate-100">
                      {emps.map(emp => (
                        <div key={emp.id} className={`p-4 flex items-center justify-between hover:bg-slate-50 group cursor-pointer ${emp.status === 'Férias' ? 'bg-orange-50/50' : ''}`} onClick={() => setSelectedEmployeeId(selectedEmployeeId === emp.id ? null : emp.id)}>
                          <div className="flex items-center gap-3">
                             <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-white shadow-sm ${emp.group.includes('Noturno') ? 'bg-indigo-600' : 'bg-orange-500'}`}>{emp.name[0]}</div>
                             <div>
                                <h4 className="font-bold text-slate-800 text-sm">{emp.name}</h4>
                                <p className="text-[10px] text-slate-400 font-bold uppercase">{emp.role} • {emp.group}</p>
                                {emp.status === 'Férias' && <span className="text-[9px] bg-orange-100 text-orange-700 px-1.5 py-0.5 rounded uppercase font-black">Em Férias</span>}
                             </div>
                          </div>
                          {selectedEmployeeId === emp.id && (
                            <div className="flex gap-1 animate-in slide-in-from-right-2">
                               <button onClick={(e) => { e.stopPropagation(); handleToggleVacation(emp); }} className="p-1.5 text-orange-600 hover:bg-orange-50 rounded"><Palmtree size={16} /></button>
                               <button onClick={(e) => { e.stopPropagation(); handleDismiss(emp); }} className="p-1.5 text-red-600 hover:bg-red-50 rounded"><UserMinus size={16} /></button>
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="space-y-4">
                 {vacancies.map(v => (
                   <div key={v.id} className="bg-white p-4 rounded-2xl border-l-4 border-l-red-500 border border-slate-200 flex items-center justify-between">
                      <div>
                        <h4 className="font-bold text-slate-800">{v.name}</h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Saída registrada em {v.openSince}</p>
                      </div>
                      <button className="text-blue-600 font-bold text-xs uppercase hover:underline">Recontratar</button>
                   </div>
                 ))}
              </div>
            )}
          </div>
        )}
      </main>

      {/* Vacation Modal */}
      {isVacationModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl p-6">
             <h2 className="text-lg font-bold text-slate-800 mb-4">Agendar Férias</h2>
             <form onSubmit={handleSaveVacation} className="space-y-4">
                <div>
                   <label className="text-[10px] font-bold text-slate-500 uppercase">Data Início</label>
                   <input required type="date" value={vacationForm.startDate} onChange={e => setVacationForm({...vacationForm, startDate: e.target.value})} className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" />
                </div>
                <div>
                   <label className="text-[10px] font-bold text-slate-500 uppercase">Dias</label>
                   <input required type="number" value={vacationForm.days} onChange={e => setVacationForm({...vacationForm, days: parseInt(e.target.value)})} className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" />
                </div>
                <button type="submit" className="w-full bg-orange-500 text-white font-bold py-3 rounded-xl shadow-lg">Confirmar</button>
             </form>
          </div>
        </div>
      )}

      {/* Menu Lateral */}
      <div id="menu-lateral" className={`fixed inset-0 z-50 transition-all duration-300 ${isMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-slate-900/40 backdrop-blur-sm transition-opacity duration-300 ${isMenuOpen ? 'opacity-100' : 'opacity-0'}`} onClick={() => setIsMenuOpen(false)} />
        <div className={`absolute right-0 top-0 bottom-0 w-80 bg-white shadow-2xl transition-transform duration-300 transform p-6 flex flex-col gap-6 ${isMenuOpen ? 'translate-x-0' : 'translate-x-full'} overflow-y-auto`}>
          <div className="flex items-center justify-between"><h2 className="text-lg font-black text-slate-800 flex items-center gap-2"><Settings size={20} className="text-blue-600" /> CONFIGURAÇÕES</h2><button onClick={() => setIsMenuOpen(false)} className="p-2 text-slate-400"><X size={24} /></button></div>
          <div className="space-y-6">
             <div className="space-y-4 pt-4 border-t border-slate-100">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><RefreshCw size={14} /> Backup</h3>
               <div className="grid grid-cols-2 gap-2">
                 <button onClick={handleExportData} className="flex items-center justify-center gap-2 bg-slate-100 hover:bg-blue-600 hover:text-white text-slate-600 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all border border-slate-200"><Download size={14} /> Exportar</button>
                 <button onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center gap-2 bg-slate-100 hover:bg-emerald-600 hover:text-white text-slate-600 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all border border-slate-200"><Upload size={14} /> Importar</button>
               </div>
               <input type="file" ref={fileInputRef} onChange={handleImportData} className="hidden" accept=".json" />
             </div>
             <div className="pt-4 border-t border-slate-100">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Meta Mensal (KG)</label>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full mt-2 bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600" />
             </div>
          </div>
        </div>
      </div>

      <div className="fixed bottom-4 right-4 z-40 flex flex-col items-end gap-2 no-print">
        {isChatOpen && (
          <div className="bg-white rounded-2xl shadow-2xl border border-slate-100 w-80 h-96 flex flex-col overflow-hidden mb-2 animate-in slide-in-from-bottom-10">
             <div className="bg-blue-600 p-3 flex items-center justify-between text-white">
               <h3 className="font-bold text-sm flex items-center gap-2"><MessageSquare size={16} /> Chat de Turno</h3>
               <button onClick={() => setIsChatOpen(false)}><X size={16} /></button>
             </div>
             <div className="flex-1 overflow-y-auto p-3 space-y-3 bg-slate-50">
               {chatMessages.map(msg => (
                 <div key={msg.id} className={`flex flex-col ${msg.user === (authData.user || 'Eu') ? 'items-end' : 'items-start'}`}>
                   <div className={`max-w-[80%] rounded-xl p-2.5 text-xs font-medium shadow-sm ${msg.user === (authData.user || 'Eu') ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white border border-slate-200 text-slate-700 rounded-tl-none'}`}>
                     {msg.text}
                   </div>
                   <span className="text-[9px] text-slate-400 mt-1 px-1">{msg.user} • {msg.time}</span>
                 </div>
               ))}
               <div ref={chatEndRef} />
             </div>
             <form onSubmit={handleSendMessage} className="p-2 bg-white border-t border-slate-100 flex gap-2">
               <input className="flex-1 bg-slate-100 rounded-xl px-3 py-2 text-xs font-medium focus:outline-none focus:ring-2 focus:ring-blue-500/20" placeholder="Digite sua mensagem..." value={chatMessage} onChange={e => setChatMessage(e.target.value)} />
               <button type="submit" className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700 transition-colors">
                 <Send size={16} />
               </button>
             </form>
          </div>
        )}
        <button onClick={() => setIsChatOpen(!isChatOpen)} className="bg-blue-600 hover:bg-blue-700 text-white p-4 rounded-full shadow-lg shadow-blue-300 transition-all hover:scale-110 active:scale-95 flex items-center justify-center relative group">
          {isChatOpen ? <X size={24} /> : <MessageSquare size={24} />}
          {!isChatOpen && chatMessages.length > 0 && (
             <span className="absolute top-0 right-0 w-3 h-3 bg-red-500 rounded-full border-2 border-white"></span>
          )}
        </button>
      </div>

      <LaunchModal
        isOpen={isModalOpen}
        onClose={() => { setIsModalOpen(false); setEditingEntry(null); }}
        onSave={handleSaveEntry}
        operators={operators}
        activeMachines={Object.keys(machineManualStatus).filter(k => machineManualStatus[k] === 'Operando')}
        initialData={editingEntry}
      />
    </div>
  );
};

export default App;

