              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {Object.entries(groupedPersonnel).map(([key, emps]) => (
                  <div key={key} className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                    <div className="bg-slate-50 px-4 py-2 font-bold text-[10px] text-slate-500 uppercase border-b">{key}</div>
                    <div className="divide-y divide-slate-100">
                      {emps.map(emp => (
                        <div key={emp.id} className="p-4 flex items-center justify-between hover:bg-slate-50 group cursor-pointer" onClick={() => setSelectedEmployeeId(selectedEmployeeId === emp.id ? null : emp.id)}>
                          <div className="flex items-center gap-3">
                             <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-white ${emp.group.includes('Noturno') ? 'bg-indigo-600' : 'bg-orange-500'}`}>{emp.name[0]}</div>
                             <div>
                                <h4 className="font-bold text-slate-800 text-sm">{emp.name}</h4>
                                <p className="text-[10px] text-slate-400 font-bold uppercase">{emp.role}</p>
                             </div>
                          </div>
                          {selectedEmployeeId === emp.id && (
                            <button onClick={(e) => handleDismiss(e, emp)} className="p-2 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"><Trash2 size={16} /></button>
