                 <button onClick={handleExportData} className="flex items-center justify-center gap-2 bg-slate-100 hover:bg-blue-600 hover:text-white text-slate-600 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all border border-slate-200"><Download size={14} /> Exportar</button>
                 <button onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center gap-2 bg-slate-100 hover:bg-emerald-600 hover:text-white text-slate-600 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all border border-slate-200"><Upload size={14} /> Importar</button>
               </div>
               <input type="file" ref={fileInputRef} onChange={handleImportData} className="hidden" accept=".json" />
             </div>
             <div className="pt-4 border-t border-slate-100">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Meta Mensal (KG)</label>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(parseFloat(e.target.value) || 0)} className="w-full mt-2 bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-black text-blue-600" />
             </div>
             <div className="pt-4 border-t border-slate-100">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Gestão de Operadores</label>
                <div className="flex gap-2 mt-2">
                  <input type="text" value={newOperatorName} onChange={e => setNewOperatorName(e.target.value)} placeholder="Novo nome..." className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs" />
                  <button onClick={handleAddOperator} className="bg-blue-600 text-white p-2 rounded-xl"><Plus size={16} /></button>
                </div>
                <div className="mt-3 space-y-1">
                  {operators.map(op => (
                    <div key={op} className="flex items-center justify-between bg-slate-50 p-2 rounded-lg text-xs font-bold text-slate-600 group">
                      <span>{op}</span>
                      <button onClick={() => handleRemoveOperator(op)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={12} /></button>
                    </div>
                  ))}
                </div>
             </div>
          </div>
        </div>
      </div>

      <div className="fixed bottom-4 right-4 z-40 flex flex-col items-end gap-2 no-print">
        {isChatOpen && (
          <div className="bg-white rounded-2xl shadow-2xl border border-slate-100 w-80 h-96 flex flex-col overflow-hidden mb-2 animate-in slide-in-from-bottom-10">
             <div className="bg-blue-600 p-3 flex items-center justify-between text-white">
               <h3 className="font-bold text-sm flex items-center gap-2"><MessageSquare size={16} /> Chat de Turno</h3>
               <button onClick={() => setIsChatOpen(false)}><X size={16} /></button>
             </div>
             <div className="flex-1 overflow-y-auto p-3 space-y-3 bg-slate-50">
               {chatMessages.map(msg => (
                 <div key={msg.id} className={`flex flex-col ${msg.user === authData.user ? 'items-end' : 'items-start'}`}>
                   <div className={`max-w-[80%] rounded-xl p-2.5 text-xs font-medium shadow-sm ${msg.user === authData.user ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white border text-slate-700 rounded-tl-none'}`}>{msg.text}</div>
                   <span className="text-[9px] text-slate-400 mt-1">{msg.time}</span>
                 </div>
               ))}
               <div ref={chatEndRef} />
             </div>
             <form onSubmit={handleSendMessage} className="p-2 bg-white border-t flex gap-2">
               <input className="flex-1 bg-slate-100 rounded-xl px-3 py-2 text-xs focus:outline-none" placeholder="Mensagem..." value={chatMessage} onChange={e => setChatMessage(e.target.value)} />
               <button type="submit" className="bg-blue-600 text-white p-2 rounded-xl"><Send size={16} /></button>
             </form>
          </div>
        )}
        <button onClick={() => setIsChatOpen(!isChatOpen)} className="bg-blue-600 text-white p-4 rounded-full shadow-lg transition-all active:scale-95 flex items-center justify-center relative">
          {isChatOpen ? <X size={24} /> : <MessageSquare size={24} />}
          {!isChatOpen && chatMessages.length > 0 && <span className="absolute top-0 right-0 w-3 h-3 bg-red-500 rounded-full border-2 border-white"></span>}
        </button>
      </div>

      <LaunchModal isOpen={isModalOpen} onClose={() => { setIsModalOpen(false); setEditingEntry(null); }} onSave={handleSaveEntry} operators={operators} activeMachines={Object.keys(machineManualStatus).filter(k => machineManualStatus[k] === 'Operando')} initialData={editingEntry} />
    </div>
  );
};

export default App;

