  const [goalValue, setGoalValue] = useState<number>(() => {
    const saved = localStorage.getItem('manupackaging_goal');
    return saved ? parseFloat(saved) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const saved = localStorage.getItem('manupackaging_operators');
    return saved ? JSON.parse(saved) : DEFAULT_OPERATORS;
  });

  const [employees, setEmployees] = useState<any[]>(() => {
    const saved = localStorage.getItem('manupackaging_employees');
    return saved ? JSON.parse(saved) : PERSONNEL_INITIAL_DATA;
  });

  const [vacancies, setVacancies] = useState<any[]>(() => {
    const saved = localStorage.getItem('manupackaging_vacancies');
    return saved ? JSON.parse(saved) : [];
  });

  const [shifts, setShifts] = useState<Shift[]>(() => {
    const saved = localStorage.getItem('manupackaging_shifts');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: 'Diurno 1', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
      { id: '2', name: 'Noturno 1', startTime: '19:00', endTime: '07:00', type: 'Noturno' }
    ];
  });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isShiftModalOpen, setIsShiftModalOpen] = useState(false);
  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [chatMessages, setChatMessages] = useState<any[]>(() => JSON.parse(localStorage.getItem('manupackaging_chat_history') || '[]'));
  const [teamViewMode, setTeamViewMode] = useState<'active' | 'vacancies' | 'shifts'>('active');
  const [isEditPersonnelModalOpen, setIsEditPersonnelModalOpen] = useState(false);
  const [editingPersonnel, setEditingPersonnel] = useState<any | null>(null);
  const [isAddVacancyModalOpen, setIsAddVacancyModalOpen] = useState(false);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_employees', JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem('manupackaging_vacancies', JSON.stringify(vacancies)); }, [vacancies]);
  useEffect(() => { localStorage.setItem('manupackaging_shifts', JSON.stringify(shifts)); }, [shifts]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_operators', JSON.stringify(operators)); }, [operators]);
  useEffect(() => { 
    localStorage.setItem('manupackaging_chat_history', JSON.stringify(chatMessages));
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'> & { id?: string }) => {
    if (newEntry.id) {
      setProductionData(prev => prev.map(e => e.id === newEntry.id ? (newEntry as ProductionEntry) : e));
    } else {
      setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) } as ProductionEntry, ...prev]);
    }
    setEditingEntry(null);
  };

  const handleSaveShift = (newShift: Omit<Shift, 'id'>) => {
    const shift: Shift = {
      ...newShift,
      id: Math.random().toString(36).substr(2, 9)
    };
    setShifts(prev => [...prev, shift]);
  };

  const handleDeleteEntry = (id: string) => {
    if (window.confirm('Excluir este lançamento permanentemente?')) {
      setProductionData(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleExportData = () => {
    const data = { production: productionData, employees, shifts, goal: goalValue, operators };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `manupackaging_backup_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.production) setProductionData(data.production);
        if (data.employees) setEmployees(data.employees);
        if (data.shifts) setShifts(data.shifts);
        if (data.goal) setGoalValue(data.goal);
        alert('Dados importados com sucesso!');
      } catch { alert('Erro na leitura do arquivo.'); }
    };
    reader.readAsText(file);
  };

  const filteredDataForTable = useMemo<ProductionEntry[]>(() => {
    return productionData.filter(e => {
      const s = searchTerm.toLowerCase();
      return !searchTerm || e.operator.toLowerCase().includes(s) || e.machine.toLowerCase().includes(s) || e.date.includes(s);
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, searchTerm]);

  const { currentMonthStats, currentYearStats, currentWeekStats, currentDayStats } = useMemo(() => {
    const now = new Date();
    const currentYearStr = now.getFullYear().toString();
    const currentMonthPrefix = `${currentYearStr}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const currentDayStr = now.toLocaleDateString('sv-SE');

    const d = new Date(now);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    const mondayStr = new Date(d.setDate(diff)).toISOString().split('T')[0];

    return productionData.reduce((acc, e) => {
      if (e.date.startsWith(currentYearStr)) acc.currentYearStats += (e.netWeight || 0);
      if (e.date.startsWith(currentMonthPrefix)) acc.currentMonthStats += (e.netWeight || 0);
      if (e.date >= mondayStr) acc.currentWeekStats += (e.netWeight || 0);
      if (e.date === currentDayStr) acc.currentDayStats += (e.netWeight || 0);
      return acc;
    }, { currentMonthStats: 0, currentYearStats: 0, currentWeekStats: 0, currentDayStats: 0 });
  }, [productionData]);

  // Use explicit typing for operatorStats to ensure proper inference for chart data
  const operatorStats = useMemo<OperatorStat[]>(() => {
    const now = new Date();
    const yearStr = now.getFullYear().toString();
    const dayStr = now.toLocaleDateString('sv-SE');
    const d = new Date(now);
    const diff = d.getDate() - d.getDay() + (d.getDay() === 0 ? -6 : 1);
    const mondayStr = new Date(d.setDate(diff)).toISOString().split('T')[0];

    const stats: Record<string, OperatorStat> = {};
    operators.forEach(op => {
      stats[op] = { name: op, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0 };
    });

    productionData.forEach(e => {
      let matchesTimeframe = false;
      if (selectedTimeframe === 'all') matchesTimeframe = true;
      if (selectedTimeframe === 'year' && e.date.startsWith(yearStr)) matchesTimeframe = true;
      if (selectedTimeframe === 'day' && e.date === dayStr) matchesTimeframe = true;
      if (selectedTimeframe === 'week' && e.date >= mondayStr) matchesTimeframe = true;

      if (matchesTimeframe && stats[e.operator]) {
        stats[e.operator].prod += (e.netWeight || 0);
        stats[e.operator].ecoA += (e.ecoA || 0);
        stats[e.operator].ecoBP += (e.ecoBP || 0);
        stats[e.operator].ecoBM += (e.ecoBM || 0);
      }
    });
    // Return an array derived from the stats object to ensure correct typing
    return operators.map(op => stats[op]);
  }, [productionData, operators, selectedTimeframe]);

  const prodChartData = useMemo<OperatorStat[]>(() => [...operatorStats].filter(s => s.prod > 0).sort((a, b) => b.prod - a.prod), [operatorStats]);
  const ecoAChartData = useMemo<OperatorStat[]>(() => [...operatorStats].filter(s => s.ecoA > 0).sort((a, b) => b.ecoA - a.ecoA), [operatorStats]);

  const groupedPersonnel = useMemo<Record<string, any[]>>(() => {
    const g: Record<string, any[]> = {};
    employees.forEach(e => {
      const key = `${e.sector} - ${e.group}`;
      if (!g[key]) g[key] = [];
      g[key].push(e);
    });
    return g;
  }, [employees]);

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl shadow-xl border border-slate-100 p-8 w-full max-w-md space-y-8">
          <div className="text-center space-y-2">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4"><ShieldCheck size={32} /></div>
            <h1 className="text-2xl font-black text-slate-800 tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></h1>
            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Controle de Acesso</p>
          </div>
          <form onSubmit={(e) => { e.preventDefault(); localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="space-y-6">
            <input type="text" value={authData.user} readOnly className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold" />
            <input type="password" value={authData.pass} readOnly className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold" />
            <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl shadow-lg transition-all">Entrar</button>
          </form>
        </div>
      </div>
    );
  }

  const formatWeight = (val: number) => val >= 1000 ? (val / 1000).toFixed(1) + ' T' : val.toLocaleString() + ' KG';

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
           <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white"><Cpu size={18} /></div>
           <span className="tracking-tight">Manupackaging <span className="text-blue-600">Pro</span></span>
        </h1>
        <div className="flex items-center gap-2">
          <button onClick={handleExportData} className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold px-4 py-2 rounded-lg text-sm flex items-center gap-2"><Save size={18} /><span className="hidden sm:inline">Backup</span></button>
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white font-bold px-4 py-2 rounded-lg text-sm flex items-center gap-2"><Plus size={18} /><span className="hidden sm:inline">Lançar</span></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2 text-slate-600 hover:bg-slate-100 rounded-lg"><Settings size={24} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="bg-slate-200/50 p-1 rounded-2xl inline-flex gap-1 overflow-x-auto no-scrollbar max-w-full">
          {['dashboard', 'reports', 'personnel'].map((tab) => (
            <button key={tab} onClick={() => setActiveTab(tab as any)} className={`flex items-center gap-2 px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>
              {tab === 'dashboard' ? <BarChart3 size={16} /> : tab === 'reports' ? <FileText size={16} /> : <Users2 size={16} />}
              {tab === 'dashboard' ? 'Dashboard' : tab === 'reports' ? 'Relatórios' : 'Pessoal'}
            </button>
          ))}
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' ? (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div onClick={() => setSelectedTimeframe('year')} className={`bg-white rounded-3xl p-6 shadow-sm border transition-all cursor-pointer relative group ${selectedTimeframe === 'year' ? 'border-blue-500 ring-2 ring-blue-500/20 bg-blue-50/10' : 'border-slate-100 hover:border-blue-200'}`}>
                <div className="flex justify-between items-start">
                  <span className={`text-[10px] uppercase font-black tracking-widest ${selectedTimeframe === 'year' ? 'text-blue-600' : 'text-slate-400'}`}>Produção do Ano</span>
                  {selectedTimeframe === 'year' && <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>}
                </div>
                <div className="text-2xl font-black text-slate-800 mt-1">{formatWeight(currentYearStats)}</div>
                <div className={`mt-2 text-[9px] font-bold uppercase transition-opacity ${selectedTimeframe === 'year' ? 'text-blue-500 opacity-100' : 'text-slate-300 opacity-0 group-hover:opacity-100'}`}>Filtrar Gráficos</div>
              </div>

              <div onClick={() => setSelectedTimeframe('day')} className={`bg-white rounded-3xl p-6 shadow-sm border transition-all cursor-pointer relative group ${selectedTimeframe === 'day' ? 'border-blue-500 ring-2 ring-blue-500/20 bg-blue-50/10' : 'border-slate-100 hover:border-blue-200'}`}>
                <div className="flex justify-between items-start">
                  <span className={`text-[10px] uppercase font-black tracking-widest ${selectedTimeframe === 'day' ? 'text-blue-600' : 'text-slate-400'}`}>Produção Diária</span>
                  {selectedTimeframe === 'day' && <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>}
                </div>
                <div className="text-2xl font-black text-blue-600 mt-1">{formatWeight(currentDayStats)}</div>
                <div className={`mt-2 text-[9px] font-bold uppercase transition-opacity ${selectedTimeframe === 'day' ? 'text-blue-500 opacity-100' : 'text-slate-300 opacity-0 group-hover:opacity-100'}`}>Filtrar Gráficos</div>
              </div>

              <div onClick={() => setSelectedTimeframe('week')} className={`bg-white rounded-3xl p-6 shadow-sm border transition-all cursor-pointer relative group ${selectedTimeframe === 'week' ? 'border-blue-500 ring-2 ring-blue-500/20 bg-blue-50/10' : 'border-slate-100 hover:border-blue-200'}`}>
                <div className="flex justify-between items-start">
                  <span className={`text-[10px] uppercase font-black tracking-widest ${selectedTimeframe === 'week' ? 'text-blue-600' : 'text-slate-400'}`}>Produção da Semana</span>
                  {selectedTimeframe === 'week' && <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>}
                </div>
                <div className="text-2xl font-black text-emerald-600 mt-1">{formatWeight(currentWeekStats)}</div>
                <div className={`mt-2 text-[9px] font-bold uppercase transition-opacity ${selectedTimeframe === 'week' ? 'text-blue-500 opacity-100' : 'text-slate-300 opacity-0 group-hover:opacity-100'}`}>Filtrar Gráficos</div>
              </div>
            </div>

            <div onClick={() => setSelectedTimeframe('all')} className={`bg-white rounded-3xl p-6 shadow-sm border transition-all cursor-pointer relative group ${selectedTimeframe === 'all' ? 'border-blue-500 ring-2 ring-blue-500/20 bg-blue-50/10' : 'border-slate-100 hover:border-blue-300'} space-y-4`}>
              <div className="flex items-center justify-between font-black">
                <div>
                  <span className={`text-[10px] uppercase font-black tracking-widest ${selectedTimeframe === 'all' ? 'text-blue-600' : 'text-slate-400'}`}>Meta Mensal (Status Geral)</span>
                  <div className="flex items-baseline gap-2">
                    <span className="text-3xl text-slate-800 tracking-tighter">{(currentMonthStats/1000).toFixed(1)} T</span>
                    <span className="text-slate-400 font-medium text-xs">/ {(goalValue/1000).toFixed(1)} T</span>
                  </div>
                </div>
                <div className="flex items-center gap-4">
                  <span className={`text-3xl ${currentMonthStats >= goalValue ? 'text-emerald-600' : 'text-blue-600'}`}>{goalValue > 0 ? Math.round((currentMonthStats / goalValue) * 100) : 0}%</span>
                  {selectedTimeframe === 'all' && <div className="w-3 h-3 bg-blue-500 rounded-full animate-ping"></div>}
                </div>
              </div>
              <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
                <div className={`h-full rounded-full transition-all duration-1000 ${currentMonthStats >= goalValue ? 'bg-emerald-500' : 'bg-blue-600'}`} style={{ width: `${Math.min((currentMonthStats / (goalValue || 1)) * 100, 100)}%` }}></div>
              </div>
              <div className={`text-center text-[9px] font-black uppercase tracking-tighter transition-opacity ${selectedTimeframe === 'all' ? 'text-blue-600' : 'text-slate-300 opacity-0 group-hover:opacity-100'}`}>
                {selectedTimeframe === 'all' ? '✓ EXIBINDO TUDO (NORMAL)' : 'CLIQUE PARA VOLTAR AO NORMAL (GERAL)'}
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 flex flex-col h-[520px]">
                  <h3 className="font-black text-xs uppercase tracking-widest text-slate-800 mb-4 flex items-center justify-between">
                    <span>🏆 Produção Líquida (KG)</span>
                  </h3>
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={prodChartData} cx="50%" cy="50%" outerRadius={100} innerRadius={60} dataKey="prod" nameKey="name" label={renderCustomizedLabel} paddingAngle={2}>
                        {prodChartData.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} stroke="none" />)}
                      </Pie>
                      <Tooltip formatter={(val: number) => `${val.toLocaleString()} KG`} contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)'}} />
                      <Legend verticalAlign="bottom" height={120} align="center" iconType="circle" />
                    </PieChart>
                  </ResponsiveContainer>
               </div>
               <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 flex flex-col h-[520px]">
                  <h3 className="font-black text-xs uppercase tracking-widest text-slate-800 mb-4 flex items-center justify-between">
                    <span>♻️ Eco A (KG)</span>
                  </h3>
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={ecoAChartData} cx="50%" cy="50%" outerRadius={100} innerRadius={60} dataKey="ecoA" nameKey="name" label={renderCustomizedLabel} paddingAngle={2}>
                        {ecoAChartData.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} stroke="none" />)}
                      </Pie>
                      <Tooltip formatter={(val: number) => `${val.toLocaleString()} KG`} contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)'}} />
                      <Legend verticalAlign="bottom" height={120} align="center" iconType="circle" />
                    </PieChart>
                  </ResponsiveContainer>
               </div>
            </div>
          </div>
        ) : activeTab === 'reports' ? (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="p-4 border-b border-slate-100 flex items-center justify-between gap-4 bg-slate-50/50">
               <div className="relative flex-1 max-w-md">
                 <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                 <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Pesquisar registros..." className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-xl text-xs font-bold text-slate-700 focus:outline-none" />
               </div>
               <button onClick={() => window.print()} className="flex items-center gap-2 px-4 py-2 bg-slate-800 text-white rounded-xl text-xs font-bold uppercase no-print"><Printer size={16} /> Imprimir</button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[900px]">
                <thead>
                  <tr className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                    <th className="px-4 py-3">Data</th>
                    <th className="px-4 py-3">Operador</th>
                    <th className="px-4 py-3">Máquina</th>
                    <th className="px-4 py-3 font-black text-blue-700">Líquido (KG)</th>
                    <th className="px-4 py-3 text-emerald-600">Eco A</th>
                    <th className="px-4 py-3 text-red-500">Borra</th>
                    <th className="px-4 py-3 text-right">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[10px] font-bold">
                  {filteredDataForTable.map((e) => (
                    <tr key={e.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-4 py-3">{e.date}</td>
                      <td className="px-4 py-3">{e.operator}</td>
                      <td className="px-4 py-3">{e.machine}</td>
                      <td className="px-4 py-3 font-black">{e.netWeight}</td>
                      <td className="px-4 py-3 text-emerald-600">{e.ecoA}</td>
                      <td className="px-4 py-3 text-red-500">{e.borraTotal}</td>
                      <td className="px-4 py-3 text-right space-x-2">
                        <button onClick={() => { setEditingEntry(e); setIsModalOpen(true); }} className="text-blue-500 p-1.5 hover:bg-blue-50 rounded-lg transition-all"><FileText size={14} /></button>
                        <button onClick={() => handleDeleteEntry(e.id)} className="text-red-400 hover:text-red-600 p-1.5 hover:bg-red-50 rounded-lg transition-all"><Trash2 size={14} /></button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        ) : (
          <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center bg-white p-4 rounded-3xl shadow-sm border border-slate-100 gap-4">
               <div className="flex gap-4 overflow-x-auto no-scrollbar w-full md:w-auto">
                  <button onClick={() => setTeamViewMode('active')} className={`text-xs font-black uppercase tracking-widest pb-1 border-b-2 whitespace-nowrap transition-all ${teamViewMode === 'active' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>Equipe Ativa</button>
                  <button onClick={() => setTeamViewMode('shifts')} className={`text-xs font-black uppercase tracking-widest pb-1 border-b-2 whitespace-nowrap transition-all ${teamViewMode === 'shifts' ? 'border-orange-600 text-orange-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>Turnos</button>
                  <button onClick={() => setTeamViewMode('vacancies')} className={`text-xs font-black uppercase tracking-widest pb-1 border-b-2 whitespace-nowrap transition-all ${teamViewMode === 'vacancies' ? 'border-red-600 text-red-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>Vagas</button>
               </div>
               <div className="flex items-center gap-2 w-full md:w-auto">
                 <button onClick={() => setIsShiftModalOpen(true)} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2 bg-orange-50 text-orange-600 border border-orange-100 rounded-xl text-xs font-black uppercase hover:bg-orange-100 transition-all">
                   <Clock size={16} /> Adicionar Turno
                 </button>
                 <button onClick={() => setIsAddVacancyModalOpen(true)} className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-2 bg-slate-50 text-slate-600 border border-slate-200 rounded-xl text-xs font-black uppercase hover:bg-slate-100 transition-all">
                   <Plus size={16} /> Nova Vaga
                 </button>
               </div>
            </div>

            {teamViewMode === 'active' ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {/* Use Object.keys for better compatibility and type safety when iterating over records */}
                {Object.keys(groupedPersonnel).map((key) => {
                  const emps = groupedPersonnel[key];
                  return (
