                    >
                      <Trash2 size={14} />
                    </button>
                  </div>
                ))}
              </div>
            ) : (
              <div className="space-y-4">
                {vacancies.length === 0 ? (
                  <div className="bg-white p-12 text-center rounded-3xl border border-slate-100">
                    <AlertTriangle size={32} className="mx-auto text-slate-300 mb-2" />
                    <p className="text-slate-400 font-bold text-sm">Nenhuma vaga aberta no momento.</p>
                  </div>
                ) : (
                  vacancies.map(v => (
                    <div key={v.id} className="bg-white p-4 rounded-3xl border border-slate-200 flex items-center justify-between">
                      <div>
                        <h4 className="font-bold text-slate-800">{v.name}</h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">Grupo: {v.group} | Aberta desde: {v.openSince}</p>
                      </div>
                      <button onClick={() => setVacancies(prev => prev.filter(x => x.id !== v.id))} className="text-red-400 p-2"><Trash2 size={16} /></button>
                    </div>
                  ))
                )}
              </div>
            )}
          </div>
        )}
      </main>

      <ShiftModal isOpen={isShiftModalOpen} onClose={() => setIsShiftModalOpen(false)} onSave={handleSaveShift} />
      <LaunchModal isOpen={isModalOpen} onClose={() => { setIsModalOpen(false); setEditingEntry(null); }} onSave={handleSaveEntry} operators={operators} activeMachines={['Cast 1', 'Cast 2']} initialData={editingEntry} />
    </div>
  );
};

